const ATLAS_HISTORY_V2_KEY = "agent_crypto_history_v2";
const ATLAS_HISTORY_V2_MAX = 30;

function atlasHistoryV2Read() {
  try {
    const raw = localStorage.getItem(ATLAS_HISTORY_V2_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch (_) {
    return [];
  }
}

function atlasHistoryV2Write(entries) {
  const clean = Array.isArray(entries) ? entries.slice(-ATLAS_HISTORY_V2_MAX) : [];
  try {
    localStorage.setItem(ATLAS_HISTORY_V2_KEY, JSON.stringify(clean));
  } catch (_) {}
  return clean;
}

function atlasHistoryV2CompactSnapshot(snapshot) {
  if (!snapshot?.fingerprint) return null;

  const raw = snapshot.raw_context || {};
  const strict = snapshot.strict_contract || {};
  const market = strict.sources?.market || {};
  const binance = strict.sources?.binance || {};
  const top5 = Array.isArray(raw.binance_top5?.assets)
    ? raw.binance_top5.assets.map(asset => ({
        id: asset.id || null,
        symbol: String(asset.symbol || "").toUpperCase(),
        price: Number.isFinite(Number(asset.price)) ? Number(asset.price) : null,
        change24h: Number.isFinite(Number(asset.change24h)) ? Number(asset.change24h) : null
      }))
    : [];

  const watch = raw.watchlist_intelligence_v4 || state.watchlistIntelligence || null;
  const news = raw.news_event_reaction_v1 || state.newsEventReaction || null;
  const math = raw.math_core_v4 || state.math || null;

  return {
    schema: "atlas_history_snapshot_v2",
    fingerprint: snapshot.fingerprint,
    generated_at: snapshot.generated_at || new Date().toISOString(),
    market_status: market.status || null,
    market_count: Number.isFinite(Number(market.count)) ? Number(market.count) : null,
    binance_direct: Number(binance.direct_pairs || 0),
    binance_derived: Number(binance.derived_pairs || 0),
    top5,
    watchlist: watch ? {
      leaders: (watch.leaders || []).map(item => item.symbol).slice(0, 5),
      laggards: (watch.laggards || []).map(item => item.symbol).slice(0, 5),
      foundations: (watch.foundations || []).map(item => item.symbol).slice(0, 6),
      speculative: (watch.speculative || []).map(item => item.symbol).slice(0, 6)
    } : null,
    news: news ? {
      status: news.status || null,
      headline: news.headline || null,
      reaction: news.reaction || null,
      direction: news.direction || null
    } : null,
    math: math ? {
      schema: math.schema || null,
      volatility: Number.isFinite(Number(math.realizedWindowPct)) ? Number(math.realizedWindowPct) : null,
      drawdown: Number.isFinite(Number(math.drawdown?.pct)) ? Number(math.drawdown.pct) : null,
      var95: Number.isFinite(Number(math.var95StepPct)) ? Number(math.var95StepPct) : null
    } : null
  };
}

function atlasHistoryV2RememberCurrent(snapshot) {
  const compact = atlasHistoryV2CompactSnapshot(snapshot);
  if (!compact) return null;

  const history = atlasHistoryV2Read()
    .filter(entry => entry?.fingerprint && entry.fingerprint !== compact.fingerprint);

  history.push(compact);
  atlasHistoryV2Write(history);
  return compact;
}

function atlasHistoryV2Previous(currentFingerprint = "") {
  const history = atlasHistoryV2Read();
  if (!history.length) return null;
  const filtered = currentFingerprint
    ? history.filter(entry => entry?.fingerprint !== currentFingerprint)
    : history;
  return filtered.length ? filtered[filtered.length - 1] : null;
}

function atlasHistoryV2Compare(currentSnapshot) {
  const current = atlasHistoryV2CompactSnapshot(currentSnapshot);
  if (!current) {
    return {
      schema: "atlas_snapshot_compare_v2",
      status: "missing-current",
      summary: "INFORMATION MANQUANTE"
    };
  }

  const previous = atlasHistoryV2Previous(current.fingerprint);
  if (!previous) {
    return {
      schema: "atlas_snapshot_compare_v2",
      status: "no-previous",
      current_fingerprint: current.fingerprint,
      previous_fingerprint: null,
      summary: "Premier snapshot historique disponible : aucune comparaison antérieure."
    };
  }

  const prevBySymbol = Object.fromEntries(
    (previous.top5 || []).map(item => [String(item.symbol || "").toUpperCase(), item])
  );

  const assetMoves = (current.top5 || []).map(item => {
    const prev = prevBySymbol[item.symbol];
    const priceDeltaPct =
      prev?.price > 0 && item.price !== null
        ? ((item.price - prev.price) / prev.price) * 100
        : null;
    return {
      symbol: item.symbol,
      previous_price: prev?.price ?? null,
      current_price: item.price,
      price_delta_pct: Number.isFinite(priceDeltaPct) ? priceDeltaPct : null,
      current_change_24h: item.change24h
    };
  });

  const notable = assetMoves
    .filter(item => item.price_delta_pct !== null)
    .sort((a, b) => Math.abs(b.price_delta_pct) - Math.abs(a.price_delta_pct));

  return {
    schema: "atlas_snapshot_compare_v2",
    status: "compared",
    current_fingerprint: current.fingerprint,
    previous_fingerprint: previous.fingerprint,
    current_generated_at: current.generated_at,
    previous_generated_at: previous.generated_at,
    market_count_delta:
      current.market_count !== null && previous.market_count !== null
        ? current.market_count - previous.market_count
        : null,
    asset_moves: assetMoves,
    biggest_change: notable[0] || null,
    news_changed:
      String(current.news?.headline || "") !== String(previous.news?.headline || ""),
    current_news: current.news,
    previous_news: previous.news,
    current_watchlist: current.watchlist,
    previous_watchlist: previous.watchlist,
    summary: notable.length
      ? `Plus grand changement entre snapshots : ${notable[0].symbol} ${notable[0].price_delta_pct >= 0 ? "+" : ""}${notable[0].price_delta_pct.toFixed(2)} %.`
      : "Comparaison disponible, variations de prix insuffisantes pour un classement."
  };
}

function atlasHistoryV2CompareLine(compare) {
  if (!compare || compare.status === "missing-current") return "Historique : INFORMATION MANQUANTE.";
  if (compare.status === "no-previous") return `Historique : ${compare.summary}`;
  const moves = (compare.asset_moves || [])
    .filter(item => item.price_delta_pct !== null)
    .slice()
    .sort((a, b) => Math.abs(b.price_delta_pct) - Math.abs(a.price_delta_pct))
    .slice(0, 5)
    .map(item => `${item.symbol} ${item.price_delta_pct >= 0 ? "+" : ""}${item.price_delta_pct.toFixed(2)} %`)
    .join(" · ");
  return `Depuis le snapshot précédent : ${moves || "variations insuffisantes"} · ${compare.news_changed ? "News principale différente" : "News principale inchangée"}.`;
}

const ATLAS_CURRENT_STATE_SCHEMA = "atlas_crypto_current_state_v1";
const ATLAS_CURRENT_STATE_KEY = "agent_crypto_current_state_v1";

function atlasCurrentStateRead() {
  try {
    const raw = localStorage.getItem(ATLAS_CURRENT_STATE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch (_) {
    return null;
  }
}

function atlasCurrentStateWrite(state) {
  try {
    localStorage.setItem(ATLAS_CURRENT_STATE_KEY, JSON.stringify(state));
  } catch (_) {}
  return state;
}

function atlasCurrentFingerprint(snapshot) {
  return String(snapshot?.fingerprint || atlasAnalyticalTruthState?.currentFingerprint || "").trim();
}

function atlasCurrentReportFingerprint(report) {
  return String(report?.fingerprint || report?.snapshot_fingerprint || report?.meta?.fingerprint || "").trim();
}

function atlasCurrentConclusionFingerprint(conclusion) {
  return String(conclusion?.fingerprint || conclusion?.snapshot_fingerprint || conclusion?.meta?.fingerprint || "").trim();
}

function atlasCurrentQualification(snapshot) {
  const fp = atlasCurrentFingerprint(snapshot);
  const binance = snapshot?.strict_contract?.sources?.binance || {};
  const directCount = Number(binance.direct_pairs || 0);
  const derivedCount = Number(binance.derived_pairs || 0);
  const expectedCount = 5;
  const feedReady = String(binance.feed_status || "").toLowerCase() === "ready";
  const stableReady = binance.stable_5_5_ready === true;

  return {
    fingerprint: fp,
    expected_count: expectedCount,
    price_count: Math.min(expectedCount, Math.max(0, directCount + derivedCount)),
    direct_count: directCount,
    derived_count: derivedCount,
    stable_ready: stableReady,
    qualified: !!fp
      && feedReady
      && directCount === expectedCount
      && derivedCount === 0
      && stableReady
  };
}

function atlasCurrentStage(snapshot, status, reason = "", extra = {}) {
  const q = atlasCurrentQualification(snapshot);
  const previous = atlasCurrentStateRead() || {};
  const state = {
    schema: ATLAS_CURRENT_STATE_SCHEMA,
    status,
    fingerprint: q.fingerprint || previous.fingerprint || null,
    previous_current_fingerprint:
      previous.status === "CURRENT" ? previous.fingerprint : (previous.previous_current_fingerprint || null),
    generated_at: snapshot?.generated_at || previous.generated_at || new Date().toISOString(),
    updated_at: new Date().toISOString(),
    price_count: q.price_count,
    direct_count: q.direct_count,
    derived_count: q.derived_count,
    expected_count: q.expected_count,
    reason,
    ...extra
  };
  atlasCurrentStateWrite(state);
  atlasCurrentRenderBanner(state);
  return state;
}

function atlasCurrentMarkPending(snapshot, reason = "snapshot_changed") {
  const q = atlasCurrentQualification(snapshot);
  const prev = atlasCurrentStateRead();
  const state = {
    schema: ATLAS_CURRENT_STATE_SCHEMA,
    status: q.qualified ? "PENDING_ANALYSIS" : "WAITING_5_5_DIRECT",
    fingerprint: q.fingerprint || null,
    previous_current_fingerprint: prev?.status === "CURRENT" ? prev.fingerprint : (prev?.previous_current_fingerprint || null),
    generated_at: snapshot?.generated_at || new Date().toISOString(),
    reason,
    price_count: q.price_count,
    direct_count: q.direct_count,
    derived_count: q.derived_count,
    expected_count: q.expected_count
  };
  atlasCurrentStateWrite(state);
  atlasCurrentRenderBanner(state);
  return state;
}

function atlasCurrentPromoteIfComplete(snapshot, reports, conclusion) {
  const q = atlasCurrentQualification(snapshot);
  if (!q.qualified) return atlasCurrentMarkPending(snapshot, "waiting_5_5_direct");

  const list = ATLAS_LOCAL_REPORT_MODES
    .map(mode => reports?.[mode])
    .filter(Boolean);
  const reportFps = list.map(atlasCurrentReportFingerprint).filter(Boolean);
  const fourReports = list.length === ATLAS_LOCAL_REPORT_MODES.length;
  const reportsMatch = fourReports
    && reportFps.length === ATLAS_LOCAL_REPORT_MODES.length
    && reportFps.every(fp => fp === q.fingerprint);

  const conclusionFp = atlasCurrentConclusionFingerprint(conclusion);
  const conclusionOk = !!conclusion?.answer && conclusionFp === q.fingerprint;

  if (!reportsMatch || !conclusionOk) {
    return atlasCurrentMarkPending(snapshot, !reportsMatch ? "atlas_reports_not_current" : "aerith_conclusion_not_current");
  }

  const state = {
    schema: ATLAS_CURRENT_STATE_SCHEMA,
    status: "CURRENT",
    fingerprint: q.fingerprint,
    generated_at: snapshot?.generated_at || new Date().toISOString(),
    promoted_at: new Date().toISOString(),
    price_count: q.price_count,
    direct_count: q.direct_count,
    derived_count: q.derived_count,
    expected_count: q.expected_count,
    atlas_reports: 4,
    aerith_conclusion: true,
    model: "gpt-oss:20b-32k"
  };
  atlasCurrentStateWrite(state);
  atlasCurrentRenderBanner(state);
  return state;
}


function atlasCurrentClosedAnalysisFingerprint() {
  if (!atlasLocalReportsState?.automaticCycleClosed) return "";
  return String(atlasLocalReportsState.automaticCycleFingerprint || "").trim();
}

function atlasCurrentPreserveClosedAnalysis(snapshot, previous, reason = "live-market-advanced") {
  const closedFp = atlasCurrentClosedAnalysisFingerprint();
  if (!closedFp || !previous || previous.status !== "CURRENT" || previous.fingerprint !== closedFp) return null;
  const q = atlasCurrentQualification(snapshot);
  const preserved = {
    ...previous,
    status: "CURRENT",
    fingerprint: closedFp,
    updated_at: new Date().toISOString(),
    live_fingerprint: q.fingerprint || null,
    live_generated_at: snapshot?.generated_at || new Date().toISOString(),
    live_changed_since_current: !!q.fingerprint && q.fingerprint !== closedFp,
    reason
  };
  atlasCurrentStateWrite(preserved);
  atlasCurrentRenderBanner(preserved);
  return preserved;
}

function atlasCurrentSyncFromLiveGate(reason = "live-gate") {
  try {
    const snapshot = atlasBuildCryptoPageSnapshot();
    if (!snapshot?.fingerprint) return null;

    const q = atlasCurrentQualification(snapshot);
    const readiness = atlasLocalReportsReadiness(snapshot);
    const previous = atlasCurrentStateRead();
    const preservedClosed = atlasCurrentPreserveClosedAnalysis(snapshot, previous, reason);
    if (preservedClosed) return preservedClosed;

    let status = previous?.status || "WAITING_5_5_DIRECT";
    const sameFingerprint = !!(
      previous?.fingerprint
      && q.fingerprint
      && previous.fingerprint === q.fingerprint
    );
    const preserveSameSnapshotState = new Set([
      "CURRENT",
      "ERROR",
      "ATLAS_4_4_READY",
      "NOX_READY",
      "AERITH_RUNNING"
    ]);

    if (atlasLocalReportsState.running) status = "ATLAS_RUNNING";
    else if (atlasLocalConclusionState.running) status = "AERITH_RUNNING";
    else if (sameFingerprint && preserveSameSnapshotState.has(String(previous?.status || ""))) {
      status = previous.status;
    }
    else if (q.qualified && readiness.ready) status = "PENDING_ANALYSIS";
    else if (q.direct_count === 5 && q.derived_count === 0 && !q.stable_ready) status = "WAITING_STABLE_5_5";
    else if (q.direct_count === 5 && q.derived_count === 0) status = "WAITING_PREREQUISITES";
    else status = "WAITING_5_5_DIRECT";

    return atlasCurrentStage(snapshot, status, reason, {
      readiness_label: atlasLocalReportsReadinessLabel(readiness),
      bridge_ready: readiness.bridgeReady,
      market_ready: readiness.marketReady,
      graph_ready: readiness.graphReady,
      binance_ready: readiness.binanceReady,
      stable_age_ms: readiness.stableAgeMs
    });
  } catch (_) {
    return null;
  }
}

function atlasCurrentRenderBanner(state = atlasCurrentStateRead()) {
  if (!state) return;
  const host = document.getElementById("atlasCurrentAnalysisBannerMount");
  if (!host) return;
  let banner = document.getElementById("atlasCurrentAnalysisBanner");
  if (!banner) {
    banner = document.createElement("div");
    banner.id = "atlasCurrentAnalysisBanner";
    banner.style.cssText = "margin:10px 0;padding:10px 14px;border:1px solid rgba(120,220,255,.32);border-radius:12px;background:rgba(4,20,31,.88);font-size:.92rem;line-height:1.35";
    host.appendChild(banner);
  }

  const status = String(state.status || "");
  const localComputeOff = !atlasDeviceComputeAllowed();
  if (localComputeOff && status !== "CURRENT") {
    banner.innerHTML = `<b>Lecture seule sur ce poste</b> · STOP calcul Atlas/Aerith/Ollama · marché live et historique restent disponibles.`;
    banner.style.borderColor = "rgba(255,185,72,.62)";
  } else if (status === "CURRENT") {
    const liveNote = state.live_changed_since_current
      ? " · marché live plus récent disponible, analyse CURRENT conservée jusqu’à une nouvelle relance opérateur"
      : " · snapshot analysé figé";
    banner.innerHTML = `<b>Analyse CURRENT</b> · Atlas 4/4 + NØX + Aerith cohérents · ${String(state.fingerprint || "").slice(0,18)}…${liveNote}${localComputeOff ? " · ce poste est en lecture seule" : ""}`;
    banner.style.borderColor = "rgba(76,220,160,.55)";
  } else if (status === "ATLAS_RUNNING") {
    banner.innerHTML = `<b>Analyse automatique</b> · Atlas ${Number(state.completed || 0)}/4 · snapshot figé ${String(state.fingerprint || "").slice(0,18)}… · supervision Bridge + chaîne active en arrière-plan`;
    banner.style.borderColor = "rgba(82,190,255,.55)";
  } else if (status === "ATLAS_4_4_READY" || status === "NOX_READY") {
    banner.innerHTML = `<b>Atlas 4/4 prêt</b> · NØX vérifié · Aerith prépare la synthèse courante.`;
    banner.style.borderColor = "rgba(172,116,255,.55)";
  } else if (status === "AERITH_RUNNING") {
    banner.innerHTML = `<b>Aerith analyse toute la page</b> · ancienne conclusion conservée uniquement comme historique.`;
    banner.style.borderColor = "rgba(222,116,255,.55)";
  } else if (status === "ERROR") {
    banner.innerHTML = `<b>Analyse courante non remplacée</b> · ${atlasLocalEscapeHtml(state.reason || "erreur locale")} · ancien résultat conservé comme historique.`;
    banner.style.borderColor = "rgba(255,110,110,.65)";
  } else if (status === "PENDING_ANALYSIS") {
    banner.innerHTML = `<b>Snapshot qualifié · analyse autorisée</b> · prix ${Number(state.price_count || 0)}/${Number(state.expected_count || 5)} · Binance directes ${Number(state.direct_count || 0)}/${Number(state.expected_count || 5)} · dérivées ${Number(state.derived_count || 0)} · lancement Atlas automatique · ${String(state.fingerprint || "").slice(0,18)}…`;
    banner.style.borderColor = "rgba(76,220,160,.72)";
  } else if (status === "WAITING_STABLE_5_5") {
    const age = Math.min(
      ATLAS_DIRECT_5_5_STABLE_MS / 1000,
      Math.floor(Number(state.stable_age_ms || 0) / 1000)
    );
    banner.innerHTML = `<b>5/5 Binance directes détectées</b> · dérivées 0 · confirmation de stabilité ${age}/${ATLAS_DIRECT_5_5_STABLE_MS / 1000}s avant Atlas.`;
    banner.style.borderColor = "rgba(255,198,84,.55)";
  } else if (status === "WAITING_PREREQUISITES") {
    banner.innerHTML = `<b>5/5 Binance directes validées</b> · Atlas attend encore un prérequis · ${atlasLocalEscapeHtml(state.readiness_label || "vérification en cours")}`;
    banner.style.borderColor = "rgba(255,198,84,.55)";
  } else {
    banner.innerHTML = `<b>Analyse en attente</b> · prix disponibles ${Number(state.price_count || 0)}/${Number(state.expected_count || 5)} · Binance directes ${Number(state.direct_count || 0)}/${Number(state.expected_count || 5)} · dérivées ${Number(state.derived_count || 0)}.`;
    banner.style.borderColor = "rgba(255,198,84,.55)";
  }
  const productiveStatus = new Set(["PENDING_ANALYSIS", "ATLAS_RUNNING", "ATLAS_4_4_READY", "NOX_READY", "AERITH_RUNNING", "CURRENT"]);
  if (!localComputeOff && productiveStatus.has(status)) {
    banner.dataset.tone = status === "CURRENT" ? "ready" : "active";
    banner.style.borderColor = status === "CURRENT" ? "rgba(79,235,170,.82)" : "rgba(82,225,166,.72)";
    banner.style.background = status === "CURRENT" ? "rgba(4,39,34,.92)" : "rgba(4,31,31,.92)";
    banner.style.boxShadow = "0 0 0 1px rgba(80,235,175,.06) inset, 0 0 22px rgba(58,220,165,.07)";
  } else if (status === "ERROR") {
    banner.dataset.tone = "error";
    banner.style.background = "rgba(42,15,21,.9)";
    banner.style.boxShadow = "none";
  } else {
    banner.dataset.tone = localComputeOff ? "observer" : "waiting";
    banner.style.background = "rgba(4,20,31,.88)";
    banner.style.boxShadow = "none";
  }
  atlasRenderSnapshotLiveTruth(state);
}


function atlasRenderSnapshotLiveTruth(current = atlasCurrentStateRead()) {
  const root = document.getElementById("atlasFrameTruth");
  if (!root) return null;
  const snapshotNode = document.getElementById("atlasFrameTruthSnapshot");
  const snapshotDetail = document.getElementById("atlasFrameTruthSnapshotDetail");
  const liveNode = document.getElementById("atlasFrameTruthLive");
  const liveDetail = document.getElementById("atlasFrameTruthLiveDetail");
  const badge = document.getElementById("atlasFrameTruthBadge");
  const status = document.getElementById("atlasFrameTruthStatus");

  const feed = state.dataBroker?.exchangeFeed || {};
  const liveDirect = Math.max(0, Number(feed.directCount || 0));
  const liveDerived = Math.max(0, Number(feed.derivedCount || 0));
  const liveTime = atlasStrictTimestamp(feed.lastMessageAt || state.timestamp);
  const isCurrent = String(current?.status || "") === "CURRENT" && !!current?.fingerprint;

  if (snapshotNode) snapshotNode.textContent = isCurrent
    ? `CURRENT · Binance ${Number(current.direct_count || 0)}/5 directes · ${Number(current.derived_count || 0)} dérivée(s)`
    : "Aucun CURRENT validé";
  if (snapshotDetail) snapshotDetail.textContent = isCurrent
    ? `${String(current.fingerprint || "").slice(0, 22)}… · ${current.generated_at ? new Date(current.generated_at).toLocaleString("fr-FR") : "heure inconnue"}`
    : "Atlas figera ici les cinq cotations directes utilisées pour la prochaine analyse.";

  if (liveNode) liveNode.textContent = `LIVE · Binance ${liveDirect}/5 directes · ${liveDerived} secours`;
  if (liveDetail) liveDetail.textContent = `${liveTime ? new Date(liveTime).toLocaleString("fr-FR") : "heure inconnue"} · prix live indépendants du CURRENT analytique`;

  const changed = isCurrent && (current.live_changed_since_current === true || (current.live_fingerprint && current.live_fingerprint !== current.fingerprint));
  root.dataset.state = isCurrent ? (changed ? "advanced" : "current") : "waiting";
  if (badge) {
    badge.textContent = isCurrent ? (changed ? "LIVE plus récent" : "Même fenêtre") : "En attente";
    badge.className = `pill ${isCurrent ? "ok" : "warn"}`;
  }
  if (status) status.textContent = isCurrent
    ? (changed
      ? "Le marché live a avancé. Le CURRENT reste volontairement attaché à son snapshot jusqu’à une nouvelle relance opérateur."
      : "Snapshot analysé et marché live encore alignés. Le CURRENT reste figé après la fin du cycle.")
    : "Aucun CURRENT à comparer. Les prix live peuvent être affichés sans déclencher une conclusion.";
  return { isCurrent, liveDirect, liveDerived, changed };
}

function atlasCurrentConclusionIsStale(conclusion, snapshot) {
  const frozenFp = atlasCurrentClosedAnalysisFingerprint();
  const currentFp = frozenFp || atlasCurrentFingerprint(snapshot);
  const conclusionFp = atlasCurrentConclusionFingerprint(conclusion);
  return !!currentFp && !!conclusionFp && currentFp !== conclusionFp;
}

function atlasCurrentDecorateConclusion(snapshot, conclusion) {
  const panel = document.querySelector(".atlas-local-response-panel");
  if (!panel) return;

  const stale = atlasCurrentConclusionIsStale(conclusion, snapshot);
  panel.dataset.currentState = stale ? "historical" : "current";
  panel.style.opacity = "";

  const oldMarker = panel.querySelector(".atlas-current-marker");
  if (oldMarker) oldMarker.remove();

  const title = document.getElementById("atlasLocalResponseTitle");
  const meta = document.getElementById("atlasLocalResponseMeta");

  if (title) {
    title.dataset.currentState = stale ? "historical" : "current";
    title.style.color = stale ? "#f1d69a" : "";
  }

  if (meta) {
    meta.dataset.currentState = stale ? "historical" : "current";
  }
}

function atlasCurrentOnSnapshot(snapshot) {
  const q = atlasCurrentQualification(snapshot);
  const state = atlasCurrentStateRead();
  if (!q.fingerprint) return;

  const preservedClosed = atlasCurrentPreserveClosedAnalysis(snapshot, state, "live-market-advanced");
  if (preservedClosed) {
    atlasSharedSynthesisReconcileCurrent();
    atlasCurrentDecorateConclusion(snapshot, atlasLocalDialogueState?.conclusionResponse || null);
    return;
  }

  atlasSharedSynthesisReconcileCurrent();

  if (state?.status === "CURRENT" && state.fingerprint && state.fingerprint !== q.fingerprint) {
    atlasCurrentStage(snapshot, q.qualified ? "PENDING_ANALYSIS" : "WAITING_5_5_DIRECT", "persisted_current_demoted", {
      previous_current_fingerprint: state.fingerprint,
      previous_current_preserved: true
    });
  } else if (!state || state.fingerprint !== q.fingerprint || state.status !== "CURRENT") {
    atlasCurrentMarkPending(snapshot, "new_qualified_snapshot");
  }

  atlasCurrentDecorateConclusion(snapshot, atlasLocalDialogueState?.conclusionResponse || null);
}



const ATLAS_V2_MODE_KEY = "agent_crypto_erith_ia_v2_interface_mode";

const ATLAS_V2_ALLOWED_MODES = new Set(["essential", "intermediate", "advanced"]);

const ATLAS_ACCESS_RETURN_MODE_KEY = "agent_crypto_erith_ia_access_return_mode";

function atlasV2ManifestEntry(idOrHash) {
  const id = decodeURIComponent(String(idOrHash || "").replace(/^#/, ""));
  return ATLAS_V2_MANIFEST_BY_ID.get(id) || null;
}

function atlasV2ClassifySections() {
  document.querySelectorAll(".v2-managed-section").forEach(element => {
    element.classList.remove("v2-managed-section", "v2-advanced-section");
    delete element.dataset.v2Section;
    delete element.dataset.v2Group;
    delete element.dataset.v2Level;
  });

  for (const entry of ATLAS_V2_SECTION_MANIFEST) {
    const target = atlasV2ManifestTarget(entry);
    if (!target) continue;

    target.classList.add("v2-managed-section");
    target.dataset.v2Level = entry.level;
    target.dataset.v2Group = entry.group;

    if (!["essential", "adaptive"].includes(entry.level)) {
      target.classList.add("v2-advanced-section");
      target.dataset.v2Section = "advanced";
    }

    if (entry.level === "project") target.dataset.v2Accent = "project";
    if (entry.level === "diagnostic") target.dataset.v2Accent = "diagnostic";
  }
}

function atlasV2IsExpandedMode(mode = atlasV2Mode()) {
  return mode === "intermediate" || mode === "advanced";
}

function atlasV2IntermediateAllowsEntry(entry) {
  return !!entry && !ATLAS_V2_INTERMEDIATE_HIDDEN_IDS.has(entry.id);
}

function atlasV2EntryVisibleInMode(entry, mode) {
  if (!entry) return false;
  if (entry.level === "adaptive" || entry.level === "essential") return true;
  if (mode === "advanced") return true;
  if (mode === "intermediate") return atlasV2IntermediateAllowsEntry(entry);
  return false;
}

function atlasV2ApplySectionVisibility(mode) {
  const expanded = atlasV2IsExpandedMode(mode);
  const resolved = new Map();

  for (const entry of ATLAS_V2_SECTION_MANIFEST) {
    const target = atlasV2ManifestTarget(entry);
    if (!target || entry.level === "adaptive") continue;

    const visible = atlasV2EntryVisibleInMode(entry, mode);
    const previous = resolved.get(target);
    resolved.set(target, previous === true ? true : visible);
  }

  for (const [target, visible] of resolved) {
    target.hidden = !visible;
    target.setAttribute("aria-hidden", visible ? "false" : "true");
  }

  const risk = document.getElementById("risques");
  if (risk) {
    risk.hidden = !expanded;
    risk.setAttribute("aria-hidden", expanded ? "false" : "true");
  }

  const newsRegistry = document.getElementById("newsSourceRegistry");
  if (newsRegistry) {
    newsRegistry.hidden = !expanded;
    newsRegistry.setAttribute("aria-hidden", expanded ? "false" : "true");
  }
}

function atlasV2SyncMixedSectionLabels(mode) {
  const advanced = atlasV2IsExpandedMode(mode);
  setText(
    document.getElementById("watchRiskCollapseTitle"),
    advanced ? "Watchlist V3 + Risques V2" : "Watchlist V3"
  );
  setText(
    document.getElementById("watchRiskCollapseSubtitle"),
    advanced
      ? "Actifs suivis, conditions et validation croisée"
      : "Actifs suivis et conditions locales"
  );
}

function atlasV2ModuleGroupLabel(group) {
  return {
    analysis: "Analyse V2",
    decision: "Décision et veille",
    memory: "Mémoire",
    workshop: "Atelier",
    system: "Système",
    projects: "Projets @erith.IA"
  }[group] || "Module V2";
}

function atlasV2ReadSetting(key, fallback) {
  try {
    return localStorage.getItem(key) || fallback;
  } catch {
    return fallback;
  }
}

function atlasV2WriteSetting(key, value) {
  try {
    localStorage.setItem(key, value);
  } catch {}
}

function atlasV2ModeFromUrl() {
  try {
    const value = new URL(window.location.href).searchParams.get("view");
    return value === ATLAS_V2_INTERMEDIATE_QUERY_VALUE ? "intermediate" : "";
  } catch {
    return "";
  }
}

function atlasV2SyncShareableUrl(mode, options = {}) {
  try {
    const url = new URL(window.location.href);
    if (mode === "intermediate") url.searchParams.set("view", ATLAS_V2_INTERMEDIATE_QUERY_VALUE);
    else url.searchParams.delete("view");
    const next = `${url.pathname}${url.search}${url.hash}`;
    if (options.push === true) history.pushState(null, "", next);
    else history.replaceState(null, "", next);
  } catch {}
}

function atlasV2Mode() {
  const urlMode = atlasV2ModeFromUrl();
  if (urlMode) return urlMode;
  const stored = atlasV2ReadSetting(ATLAS_V2_MODE_KEY, "essential");
  const mode = ATLAS_V2_ALLOWED_MODES.has(stored) ? stored : "essential";
  return mode === "advanced" && !atlasAccessIsAuthorized() ? "essential" : mode;
}

function atlasV2ApplyMode(mode, options = {}) {
  const requested = ATLAS_V2_ALLOWED_MODES.has(mode) ? mode : "essential";
  if (requested === "advanced" && !atlasAccessIsAuthorized()) {
    if (!options.silentAuth) atlasAccessOpen(options.pendingHash || "");
    mode = "essential";
  }
  const next = ATLAS_V2_ALLOWED_MODES.has(mode) ? mode : "essential";
  const visualMode = next === "intermediate" ? "advanced" : next;
  const administrator = next === "advanced" && atlasAccessIsAuthorized();
  const operator = next === "intermediate";
  const expanded = administrator || operator;

  document.documentElement.dataset.atlasMode = visualMode;
  document.body.dataset.atlasMode = visualMode;
  document.documentElement.dataset.atlasView = next;
  document.body.dataset.atlasView = next;

  document.querySelectorAll("[data-atlas-view-mode]").forEach(button => {
    const active = button.dataset.atlasViewMode === next;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });

  const title = document.getElementById("atlasV2ModeTitle");
  const description = document.getElementById("atlasV2ModeDescription");

  const role = administrator ? "administrator" : operator ? "operator" : "public";
  document.documentElement.dataset.atlasRole = role;
  document.body.dataset.atlasRole = role;

  if (title) title.textContent = administrator ? "Privé Christophe" : operator ? "Vue intermédiaire" : "Marché public";
  if (description) description.textContent = administrator
    ? "Administration locale · Atlas · Aerith · analyse · mémoire · décision · système · projets."
    : operator
      ? "Analyse · décision · mémoire · opérations · système · audience · sources. Missions de vie masquées."
      : "Graphique · Target Top 5 · Market Flow · Market Snapshot · Sources.";

  const accountToggle = document.getElementById("btnAdminAccountToggle");
  const accountText = document.getElementById("adminAccountLinkText");
  if (accountToggle) {
    accountToggle.classList.toggle("is-admin", administrator);
    accountToggle.setAttribute("aria-pressed", administrator ? "true" : "false");
    accountToggle.setAttribute("aria-label", administrator
      ? "Verrouiller l’administration locale"
      : atlasAccessIsAuthorized()
        ? "Revenir à l’administration Christophe"
        : "Ouvrir l’accès privé local");
  }
  if (accountText) accountText.textContent = "Administration";

  const basicToggle = document.getElementById("btnBasicViewToggle");
  const intermediateToggle = document.getElementById("btnIntermediateViewToggle");
  if (basicToggle) basicToggle.setAttribute("aria-label", "Ouvrir la vue basique");
  if (intermediateToggle) intermediateToggle.setAttribute("aria-label", "Ouvrir la vue intermédiaire");

  atlasV2ApplySectionVisibility(next);
  atlasV2SyncMixedSectionLabels(next);

  const liveSourcesCollapse = document.getElementById("liveSourcesCollapse");
  if (liveSourcesCollapse) {
    liveSourcesCollapse.hidden = false;
    liveSourcesCollapse.setAttribute("aria-hidden", "false");
  }

  document.querySelectorAll(".atlas-v2-nav-advanced").forEach(element => {
    element.hidden = !expanded;
  });

  const commandKicker = document.getElementById("atlasCommandKicker");
  const commandTitle = document.getElementById("atlasCommandTitle");
  if (commandKicker) commandKicker.textContent = operator ? "INTERMÉDIAIRE" : "ADMIN";
  if (commandTitle) commandTitle.textContent = operator ? "Vue intermédiaire Agent-Crypto" : "Administration Agent-Crypto";

  const missionsQuickLink = document.getElementById("atlasMissionsQuickLink");
  if (missionsQuickLink) missionsQuickLink.hidden = operator;
  const privateMissionsGroup = document.getElementById("atlasPrivateMissionsOptionGroup");
  if (privateMissionsGroup) {
    privateMissionsGroup.hidden = operator;
    privateMissionsGroup.disabled = operator;
  }
  setText(document.getElementById("atlasProjectsClusterLabel"), operator ? "Création" : "Projets");
  setText(document.getElementById("atlasProjectsShortcutLabel"), operator ? "Création" : "Projets");
  setText(document.getElementById("atlasProjectsShortcutCount"), operator ? "1" : "2");

  const selector = document.getElementById("atlasV2AdvancedModuleSelect");
  if (operator && selector && ATLAS_V2_INTERMEDIATE_HIDDEN_IDS.has(selector.value)) selector.value = "";

  if (!expanded) {
    const legacy = document.querySelector("[data-collapse-key='mode-debutant-avance']");
    if (legacy) legacy.hidden = true;
    /* Public contract: Math Core V3 always remains visible beside Market.
       A previously stored top/rail admin position must never hide it. */
    atlasV2ApplyMathDock("side", { persist: false });
    const topDock = document.getElementById("mathTopDock");
    if (topDock) topDock.hidden = true;
    atlasSetCleanLensCollapsed(true, false);
    const marketPanel = document.getElementById("marketSnapshotPanel");
    if (marketPanel) marketPanel.dataset.marketColumns = "essential";
  } else {
    atlasV2ApplyMathDock(atlasV2MathDockPosition(), { persist: false });
    let detailCollapsed = true;
    try {
      const storedDetailState = localStorage.getItem(ATLAS_CLEAN_LENS_PANEL_KEY);
      detailCollapsed = storedDetailState === null ? true : storedDetailState === "1";
    } catch {}
    atlasSetCleanLensCollapsed(detailCollapsed, false);
    const marketPanel = document.getElementById("marketSnapshotPanel");
    if (marketPanel) marketPanel.dataset.marketColumns = state.chartViewV2?.marketColumns || "essential";
  }

  atlasChartV2SyncControls?.();
  if (typeof renderAtlasMathCore === "function") renderAtlasMathCore();

  if (options.persist !== false) atlasV2WriteSetting(ATLAS_V2_MODE_KEY, next);
  if (options.syncUrl === true) atlasV2SyncShareableUrl(next, { push: options.pushUrl === true });
  atlasScheduleStableChartResize();
  atlasScheduleRuntimeValidation("mode-apply");
  window.dispatchEvent(new CustomEvent("atlas:v2mode", { detail: { mode: next, role } }));
  return next !== "advanced" || administrator;
}

function atlasV2OpenSelectedModule() {
  const selector = document.getElementById("atlasV2AdvancedModuleSelect");
  const id = selector?.value || "";
  if (!id) return;
  atlasV2OpenAdvancedForTarget(`#${id}`);
}

function atlasV2SyncAdvancedSelectorFromViewport() {
  if (!atlasV2IsExpandedMode()) return;
  const selector = document.getElementById("atlasV2AdvancedModuleSelect");
  if (!selector) return;

  const probe = window.scrollY + Math.min(window.innerHeight * 0.3, 240);
  let current = "";

  for (const entry of ATLAS_V2_SECTION_MANIFEST) {
    if (["essential", "adaptive"].includes(entry.level)) continue;
    const target = document.getElementById(entry.id);
    if (!target || target.hidden) continue;
    if (target.offsetTop <= probe) current = entry.id;
  }

  if (current && [...selector.options].some(option => option.value === current)) {
    selector.value = current;
  }
}

function atlasInitV2Shell() {
  atlasV2ClassifySections();
  atlasInitLocalAccess();

  document.getElementById("btnAdminAccountToggle")?.addEventListener("click", () => {
    if (atlasAccessIsAuthorized() && atlasV2Mode() === "advanced") {
      atlasAccessLock();
    } else if (atlasAccessIsAuthorized()) {
      atlasV2SyncShareableUrl("advanced");
      atlasV2WriteSetting(ATLAS_V2_MODE_KEY, "advanced");
      atlasV2ApplyMode("advanced", { persist: false, silentAuth: true });
      window.setTimeout(() => atlasAdminOpenWorkspace({ source: "owner-return" }), 40);
    } else {
      atlasAccessOpen();
    }
  });

  document.getElementById("btnBasicViewToggle")?.addEventListener("click", () => {
    atlasV2WriteSetting(ATLAS_V2_MODE_KEY, "essential");
    atlasV2ApplyMode("essential", { persist: false, syncUrl: true });
    window.requestAnimationFrame(() => document.getElementById("accueil")?.scrollIntoView({ behavior: "smooth", block: "start" }));
  });

  document.getElementById("btnIntermediateViewToggle")?.addEventListener("click", () => {
    atlasV2WriteSetting(ATLAS_V2_MODE_KEY, "intermediate");
    atlasV2ApplyMode("intermediate", { persist: false, syncUrl: true });
    window.requestAnimationFrame(() => document.getElementById("accueil")?.scrollIntoView({ behavior: "smooth", block: "start" }));
  });

  document.querySelectorAll("[data-math-position]").forEach(button => {
    button.addEventListener("click", () => atlasV2ApplyMathDock(button.dataset.mathPosition));
  });

  document.querySelectorAll(".atlas-v2-nav-essential a").forEach(link => {
    link.addEventListener("click", () => {
      const hash = link.getAttribute("href");
      if (hash) atlasV2OpenAdvancedForTarget(hash, { updateHash: false, scroll: false });
    });
  });

  document.getElementById("btnOpenAdvancedModule")?.addEventListener("click", atlasV2OpenSelectedModule);
  document.addEventListener("click", event => {
    const link = event.target.closest('a[href^="#"]');
    if (!link) return;
    const hash = link.getAttribute("href");
    const entry = atlasV2ManifestEntry(hash);
    if (!entry || ["essential", "adaptive"].includes(entry.level)) return;
    event.preventDefault();
    atlasV2OpenAdvancedForTarget(hash);
  });

  window.addEventListener("hashchange", () => atlasV2HandleHashTarget({ scroll: true }));
  let selectorScheduled = false;
  const scheduleSelectorSync = () => {
    if (selectorScheduled) return;
    selectorScheduled = true;
    requestAnimationFrame(() => {
      selectorScheduled = false;
      atlasV2SyncAdvancedSelectorFromViewport();
    });
  };
  window.addEventListener("scroll", scheduleSelectorSync, { passive: true });
  window.addEventListener("resize", scheduleSelectorSync, { passive: true });

  const initialV2Mode = atlasV2Mode();
  if (initialV2Mode === "intermediate") atlasV2WriteSetting(ATLAS_V2_MODE_KEY, "intermediate");

  /* Math Core V3 est déclaré plus bas dans le fichier stable R18.
     L'application initiale du mode attend donc la fin de l'évaluation du script. */
  queueMicrotask(() => {
    atlasV2ApplyMode(initialV2Mode, { persist: false, silentAuth: true });
    atlasV2DecisionLockRefresh();
    if (location.hash) requestAnimationFrame(() => atlasV2HandleHashTarget({ scroll: false, instant: true }));
  });

  window.setInterval(() => { atlasV2SyncMathRail(); atlasV2DecisionLockRefresh(); }, 2000);
}

const ATLAS_RUNTIME_EXPECTED_CONTROLS = Object.freeze({
  view: 2,
  scale: 2,
  display: 2,
  period: 7,
  compare: 8
});

const ATLAS_RUNTIME_REQUIRED_IDS = Object.freeze([
  "atlasV2ModeTitle",
  "atlasV2ReleaseBadge",
  "btnAdminAccountToggle",
  "adminAccountLinkText",
  "livecheck",
  "analyste",
  "market-workspace",
  "marketSnapshotPanel",
  "marketWorkspaceGrid",
  "math",
  "atlasMathRailTrigger",
  "sources",
  "liveSourcesCollapse",
  "chart",
  "activeChartSummary"
]);

let atlasRuntimeValidationTimer = 0;

function atlasRuntimeControlCounts() {
  return {
    view: document.querySelectorAll("[data-chart-view]").length,
    scale: document.querySelectorAll("[data-chart-scale]").length,
    display: document.querySelectorAll("[data-chart-display]").length,
    period: document.querySelectorAll(".period-btn").length,
    compare: document.querySelectorAll(".compare-btn").length
  };
}

function atlasRuntimeViewportProfile(width = window.innerWidth) {
  const value = Number(width) || 0;
  if (value >= 1500) return "wide";
  if (value >= 1180) return "desktop";
  if (value >= 800) return "transformer";
  if (value >= 620) return "compact";
  return "mobile";
}

function atlasSyncResponsiveRuntime() {
  const root = document.documentElement;
  const profile = atlasRuntimeViewportProfile();
  const previous = root.dataset.atlasViewport || "";

  root.dataset.atlasViewport = profile;
  root.style.setProperty("--atlas-runtime-width", `${Math.max(0, window.innerWidth)}px`);
  root.style.setProperty("--atlas-runtime-height", `${Math.max(0, window.innerHeight)}px`);

  if (previous !== profile) {
    window.dispatchEvent(new CustomEvent("atlas:viewport", {
      detail: { previous, profile, width: window.innerWidth, height: window.innerHeight }
    }));
  }

  atlasScheduleStableChartResize();
}

function atlasRuntimeVisibilityLeaks() {
  if (atlasV2Mode() !== "essential") return [];

  return ATLAS_V2_SECTION_MANIFEST
    .filter(entry => !["essential", "adaptive"].includes(entry.level))
    .filter(entry => {
      const target = atlasV2ManifestTarget(entry);
      if (!target) return false;
      return target.hidden === false && getComputedStyle(target).display !== "none";
    })
    .map(entry => entry.id);
}

function atlasRuntimeValidate(reason = "manual") {
  const missingIds = ATLAS_RUNTIME_REQUIRED_IDS.filter(id => !document.getElementById(id));
  const controls = atlasRuntimeControlCounts();
  const controlErrors = Object.entries(ATLAS_RUNTIME_EXPECTED_CONTROLS)
    .filter(([key, expected]) => controls[key] !== expected)
    .map(([key, expected]) => ({ key, expected, actual: controls[key] }));

  const leaks = atlasRuntimeVisibilityLeaks();
  const sources = document.getElementById("liveSourcesCollapse");
  const sourceVisible = !!sources && sources.hidden === false && getComputedStyle(sources).display !== "none";
  const releaseVisible = document.getElementById("atlasV2ReleaseBadge")?.textContent?.includes(ATLAS_RELEASE) === true;

  const report = {
    release: ATLAS_RELEASE,
    checked_at: new Date().toISOString(),
    reason,
    mode: atlasV2Mode(),
    viewport: document.documentElement.dataset.atlasViewport || atlasRuntimeViewportProfile(),
    missing_ids: missingIds,
    control_counts: controls,
    control_errors: controlErrors,
    advanced_leaks_in_essential: leaks,
    live_sources_visible: sourceVisible,
    release_visible: releaseVisible,
    ok: !missingIds.length && !controlErrors.length && !leaks.length && sourceVisible && releaseVisible
  };

  window.__ATLAS_RUNTIME_REPORT__ = report;
  document.documentElement.dataset.atlasRuntime = report.ok ? "ok" : "degraded";

  if (!report.ok) {
    console.warn("Atlas runtime validation", report);
  }

  return report;
}

function atlasScheduleRuntimeValidation(reason = "scheduled") {
  if (atlasRuntimeValidationTimer) clearTimeout(atlasRuntimeValidationTimer);
  atlasRuntimeValidationTimer = window.setTimeout(() => {
    atlasRuntimeValidationTimer = 0;
    atlasRuntimeValidate(reason);
  }, 90);
}

function atlasRestoreRuntimeUi(reason = "restore") {
  atlasV2ClassifySections();
  atlasV2ApplyMode(atlasV2Mode(), { persist: false });
  atlasV2ApplyMathDock(
    atlasV2Mode() === "essential" ? "rail" : atlasV2MathDockPosition(),
    { persist: false }
  );
  atlasChartV2SyncControls?.();
  atlasSyncReleaseLabels();
  atlasSyncResponsiveRuntime();
  atlasScheduleRuntimeValidation(reason);
}

function atlasInitRuntimeStability() {
  atlasSyncResponsiveRuntime();

  let resizeQueued = false;
  const onResize = () => {
    if (resizeQueued) return;
    resizeQueued = true;
    requestAnimationFrame(() => {
      resizeQueued = false;
      atlasSyncResponsiveRuntime();
      atlasScheduleRuntimeValidation("resize");
    });
  };

  window.addEventListener("resize", onResize, { passive: true });
  window.addEventListener("orientationchange", onResize, { passive: true });

  window.addEventListener("pageshow", event => {
    requestAnimationFrame(() => {
      atlasRestoreRuntimeUi(event.persisted ? "pageshow-cache" : "pageshow");
    });
  });

  document.addEventListener("visibilitychange", () => {
    if (!document.hidden) atlasRestoreRuntimeUi("visibility-return");
  });

  window.addEventListener("atlas:v2mode", () => {
    atlasScheduleStableChartResize();
    atlasScheduleRuntimeValidation("mode-change");
  });

  window.addEventListener("atlas:viewport", () => {
    atlasScheduleRuntimeValidation("viewport-change");
  });

  requestAnimationFrame(() => {
    atlasScheduleRuntimeValidation("initial");
  });
}

