const ATLAS_MARKET_CARD_MODE_KEY = "agent_crypto_erith_ia_market_card_mode_v1";
const ATLAS_MARKET_CARD_DOCK_MIN_MARKET_WIDTH = 980;
const ATLAS_MARKET_CARD_DOCK_PANEL_MIN_WIDTH = 320;
let atlasMarketCardSelectedCoinId = "";

function atlasMarketCardPreferredMode() {
  try { return localStorage.getItem(ATLAS_MARKET_CARD_MODE_KEY) === "dock" ? "dock" : "floating"; }
  catch { return "floating"; }
}

function atlasMarketCardDockAvailability() {
  const grid = document.getElementById("marketWorkspaceGrid");
  if (!grid) return { available:false, reason:"Zone Marché indisponible" };
  if (grid.classList.contains("math-dock-side")) {
    return { available:false, reason:"Passe le Math Core sur Réduit ou Dessus pour libérer la colonne latérale." };
  }

  const gridRect = grid.getBoundingClientRect();
  const gridStyle = window.getComputedStyle(grid);
  const columnGap = Math.max(0, Number.parseFloat(gridStyle.columnGap) || 0);
  const math = document.getElementById("math");
  const railWidth = grid.classList.contains("math-dock-rail")
    ? Math.max(0, math?.getBoundingClientRect?.().width || 0)
    : 0;
  const columnCount = grid.classList.contains("math-dock-rail") ? 3 : 2;
  const requiredWidth = ATLAS_MARKET_CARD_DOCK_MIN_MARKET_WIDTH
    + ATLAS_MARKET_CARD_DOCK_PANEL_MIN_WIDTH
    + railWidth
    + columnGap * Math.max(1, columnCount - 1);
  const available = gridRect.width >= requiredWidth;

  return {
    available,
    gridWidth: gridRect.width,
    requiredWidth,
    reason: available
      ? "Ancrer la fiche à droite sans recouvrir le tableau"
      : "La fiche reste flottante tant que la zone Marché n’a pas assez de place pour conserver le tableau lisible."
  };
}

function atlasMarketCardDockAvailable() {
  return atlasMarketCardDockAvailability().available;
}

function atlasMarketCardEffectiveMode() {
  return atlasMarketCardPreferredMode() === "dock" && atlasMarketCardDockAvailable() ? "dock" : "floating";
}

function atlasMarketCardToolbarMarkup() {
  const effective = atlasMarketCardEffectiveMode();
  const dockState = atlasMarketCardDockAvailability();
  const dockAvailable = dockState.available;
  const dockTitle = dockState.reason;
  return `<div class="atlas-help-market-toolbar">
    <div class="atlas-help-kicker">FICHE CRYPTO · MARKET SNAPSHOT</div>
    <div class="atlas-help-market-mode" role="group" aria-label="Position de la fiche Crypto">
      <button type="button" data-market-card-mode="floating" class="${effective === "floating" ? "is-active" : ""}" aria-pressed="${effective === "floating"}">Flottante</button>
      <button type="button" data-market-card-mode="dock" class="${effective === "dock" ? "is-active" : ""}" aria-pressed="${effective === "dock"}"${dockAvailable ? "" : " disabled"} title="${escapeHtml(dockTitle)}">Latérale</button>
    </div>
  </div>`;
}

function atlasMarketCardRememberSelection(target, definition = null) {
  const coinId = String(definition?.marketCoinId || target?.dataset?.marketHelpId || "").trim();
  if (coinId) atlasMarketCardSelectedCoinId = coinId;
  return coinId;
}

function atlasMarketCardRememberedTarget() {
  if (!atlasMarketCardSelectedCoinId) return null;
  try {
    return document.querySelector(`[data-market-help-id="${CSS.escape(atlasMarketCardSelectedCoinId)}"]`);
  } catch {
    return null;
  }
}

function atlasMarketCardDockHost() {
  const grid = document.getElementById("marketWorkspaceGrid");
  if (!grid) return null;
  let host = document.getElementById("atlasMarketCardDockHost");
  if (!host) {
    host = document.createElement("aside");
    host.id = "atlasMarketCardDockHost";
    host.className = "atlas-market-card-dock-host";
    host.setAttribute("aria-label", "Fiche Crypto latérale");
    host.setAttribute("aria-live", "polite");
    host.hidden = true;
  }
  const math = document.getElementById("math");
  if (math?.parentElement === grid) grid.insertBefore(host, math);
  else if (host.parentElement !== grid) grid.appendChild(host);
  return host;
}

function atlasHideMarketCardDock(options = {}) {
  const host = document.getElementById("atlasMarketCardDockHost");
  const grid = document.getElementById("marketWorkspaceGrid");
  if (host) {
    host.hidden = true;
    host.innerHTML = "";
    delete host.dataset.marketHelpCoinId;
  }
  grid?.classList.remove("market-card-dock-active");
  if (options.clearSelection === true) atlasMarketCardSelectedCoinId = "";
}

function atlasRenderMarketCardDock(target, definition) {
  if (!target || !definition?.marketCoinId || !atlasMarketCardDockAvailable()) return false;
  const host = atlasMarketCardDockHost();
  const grid = document.getElementById("marketWorkspaceGrid");
  if (!host || !grid) return false;
  atlasMarketCardRememberSelection(target, definition);
  host.innerHTML = atlasHelpMarkup(definition);
  host.dataset.marketHelpCoinId = definition.marketCoinId;
  host.hidden = false;
  grid.classList.add("market-card-dock-active");
  const describedBy = new Set((target.getAttribute("aria-describedby") || "").split(/\s+/).filter(Boolean));
  describedBy.delete("atlasHelpLayer");
  describedBy.add("atlasMarketCardDockHost");
  target.setAttribute("aria-describedby", [...describedBy].join(" "));
  return true;
}

function atlasRefreshMarketCardSurface() {
  const activeTarget = atlasHelpActiveTarget?.matches?.("[data-market-help-id]") ? atlasHelpActiveTarget : null;
  const target = activeTarget || atlasMarketCardRememberedTarget();
  if (!target) {
    if (!atlasMarketCardDockAvailable()) atlasHideMarketCardDock();
    return;
  }
  const definition = atlasMarketHelpDefinition(target);
  if (!definition) return;
  if (atlasMarketCardEffectiveMode() === "dock") {
    const layer = document.getElementById("atlasHelpLayer");
    if (layer) {
      layer.hidden = true;
      layer.setAttribute("aria-hidden", "true");
      delete layer.dataset.marketHelpCoinId;
    }
    atlasRenderMarketCardDock(target, definition);
  } else {
    atlasHideMarketCardDock();
  }
}

function atlasSetMarketCardMode(mode) {
  const next = mode === "dock" ? "dock" : "floating";
  try { localStorage.setItem(ATLAS_MARKET_CARD_MODE_KEY, next); } catch {}
  const dockCoinId = document.getElementById("atlasMarketCardDockHost")?.dataset?.marketHelpCoinId || "";
  const activeMarketTarget = atlasHelpActiveTarget?.matches?.("[data-market-help-id]") ? atlasHelpActiveTarget : null;
  const pinnedTarget = dockCoinId ? document.querySelector(`[data-market-help-id="${CSS.escape(dockCoinId)}"]`) : null;
  const target = activeMarketTarget || pinnedTarget || atlasMarketCardRememberedTarget();
  atlasHideMarketCardDock();
  const layer = document.getElementById("atlasHelpLayer");
  if (layer) {
    layer.hidden = true;
    layer.setAttribute("aria-hidden", "true");
    delete layer.dataset.marketHelpCoinId;
  }
  if (target) atlasShowHelpLayer(target);
}

let atlasHelpHideTimer = null;

function atlasHelpMarkup(definition) {
  if (definition.rich) return definition.html;
  return `<div class="atlas-help-kicker">HELP LAYER V1</div><strong class="atlas-help-title">${escapeHtml(definition.title)}</strong><p>${escapeHtml(definition.body)}</p>${definition.example ? `<div class="atlas-help-example"><b>Exemple</b><span>${escapeHtml(definition.example.replace(/^Exemple\s*:\s*/i, ""))}</span></div>` : ""}${definition.rule ? `<div class="atlas-help-rule">${escapeHtml(definition.rule)}</div>` : ""}`;
}

function atlasPositionHelpLayer(layer, target, pointer = null) {
  layer.hidden = false;
  layer.style.visibility = "hidden";
  const measured = layer.getBoundingClientRect();
  const margin = 12;
  let left;
  let top;
  if (pointer && Number.isFinite(pointer.clientX) && Number.isFinite(pointer.clientY)) {
    left = pointer.clientX + 18;
    top = pointer.clientY + 18;
  } else {
    const rect = target.getBoundingClientRect();
    left = rect.right + margin;
    top = rect.top;
    if (left + measured.width > window.innerWidth - margin) left = rect.left - measured.width - margin;
  }
  left = clamp(margin, Math.max(margin, window.innerWidth - measured.width - margin), left);
  top = clamp(margin, Math.max(margin, window.innerHeight - measured.height - margin), top);
  layer.style.left = `${Math.round(left)}px`;
  layer.style.top = `${Math.round(top)}px`;
  layer.style.visibility = "visible";
}

function atlasShowHelpLayer(target, pointer = null) {
  window.clearTimeout(atlasHelpHideTimer);
  const layer = document.getElementById("atlasHelpLayer");
  const live = document.getElementById("atlasHelpLive");
  if (!layer || !target) return;
  const definition = target.matches?.("[data-market-help-id]") ? atlasMarketHelpDefinition(target) : atlasHelpDefinitionFor(target);
  if (!definition) return;
  if (definition.marketCoinId) atlasMarketCardRememberSelection(target, definition);
  if (atlasHelpActiveTarget && atlasHelpActiveTarget !== target) atlasRestoreHelpDescription(atlasHelpActiveTarget);
  atlasHelpActiveTarget = target;
  if (!("atlasHelpOriginalDescribedby" in target.dataset)) target.dataset.atlasHelpOriginalDescribedby = target.getAttribute("aria-describedby") || "";
  if (live) live.textContent = definition.liveText || `${definition.title}. ${definition.body}${definition.example ? ` ${definition.example}` : ""}`;

  if (definition.marketCoinId && atlasMarketCardEffectiveMode() === "dock") {
    layer.hidden = true;
    layer.setAttribute("aria-hidden", "true");
    delete layer.dataset.marketHelpCoinId;
    atlasRenderMarketCardDock(target, definition);
    return;
  }

  if (definition.marketCoinId) atlasHideMarketCardDock();
  layer.innerHTML = atlasHelpMarkup(definition);
  if (definition.marketCoinId) layer.dataset.marketHelpCoinId = definition.marketCoinId;
  else delete layer.dataset.marketHelpCoinId;
  layer.setAttribute("aria-hidden", "false");
  const describedBy = new Set((target.getAttribute("aria-describedby") || "").split(/\s+/).filter(Boolean));
  describedBy.delete("atlasMarketCardDockHost");
  describedBy.add("atlasHelpLayer");
  target.setAttribute("aria-describedby", [...describedBy].join(" "));
  atlasPositionHelpLayer(layer, target, pointer);
}

function atlasRestoreHelpDescription(target) {
  if (!target) return;
  const original = target.dataset.atlasHelpOriginalDescribedby;
  if (original) target.setAttribute("aria-describedby", original);
  else target.removeAttribute("aria-describedby");
  delete target.dataset.atlasHelpOriginalDescribedby;
}

function atlasHideHelpLayer(immediate = false) {
  const hide = () => {
    const layer = document.getElementById("atlasHelpLayer");
    if (layer) {
      layer.hidden = true;
      layer.setAttribute("aria-hidden", "true");
      delete layer.dataset.marketHelpCoinId;
    }
    if (atlasMarketCardEffectiveMode() === "dock"
      && !document.getElementById("atlasMarketCardDockHost")?.hidden
      && atlasHelpActiveTarget?.matches?.("[data-market-help-id]")) return;
    atlasRestoreHelpDescription(atlasHelpActiveTarget);
    atlasHelpActiveTarget = null;
  };
  window.clearTimeout(atlasHelpHideTimer);
  if (immediate) hide();
  else atlasHelpHideTimer = window.setTimeout(hide, 110);
}

function initAtlasHelpLayerV1() {
  const layer = document.getElementById("atlasHelpLayer");
  layer?.addEventListener("pointerenter", () => window.clearTimeout(atlasHelpHideTimer));
  layer?.addEventListener("pointerleave", () => atlasHideHelpLayer());

  document.addEventListener("pointerover", event => {
    const target = atlasHelpTargetFromNode(event.target);
    if (!target) return;
    if (atlasHelpActiveTarget === target && !(target.matches?.("[data-market-help-id]") && atlasMarketCardEffectiveMode() === "dock")) return;
    atlasShowHelpLayer(target, event);
  });
  document.addEventListener("pointerout", event => {
    const target = atlasHelpTargetFromNode(event.target);
    if (!target || target !== atlasHelpActiveTarget) return;
    if (target.matches?.("[data-market-help-id]") && atlasMarketCardEffectiveMode() === "dock") return;
    if (event.relatedTarget instanceof Node && target.contains(event.relatedTarget)) return;
    atlasHideHelpLayer();
  });
  document.addEventListener("focusin", event => {
    const target = atlasHelpTargetFromNode(event.target);
    if (target) atlasShowHelpLayer(target);
  });
  document.addEventListener("focusout", event => {
    const target = atlasHelpTargetFromNode(event.target);
    if (!target || target !== atlasHelpActiveTarget) return;
    if (target.matches?.("[data-market-help-id]") && atlasMarketCardEffectiveMode() === "dock") return;
    atlasHideHelpLayer();
  });
  document.addEventListener("click", event => {
    const button = event.target.closest?.("[data-market-card-mode]");
    if (!button || button.disabled) return;
    event.preventDefault();
    event.stopPropagation();
    atlasSetMarketCardMode(button.dataset.marketCardMode);
  });
  document.addEventListener("keydown", event => {
    if (event.key !== "Escape") return;
    atlasHideMarketCardDock({ clearSelection:true });
    atlasHideHelpLayer(true);
  });
  window.addEventListener("scroll", () => {
    if (atlasMarketCardEffectiveMode() !== "dock") atlasHideHelpLayer(true);
  }, { passive: true });
  window.addEventListener("resize", () => {
    atlasHideHelpLayer(true);
    atlasRefreshMarketCardSurface();
  }, { passive: true });
}

const ATLAS_ADMIN_CENTER_KEY = "atlas.admin.command.center.open.v1";

const ATLAS_ADMIN_MODULE_KEY = "atlas.admin.last.module.v1";

const ATLAS_ADMIN_CLUSTERS = Object.freeze(["decision", "analysis", "system", "projects"]);

function atlasAdminCenterSavedOpen() {
  try { return localStorage.getItem(ATLAS_ADMIN_CENTER_KEY) === "1"; }
  catch { return false; }
}

function atlasAdminLastModuleRead() {
  try { return localStorage.getItem(ATLAS_ADMIN_MODULE_KEY) || ""; }
  catch { return ""; }
}

function atlasAdminLastModuleWrite(id) {
  const value = String(id || "").replace(/^#/, "");
  if (!value || !document.getElementById(value)) return;
  try { localStorage.setItem(ATLAS_ADMIN_MODULE_KEY, value); } catch {}
}

function atlasAdminClusterForModule(id) {
  const value = String(id || "").replace(/^#/, "");
  if (["watchlist", "decision-board", "news-sentinel", "nofomo"].includes(value)) return "decision";
  if (["math", "multi-horizon", "lecture-froide", "risques", "debutant"].includes(value)) return "analysis";
  if (["auto-reader", "shared-memory", "github-memory", "safety", "simulation", "commandes", "newsSourceRegistry", "news-plan", "local-ai-hub"].includes(value)) return "system";
  if (["missions-vie", "forge-aerith"].includes(value)) return "projects";
  return "";
}

function atlasAdminCenterElements() {
  return {
    dock: document.querySelector(".atlas-admin-dock"),
    drawer: document.getElementById("atlasAdminCenterDrawer"),
    toggle: document.getElementById("atlasAdminCenterToggle"),
    state: document.getElementById("atlasAdminCenterToggleState"),
    close: document.getElementById("atlasAdminCenterClose")
  };
}

function atlasAdminCenterSet(open, options = {}) {
  const { drawer, toggle, state } = atlasAdminCenterElements();
  if (!drawer || !toggle) return;

  const next = !!open && atlasV2IsExpandedMode();
  const requestedTarget = String(options.target || "");
  const target = ATLAS_ADMIN_CLUSTERS.includes(requestedTarget)
    ? requestedTarget
    : next
      ? atlasAdminCenterSavedTarget()
      : "";

  drawer.hidden = !next;
  toggle.setAttribute("aria-expanded", next ? "true" : "false");
  if (state) state.textContent = next ? "Replier −" : "Déployer +";

  document.querySelectorAll("[data-admin-cluster-target]").forEach(button => {
    const selected = next && !!target && button.dataset.adminClusterTarget === target;
    button.setAttribute("aria-expanded", next ? "true" : "false");
    button.classList.toggle("is-selected", selected);
  });

  document.querySelectorAll("[data-admin-cluster]").forEach(cluster => {
    cluster.classList.toggle("is-targeted", next && !!target && cluster.dataset.adminCluster === target);
  });

  if (target) drawer.dataset.activeCluster = target;
  document.body.classList.toggle("atlas-admin-center-open", next);

  if (options.persist !== false) {
    try {
      localStorage.setItem(ATLAS_ADMIN_CENTER_KEY, next ? "1" : "0");
      if (target) localStorage.setItem(ATLAS_ADMIN_CENTER_TARGET_KEY, target);
    } catch {}
  }

  if (next && target && options.scrollTarget !== false) {
    const cluster = drawer.querySelector(`[data-admin-cluster="${target}"]`);
    if (cluster) {
      window.setTimeout(() => {
        cluster.scrollIntoView({
          block: "nearest",
          inline: "nearest",
          behavior: options.instant ? "auto" : "smooth"
        });
      }, 30);
    }
  }

  window.dispatchEvent(new CustomEvent("atlas:admin-center", {
    detail: { open: next, target: target || drawer.dataset.activeCluster || "" }
  }));
}

function initAtlasAdminCommandCenter() {
  const { drawer, toggle, close } = atlasAdminCenterElements();
  if (!drawer || !toggle) return;
  if (drawer.parentElement !== document.body) document.body.appendChild(drawer);

  const restoreCenter = () => {
    if (!atlasV2IsExpandedMode()) {
      atlasAdminCenterSet(false, { persist: false, scrollTarget: false });
      return;
    }
    const forcedOpen = atlasAdminForceWorkspaceIsActive();
    atlasAdminCenterSet(forcedOpen || atlasAdminCenterSavedOpen(), {
      persist: forcedOpen,
      target: forcedOpen
        ? (atlasAdminClusterForModule(atlasAdminLastModuleRead()) || atlasAdminCenterSavedTarget() || "analysis")
        : atlasAdminCenterSavedTarget(),
      scrollTarget: false,
      instant: true
    });
  };

  toggle.addEventListener("click", () => atlasAdminCenterSet(drawer.hidden));
  close?.addEventListener("click", () => atlasAdminCenterSet(false));

  document.querySelectorAll("[data-admin-cluster-target]").forEach(button => {
    button.addEventListener("click", () => {
      const target = button.dataset.adminClusterTarget || "";
      const alreadyOpen = !drawer.hidden;
      const alreadySelected = button.classList.contains("is-selected");
      if (alreadyOpen && alreadySelected) atlasAdminCenterSet(false);
      else atlasAdminCenterSet(true, { target });
    });
  });

  const selector = document.getElementById("atlasV2AdvancedModuleSelect");
  selector?.addEventListener("change", () => {
    if (selector.value) atlasAdminLastModuleWrite(selector.value);
  });

  drawer.addEventListener("click", event => {
    const link = event.target.closest("a[href^='#']");
    if (!link) return;
    const id = String(link.getAttribute("href") || "").replace(/^#/, "");
    if (id) atlasAdminLastModuleWrite(id);
    atlasAdminCenterSet(false);
  });

  document.addEventListener("pointerdown", event => {
    const { dock } = atlasAdminCenterElements();
    if (!drawer.hidden && dock && !dock.contains(event.target) && !drawer.contains(event.target)) {
      atlasAdminCenterSet(false);
    }
  });

  document.addEventListener("keydown", event => {
    if (event.key === "Escape" && !drawer.hidden) atlasAdminCenterSet(false);
  });

  window.addEventListener("atlas:v2mode", event => {
    if (!atlasV2IsExpandedMode(event.detail?.mode)) {
      atlasAdminCenterSet(false, { persist: false, scrollTarget: false });
    } else {
      window.requestAnimationFrame(restoreCenter);
    }
  });

  window.requestAnimationFrame(restoreCenter);
}

