function atlasChartTooltipCoinMarkup(coin, color, gradientCss = "") {
  const symbol = escapeHtml(String(coin?.symbol || "ACTIF").toUpperCase());
  const name = escapeHtml(coin?.name || symbol);
  const image = coin?.image
    ? `<img src="${escapeHtml(coin.image)}" alt="" loading="eager">`
    : `<span class="atlas-chart-tooltip-fallback" aria-hidden="true">${symbol.slice(0, 1)}</span>`;
  const style = `--atlas-series-color:${escapeHtml(color || "#F7931A")};--atlas-series-gradient:${escapeHtml(gradientCss || `linear-gradient(90deg, ${color || "#F7931A"}, ${color || "#F7931A"})`)}`;
  return `<span class="atlas-chart-tooltip-identity" style="${style}">${image}<span><b>${symbol}</b><small>${name}</small></span></span>`;
}

function atlasComparisonTooltipRows(chart, targetX) {
  const datasets = Array.isArray(chart?.data?.datasets) ? chart.data.datasets : [];
  return datasets.map(dataset => {
    const point = atlasNearestComparisonPoint(dataset, targetX);
    const rows = Array.isArray(dataset?.data) ? dataset.data : [];
    const nativeInterval = atlasMedianInterval(rows) || Infinity;
    const distance = point ? Math.abs(Number(point.x) - Number(targetX)) : Infinity;
    const usable = !!point && (!Number.isFinite(nativeInterval) || distance <= nativeInterval * 4);
    return {
      coin: dataset.atlasCoin || {},
      color: dataset.atlasPrimaryColor || dataset.borderColor,
      gradientCss: dataset.atlasGradientCss || "",
      baseValue: usable ? Number(point.y) : NaN,
      rawPrice: usable ? Number(point.rawPrice) : NaN,
      timestamp: usable ? Number(point.x) : Number(targetX),
      isLiveEndpoint: usable && point?.atlasLiveEndpoint === true,
      liveSource: usable ? String(point?.atlasLiveSource || "") : "",
      liveStatus: usable ? String(point?.atlasLiveStatus || "") : "",
      liveKind: usable ? String(point?.atlasLiveKind || "") : "",
      liveObservedAt: usable ? Number(point?.atlasLiveObservedAt || point?.x) : null
    };
  });
}

function atlasChartTooltipChangeMarkup(baseValue) {
  const normalized = Number(baseValue);
  if (!Number.isFinite(normalized)) {
    return '<small class="atlas-chart-tooltip-change is-missing" title="Variation indisponible">—</small>';
  }

  const change = Math.abs(normalized - 100) < 0.005 ? 0 : normalized - 100;
  const stateClass = change > 0 ? 'is-positive' : change < 0 ? 'is-negative' : 'is-neutral';
  const arrow = change > 0 ? '▲' : change < 0 ? '▼' : '•';
  const value = `${change > 0 ? '+' : ''}${change.toFixed(2)} %`;
  return `<small class="atlas-chart-tooltip-change ${stateClass}" title="Variation depuis le début de la période">${arrow} ${escapeHtml(value)}</small>`;
}

const atlasTooltipPointerPlugin = {
  id: "atlasTooltipPointer",
  beforeEvent(chart, args) {
    const event = args?.event;
    if (!chart || !event) return;

    if (event.type === "mouseout" || event.type === "mouseleave") {
      chart.$atlasTooltipPointer = null;
      return;
    }

    const x = Number(event.x);
    const y = Number(event.y);
    if (!Number.isFinite(x) || !Number.isFinite(y)) return;

    chart.$atlasTooltipPointer = { x, y };
  }
};

function atlasPositionChartTooltip(chart, tooltip, node) {
  const shell = chart?.canvas?.closest?.(".chart-shell");
  if (!shell || !node) return;

  const shellRect = shell.getBoundingClientRect();
  const canvasRect = chart.canvas.getBoundingClientRect();
  const measured = node.getBoundingClientRect();
  const pointer = chart.$atlasTooltipPointer || null;

  const canvasLeft = canvasRect.left - shellRect.left;
  const canvasTop = canvasRect.top - shellRect.top;
  const canvasWidth = canvasRect.width || shell.clientWidth;
  const canvasHeight = canvasRect.height || shell.clientHeight;

  const pointerX = Number.isFinite(Number(pointer?.x))
    ? Number(pointer.x)
    : Number(tooltip.caretX || 0);
  const pointerY = Number.isFinite(Number(pointer?.y))
    ? Number(pointer.y)
    : Number(tooltip.caretY || 0);

  const anchorX = canvasLeft + clamp(0, canvasWidth, pointerX);
  const anchorY = canvasTop + clamp(0, canvasHeight, pointerY);
  const gap = 18;
  const edge = 10;
  const switchTolerance = 34;
  const width = measured.width || 344;
  const height = measured.height || 120;
  const roomLeft = anchorX - gap - edge;
  const roomRight = shell.clientWidth - anchorX - gap - edge;

  let dock = node.dataset.dock === "left" || node.dataset.dock === "right"
    ? node.dataset.dock
    : "";

  if (!dock) {
    dock = roomRight >= width || roomRight >= roomLeft ? "right" : "left";
  } else if (dock === "right") {
    if (roomRight < width && roomLeft > roomRight + switchTolerance) dock = "left";
  } else if (roomLeft < width && roomRight > roomLeft + switchTolerance) {
    dock = "right";
  }

  let left = dock === "left"
    ? anchorX - width - gap
    : anchorX + gap;
  let top = anchorY - height * 0.50;

  left = clamp(edge, Math.max(edge, shell.clientWidth - width - edge), left);
  top = clamp(edge, Math.max(edge, shell.clientHeight - height - edge), top);

  node.dataset.dock = dock;
  node.style.left = `${Math.round(left)}px`;
  node.style.top = `${Math.round(top)}px`;
}

function atlasExternalChartTooltip(context) {
  const chart = context?.chart;
  const tooltip = context?.tooltip;
  const node = atlasChartTooltipNode();
  if (!chart || !node) return;

  if (!tooltip || tooltip.opacity === 0) {
    atlasHideChartTooltip();
    return;
  }

  const point = tooltip.dataPoints?.[0] || null;
  const targetX = Number(point?.parsed?.x);
  const comparison = chart.$atlasMode === "comparison";
  const rows = comparison
    ? atlasComparisonTooltipRows(chart, targetX, point?.dataIndex)
    : point ? [{
        coin: point.dataset?.atlasCoin || chart.$atlasCoin || {},
        color: point.dataset?.atlasPrimaryColor || point.dataset?.borderColor,
        gradientCss: point.dataset?.atlasGradientCss || "",
        rawPrice: Number(point.raw?.rawPrice),
        baseValue: Number(point.raw?.baseValue ?? point.raw?.y),
        timestamp: Number(point.raw?.x ?? point.parsed?.x),
        isLiveEndpoint: point.raw?.atlasLiveEndpoint === true,
        liveSource: String(point.raw?.atlasLiveSource || ""),
        liveStatus: String(point.raw?.atlasLiveStatus || ""),
        liveKind: String(point.raw?.atlasLiveKind || ""),
        liveObservedAt: Number(point.raw?.atlasLiveObservedAt || point.raw?.x)
      }] : [];

  if (!rows.length) {
    atlasHideChartTooltip();
    return;
  }

  const body = rows.map((row, index) => {
    const palette = atlasCryptoPalette(row.coin, index);
    const gradientCss = row.gradientCss || atlasCryptoGradientCss(row.coin, index);
    const historicalPrice = Number(row.rawPrice);
    const currentPrice = Number.isFinite(historicalPrice) && historicalPrice > 0
      ? atlasFormatEUR(historicalPrice)
      : "—";
    const style = `--atlas-series-color:${escapeHtml(palette.primary)};--atlas-series-gradient:${escapeHtml(gradientCss)}`;

    return `<div class="atlas-chart-tooltip-row" style="${style}">
      ${atlasChartTooltipCoinMarkup(row.coin, palette.primary, gradientCss)}
      <span class="atlas-chart-tooltip-color-bridge" aria-hidden="true"><i></i></span>
      <span class="atlas-chart-tooltip-values">
        <strong>${escapeHtml(currentPrice)}</strong>
        ${atlasChartTooltipChangeMarkup(row.baseValue)}
      </span>
    </div>`;
  }).join("");

  const liveRows = rows.filter(row => row.isLiveEndpoint);
  const everyRowIsCurrent = liveRows.length > 0 && liveRows.length === rows.length;
  const kinds = everyRowIsCurrent
    ? rows.map(row => String(row.liveKind || "unavailable"))
    : [];
  const allKinds = kind => kinds.length > 0 && kinds.every(value => value === kind);
  const tooltipPeriodLabel = atlasChartPeriodLabel(Number(chart.$atlasPeriod || state.chartPeriodDays || 1));
  const tooltipTitle = !everyRowIsCurrent
    ? `PRIX HISTORIQUE · VARIATION ${tooltipPeriodLabel}`
    : allKinds("live-binance")
      ? `PRIX LIVE BINANCE · VARIATION ${tooltipPeriodLabel}`
      : allKinds("collected")
        ? "OBSERVATIONS COLLECTÉES"
        : allKinds("conserved")
          ? "DERNIERS PRIX CONSERVÉS"
          : allKinds("snapshot")
            ? "PRIX SNAPSHOT COINGECKO"
            : kinds.some(kind => kind === "collected")
              ? "OBSERVATIONS ACTUELLES MIXTES"
              : kinds.some(kind => ["conserved", "snapshot"].includes(kind))
                ? "DERNIERS PRIX DISPONIBLES"
                : "PRIX ACTUELS";
  node.innerHTML = `<div class="atlas-chart-tooltip-date">${tooltipTitle}</div>${body}`;
  node.hidden = false;
  node.setAttribute("aria-hidden", "false");

  requestAnimationFrame(() => atlasPositionChartTooltip(chart, tooltip, node));
}

function atlasSetChartCaptionHtml(html, plainText) {
  if (!els.chartCaption) return;
  els.chartCaption.innerHTML = html;
  els.chartCaption.setAttribute("aria-label", plainText);
}

function atlasSetChartCaptionText(text) {
  if (!els.chartCaption) return;
  els.chartCaption.textContent = String(text || "");
  els.chartCaption.removeAttribute("aria-label");
}

function atlasRenderComparisonCaption(
  entries,
  period,
  unavailableItems = [],
  requestedCount = null
) {
  const periodLabel = atlasChartPeriodLabel(period);
  const unavailableCount = Array.isArray(unavailableItems)
    ? unavailableItems.length
    : Number(unavailableItems || 0);
  const selectedCount = Number(
    requestedCount || atlasComparisonIds().length || entries.length
  );
  const complete =
    entries.length === selectedCount
    && unavailableCount === 0;

  const truthResult = {
    comparison: true,
    entries,
    sourceMode: "comparison-base100"
  };
  const truth = atlasChartTruth(truthResult, period);
  const composition = truth.composition
    || atlasComparisonHistoryComposition(truthResult, period);
  const timestamps = entries
    .map(entry => Number(entry?.result?.integrity?.metrics?.lastTimestamp || 0))
    .filter(value => Number.isFinite(value) && value > 0);
  const exact = timestamps.length
    ? atlasExactTimestampLabel(Math.min(...timestamps))
    : "horodatage inconnu";

  const status =
    `Comparaison ${periodLabel} ${complete ? "complète" : "partielle"}`
    + ` · ${entries.length}/${selectedCount} séries`
    + `${unavailableCount ? ` · ${unavailableCount} indisponible${unavailableCount > 1 ? "s" : ""}` : ""}`
    + ` · ${truth.label}`
    + ` · plus ancien historique : ${exact}`
    + ` · point terminal séparé des historiques.`;

  atlasSetChartCaptionText(status);
}

function atlasRenderSingleCaption(c, periodLabel, result, warning = "") {
  const metrics = result?.integrity?.metrics || {};
  const change = Number(metrics.changePct);
  const count = Array.isArray(result?.series) ? result.series.length : 0;
  const truth = atlasChartTruth(result, Number(state.chartPeriodDays || 1));
  const view =
    atlasChartV2EffectiveView() === "base100"
      ? "Base 100"
      : "Prix EUR";
  const scale =
    atlasChartV2EffectiveScale() === "logarithmic"
      ? "log"
      : "normal";
  const changeText = Number.isFinite(change)
    ? fmtPct(change)
    : "—";
  const seriesExact = truth.exact;

  const plain =
    `${c.symbol} · ${periodLabel} · ${view} · ${changeText}`
    + ` · ${count} points · ${truth.label}`
    + ` · série ${seriesExact}${warning}`;

  const asset =
    `<span class="chart-caption-asset" `
    + `style="--atlas-series-color:${escapeHtml(atlasCryptoPalette(c,0).primary)}">`
    + `<i></i><b>${escapeHtml(c.symbol)}</b>`
    + `<strong>${escapeHtml(changeText)}</strong></span>`;

  atlasSetChartCaptionHtml(
    `${asset}<span class="chart-caption-text">`
      + `${escapeHtml(periodLabel)} · ${escapeHtml(view)} · ${escapeHtml(scale)}`
      + ` · ${count} points · ${escapeHtml(truth.label)}`
      + ` · série ${escapeHtml(seriesExact)}${escapeHtml(warning)}`
      + `</span>`,
    plain
  );
}

function atlasHexToRgb(hex) {
  const normalized = String(hex || "#62ecff").replace("#", "").trim();
  const full = normalized.length === 3
    ? normalized.split("").map(char => char + char).join("")
    : normalized.padEnd(6, "f").slice(0, 6);
  const value = Number.parseInt(full, 16);
  if (!Number.isFinite(value)) return [98, 236, 255];
  return [(value >> 16) & 255, (value >> 8) & 255, value & 255];
}

function atlasRoundedRectPath(ctx, x, y, width, height, radius = 6) {
  const r = Math.max(0, Math.min(radius, Math.abs(width) / 2, Math.abs(height) / 2));
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + width, y, x + width, y + height, r);
  ctx.arcTo(x + width, y + height, x, y + height, r);
  ctx.arcTo(x, y + height, x, y, r);
  ctx.arcTo(x, y, x + width, y, r);
  ctx.closePath();
}

function atlasMedianInterval(rows = []) {
  if (!Array.isArray(rows) || rows.length < 2) return null;
  const gaps = [];
  for (let index = 1; index < rows.length; index += 1) {
    const gap = Number(rows[index]?.t ?? rows[index]?.x) - Number(rows[index - 1]?.t ?? rows[index - 1]?.x);
    if (Number.isFinite(gap) && gap > 0) gaps.push(gap);
  }
  if (!gaps.length) return null;
  gaps.sort((a, b) => a - b);
  return gaps[Math.floor(gaps.length / 2)];
}

function atlasDrawCurveFollowingShadowBars({
  ctx,
  rows,
  xFor,
  yForPrice,
  baseline,
  clipLeft,
  clipTop,
  clipRight,
  clipBottom,
  color = "#62ecff",
  opacity = 0.18,
  heightRatio = 0.88,
  seriesIndex = 0,
  seriesCount = 1
}) {
  const safeRows = Array.isArray(rows)
    ? rows
        .filter(point =>
          Number.isFinite(Number(point?.x))
          && Number.isFinite(Number(point?.price))
          && Number(point.price) > 0
        )
        .sort((a, b) => Number(a.x) - Number(b.x))
    : [];

  if (!ctx || safeRows.length < 2) return;

  const safeBaseline = Math.min(
    Number(baseline),
    Number(clipBottom) - 1
  );
  const safeRatio = Math.max(
    0.10,
    Math.min(0.96, Number(heightRatio) || 0.88)
  );
  const safeOpacity = Math.max(
    0.025,
    Math.min(0.42, Number(opacity) || 0.18)
  );

  const pixelXs = safeRows
    .map(point => Number(xFor(point.x)))
    .filter(Number.isFinite)
    .sort((a, b) => a - b);

  const pixelGaps = pixelXs
    .slice(1)
    .map((value, index) => value - pixelXs[index])
    .filter(value => Number.isFinite(value) && value > 0)
    .sort((a, b) => a - b);

  const medianPixelGap = pixelGaps.length
    ? pixelGaps[Math.floor(pixelGaps.length / 2)]
    : 4;

  const safeSeriesCount = Math.max(
    1,
    Math.min(12, Math.round(Number(seriesCount) || 1))
  );
  const safeSeriesIndex = Math.max(
    0,
    Math.min(
      safeSeriesCount - 1,
      Math.round(Number(seriesIndex) || 0)
    )
  );

  const groupWidth = Math.max(
    1.8,
    Math.min(6.4, medianPixelGap * 0.74)
  );
  const slotWidth = groupWidth / safeSeriesCount;
  const barWidth = safeSeriesCount === 1
    ? Math.max(1.25, Math.min(4.0, groupWidth * 0.58))
    : Math.max(0.68, Math.min(1.8, slotWidth * 0.78));
  const xOffset = safeSeriesCount === 1
    ? 0
    : (
        safeSeriesIndex - (safeSeriesCount - 1) / 2
      ) * slotWidth;

  const volumeValues = safeRows
    .map(point => Number(point?.y))
    .filter(value => Number.isFinite(value) && value >= 0);
  const maxVolume = Math.max(...volumeValues, 0);

  ctx.save();
  ctx.beginPath();
  ctx.rect(
    Number(clipLeft),
    Number(clipTop),
    Number(clipRight) - Number(clipLeft),
    Number(clipBottom) - Number(clipTop)
  );
  ctx.clip();

  /*
    Canonical geometry:
    - bars are vertical and parallel;
    - every bar starts from the exact bottom edge of the price plot;
    - no artificial date-axis reserve shifts the bars upward;
    - every bar follows its crypto curve point by point;
    - every bar reaches 88% of the baseline-to-curve distance;
    - the remaining 12% is the clean gap below the crypto line;
    - each series uses its own crypto color;
    - real volume only modulates opacity, never bar height.
  */
  for (const point of safeRows) {
    const rawX = Number(xFor(point.x));
    const rawCurveY = Number(yForPrice(point.price));
    if (!Number.isFinite(rawX) || !Number.isFinite(rawCurveY)) continue;

    const curveY = Math.max(
      Number(clipTop),
      Math.min(safeBaseline - 1, rawCurveY)
    );
    const distanceToCurve = Math.max(1, safeBaseline - curveY);
    const shadowHeight = distanceToCurve * safeRatio;
    const shadowTop = safeBaseline - shadowHeight;

    const volumeRatio = maxVolume > 0
      ? Math.max(
          0,
          Math.min(1, Number(point.y || 0) / maxVolume)
        )
      : 0;

    ctx.globalAlpha = safeOpacity * (0.78 + volumeRatio * 0.22);
    ctx.fillStyle = color;
    ctx.fillRect(
      rawX + xOffset - barWidth / 2,
      shadowTop,
      barWidth,
      Math.max(1, shadowHeight)
    );
  }

  ctx.restore();
}

const atlasChartMetadataPlugin = {
  id: "atlasChartMetadata",

  beforeInit(chart, _args, options = {}) {
    chart.$atlasMode = options.mode || "single";
    chart.$atlasCoin = options.coin || null;
    chart.$atlasView = options.view || (
      options.mode === "comparison"
        ? "base100"
        : "price"
    );
    chart.$atlasScale = options.scale || "linear";
    chart.$atlasPeriod = Number(
      options.period || state.chartPeriodDays || 1
    );
    chart.$atlasPriceAxisId =
      options.priceAxisId || "y";
    chart.$atlasVolumeAxisId =
      options.volumeAxisId || null;
    chart.$atlasVolume =
      options.volumeVisible === true;
    chart.$atlasVolumeVisible =
      options.volumeVisible === true;
    chart.$atlasVolumeRows =
      Array.isArray(options.volumeRows)
        ? options.volumeRows
        : [];
    chart.$atlasVolumeColor =
      options.volumeColor || "#62ecff";
    chart.$atlasShadowSeries =
      Array.isArray(options.shadowSeries)
        ? options.shadowSeries
        : [];
    chart.$atlasTimeline =
      Array.isArray(options.timeline)
        ? options.timeline
        : [];
    chart.$atlasPreset = String(
      options.preset || state.dataBroker?.comparison?.preset || "manual"
    );
  }
};

const atlasVolumeOverlayPlugin = {
  id: "atlasVolumeOverlay",
  beforeDatasetsDraw(chart) {
    if (!chart?.$atlasVolumeVisible) return;

    const area = chart.chartArea;
    const xScale = chart.scales?.x;
    const yScale = chart.scales?.[chart.$atlasPriceAxisId || "y"];
    if (!area || !xScale || !yScale) return;

    /*
      The Chart.js chartArea already excludes the x-axis labels.
      The shadow baseline must therefore use the true plot bottom.
    */
    const baseline = area.bottom;

    const configuredSeries = Array.isArray(chart.$atlasShadowSeries)
      ? chart.$atlasShadowSeries
      : [];

    const series = configuredSeries.length
      ? configuredSeries
      : Array.isArray(chart.$atlasVolumeRows) && chart.$atlasVolumeRows.length
        ? [{
            rows: chart.$atlasVolumeRows,
            color: chart.$atlasVolumeColor || "#62ecff",
            opacity: 0.20,
            heightRatio: 0.88
          }]
        : [];

    series.forEach((entry, index) => {
      atlasDrawCurveFollowingShadowBars({
        ctx: chart.ctx,
        rows: entry.rows,
        xFor: value => xScale.getPixelForValue(value),
        yForPrice: value => yScale.getPixelForValue(value),
        baseline,
        clipLeft: area.left,
        clipTop: area.top,
        clipRight: area.right,
        clipBottom: area.bottom,
        color: entry.color || "#62ecff",
        opacity: Number.isFinite(Number(entry.opacity))
          ? Number(entry.opacity)
          : index === 0 ? 0.18 : 0.10,
        heightRatio: 0.88,
        seriesIndex: index,
        seriesCount: series.length
      });
    });
  }
};

const atlasOverlayAxesPlugin = {
  id: "atlasOverlayAxes",
  afterDraw(chart) {
    const area = chart?.chartArea;
    const xScale = chart?.scales?.x;
    const yScale = chart?.scales?.y;
    if (!area || !xScale || !yScale) return;

    const ctx = chart.ctx;
    const view = chart.$atlasView === "base100" || chart.$atlasMode === "comparison" ? "base100" : "price";
    const period = Number(chart.$atlasPeriod || state.chartPeriodDays || 1);
    const width = area.right - area.left;
    const height = area.bottom - area.top;

    ctx.save();
    ctx.beginPath();
    ctx.rect(area.left, area.top, width, height);
    ctx.clip();

    const yTicks = (yScale.ticks || []).filter(tick => Number.isFinite(Number(tick.value)));
    const visibleY = yTicks.length > 6
      ? yTicks.filter((_, index) => index % Math.ceil(yTicks.length / 6) === 0)
      : yTicks;

    ctx.font = `750 ${atlasChartAxisMetrics().yFont}px system-ui, sans-serif`;
    ctx.textAlign = "right";
    ctx.textBaseline = "middle";

    for (const tick of visibleY) {
      const y = yScale.getPixelForValue(tick.value);
      if (y < area.top + 8 || y > area.bottom - 24) continue;
      const text = atlasChartAxisPriceLabel(tick.value, view);
      const textWidth = ctx.measureText(text).width;
      const boxWidth = textWidth + 16;
      const x = area.right - 6;

      atlasRoundedRectPath(ctx, x - boxWidth, y - 10, boxWidth, 20, 7);
      ctx.fillStyle = "rgba(3,10,20,.58)";
      ctx.fill();
      ctx.fillStyle = "rgba(239,249,255,.94)";
      ctx.fillText(text, x - 7, y);
    }

    const xTicks = (xScale.ticks || []).filter(tick => Number.isFinite(Number(tick.value)));
    const visibleX = xTicks.length > atlasChartXAxisTickLimit(period)
      ? xTicks.filter((_, index) => index % Math.ceil(xTicks.length / atlasChartXAxisTickLimit(period)) === 0)
      : xTicks;

    ctx.font = `700 ${atlasChartAxisMetrics().xFont}px system-ui, sans-serif`;
    ctx.textAlign = "center";
    ctx.textBaseline = "bottom";

    for (const tick of visibleX) {
      const x = xScale.getPixelForValue(tick.value);
      if (x < area.left + 24 || x > area.right - 72) continue;
      const text = atlasChartLabelForTime(Number(tick.value), period);
      const textWidth = ctx.measureText(text).width;
      atlasRoundedRectPath(ctx, x - textWidth / 2 - 6, area.bottom - 24, textWidth + 12, 20, 6);
      ctx.fillStyle = "rgba(3,10,20,.48)";
      ctx.fill();
      ctx.fillStyle = "rgba(226,244,255,.92)";
      ctx.fillText(text, x, area.bottom - 5);
    }

    ctx.restore();
  }
};

function drawLineChart(canvas, series, label = "", result = {}, chartKey = "") {
  if (!canvas) return;

  const period = Number(result?.periodDays || state.chartPeriodDays || 1);
  const rows = atlasSanitizeChartRows(series)
    .map(point => ({ t: Number(point?.[0]), price: Number(point?.[1]) }));

  if (rows.length < atlasChartRules(period).minPoints) {
    drawChartBlocked(canvas);
    atlasChartV2RenderLegend([]);
    return;
  }

  const coin = result?.coin || getSelectedCoin() || {};
  const palette = atlasCryptoPalette(coin, 0);
  const firstPrice = rows[0].price;
  const view = atlasChartV2EffectiveView();
  const scaleType = atlasChartV2EffectiveScale();
  const showVolume = state.chartViewV2.volume && !atlasChartV2ComparisonMode();

  const points = rows.map(row => ({
    x: row.t,
    y: view === "base100" ? row.price / firstPrice * 100 : row.price,
    rawPrice: row.price,
    baseValue: row.price / firstPrice * 100
  }));

  const values = points.map(point => point.y).filter(Number.isFinite);
  const min = Math.min(...values);
  const max = Math.max(...values);
  const yPad = view === "base100"
    ? Math.max((max - min) * 0.08, 0.45)
    : Math.max((max - min) * 0.06, Math.abs(max) * 0.00035, 1e-8);


  const freshness = result?.integrity?.metrics?.freshness?.level || "fresh";
  atlasDestroyRealChart();
  atlasSetChartShellState(
    canvas,
    "valid",
    `${label} · ${view === "base100" ? "Base 100" : "Prix EUR"} · ${scaleType === "logarithmic" ? "log" : "normal"}`,
    freshness,
    atlasChartSourceMode(result),
    atlasChartProviderLabel(result),
    result
  );
  state.chartEngineV2.lastRenderedKey = chartKey;
  state.chartEngineV2.lastFingerprint = `${atlasChartResultFingerprint(result)}:${view}:${scaleType}:${state.chartViewV2.volume}:${atlasChartV2ComparisonMode()?state.chartViewV2.comparisonLegend:state.chartViewV2.legend}`;

  if (window.Chart) {
    const ctx = canvas.getContext("2d");
    const gradient = ctx.createLinearGradient(0, 0, 0, canvas.clientHeight || 400);
    gradient.addColorStop(0, `${palette.primary}33`);
    gradient.addColorStop(0.55, `${palette.primary}10`);
    gradient.addColorStop(1, `${palette.primary}02`);

    const datasets = [{
      type: "line",
      label: `${label} · ${atlasChartProviderLabel(result)} EUR`,
      atlasCoin: coin,
      atlasPrimaryColor: palette.primary,
      atlasGradientCss: atlasCryptoGradientCss(coin, 0),
      data: points,
      parsing: false,
      yAxisID: "y",
      borderWidth: 2.55,
      pointRadius(context) {
        return context.dataIndex === context.dataset.data.length - 1 ? 5.2 : 0;
      },
      pointHoverRadius: 6.4,
      pointHitRadius: 32,
      tension: 0.08,
      fill: { target: "start" },
      backgroundColor: gradient,
      borderColor: palette.primary,
      order: 1
    }];

    const volumeRows =
      atlasAlignVolumeToPriceTimeline(
        result?.volumeSeries,
        points.map(point => ({
          t: point.x,
          price: point.y
        }))
      );

    const shadowSeries = [{
      rows: volumeRows,
      color: palette.primary,
      opacity: 0.22,
      heightRatio: 0.88
    }];

    state.chartEngineV2.realChart = new Chart(ctx, {
      type: "line",
      data: { datasets },
      plugins: [atlasChartMetadataPlugin, atlasVolumeOverlayPlugin, atlasOverlayAxesPlugin, atlasTooltipPointerPlugin],
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        normalized: true,
        parsing: false,
        interaction: { mode: "nearest", intersect: false, axis: "x" },
        layout: { padding: { top: 8, right: 4, bottom: 46, left: 4 } },
        plugins: {
          atlasChartMetadata: {
            mode: "single",
            coin,
            view,
            scale: scaleType,
            period,
            priceAxisId: "y",
            volumeAxisId: null,
            volumeVisible: showVolume,
            volumeRows,
            volumeColor: palette.primary,
            shadowSeries
          },
          legend: { display: false },
          tooltip: {
            enabled: false,
            external: atlasExternalChartTooltip
          }
        },
        scales: {
          x: {
            type: "linear",
            min: rows[0].t,
            max: rows[rows.length - 1].t,
            bounds: "data",
            offset: false,
            afterFit(scale) { scale.height = 0; },
            border: { display: false },
            grid: { color: "rgba(176,236,255,.075)", drawTicks: false },
            ticks: {
              display: false,
              maxTicksLimit: atlasChartXAxisTickLimit(period),
              autoSkip: true,
              maxRotation: 0
            }
          },
          y: {
            type: scaleType,
            position: "right",
            min: scaleType === "linear" ? min - yPad : undefined,
            max: scaleType === "linear" ? max + yPad : undefined,
            afterFit(scale) { scale.width = 0; },
            border: { display: false },
            grid: { color: "rgba(176,236,255,.105)", drawTicks: false },
            ticks: { display: false, maxTicksLimit: 6 },
            title: { display: false }
          },
          yVolume: {
            display: false,
            min: 0,
            max: 1,
            grid: { display: false },
            ticks: { display: false },
            border: { display: false }
          }
        }
      }
    });

    atlasRefreshChartScale(
      state.chartEngineV2.realChart
    );
    state.chartEngineV2.realChart.update("none");
    atlasChartV2RenderLegend([{ coin, result }], { result });
    atlasRenderChartValueOverlay([{ coin, result, data: points, first: firstPrice }], { comparison: false, period });
    atlasChartV2SyncControls();
    return;
  }

  const ctx = canvas.getContext("2d");
  const rect = canvas.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  const width = Math.max(560, Math.floor(rect.width || canvas.clientWidth || 980));
  const height = Math.max(300, Math.floor(rect.height || canvas.clientHeight || 320));
  canvas.width = Math.floor(width * dpr);
  canvas.height = Math.floor(height * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, width, height);

  const left = 52, right = 100, top = 42, bottom = 42;
  const plotWidth = width - left - right;
  const plotHeight = height - top - bottom;
  const low = min - yPad;
  const high = max + yPad;
  const startTime = rows[0].t;
  const endTime = rows[rows.length - 1].t;
  const xFor = time => left + ((time - startTime) / (endTime - startTime || 1)) * plotWidth;
  const yFor = value => top + plotHeight - ((value - low) / (high - low || 1)) * plotHeight;

  if (showVolume) {
    const fallbackVolumeRows = atlasAlignVolumeToPriceTimeline(
      result?.volumeSeries,
      points.map(point => ({ t: point.x, price: point.y }))
    );
    atlasDrawCurveFollowingShadowBars({
      ctx,
      rows: fallbackVolumeRows,
      xFor,
      yForPrice: yFor,
      baseline: top + plotHeight,
      clipLeft: left,
      clipTop: top,
      clipRight: left + plotWidth,
      clipBottom: top + plotHeight,
      color: palette.primary
    });
  }

  ctx.beginPath();
  points.forEach((point, index) => {
    const x = xFor(point.x);
    const y = yFor(point.y);
    if (index === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  });
  ctx.strokeStyle = palette.primary;
  ctx.lineWidth = 2.2;
  ctx.stroke();
  atlasChartV2RenderLegend([{ coin, result }], { result });
  atlasRenderChartValueOverlay([{ coin, result, data: points, first: firstPrice }], { comparison: false, period });
  atlasChartV2SyncControls();
}

function atlasChartPriceDatasets(chart) {
  return (chart?.data?.datasets || []).filter(dataset =>
    !dataset?.atlasVolumeDataset
    && (dataset?.yAxisID || "y") === "y"
  );
}

function atlasChartVolumeDatasets(chart) {
  return (chart?.data?.datasets || []).filter(dataset =>
    dataset?.atlasVolumeDataset
    || dataset?.yAxisID === "yVolume"
  );
}

function atlasRefreshChartScale(chart) {
  if (!chart?.data?.datasets?.length) return;

  const priceDatasets = atlasChartPriceDatasets(chart);
  const priceValues = priceDatasets
    .flatMap(dataset => (dataset.data || []).map(point => Number(point?.y)))
    .filter(value => Number.isFinite(value) && value > 0);

  const times = priceDatasets
    .flatMap(dataset => (dataset.data || []).map(point => Number(point?.x)))
    .filter(Number.isFinite);

  const yScale = chart.options?.scales?.y;
  if (priceValues.length && yScale) {
    const min = Math.min(...priceValues);
    const max = Math.max(...priceValues);
    const comparison = chart.$atlasMode === "comparison";
    const pad = comparison
      ? Math.max((max - min) * 0.08, 0.5)
      : Math.max((max - min) * 0.06, Math.abs(max) * 0.00035, 0.00000001);

    if (String(yScale.type || "linear") === "logarithmic") {
      delete yScale.min;
      delete yScale.max;
      yScale.suggestedMin = Math.max(Number.MIN_VALUE, min * 0.94);
      yScale.suggestedMax = max * 1.06;
    } else {
      delete yScale.suggestedMin;
      delete yScale.suggestedMax;
      yScale.min = min - pad;
      yScale.max = max + pad;
    }
  }

  const volumeValues = atlasChartVolumeDatasets(chart)
    .flatMap(dataset => (dataset.data || []).map(point => Number(point?.y)))
    .filter(value => Number.isFinite(value) && value >= 0);

  const volumeScale = chart.options?.scales?.yVolume;
  if (volumeScale && volumeValues.length) {
    const maxVolume = Math.max(...volumeValues);
    volumeScale.beginAtZero = true;
    volumeScale.suggestedMin = 0;
    volumeScale.suggestedMax = maxVolume > 0 ? maxVolume * 3.2 : 1;
  }

  if (times.length && chart.options?.scales?.x) {
    chart.options.scales.x.min = Math.min(...times);
    chart.options.scales.x.max = Math.max(...times);
  }
}

function atlasPatchChartLastPoint(
  quotes = state.dataBroker?.spotBook?.quotes || {},
  sharedTimestamp = Date.now()
) {
  const brokerChart =
    state.dataBroker?.chart;

  if (
    brokerChart?.status !== "ready"
    || !atlasChartContextMatches(
      brokerChart
    )
  ) {
    return false;
  }

  const relevantIds =
    brokerChart.result?.comparison
      ? (
          brokerChart.result.entries || []
        )
          .map(entry => entry?.coin?.id)
          .filter(Boolean)
      : [state.selectedCoinId]
          .filter(Boolean);

  const hasFreshDirectSpot =
    relevantIds.some(id => {
      const price =
        Number(quotes?.[id]?.eur);

      return (
        atlasSpotQuoteIsFreshDirect(id)
        && Number.isFinite(price)
        && price > 0
      );
    });

  if (!hasFreshDirectSpot) {
    return false;
  }

  /*
    Le spot direct continue d'alimenter
    les rubans, le tableau et le détail.
    Il ne réécrit jamais market_chart :
    - aucun déplacement de l'axe X ;
    - aucune ancienneté trompeuse ;
    - aucune déformation Base 100 ;
    - aucun saut toutes les 30 secondes.
  */
  brokerChart.spotObservedAt =
    new Date(
      Number(
        sharedTimestamp || Date.now()
      )
    ).toISOString();

  brokerChart.spotPatchedAt = null;

  atlasRefreshSelectedDetailOnly();
  renderMultiHorizon();
  atlasRenderBrokerStrip();

  return true;
}

function atlasLiveEndpointAnchorX(chart, datasets = []) {
  const existing = Number(chart?.$atlasLiveEndpointX);
  if (Number.isFinite(existing)) return existing;

  const historicalTimes = (datasets || [])
    .flatMap(dataset => (dataset?.data || [])
      .filter(point => point?.atlasLiveEndpoint !== true)
      .map(point => Number(point?.x)))
    .filter(Number.isFinite);

  if (!historicalTimes.length) return NaN;

  const intervals = (datasets || [])
    .map(dataset => atlasMedianInterval(
      (dataset?.data || []).filter(point => point?.atlasLiveEndpoint !== true)
    ))
    .filter(value => Number.isFinite(value) && value > 0)
    .sort((a, b) => a - b);

  const medianInterval = intervals.length
    ? intervals[Math.floor(intervals.length / 2)]
    : 60000;
  const terminalGap = clamp(1000, 60000, medianInterval * 0.08);
  const anchor = Math.max(...historicalTimes) + terminalGap;

  chart.$atlasLiveEndpointX = anchor;
  return anchor;
}

function atlasPatchVisibleChartLiveEndpoints(changedIds = []) {
  const chart = state.chartEngineV2?.realChart;
  if (!chart || !Array.isArray(chart.data?.datasets) || !chart.data.datasets.length) return false;

  const datasets = atlasChartPriceDatasets(chart);
  if (!datasets.length) return false;

  const visibleIds = new Set(datasets
    .map(dataset => (dataset?.atlasCoin || chart.$atlasCoin || null)?.id || '')
    .filter(Boolean));
  const changed = new Set((changedIds || []).filter(Boolean));
  if (changed.size && ![...changed].some(id => visibleIds.has(id))) return false;

  const comparison = chart.$atlasMode === "comparison";
  const base100 = comparison || chart.$atlasView === "base100";
  const sharedX = atlasLiveEndpointAnchorX(chart, datasets);
  if (!Number.isFinite(sharedX)) return false;

  let touched = false;

  datasets.forEach(dataset => {
    const coin = dataset?.atlasCoin || chart.$atlasCoin || null;
    const coinId = coin?.id || "";
    if (!coinId) return;

    const data = Array.isArray(dataset.data) ? dataset.data : [];
    if (!data.length) return;

    const firstHistorical = data.find(point =>
      point?.atlasLiveEndpoint !== true
      && Number.isFinite(Number(point?.rawPrice))
      && Number(point.rawPrice) > 0
    );
    const firstPrice = Number(firstHistorical?.rawPrice);
    if (base100 && !(Number.isFinite(firstPrice) && firstPrice > 0)) return;

    const quote = atlasCurrentChartObservation(coin, chart);
    const livePrice = Number(quote?.price);
    const quoteIsUsable = Number.isFinite(livePrice)
      && livePrice > 0;

    const last = data[data.length - 1];
    if (!quoteIsUsable) {
      if (last?.atlasLiveEndpoint === true && Number(last.x) !== sharedX) {
        last.x = sharedX;
        touched = true;
      }
      return;
    }

    const livePoint = {
      x: sharedX,
      y: base100 ? livePrice / firstPrice * 100 : livePrice,
      rawPrice: livePrice,
      baseValue: base100 ? livePrice / firstPrice * 100 : null,
      atlasLiveEndpoint: true,
      atlasLiveSource: String(quote.source || "Observation actuelle"),
      atlasLiveStatus: String(quote.status || ""),
      atlasLiveKind: atlasObservationKind(quote),
      atlasLiveObservedAt: Number(quote.timestamp || Date.now())
    };

    if (last?.atlasLiveEndpoint === true) {
      const changedPoint = Number(last.x) !== livePoint.x
        || Number(last.y) !== livePoint.y
        || Number(last.rawPrice) !== livePoint.rawPrice;
      Object.assign(last, livePoint);
      touched = touched || changedPoint;
    } else {
      data.push(livePoint);
      touched = true;
    }

    dataset.atlasLiveQuote = quote;
  });

  atlasRefreshComparisonEndpointTruth(
    datasets.map(dataset => dataset?.atlasCoin).filter(Boolean),
    chart
  );

  if (!touched) return false;

  atlasRefreshChartScale(chart);
  chart.update("none");

  if (chart.tooltip?.opacity > 0) {
    requestAnimationFrame(() => atlasExternalChartTooltip({ chart, tooltip: chart.tooltip }));
  }

  return true;
}

function atlasComparisonResultFingerprint(entries, period) {
  return `${Number(period || 1)}|${entries.map(entry => `${entry.coin.id}:${atlasChartResultFingerprint(entry.result)}`).join("|")}`;
}

function atlasComparisonSummary(entries) {
  return entries.map(entry => {
    const metrics = entry.result?.integrity?.metrics || {};
    return `${entry.coin.symbol} ${Number.isFinite(metrics.changePct) ? fmtPct(metrics.changePct) : "—"}`;
  }).join(" · ");
}

function atlasNearestComparisonPoint(dataset, targetX) {
  const data = Array.isArray(dataset?.data) ? dataset.data : [];
  if (!data.length || !Number.isFinite(Number(targetX))) return null;
  let low = 0;
  let high = data.length - 1;
  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    if (Number(data[mid]?.x) < Number(targetX)) low = mid + 1;
    else high = mid;
  }
  const right = data[low] || null;
  const left = data[Math.max(0, low - 1)] || null;
  if (!left) return right;
  if (!right) return left;
  return Math.abs(Number(left.x) - Number(targetX)) <= Math.abs(Number(right.x) - Number(targetX)) ? left : right;
}

function atlasComparisonRows(entry) {
  return atlasSanitizeChartRows(entry?.result?.series || [])
    .map(point => ({ t: Number(point?.[0]), price: Number(point?.[1]) }));
}

function atlasComparisonMaximumPoints(period) {
  const days = Number(period || 1);
  if (days <= 1) return 420;
  if (days <= 7) return 560;
  if (days <= 90) return 640;
  return 720;
}

function atlasDownsampleNativeComparisonRows(rows, maximumPoints) {
  const source = Array.isArray(rows) ? rows : [];
  const limit = Math.max(32, Number(maximumPoints || 640));
  if (source.length <= limit) return source;
  const stride = Math.max(1, Math.ceil((source.length - 2) / Math.max(1, limit - 2)));
  return source.filter((_, index) =>
    index === 0
    || index === source.length - 1
    || index % stride === 0
  );
}

function atlasBuildNativeComparisonTimeline(entries, maximumPoints = 720) {
  const timestamps = [...new Set(
    (Array.isArray(entries) ? entries : [])
      .flatMap(entry => (entry?.rows || []).map(row => Number(row?.t)))
      .filter(Number.isFinite)
  )].sort((a, b) => a - b);
  if (timestamps.length <= maximumPoints) return timestamps;
  const stride = Math.max(1, Math.ceil((timestamps.length - 2) / Math.max(1, maximumPoints - 2)));
  return timestamps.filter((_, index) =>
    index === 0
    || index === timestamps.length - 1
    || index % stride === 0
  );
}

function atlasBuildAlignedComparisonEntries(entries, period) {
  const minimum = atlasChartRules(period).minPoints;
  const maximumPoints = atlasComparisonMaximumPoints(period);
  const prepared = entries.map((entry, index) => ({
    ...entry,
    index,
    rows: atlasComparisonRows(entry)
  })).filter(entry => entry.rows.length >= minimum);

  if (!prepared.length) return [];

  const commonStart = Math.max(...prepared.map(entry => entry.rows[0].t));
  const commonEnd = Math.min(...prepared.map(entry => entry.rows[entry.rows.length - 1].t));
  if (!Number.isFinite(commonStart) || !Number.isFinite(commonEnd) || commonEnd <= commonStart) return [];

  const nativeEntries = prepared.map(entry => {
    const overlapRows = entry.rows.filter(row => row.t >= commonStart && row.t <= commonEnd);
    if (overlapRows.length < minimum) return null;
    const sampledRows = atlasDownsampleNativeComparisonRows(overlapRows, maximumPoints);
    const first = Number(sampledRows[0]?.price);
    if (!Number.isFinite(first) || first <= 0) return null;
    const data = sampledRows.map(row => ({
      x: row.t,
      y: row.price / first * 100,
      rawPrice: row.price
    })).filter(point =>
      Number.isFinite(point.x)
      && Number.isFinite(point.y)
      && Number.isFinite(point.rawPrice)
      && point.rawPrice > 0
    );
    if (data.length < minimum) return null;
    return {
      ...entry,
      rows: sampledRows,
      first,
      data,
      nativePointCount: overlapRows.length,
      sampledPointCount: data.length,
      missingPointCount: 0
    };
  }).filter(Boolean);

  if (!nativeEntries.length) return [];
  const nativeTimeline = atlasBuildNativeComparisonTimeline(nativeEntries, maximumPoints);
  return nativeEntries.map(entry => ({
    ...entry,
    alignedTimeline: nativeTimeline
  }));
}

function atlasBuildBestAlignedComparisonEntries(entries, period, targetCount = ATLAS_COMPARISON_MAX_SERIES) {
  const source = Array.isArray(entries) ? entries.filter(Boolean).slice(0, ATLAS_COMPARISON_MAX_SERIES) : [];
  const maximum = Math.min(Math.max(1, Number(targetCount || source.length)), source.length);
  const combinations = (items, size, start = 0, prefix = [], output = []) => {
    if (prefix.length === size) {
      output.push([...prefix]);
      return output;
    }
    for (let index = start; index <= items.length - (size - prefix.length); index += 1) {
      prefix.push(items[index]);
      combinations(items, size, index + 1, prefix, output);
      prefix.pop();
    }
    return output;
  };

  for (let size = maximum; size >= 1; size -= 1) {
    for (const subset of combinations(source, size)) {
      const aligned = atlasBuildAlignedComparisonEntries(subset, period);
      if (aligned.length === subset.length) return aligned;
    }
  }
  return [];
}

function drawComparisonChart(canvas, entries, period, chartKey = "") {
  if (!canvas || !Array.isArray(entries) || entries.length < 1) {
    state.dataBroker.comparison.renderedIds = [];
    return [];
  }
  const normalizedEntries = atlasBuildAlignedComparisonEntries(entries, period);
  if (normalizedEntries.length < 1) {
    state.dataBroker.comparison.renderedIds = [];
    return [];
  }
  state.dataBroker.comparison.renderedIds = normalizedEntries.map(entry => entry.coin.id);

  const allValues = normalizedEntries.flatMap(entry => entry.data.filter(Boolean).map(point => point.y));
  const min = Math.min(...allValues);
  const max = Math.max(...allValues);
  const yPad = Math.max((max - min) * 0.08, 0.5);
  const timeline = normalizedEntries[0].alignedTimeline;
  const startTime = timeline[0];
  const endTime = timeline[timeline.length - 1];
  const summary = `${atlasComparisonSummary(normalizedEntries)} · ${normalizedEntries.length} séries · CoinGecko EUR`;

  const comparisonTruthResult = {
    comparison: true,
    entries: normalizedEntries,
    sourceMode: "comparison-base100"
  };
  const comparisonFreshness = atlasChartWorstFreshness(
    comparisonTruthResult,
    period
  );
  const comparisonOrigin = atlasChartSourceMode(comparisonTruthResult);

  const comparisonFingerprint =
    atlasComparisonResultFingerprint(
      normalizedEntries,
      period
    );

  const alreadyRendered =
    state.chartEngineV2.lastRenderedKey === chartKey
    && state.chartEngineV2.lastFingerprint
      === comparisonFingerprint
    && state.chartEngineV2.realChart
    && state.chartEngineV2.realChart.$atlasMode
      === "comparison";

  atlasSetChartShellState(
    canvas,
    "valid",
    summary,
    comparisonFreshness,
    comparisonOrigin,
    atlasChartProviderLabel(comparisonTruthResult),
    comparisonTruthResult
  );

  if (alreadyRendered) {
    return normalizedEntries;
  }

  atlasDestroyRealChart();

  state.chartEngineV2.lastRenderedKey =
    chartKey;
  state.chartEngineV2.lastFingerprint =
    comparisonFingerprint;

  if (window.Chart) {
    const ctx = canvas.getContext("2d");
    const gradientWidth = canvas.getBoundingClientRect().width || canvas.clientWidth || 980;
    const datasets = normalizedEntries.map((entry, index) => {
      const palette = atlasCryptoPalette(entry.coin, index);
      const stroke = atlasCryptoCanvasGradient(ctx, entry.coin, index, gradientWidth);
      return {
        label: `${entry.coin.symbol}`,
        atlasCoin: { id: entry.coin.id, symbol: entry.coin.symbol, name: entry.coin.name, image: entry.coin.image || "" },
        atlasPrimaryColor: palette.primary,
        atlasGradientCss: atlasCryptoGradientCss(entry.coin, index),
        data: entry.data,
        parsing: false,
        borderWidth: index === 0 ? 3.15 : 2.55,
        pointRadius(context) { return context.dataIndex === context.dataset.data.length - 1 ? 5.2 : 0; },
        pointHoverRadius: 6.4,
        pointHitRadius: 32,
        tension: 0.08,
        spanGaps: false,
        fill: false,
        borderColor: stroke,
        backgroundColor: palette.primary,
        pointBackgroundColor: palette.primary,
        pointBorderColor: "rgba(3,10,20,.92)",
        pointBorderWidth: 1.5,
        borderCapStyle: "round",
        borderJoinStyle: "round"
      };
    });
    state.chartEngineV2.realChart = new Chart(ctx, {
      type: "line",
      data: { datasets },
      plugins: [atlasChartMetadataPlugin, atlasVolumeOverlayPlugin, atlasOverlayAxesPlugin, atlasTooltipPointerPlugin],
      options: {
        responsive: true,
        maintainAspectRatio: false,
        animation: false,
        normalized: false,
        parsing: false,
        interaction: { mode: "nearest", intersect: false, axis: "x" },
        layout: { padding: { top: 8, right: 4, bottom: 46, left: 4 } },
        plugins: {
          atlasChartMetadata: {
            mode: "comparison",
            preset: String(state.dataBroker?.comparison?.preset || "manual"),
            view: "base100",
            scale: "linear",
            period,
            priceAxisId: "y",
            volumeAxisId: null,
            volumeVisible:
              state.chartViewV2.volume !== false,
            timeline,
            shadowSeries:
              normalizedEntries.map(
                (entry, index) => ({
                  rows: entry.data
                    .filter(Boolean)
                    .map(point => ({
                      x: point.x,
                      price: point.y,
                      y: 1
                    })),
                  color:
                    atlasCryptoPalette(
                      entry.coin,
                      index
                    ).primary,
                  opacity:
                    index === 0
                      ? 0.16
                      : Math.max(
                          0.065,
                          0.12 - index * 0.012
                        ),
                  heightRatio: 0.88
                })
              )
          },
          legend: {
            display: false,
            position: "top",
            align: "end",
            labels: {
              color: "rgba(236,248,255,0.90)",
              usePointStyle: false,
              boxWidth: 16,
              boxHeight: 2,
              padding: 10,
              font: { size: 10, weight: "800" },
              generateLabels(chart) {
                return chart.data.datasets.map((dataset, index) => ({
                  text: dataset.atlasCoin?.symbol || dataset.label || `S${index + 1}`,
                  strokeStyle: dataset.atlasPrimaryColor || "#62ecff",
                  fillStyle: dataset.atlasPrimaryColor || "#62ecff",
                  lineWidth: 3,
                  hidden: !chart.isDatasetVisible(index),
                  datasetIndex: index
                }));
              }
            }
          },
          tooltip: { enabled: false, external: atlasExternalChartTooltip }
        },
        scales: {
          x: {
            type: "linear",
            min: startTime,
            max: endTime,
            bounds: "data",
            offset: false,
            afterFit(scale) { scale.height = 0; },
            border: { display: false },
            grid: { color: "rgba(176,236,255,0.075)", drawTicks: false },
            ticks: {
              display: false,
              maxTicksLimit: atlasChartXAxisTickLimit(period),
              autoSkip: true,
              maxRotation: 0
            }
          },
          y: {
            position: "right",
            min: min - yPad,
            max: max + yPad,
            afterFit(scale) { scale.width = 0; },
            border: { display: false },
            grid: { color: "rgba(176,236,255,0.105)", drawTicks: false },
            ticks: { display: false, maxTicksLimit: 6 },
            title: { display: false }
          }
        }
      }
    });
    atlasRefreshChartScale(
      state.chartEngineV2.realChart
    );
    state.chartEngineV2.realChart.update("none");
    atlasRenderChartValueOverlay(normalizedEntries, { comparison: true, period });
    window.requestAnimationFrame(() => atlasPatchVisibleChartLiveEndpoints());
    return normalizedEntries;
  }

  const ctx = canvas.getContext("2d");
  const rect = canvas.getBoundingClientRect();
  const dpr = window.devicePixelRatio || 1;
  const width = Math.max(560, Math.floor(rect.width || canvas.clientWidth || 980));
  const height = Math.max(300, Math.floor(rect.height || canvas.clientHeight || 320));
  canvas.width = Math.floor(width * dpr);
  canvas.height = Math.floor(height * dpr);
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, width, height);
  const left = 52, right = 100, top = 26, bottom = 42;
  const plotW = width - left - right, plotH = height - top - bottom;
  const xFor = time => left + ((time - startTime) / (endTime - startTime || 1)) * plotW;
  const yFor = value => top + plotH - ((value - (min - yPad)) / ((max + yPad) - (min - yPad) || 1)) * plotH;
  if (state.chartViewV2.volume !== false) {
    normalizedEntries.forEach((entry, index) => {
      const palette = atlasCryptoPalette(entry.coin, index);
      atlasDrawCurveFollowingShadowBars({
        ctx,
        rows: entry.data
          .filter(Boolean)
          .map(point => ({ x: point.x, price: point.y, y: 1 })),
        xFor,
        yForPrice: yFor,
        baseline: top + plotH,
        clipLeft: left,
        clipTop: top,
        clipRight: left + plotW,
        clipBottom: top + plotH,
        color: palette.primary,
        opacity: index === 0 ? 0.16 : Math.max(0.065, 0.12 - index * 0.012),
        heightRatio: 0.88,
        seriesIndex: index,
        seriesCount: normalizedEntries.length
      });
    });
  }

  normalizedEntries.forEach((entry, index) => {
    ctx.beginPath();
    entry.data.forEach((point, pointIndex) => {
      const x = xFor(point.x), y = yFor(point.y);
      if (pointIndex === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.strokeStyle = atlasCryptoPalette(entry.coin, index).primary;
    ctx.lineWidth = index === 0 ? 2.8 : 2.2;
    ctx.stroke();
  });
  atlasRenderChartValueOverlay(normalizedEntries, { comparison: true, period });
  return normalizedEntries;
}

async function atlasMapComparisonWithConcurrency(items, limit, worker) {
  const results = new Array(items.length);
  let cursor = 0;
  const run = async () => {
    while (cursor < items.length) {
      const index = cursor++;
      try { results[index] = await worker(items[index], index); }
      catch (error) { results[index] = { error }; }
    }
  };
  const workers = Array.from({ length: Math.min(Math.max(1, limit), items.length) }, () => run());
  await Promise.all(workers);
  return results;
}

function atlasComparisonAbortError(error) {
  return error?.name === "AbortError";
}

function atlasComparisonRetryableError(error) {
  if (!error || atlasComparisonAbortError(error)) return false;
  const status = Number(error.status || 0);
  if (!status) return true;
  return status === 408 || status === 425 || status === 429 || status >= 500;
}

async function atlasRespectComparisonRequestSpacing(signal = null, period = Number(state.chartPeriodDays || 1)) {
  const comparison = state.dataBroker.comparison;
  const minimumSpacing = Number(period || 1) >= 60
    ? ATLAS_COMPARISON_LONG_HORIZON_SPACING_MS
    : ATLAS_COMPARISON_REQUEST_SPACING_MS;
  const elapsed = Date.now() - Number(comparison.lastDirectRequestAt || 0);
  const waitMs = Math.max(0, minimumSpacing - elapsed);
  if (waitMs) await atlasWaitWithSignal(waitMs, signal);
  comparison.lastDirectRequestAt = Date.now();
}

function atlasRenderComparisonDetail(entries, period) {
  const coins = entries.map(entry => entry.coin);
  const primary = getSelectedCoin() || coins[0];
  atlasBrokerSeedSpot(primary);
  const preset = String(state.dataBroker?.comparison?.preset || "manual");
  const volumeMode = preset === "volume";
  const ranked = entries
    .map(entry => ({
      coin: entry.coin,
      metric: Number.isFinite(Number(entry?.atlasMarketMetric))
        ? Number(entry.atlasMarketMetric)
        : volumeMode
          ? Number(entry.coin?.volume24h)
          : Number(entry.result?.integrity?.metrics?.changePct)
    }))
    .filter(row => Number.isFinite(row.metric))
    .sort((a, b) => b.metric - a.metric);
  const metricText = row => row
    ? `${escapeHtml(row.coin.symbol)} · ${escapeHtml(volumeMode ? fmtCompactEUR.format(row.metric) : fmtPct(row.metric))}`
    : "—";
  if (els.assetDetailGrid) {
    els.assetDetailGrid.innerHTML = `
      <div><b>Mode</b><span>Comparaison normalisée</span></div>
      <div><b>Actif principal</b><span>${escapeHtml(primary?.name || "—")} (${escapeHtml(primary?.symbol || "—")})</span></div>
      <div><b>Actifs comparés</b><span>${escapeHtml(coins.map(coin => coin.symbol).join(" / "))}</span></div>
      <div><b>Période</b><span>${escapeHtml(atlasChartPeriodLabel(period))}</span></div>
      <div><b>${volumeMode ? "Volume supérieur" : "Meilleure trajectoire"}</b><span>${metricText(ranked[0])}</span></div>
      <div><b>${volumeMode ? "Volume inférieur" : "Trajectoire la plus faible"}</b><span>${metricText(ranked.at(-1))}</span></div>
      <div><b>Historiques</b><span>${escapeHtml(
        atlasComparisonHistoryLabel(
          atlasComparisonHistoryComposition(
            { comparison: true, entries },
            period
          )
        )
      )}</span></div>
      <div><b>Point terminal</b><span data-comparison-endpoint-truth>${escapeHtml(
        atlasComparisonEndpointLabel(
          atlasComparisonEndpointComposition(coins)
        )
      )}</span></div>
      <div><b>Échelle</b><span>Chaque actif commence à 100</span></div>
      <div><b>Prix absolus</b><span>Visibles dans les infobulles</span></div>
      <div><b>Décision</b><span>Observation comparative uniquement</span></div>`;
  }
  atlasSetCompactReading(`Lecture : comparaison normalisée de ${coins.map(coin => coin.symbol).join(", ")} sur ${atlasChartPeriodLabel(period)}.`);
  atlasRenderBrokerStrip();
}

async function renderComparisonAnalystPanel(options = {}) {
  if ((atlasScannerTransaction || atlasScannerQueuedRequest) && options.allowDuringScanner !== true) return;
  const coins = atlasComparisonCoins();
  if (coins.length < 2) {
    state.dataBroker.comparison.mode = "single";
    return renderAnalystPanel({ ...options, forceSingle: true });
  }

  atlasClearChartRetryTimer();
  atlasClearComparisonCompletionTimer();

  const renderToken = ++state.comparisonRenderToken;
  if (state.chartEngineV2?.controller) {
    try { state.chartEngineV2.controller.abort(); } catch {}
  }

  const controller = new AbortController();
  state.chartEngineV2.controller = controller;
  state.chartEngineV2.loading = true;

  const period = Number(state.chartPeriodDays || 1);
  const periodLabel = atlasChartPeriodLabel(period);
  const ids = coins.map(coin => coin.id);
  const chartKey = `comparison:${ids.join(",")}:${period}`;
  const comparisonPreset = String(state.dataBroker?.comparison?.preset || "manual");
  const strictAtomicComparison = ATLAS_SCANNER_PRESETS.has(comparisonPreset);
  const requiredSeriesCount = strictAtomicComparison ? coins.length : 1;
  const previousChartState = state.dataBroker.chart;
  const previousComparisonState = {
    ...state.dataBroker.comparison,
    ids: [...(state.dataBroker.comparison.ids || [])],
    pendingIds: [...(state.dataBroker.comparison.pendingIds || [])],
    unavailableIds: [...(state.dataBroker.comparison.unavailableIds || [])],
    renderedIds: [...(state.dataBroker.comparison.renderedIds || [])],
    results: { ...(state.dataBroker.comparison.results || {}) }
  };
  const previousRenderedIds = [...(state.dataBroker.comparison.renderedIds || [])];

  state.dataBroker.comparison.status = "loading";
  state.dataBroker.comparison.pendingIds = [...ids];
  state.dataBroker.comparison.unavailableIds = [];
  state.dataBroker.comparison.results = {};
  state.dataBroker.comparison.renderedIds = previousRenderedIds;
  state.dataBroker.comparison.error = null;
  state.dataBroker.comparison.completionAttempt = 0;
  state.dataBroker.comparison.completionKey = null;

  state.dataBroker.chart = {
    status: "loading",
    coinId: state.selectedCoinId,
    period,
    source: atlasComparisonPreferredSourceFamily() === "binance" ? "Binance" : "CoinGecko",
    mode: "comparison-base100",
    timestamp: null,
    pointCount: 0,
    contextKey: chartKey,
    result: null,
    error: null
  };

  atlasChartSetPeriodButtons(period, true);
  setText(els.selectedAssetTitle, `Comparaison ${coins.map(coin => coin.symbol).join(" + ")}`);

  const preservedChart = strictAtomicComparison
    ? !!state.chartEngineV2?.realChart
    : drawChartLoading(
        els.mainChart,
        `Comparaison ${periodLabel} · 0/${coins.length}`,
        "Le graphe précédent reste visible pendant la recherche des séries cohérentes."
      );

  if (!strictAtomicComparison && !preservedChart && els.chartCaption) {
    atlasSetChartCaptionText(
      `Comparaison ${periodLabel} en préparation · les séries valides seront affichées dès qu’elles sont prêtes.`
    );
  }
  atlasRenderComparisonControls();
  renderMarketTable();

  const fetched = [];
  for (let index = 0; index < coins.length; index += 1) {
    if (renderToken !== state.comparisonRenderToken || controller.signal.aborted || !atlasComparisonActive()) return;
    const coin = coins[index];

    if (preservedChart && !strictAtomicComparison) {
      atlasUpdateChartRefresh(`Série ${index + 1}/${coins.length} · ${coin.symbol}`);
    } else if (!strictAtomicComparison && els.chartCaption) {
      atlasSetChartCaptionText(
        `Comparaison ${periodLabel} · lecture ${index + 1}/${coins.length} · ${coin.symbol}.`
      );
    }

    let fetchedItem;
    try {
      fetchedItem = await atlasFetchComparisonSeriesResilient(
        coin,
        period,
        { signal: controller.signal }
      );
    } catch (error) {
      if (atlasComparisonAbortError(error)) return;
      fetchedItem = {
        coin,
        result: {
          series: [],
          blocked: true,
          reason: String(error?.message || error)
        },
        error
      };
    }

    fetched.push(fetchedItem);
    state.dataBroker.comparison.pendingIds =
      (state.dataBroker.comparison.pendingIds || [])
        .filter(id => id !== coin.id);

    if (
      fetchedItem?.result
      && !fetchedItem.result.blocked
      && Array.isArray(fetchedItem.result.series)
      && fetchedItem.result.series.length
    ) {
      state.dataBroker.comparison.results = {
        ...(state.dataBroker.comparison.results || {}),
        [coin.id]: fetchedItem.result
      };
    } else {
      state.dataBroker.comparison.unavailableIds = [
        ...new Set([
          ...(state.dataBroker.comparison.unavailableIds || []),
          coin.id
        ])
      ];
    }

    renderMarketTable();
  }

  if (renderToken !== state.comparisonRenderToken || controller.signal.aborted || !atlasComparisonActive()) return;

  const rawEntries = fetched.filter(item =>
    item?.coin
    && item?.result
    && !item.result.blocked
    && Array.isArray(item.result.series)
    && item.result.series.length
  );

  const normalizedEntries = strictAtomicComparison
    ? atlasBuildAlignedComparisonEntries(rawEntries, period)
    : atlasBuildBestAlignedComparisonEntries(rawEntries, period, coins.length);
  const normalizedIds = new Set(normalizedEntries.map(entry => entry.coin.id));
  const networkFailures = fetched.filter(item => item?.error || item?.result?.blocked);
  const alignmentFailures = rawEntries.filter(entry => !normalizedIds.has(entry.coin.id));
  const unavailableIds = [...new Set([
    ...networkFailures.map(item => item?.coin?.id),
    ...alignmentFailures.map(item => item?.coin?.id)
  ].filter(Boolean))];

  state.dataBroker.comparison.results = Object.fromEntries(
    normalizedEntries.map(entry => [entry.coin.id, entry.result])
  );
  state.dataBroker.comparison.pendingIds = [];
  state.dataBroker.comparison.unavailableIds = unavailableIds;
  state.dataBroker.comparison.error = null;

  if (normalizedEntries.length >= requiredSeriesCount) {
    const drawnEntries = drawComparisonChart(els.mainChart, normalizedEntries, period, chartKey);

    if (drawnEntries.length >= requiredSeriesCount) {
      const drawnIds = new Set(drawnEntries.map(entry => entry.coin.id));
      const finalUnavailableIds = [...new Set([
        ...unavailableIds,
        ...normalizedEntries.filter(entry => !drawnIds.has(entry.coin.id)).map(entry => entry.coin.id)
      ])];

      state.dataBroker.comparison.renderedIds = drawnEntries.map(entry => entry.coin.id);
      state.dataBroker.comparison.unavailableIds = finalUnavailableIds;
      state.dataBroker.comparison.results = Object.fromEntries(
        drawnEntries.map(entry => [entry.coin.id, entry.result])
      );
      state.dataBroker.comparison.status = finalUnavailableIds.length ? "partial" : "ready";

      const latestTimestamp = Math.max(...drawnEntries.map(entry =>
        Number(entry.result?.integrity?.metrics?.lastTimestamp || 0)
      ));
      const pointCount = drawnEntries.reduce(
        (sum, entry) => sum + Number(entry.result?.series?.length || 0),
        0
      );
      const comparisonResult = {
        comparison: true,
        entries: drawnEntries,
        periodDays: period,
        sourceMode: "comparison-base100",
        source: `${atlasChartProviderLabel({ comparison: true, entries: drawnEntries })} · historiques EUR · Base 100`
      };
      const retryCount = fetched.reduce(
        (sum, item) => sum + Math.max(0, Number(item?.attempts || 0) - 1),
        0
      );

      state.dataBroker.chart = {
        status: "ready",
        coinId: state.selectedCoinId,
        period,
        source: atlasChartProviderLabel({ comparison: true, entries: drawnEntries }),
        mode: "comparison-base100",
        timestamp: Number.isFinite(latestTimestamp) && latestTimestamp > 0
          ? new Date(latestTimestamp).toISOString()
          : null,
        pointCount,
        latencyMs: null,
        retryCount,
        contextKey: chartKey,
        result: comparisonResult,
        error: finalUnavailableIds.length
          ? `${finalUnavailableIds.length} série(s) non affichable(s)`
          : null
      };

      setText(
        els.selectedAssetTitle,
        `Comparaison ${drawnEntries.map(entry => entry.coin.symbol).join(" + ")}`
      );
      atlasRenderComparisonDetail(drawnEntries, period);
      atlasChartV2RenderLegend(drawnEntries, { comparison: true });
      atlasRenderComparisonCaption(drawnEntries, period, finalUnavailableIds, coins.length);
      atlasChartV2SyncControls();
      atlasTrackAudience("chart_comparison_loaded", {
        assets: drawnEntries.map(entry => entry.coin.id),
        days: period,
        displayed: drawnEntries.length,
        unavailable: finalUnavailableIds.length
      });
      atlasWorkspaceScheduleSave(120);
    } else {
      state.dataBroker.comparison.renderedIds = previousRenderedIds;
      state.dataBroker.comparison.status = "blocked";
    }
  } else {
    state.dataBroker.comparison.renderedIds = previousRenderedIds;
    state.dataBroker.comparison.status = "blocked";
  }

  if (state.dataBroker.comparison.status === "blocked") {
    state.dataBroker.comparison.error = "comparaison incomplète";
    if (previousChartState?.status === "ready") {
      state.dataBroker.chart = previousChartState;
      state.dataBroker.comparison = previousComparisonState;
      atlasHideChartRefresh();
      atlasChartV2RedrawFromBroker();
    } else {
      state.dataBroker.chart = {
        status: "blocked",
        coinId: state.selectedCoinId,
        period,
        source: atlasComparisonPreferredSourceFamily() === "binance" ? "Binance" : "CoinGecko",
        mode: "comparison-base100",
        timestamp: null,
        pointCount: 0,
        contextKey: chartKey,
        result: null,
        error: "aucune courbe cohérente"
      };
      state.dataBroker.comparison.renderedIds = [];
      drawChartBlocked(els.mainChart);
      if (els.chartCaption) {
        atlasSetChartCaptionText(
          `Comparaison ${periodLabel} indisponible : aucune série réelle cohérente n’est disponible pour cette sélection.`
        );
      }
    }
  }

  atlasRenderComparisonControls();
  renderMarketTable();
  atlasChartSetPeriodButtons(period, false);
  state.chartEngineV2.loading = false;
  atlasRenderBrokerStrip();
  renderMultiHorizon();
  renderAtlasMathCore();
}

function atlasNormalizeSparkline(values) {
  if (!Array.isArray(values)) return [];
  return values.map(Number).filter(value => Number.isFinite(value) && value > 0);
}

function sparkSvg(c) {
  const data = atlasNormalizeSparkline(c?.sparkline7d);
  if (data.length < 10) return '<span class="sparkline-empty" aria-label="Sparkline réelle CoinGecko indisponible">—</span>';
  const min = Math.min(...data);
  const max = Math.max(...data);
  const points = data.map((value, index) => {
    const x = (index / (data.length - 1)) * 112;
    const y = 26 - ((value - min) / (max - min || 1)) * 24;
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(" ");
  const trendClass = data[data.length - 1] >= data[0] ? "spark-up" : "spark-down";
  return `<svg class="sparkline ${trendClass}" viewBox="0 0 112 28" role="img" aria-label="Sparkline réelle CoinGecko sur 7 jours"><polyline points="${points}" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round" opacity=".95"/></svg>`;
}

function atlasCurrentDetailChartContext(coin = getSelectedCoin()) {
  const period = Number(state.chartPeriodDays || 1);
  const chart = state.dataBroker?.chart || null;
  const comparison = state.dataBroker?.comparison || null;

  if (!coin?.id) return null;
  if (
    chart?.status !== "ready"
    || chart?.period !== period
    || !atlasChartContextMatches(chart)
  ) return null;

  const comparisonActive =
    chart?.result?.comparison === true
    || chart?.mode === "comparison-base100"
    || atlasComparisonActive();

  if (comparisonActive) {
    const renderedIds = Array.isArray(comparison?.renderedIds)
      ? comparison.renderedIds
      : [];
    const result = comparison?.results?.[coin.id] || null;

    if (!renderedIds.includes(coin.id) || !result) return null;

    return {
      result,
      scope: "comparison",
      preset: comparison?.preset || "manual",
      coinId: coin.id,
      period
    };
  }

  if (chart?.coinId !== coin.id || !chart?.result) return null;

  return {
    result: chart.result,
    scope: "solo",
    preset: "solo",
    coinId: coin.id,
    period
  };
}

function atlasCurrentDetailChartResult(coin = getSelectedCoin()) {
  return atlasCurrentDetailChartContext(coin)?.result || null;
}

function atlasRefreshSelectedDetailOnly() {
  const coin = getSelectedCoin();
  if (!coin) return;

  const chart = state.dataBroker?.chart || null;
  const detailContext = atlasCurrentDetailChartContext(coin);
  const period = Number(state.chartPeriodDays || 1);
  const chartAligned = chart?.period === period && atlasChartContextMatches(chart);
  const mode = detailContext?.result
    ? "valid"
    : chartAligned && chart?.status === "blocked"
      ? "blocked"
      : "loading";

  atlasRenderAssetDetail(
    coin,
    period,
    detailContext?.result || null,
    mode
  );
}

function atlasRenderCompactDetailSummary(coin = null) {
  const strip = document.getElementById("detailCompactStrip");

  if (!coin) {
    setText(els.detailCompactAsset, "Aucune sélection");
    setText(els.detailCompactPrice, "—");
    setText(els.detailCompactDecision, "Choisir un actif");
    setText(els.detailCompactChange, "—");
    els.detailCompactChange?.classList.remove("pos", "neg", "neutral");

    if (strip) {
      strip.style.removeProperty("--active-crypto-color");
      strip.style.removeProperty("--active-crypto-gradient");
      strip.dataset.activeCryptoId = "";
      strip.dataset.changeState = "neutral";
    }
    return;
  }

  const quote = atlasCurrentQuoteForCoin(coin);
  const price = atlasQuoteIsUsable(quote)
    ? Number(quote.price)
    : Number(coin.priceEur ?? coin.price);
  const change = Number.isFinite(Number(quote?.change24h))
    ? Number(quote.change24h)
    : Number(coin.change24h);
  const changeState = clsPct(Number.isFinite(change) ? change : null);
  const palette = atlasCryptoPalette(
    coin,
    Math.max(0, Number(coin.rank || 1) - 1)
  );

  if (strip) {
    strip.style.setProperty("--active-crypto-color", palette.primary);
    strip.style.setProperty(
      "--active-crypto-gradient",
      atlasCryptoGradientCss(
        coin,
        Math.max(0, Number(coin.rank || 1) - 1)
      )
    );
    strip.dataset.activeCryptoId = coin.id || "";
    strip.dataset.changeState = changeState;
  }

  setText(
    els.detailCompactAsset,
    String(coin.symbol || coin.name || "ACTIF").toUpperCase()
  );
  setText(
    els.detailCompactPrice,
    Number.isFinite(price) ? atlasFormatEUR(price) : "—"
  );
  setText(els.detailCompactDecision, beginnerDecision(coin));
  setText(
    els.detailCompactChange,
    Number.isFinite(change) ? fmtPct(change) : "—"
  );

  if (els.detailCompactChange) {
    els.detailCompactChange.classList.remove("pos", "neg", "neutral");
    els.detailCompactChange.classList.add(changeState);
  }
}

function atlasRenderChartResult(c, period, result, chartKey, forceRedraw = false) {
  atlasBrokerCommitChart(c, period, result, "ready");
  const periodLabel = atlasChartPeriodLabel(period);
  const fingerprint = atlasChartResultFingerprint(result);
  const viewFingerprint = `${fingerprint}:${atlasChartV2EffectiveView()}:${atlasChartV2EffectiveScale()}:${state.chartViewV2.volume}:${atlasChartV2ComparisonMode()?state.chartViewV2.comparisonLegend:state.chartViewV2.legend}`;
  const alreadyRendered = state.chartEngineV2.lastRenderedKey === chartKey && state.chartEngineV2.lastFingerprint === viewFingerprint && state.chartEngineV2.realChart;
  if (forceRedraw || !alreadyRendered) drawLineChart(els.mainChart, result.series, `${c.symbol} ${periodLabel}`, result, chartKey);
  atlasRenderAssetDetail(c, period, result, "valid");
  renderMultiHorizon();
  renderAtlasMathCore();
  if (els.chartCaption) {
    const freshness = result?.integrity?.metrics?.freshness;
    const truth = atlasChartTruth(result, period);
    const warning = result?.refreshWarning
      ? ` · ${result.refreshWarning}`
      : truth.source === "cache" && freshness?.level === "fresh"
        ? ` · cache récent exact du ${truth.exact}`
        : freshness?.level === "delayed"
          ? ` · données différées (${freshness.label})`
          : freshness?.level === "archive"
            ? ` · archive réelle datée (${freshness.label})`
            : "";
    atlasRenderSingleCaption(c, periodLabel, result, warning);
  }
  atlasWorkspaceScheduleSave(120);
}

function atlasClearChartRetryTimer() {
  if (state.chartEngineV2?.retryTimer) {
    clearTimeout(state.chartEngineV2.retryTimer);
    state.chartEngineV2.retryTimer = null;
  }
}

function atlasResetChartRetry(key = "") {
  atlasClearChartRetryTimer();
  if (!state.chartEngineV2) return;
  state.chartEngineV2.retryKey = key;
  if (key) state.chartEngineV2.retryAttempts[key] = 0;
}

function atlasChartRetryPending(key) {
  return !!state.chartEngineV2?.retryTimer && state.chartEngineV2.retryKey === key;
}

function atlasScheduleChartAutoRetry(c, period, reason = "réponse réseau tardive") {
  if (!c?.id || !state.chartEngineV2) return false;
  const key = atlasChartKey(c, period);
  const attempts = Number(state.chartEngineV2.retryAttempts[key] || 0);
  if (attempts >= ATLAS_CHART_SELECTION_AUTO_RETRIES) return false;
  const retryDelayMs = ATLAS_CHART_SELECTION_RETRY_DELAYS_MS[Math.min(attempts, ATLAS_CHART_SELECTION_RETRY_DELAYS_MS.length - 1)];
  atlasClearChartRetryTimer();
  state.chartEngineV2.retryKey = key;
  state.chartEngineV2.retryAttempts[key] = attempts + 1;
  state.dataBroker.chart = {
    status: "loading", coinId: c.id, period: Number(period || 1), source: atlasChartPreferredProviderLabel(c),
    mode: "none", timestamp: null, pointCount: 0, latencyMs: null, retryCount: attempts + 1,
    contextKey: atlasExpectedChartContextKey([c.id], Number(period || 1)), result: null, error: String(reason || "")
  };
  atlasRenderAssetDetail(c, period, null, "loading");
  atlasChartSetPeriodButtons(period, true);
  drawChartLoading(
    els.mainChart,
    `${c.symbol} ${atlasChartPeriodLabel(period)} · nouvelle tentative automatique`,
    `La première lecture n’a pas répondu assez vite. Atlas réessaie automatiquement sans changer d’actif ni de période.`
  );
  if (els.chartCaption) {
    atlasSetChartCaptionText(`Graphique ${c.symbol} · période ${atlasChartPeriodLabel(period)} · nouvelle tentative automatique dans ${Math.round(retryDelayMs / 1000)} s.`);
  }
  state.chartEngineV2.retryTimer = setTimeout(() => {
    state.chartEngineV2.retryTimer = null;
    if (state.selectedCoinId !== c.id || Number(state.chartPeriodDays || 1) !== Number(period || 1)) return;
    void renderAnalystPanel({ recovery: true });
  }, retryDelayMs);
  return true;
}

function atlasPrepareChartSelection(coin, period = 1, options = {}) {
  if (!coin?.id) return;
  if (state.chartEngineV2?.controller) {
    try { state.chartEngineV2.controller.abort(); } catch {}
  }
  const normalizedPeriod = Number(period || 1);
  state.selectedCoinId = coin.id;
  state.chartPeriodDays = normalizedPeriod;
  if (!options.preserveComparison) atlasSetComparisonIds([coin.id], coin.id, { preset: options.preset || "solo" });
  const key = atlasChartKey(coin, normalizedPeriod);
  atlasResetChartRetry(key);
  state.dataBroker.chart = {
    status: "loading", coinId: coin.id, period: normalizedPeriod, source: atlasChartPreferredProviderLabel(coin),
    mode: "none", timestamp: null, pointCount: 0,
    contextKey: atlasExpectedChartContextKey([coin.id], normalizedPeriod), result: null, error: null
  };
  atlasBrokerSeedSpot(coin);
  atlasChartSetPeriodButtons(normalizedPeriod, true);
}

async function renderAnalystPanel(options = {}) {
  if ((atlasScannerTransaction || atlasScannerQueuedRequest) && options.allowDuringScanner !== true) return;
  if (!options.forceSingle && atlasComparisonActive()) return renderComparisonAnalystPanel(options);
  const c = getSelectedCoin();
  const anticipatedPeriod = Number(state.chartPeriodDays || 1);
  const anticipatedKey = c ? atlasChartKey(c, anticipatedPeriod) : "";
  if (c && !options.recovery && state.chartEngineV2?.loading && state.chartEngineV2?.activeRequestKey === anticipatedKey) {
    atlasRenderAssetDetail(c, anticipatedPeriod, state.dataBroker.chart?.result || null, "loading");
    atlasChartSetPeriodButtons(anticipatedPeriod, true);
    return;
  }
  atlasClearChartRetryTimer();
  const renderToken = ++state.chartRenderToken;
  if (state.chartEngineV2?.controller) {
    try { state.chartEngineV2.controller.abort(); } catch {}
  }
  if (!c) {
    atlasChartSetPeriodButtons(Number(state.chartPeriodDays || 1), false);
    setText(els.selectedAssetTitle, "Aucun actif sélectionné");
    state.dataBroker.chart = { ...state.dataBroker.chart, status: "blocked", coinId: null, contextKey: atlasExpectedChartContextKey([], Number(state.chartPeriodDays || 1)), result: null };
    if (state.liveOk) {
      drawChartMessage(els.mainChart, "loading", "Sélection libre", "Clique une ligne du MARKET SNAPSHOT pour afficher son historique réel.", "La sélection peut rester vide.");
      if (els.chartCaption) atlasSetChartCaptionText("Aucune crypto sélectionnée · clique une ligne du MARKET SNAPSHOT.");
    } else {
      drawChartBlocked(els.mainChart);
      if (els.chartCaption) atlasSetChartCaptionText("Graphique indisponible · Livecheck requis.");
    }
    atlasRenderBrokerStrip();
    renderMultiHorizon();
    return;
  }

  state.selectedCoinId = c.id;
  atlasBrokerSeedSpot(c);
  atlasRenderBrokerStrip();
  // Le snapshot Top 250 alimente déjà le détail. Aucun appel spot concurrent au graphique.

  const coinId = c.id;
  const period = Number(state.chartPeriodDays || 1);
  const periodLabel = atlasChartPeriodLabel(period);
  const chartKey = atlasChartKey(c, period);
  const controller = new AbortController();
  state.chartEngineV2.token = renderToken;
  state.chartEngineV2.controller = controller;
  state.chartEngineV2.lastKey = chartKey;
  state.chartEngineV2.activeRequestKey = chartKey;
  state.chartEngineV2.loading = true;
  setText(els.selectedAssetTitle, `${c.name} — ${c.symbol}`);

  const stored = atlasGetStoredChartResult(c, period);
  if (stored) {
    atlasRenderChartResult(c, period, stored, chartKey);
    if (!atlasChartNeedsRefresh(stored, period)) {
      delete state.chartEngineV2.retryAttempts[chartKey];
      state.chartEngineV2.retryKey = "";
      atlasChartSetPeriodButtons(period, false);
      return;
    }
    atlasChartSetPeriodButtons(period, true);
    atlasShowChartRefresh(els.mainChart, `${c.symbol} ${periodLabel} · actualisation discrète`);
  } else {
    state.dataBroker.chart = { status: "loading", coinId, period, source: atlasChartPreferredProviderLabel(c), mode: "none", timestamp: null, pointCount: 0, contextKey: atlasExpectedChartContextKey([coinId], period), result: null, error: null };
    atlasRenderAssetDetail(c, period, null, "loading");
    atlasChartSetPeriodButtons(period, true);
    drawChartLoading(els.mainChart, `${c.symbol} ${periodLabel} · chargement`, `Atlas interroge ${atlasChartPreferredProviderLabel(c)} pour cette série historique réelle.`);
    if (els.chartCaption) atlasSetChartCaptionText(`Graphique ${c.symbol} · période ${periodLabel} · première série réelle en cours.`);
  }

  const chartStartedAt = performance.now();
  try {
    const result = await fetchChartSeries(c, period, { signal: controller.signal, fallback: stored });
    const chartLatencyMs = Math.round(performance.now() - chartStartedAt);
    if (renderToken !== state.chartRenderToken || state.selectedCoinId !== coinId || Number(state.chartPeriodDays || 1) !== period) return;
    if (result.blocked || !Array.isArray(result.series) || !result.series.length) {
      if (stored) atlasRenderChartResult(c, period, { ...stored, refreshWarning: "Actualisation indisponible. Dernière série réelle conservée." }, chartKey);
      else if (!atlasScheduleChartAutoRetry(c, period, result.technicalReason || result.reason || "réponse réseau tardive")) {
        state.dataBroker.chart = { status: "blocked", coinId, period, source: atlasChartPreferredProviderLabel(c), mode: "none", timestamp: null, pointCount: 0, latencyMs: chartLatencyMs, retryCount: Number(state.chartEngineV2.retryAttempts[chartKey] || 0), contextKey: atlasExpectedChartContextKey([coinId], period), result, error: result.technicalReason || result.reason || null };
        drawChartBlocked(els.mainChart);
        atlasRenderAssetDetail(c, period, result, "blocked");
        if (els.chartCaption) atlasSetChartCaptionText(`Graphique ${c.symbol} · période ${periodLabel} · temporairement indisponible après nouvelle tentative automatique.`);
        atlasTrackAudience("chart_error", { asset: c.id, symbol: c.symbol, days: period, reason: String(result.technicalReason || result.reason || "indisponible") });
      }
      return;
    }

    const backgroundDirect = result.backgroundDirect;
    const cleanResult = {
      ...result,
      diagnostics: {
        ...(result?.diagnostics || {}),
        latencyMs: chartLatencyMs,
        retryCount: Number(state.chartEngineV2.retryAttempts[chartKey] || 0),
        cacheUsed: result?.sourceMode === "browser-cache"
      }
    };
    delete cleanResult.backgroundDirect;
    atlasStoreChartResult(c, period, cleanResult);
    if (period === 36500) atlasWriteChartMaxTruth(cleanResult, c);
    delete state.chartEngineV2.retryAttempts[chartKey];
    state.chartEngineV2.retryKey = "";
    atlasRenderChartResult(c, period, cleanResult, chartKey);
    atlasTrackAudience("chart_loaded", { asset: c.id, symbol: c.symbol, days: period, points: cleanResult.series?.length || 0 });

    if (backgroundDirect) {
      const upgraded = await backgroundDirect;
      if (upgraded?.ok && upgraded.value && renderToken === state.chartRenderToken && state.selectedCoinId === coinId && Number(state.chartPeriodDays || 1) === period) {
        atlasStoreChartResult(c, period, upgraded.value);
        if (period === 36500) atlasWriteChartMaxTruth(upgraded.value, c);
        atlasRenderChartResult(c, period, upgraded.value, chartKey, true);
      }
    }
  } catch (error) {
    if (error?.name === "AbortError") return;
    if (renderToken !== state.chartRenderToken || state.selectedCoinId !== coinId || Number(state.chartPeriodDays || 1) !== period) return;
    if (stored) atlasRenderChartResult(c, period, { ...stored, refreshWarning: "Actualisation indisponible. Dernière série réelle conservée." }, chartKey);
    else if (!atlasScheduleChartAutoRetry(c, period, String(error?.message || error))) {
      state.dataBroker.chart = { status: "blocked", coinId, period, source: atlasChartPreferredProviderLabel(c), mode: "none", timestamp: null, pointCount: 0, latencyMs: Math.round(performance.now() - chartStartedAt), retryCount: Number(state.chartEngineV2.retryAttempts[chartKey] || 0), contextKey: atlasExpectedChartContextKey([coinId], period), result: null, error: String(error?.message || error) };
      drawChartBlocked(els.mainChart);
      atlasRenderAssetDetail(c, period, { reason: "indisponibilité réseau" }, "blocked");
      if (els.chartCaption) atlasSetChartCaptionText(`Graphique ${c.symbol} · période ${periodLabel} · temporairement indisponible après nouvelle tentative automatique.`);
    }
  } finally {
    if (renderToken === state.chartRenderToken && Number(state.chartPeriodDays || 1) === period && !atlasChartRetryPending(chartKey)) {
      atlasChartSetPeriodButtons(period, false);
      if (state.chartEngineV2?.activeRequestKey === chartKey) {
        state.chartEngineV2.activeRequestKey = "";
        state.chartEngineV2.loading = false;
      }
    }
    atlasRenderBrokerStrip();
  }
}

function atlasComparisonResultForCoin(coin, selection = atlasComparisonIds()) {
  if (!coin?.id || !selection.includes(coin.id)) return null;

  const comparisonResult = state.dataBroker?.comparison?.results?.[coin.id];
  if (comparisonResult) return comparisonResult;

  const chart = state.dataBroker?.chart;
  if (
    selection.length === 1
    && chart?.status === "ready"
    && chart?.coinId === coin.id
    && atlasChartContextMatches(chart)
  ) {
    return chart.result || null;
  }

  return null;
}

function atlasComparisonSeriesReadiness(coin, selection = atlasComparisonIds()) {
  const selected = !!coin?.id && selection.includes(coin.id);
  if (!selected) {
    return {
      selected: false,
      state: "available",
      label: "",
      title: "Actif non sélectionné"
    };
  }

  const comparison = state.dataBroker?.comparison || {};
  const result = atlasComparisonResultForCoin(coin, selection);
  const pending = new Set(comparison.pendingIds || []).has(coin.id);
  const unavailable = new Set(comparison.unavailableIds || []).has(coin.id);
  const rendered = new Set(comparison.renderedIds || []).has(coin.id)
    || (
      selection.length === 1
      && state.dataBroker?.chart?.status === "ready"
      && state.dataBroker?.chart?.coinId === coin.id
      && atlasChartContextMatches(state.dataBroker.chart)
    );

  if (pending || (comparison.status === "loading" && !result && !unavailable)) {
    return {
      selected: true,
      state: "loading",
      label: "Chargement…",
      title: `Chargement de la série ${atlasChartPeriodLabel(state.chartPeriodDays)}`
    };
  }

  if (result) {
    const points = Math.max(
      0,
      Number(
        result?.integrity?.metrics?.pointCount
        ?? result?.series?.length
        ?? 0
      )
    );
    const rules = atlasChartRules(state.chartPeriodDays);
    const integrityOk = result?.integrity?.ok !== false;
    const coverageHours = Number(result?.integrity?.metrics?.coverageHours || 0);
    const complete = integrityOk
      && points >= Number(rules?.minPoints || 1)
      && coverageHours >= Number(rules?.minCoverageHours || 0);

    if (!complete) {
      return {
        selected: true,
        state: "incomplete",
        label: `Incomplète · ${points} pts`,
        title: result?.integrity?.reason || "Série historique incomplète"
      };
    }

    const freshness = atlasChartWorstFreshness(result, state.chartPeriodDays);
    const normalizedMode = atlasChartSourceMode(result);
    const rawMode = String(
      result?.originalSourceMode
      || result?.sourceMode
      || ""
    ).toLowerCase();
    const sourceMode = normalizedMode === "direct" || rawMode.includes("direct")
      ? "direct"
      : normalizedMode === "cache" || rawMode.includes("cache")
        ? "cache"
        : normalizedMode;
    const provider = atlasChartProviderLabel(result);

    if (freshness === "archive") {
      return {
        selected: true,
        state: "archive",
        label: `Archive · ${points} pts`,
        title: `${provider} · série réelle archivée · ${points} points`
      };
    }

    if (freshness === "delayed") {
      return {
        selected: true,
        state: sourceMode === "cache" ? "cache" : "delayed",
        label: `${sourceMode === "cache" ? "Cache retardé" : "Direct retardé"} · ${points} pts`,
        title: `${provider} · historique retardé · ${points} points`
      };
    }

    if (sourceMode === "cache") {
      return {
        selected: true,
        state: "cache",
        label: `Cache récent · ${points} pts`,
        title: `${provider} · cache historique récent · ${points} points`
      };
    }

    if (sourceMode === "direct") {
      return {
        selected: true,
        state: rendered ? "direct" : "validated",
        label: `${rendered ? "Direct" : "Validée"} · ${points} pts`,
        title: `${provider} · série historique ${rendered ? "affichée" : "validée"} · ${points} points`
      };
    }

    return {
      selected: true,
      state: rendered ? "ready" : "validated",
      label: `${rendered ? "Prête" : "Validée"} · ${points} pts`,
      title: `${provider} · ${points} points historiques`
    };
  }

  if (unavailable || ["partial", "blocked"].includes(comparison.status)) {
    const quote = atlasCurrentQuoteForCoin(coin);
    const spotOnly = atlasQuoteIsUsable(quote);
    return {
      selected: true,
      state: spotOnly ? "spot-only" : "unavailable",
      label: spotOnly ? "Prix direct seul" : "Indisponible",
      title: spotOnly
        ? "Prix courant disponible, historique non affichable"
        : "Prix et historique indisponibles"
    };
  }

  return {
    selected: true,
    state: "waiting",
    label: "Historique en attente",
    title: "Série sélectionnée, chargement historique non démarré"
  };
}

function atlasComparisonSeriesReadinessMarkup(coin, selection = atlasComparisonIds()) {
  const readiness = atlasComparisonSeriesReadiness(coin, selection);
  return `<small class="market-series-status is-${escapeHtml(readiness.state)}" data-series-state="${escapeHtml(readiness.state)}" title="${escapeHtml(readiness.title)}" ${readiness.selected ? "" : "hidden"}>${escapeHtml(readiness.label)}</small>`;
}

const ATLAS_MEMORY_COVERAGE_HORIZONS = Object.freeze([1, 7, 30, 60, 90]);

function atlasMemoryHorizonStatus(analysis, days) {
  const periodMs = Math.max(1, Number(days || 1)) * 86_400_000;
  const spanRatio = Math.min(1, analysis.spanMs / periodMs);
  const cadence = Number.isFinite(analysis.medianCadenceMs)
    ? Math.max(30_000, analysis.medianCadenceMs)
    : ATLAS_MARKET_REFRESH_MS;
  const expectedRecords = Math.max(2, Math.floor(periodMs / cadence) + 1);
  const densityRatio = Math.min(1, analysis.validRecords / expectedRecords);
  const excessGapMs = analysis.gapCount
    ? Math.max(0, analysis.largestGapMs - analysis.gapThresholdMs)
    : 0;
  const continuityPenalty = Math.min(0.55, excessGapMs / periodMs);
  const score = Math.max(
    0,
    Math.min(
      100,
      Math.round((spanRatio * 0.62 + densityRatio * 0.38) * (1 - continuityPenalty) * 100)
    )
  );

  let tone = "missing";
  let label = "Insuffisante";
  if (analysis.spanMs >= periodMs && score >= 70) {
    tone = "ok";
    label = "Solide";
  } else if (analysis.spanMs >= periodMs) {
    tone = "warn";
    label = "Fragmentée";
  } else if (analysis.spanMs >= periodMs * 0.25) {
    tone = "partial";
    label = "Partielle";
  }

  return {
    days,
    score,
    tone,
    label,
    spanRatio,
    densityRatio,
    expectedRecords
  };
}

function atlasChartCacheCoverageByPeriod() {
  const store = atlasReadLocalChartStore();
  const result = Object.fromEntries(ATLAS_MEMORY_COVERAGE_HORIZONS.map(days => [days, {
    valid: 0,
    total: 0,
    coins: [],
    latestSavedAt: null
  }]));

  for (const [key, stored] of Object.entries(store || {})) {
    const separator = key.lastIndexOf(":");
    const period = Number(separator >= 0 ? key.slice(separator + 1) : 0);
    if (!result[period]) continue;

    result[period].total += 1;
    const series = atlasNormalizeChartPayload({ prices: stored?.series });
    const coverageHours = atlasChartCoverageHours(series);
    const rules = atlasChartRules(period);
    if (
      Array.isArray(series)
      && series.length >= rules.minPoints
      && coverageHours >= rules.minCoverageHours
    ) {
      result[period].valid += 1;
      const coinId = separator >= 0 ? key.slice(0, separator) : key;
      if (coinId) result[period].coins.push(coinId);
      const savedAt = Number(stored?.savedAt || 0);
      if (savedAt > Number(result[period].latestSavedAt || 0)) {
        result[period].latestSavedAt = savedAt;
      }
    }
  }

  return result;
}

function atlasApplyRequestedPeriod(period) {
  const nextPeriod = Number(period || 1);
  const pendingPreset = atlasScannerTransaction?.preset || atlasScannerQueuedRequest?.preset || null;
  const committedPreset = String(state.dataBroker?.comparison?.preset || "");
  const scannerPreset = pendingPreset || (ATLAS_SCANNER_PRESETS.has(committedPreset) ? committedPreset : null);

  if (scannerPreset) {
    atlasScannerCancel("changement de période");
    state.chartPeriodDays = nextPeriod;
    atlasChartSetPeriodButtons(nextPeriod, true);
    atlasScannerStart(scannerPreset, 5);
    return;
  }

  const coin = getSelectedCoin();
  if (!coin) return;
  state.chartPeriodDays = nextPeriod;
  atlasChartSetPeriodButtons(nextPeriod, true);
  if (atlasComparisonActive()) {
    if (state.chartEngineV2?.controller) { try { state.chartEngineV2.controller.abort(); } catch {} }
    requestAnimationFrame(() => { void renderAnalystPanel({ periodChange: true }); });
  } else {
    atlasPrepareChartSelection(coin, nextPeriod);
    requestAnimationFrame(() => { void renderAnalystPanel({ periodChange: true, forceSingle: true }); });
  }
  atlasWorkspaceWrite();
}

function atlasAccessRandomHex(bytes = 16) {
  const data = new Uint8Array(bytes);
  crypto.getRandomValues(data);
  return [...data].map(value => value.toString(16).padStart(2, "0")).join("");
}

function atlasStrictGraphContract(period, chart, chartResult, comparisonIds, chartTruth) {
  const rows = [];

  if (chartResult?.comparison && Array.isArray(chartResult.entries)) {
    chartResult.entries.forEach(entry => {
      const coin = entry?.coin || {};
      const metrics = entry?.result?.integrity?.metrics || {};
      rows.push({
        symbol: String(coin.symbol || coin.name || "").toUpperCase() || null,
        series_change_pct: atlasStrictNumber(metrics.changePct, 2),
        points: atlasStrictNumber(metrics.pointCount ?? entry?.result?.series?.length, 0),
        first_time: atlasStrictTimestamp(metrics.firstTimestamp),
        last_time: atlasStrictTimestamp(metrics.lastTimestamp),
        source_mode: entry?.result?.sourceMode || null
      });
    });
  } else if (chartResult) {
    const coin = atlasSelectedCoin();
    const metrics = chartResult?.integrity?.metrics || {};
    rows.push({
      symbol: String(coin?.symbol || coin?.name || "").toUpperCase() || null,
      series_change_pct: atlasStrictNumber(metrics.changePct, 2),
      points: atlasStrictNumber(metrics.pointCount ?? chartResult?.series?.length, 0),
      first_time: atlasStrictTimestamp(metrics.firstTimestamp),
      last_time: atlasStrictTimestamp(metrics.lastTimestamp),
      source_mode: chartResult?.sourceMode || null
    });
  }

  const comparable = rows.filter(row => Number.isFinite(row.series_change_pct));
  const ordered = [...comparable].sort((a, b) => b.series_change_pct - a.series_change_pct);

  return {
    period_days: period,
    period_label: (() => {
      try { return atlasChartPeriodLabel(period); }
      catch { return `${period} j`; }
    })(),
    view: state.chartViewV2?.view || null,
    scale: state.chartViewV2?.scale || null,
    selected_ids: comparisonIds,
    selected_symbols: rows.map(row => row.symbol).filter(Boolean),
    status: chart?.status || null,
    provider: chartTruth?.provider || null,
    truth_label: chartTruth?.label || null,
    truth_source: chartTruth?.source || null,
    freshness: chartTruth?.freshness || null,
    timestamp: atlasStrictTimestamp(chartTruth?.timestamp || chart?.timestamp),
    series: rows,
    leader: ordered[0] || null,
    laggard: ordered.length ? ordered[ordered.length - 1] : null,
    overall_direction: null,
    interpretation_rule: "La position verticale à l’écran ne prouve aucune tendance. Utiliser seulement series_change_pct."
  };
}

function atlasScheduleStableChartResize() {
  if (atlasStableResizeFrame) cancelAnimationFrame(atlasStableResizeFrame);
  if (atlasStableResizeTimer) clearTimeout(atlasStableResizeTimer);

  atlasStableResizeFrame = requestAnimationFrame(() => {
    atlasStableResizeFrame = 0;
    try { state.chartEngineV2?.realChart?.resize?.(); } catch {}
    try { atlasCleanLensResizeChart?.(); } catch {}
  });

  atlasStableResizeTimer = window.setTimeout(() => {
    atlasStableResizeTimer = 0;
    try { state.chartEngineV2?.realChart?.resize?.(); } catch {}
    try { atlasCleanLensResizeChart?.(); } catch {}
  }, 180);
}

const ATLAS_ADMIN_GRAPH_MODE_KEY = "atlas.admin.graph.mode.v2";

const ATLAS_ADMIN_GRAPH_MODES = Object.freeze(["normal", "focus", "closed"]);

function atlasAdminGraphRead() {
  try {
    const saved = localStorage.getItem(ATLAS_ADMIN_GRAPH_MODE_KEY);
    if (ATLAS_ADMIN_GRAPH_MODES.includes(saved)) return saved;
    const legacy = localStorage.getItem("atlas.admin.graph.open.v1");
    return legacy === "0" ? "closed" : "normal";
  } catch { return "normal"; }
}

function atlasAdminGraphLabel(mode) {
  return mode === "focus" ? "Focus" : mode === "closed" ? "Fermé" : "Normal";
}

function atlasAdminGraphNext(mode) {
  const index = ATLAS_ADMIN_GRAPH_MODES.indexOf(mode);
  return ATLAS_ADMIN_GRAPH_MODES[(index + 1 + ATLAS_ADMIN_GRAPH_MODES.length) % ATLAS_ADMIN_GRAPH_MODES.length];
}

function atlasAdminGraphSyncControls(mode) {
  const label = atlasAdminGraphLabel(mode);
  const cycle = document.querySelector("[data-admin-graph-cycle]");
  if (cycle) {
    cycle.classList.remove("is-normal", "is-focus", "is-closed", "is-open");
    cycle.classList.add(`is-${mode}`);
    cycle.setAttribute("aria-pressed", mode === "closed" ? "false" : "true");
    const compactState = cycle.querySelector("b");
    if (compactState) compactState.textContent = label;
    const nextLabel = atlasAdminGraphLabel(atlasAdminGraphNext(mode));
    cycle.setAttribute("aria-label", `Vue graphique en mode ${label}. Passer au mode ${nextLabel}.`);
  }
  document.querySelectorAll("[data-admin-graph-mode]").forEach(button => {
    const active = button.dataset.adminGraphMode === mode;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
}

function atlasAdminGraphSet(mode, options = {}) {
  const zone = document.getElementById("market-zone");
  if (!zone) return;
  const next = ATLAS_ADMIN_GRAPH_MODES.includes(mode) ? mode : "normal";
  zone.classList.remove("atlas-graph-closed", "atlas-graph-mode-normal", "atlas-graph-mode-focus", "atlas-graph-mode-closed");
  zone.classList.add(`atlas-graph-mode-${next}`);
  zone.dataset.graphMode = next;
  zone.dataset.graphOpen = next === "closed" ? "false" : "true";
  atlasAdminGraphSyncControls(next);
  if (options.closeCenter !== false) atlasAdminCenterSet(false, { persist: false });
  if (options.persist !== false && atlasV2IsExpandedMode()) {
    try { localStorage.setItem(ATLAS_ADMIN_GRAPH_MODE_KEY, next); } catch {}
  }
  if (options.scroll !== false) window.requestAnimationFrame(() => {
    const behavior = options.instant ? "auto" : "smooth";
    if (next === "closed") {
      document.getElementById("market-workspace")?.scrollIntoView({ block: "start", behavior });
    } else {
      document.getElementById("analyste")?.scrollIntoView({ block: "start", behavior });
      try { atlasScheduleStableChartResize(); } catch {}
      window.setTimeout(() => { try { atlasScheduleStableChartResize(); } catch {} }, 240);
    }
  });
  window.dispatchEvent(new CustomEvent("atlas:admin-graph", { detail: { mode: next, open: next !== "closed" } }));
}

function initAtlasAdminGraphToggle() {
  const zone = document.getElementById("market-zone");
  if (!zone) return;

  document.querySelector("[data-admin-graph-cycle]")?.addEventListener("click", () => {
    const current = zone.dataset.graphMode || "normal";
    atlasAdminGraphSet(atlasAdminGraphNext(current));
  });

  document.querySelectorAll("[data-admin-graph-mode]").forEach(button => {
    button.addEventListener("click", () => atlasAdminGraphSet(button.dataset.adminGraphMode || "normal"));
  });

  document.querySelectorAll('a[href="#analyste"]').forEach(link => {
    link.addEventListener("click", () => {
      if ((zone.dataset.graphMode || "normal") === "closed") {
        atlasAdminGraphSet("normal", { persist: atlasV2IsExpandedMode(), instant: true });
      }
    });
  });

  window.addEventListener("atlas:v2mode", event => {
    const mode = event.detail?.mode;
    if (mode === "essential") {
      atlasAdminGraphSet("normal", { persist: false, instant: true, scroll: false, closeCenter: false });
    } else if (atlasV2IsExpandedMode(mode)) {
      atlasAdminGraphSet(atlasAdminGraphRead(), { persist: false, instant: true, scroll: false, closeCenter: false });
    }
  });

  const initialMode = atlasV2IsExpandedMode() ? atlasAdminGraphRead() : "normal";
  atlasAdminGraphSet(initialMode, { persist: false, instant: true, scroll: false, closeCenter: false });
}

let atlasChartOverlayLastReady = null;

function atlasChartOverlayModeLabelFor(preset, count) {
  if (count <= 1) return "SOLO";
  if (preset === "rank-3") return "TOP 3";
  if (preset === "rank-5") return "TOP 5";
  if (preset === "gainers") return "HAUSSES 5";
  if (preset === "losers") return "BAISSES 5";
  if (preset === "volume") return "VOLUMES 5";
  return `${count} SÉRIES`;
}

function atlasChartOverlayCaptureReady(chart) {
  if (!chart?.result || chart.status !== "ready") return null;

  const comparison = chart.result?.comparison && Array.isArray(chart.result.entries);
  const entries = comparison ? chart.result.entries : [];
  const preset = String(state.dataBroker?.comparison?.preset || (comparison ? "manual" : "solo"));
  const ids = comparison
    ? entries.map(entry => entry?.coin?.id).filter(Boolean)
    : [chart.result?.coin?.id || chart.coinId].filter(Boolean);

  atlasChartOverlayLastReady = {
    chart: { ...chart, result: chart.result },
    period: Number(chart.period || state.chartPeriodDays || 1),
    preset,
    count: ids.length || (comparison ? entries.length : 1),
    modeLabel: atlasChartOverlayModeLabelFor(preset, ids.length || entries.length || 1),
    viewLabel: comparison || atlasChartV2EffectiveView() === "base100" ? "BASE 100" : "PRIX EUR",
    scaleLabel: comparison || atlasChartV2EffectiveScale() !== "logarithmic" ? "NORMALE" : "LOG",
  };

  return atlasChartOverlayLastReady;
}

function atlasChartOverlayTruthKey(label) {
  const value = String(label || "").toLowerCase();
  if (/indisponible|échec|aucune|attente|non mesur/.test(value)) return "unavailable";
  if (/archive|daté|datée/.test(value)) return "archive";
  if (/cache|retard/.test(value)) return "cache";
  if (/direct|coin.?gecko/.test(value)) return "direct";
  return "archive";
}

function atlasChartOverlaySet(titleHtml, seriesHtml, summaryHtml, truthLabel = "", layout = "comparison") {
  const overlay = document.getElementById("atlasChartInsightOverlay");
  const titleNode = document.getElementById("atlasChartInsightOverlayTitle");
  const seriesNode = document.getElementById("atlasChartInsightOverlaySeries");
  const summaryNode = document.getElementById("atlasChartInsightOverlaySummary");
  if (!overlay || !titleNode || !seriesNode || !summaryNode) return;

  titleNode.innerHTML = titleHtml;
  seriesNode.innerHTML = seriesHtml;
  summaryNode.innerHTML = summaryHtml;
  overlay.dataset.truth = atlasChartOverlayTruthKey(truthLabel);
  overlay.dataset.layout = layout;
  const chartShell = overlay.closest(".chart-shell");
  if (chartShell) chartShell.dataset.analysisLayout = layout;
  overlay.hidden = state.chartViewV2.analysis === false;
  overlay.setAttribute("aria-hidden", overlay.hidden ? "true" : "false");
}

function atlasChartOverlayModeLabel() {
  const count = atlasComparisonIds().length;
  const preset = String(state.dataBroker?.comparison?.preset || "solo");
  return atlasChartOverlayModeLabelFor(preset, count);
}

function atlasChartOverlayTruth(result, period) {
  try {
    return atlasChartTruth(result, period);
  } catch {
    return { label: "source non mesurée" };
  }
}

function atlasChartOverlayOrderedEntries(result) {
  const order = atlasComparisonIds();
  const entries = Array.isArray(result?.entries) ? result.entries : [];
  return [...entries].sort((a, b) => {
    const ai = order.indexOf(a?.coin?.id);
    const bi = order.indexOf(b?.coin?.id);
    return (ai < 0 ? 999 : ai) - (bi < 0 ? 999 : bi);
  });
}

function atlasChartOverlayPointCoverage(rows) {
  const values = rows.map(row => row.points).filter(value => Number.isFinite(value) && value > 0);
  if (!values.length) return "points non mesurés";
  const min = Math.min(...values);
  const max = Math.max(...values);
  return min === max ? `${min} pts/série` : `${min}–${max} pts/série`;
}

function atlasChartOverlayCoinColor(coin, index = 0) {
  try {
    return atlasCryptoPalette(coin || {}, index).primary || "#eaf8ff";
  } catch {
    return "#eaf8ff";
  }
}

function atlasChartOverlayCoinHtml(row, index, value) {
  const color = atlasChartOverlayCoinColor(row.coin, index);
  return `<span class="atlas-hud-coin" style="--coin-color:${escapeHtml(color)}">`
    + `<b>${escapeHtml(row.symbol)}</b><em>${escapeHtml(value)}</em></span>`;
}

function atlasChartOverlayTitleHtml(context, mode, truthLabel) {
  return `<span class="atlas-hud-context">${escapeHtml(context)}</span>`
    + ` · <span class="atlas-hud-mode">${escapeHtml(mode)}</span>`
    + `<span class="atlas-hud-truth">${escapeHtml(String(truthLabel || "source non mesurée").toUpperCase())}</span>`;
}

function atlasChartOverlayComparison(chart, period, options = {}) {
  const result = chart?.result || {};
  const entries = atlasChartOverlayOrderedEntries(result);
  const selectedCount = Number(options.selectedCount || atlasComparisonIds().length || entries.length);
  const periodLabel = atlasChartPeriodLabel(period);
  const preset = String(options.preset || state.dataBroker?.comparison?.preset || "manual");
  const truth = atlasChartOverlayTruth(
    { comparison: true, entries, sourceMode: "comparison-base100" },
    period
  );
  const scaleLabel = String(options.scaleLabel || (atlasChartV2EffectiveScale() === "logarithmic" ? "LOG" : "NORMALE"));

  const rows = entries.map(entry => {
    const coin = entry?.coin || {};
    const marketCoin = state.coins.find(item => item.id === coin.id) || coin;
    const metrics = entry?.result?.integrity?.metrics || {};
    return {
      coin,
      symbol: String(coin.symbol || coin.name || "ACTIF").toUpperCase(),
      change: Number.isFinite(Number(entry?.atlasMarketMetric))
        ? Number(entry.atlasMarketMetric)
        : Number(metrics.changePct),
      volume: Number.isFinite(Number(entry?.atlasMarketMetric)) && preset === "volume"
        ? Number(entry.atlasMarketMetric)
        : Number(marketCoin?.volume24h),
      timestamp: Number(metrics.lastTimestamp || 0),
      points: Number(metrics.pointCount || entry?.result?.series?.length || 0),
    };
  });

  const seriesLine = rows.map((row, index) => {
    const value = preset === "volume"
      ? (Number.isFinite(row.volume) ? fmtCompactEUR.format(row.volume) : "non mesuré")
      : (Number.isFinite(row.change) ? fmtPct(row.change) : "non mesuré");
    return atlasChartOverlayCoinHtml(row, index, value);
  }).join("");

  const oldest = rows.map(row => row.timestamp).filter(value => value > 0);
  const oldestText = oldest.length
    ? atlasExactTimestampLabel(Math.min(...oldest))
    : "horodatage inconnu";
  const coverage = atlasChartOverlayPointCoverage(rows);

  const scannerHistorySummary = String(
    result?.scanner?.historySummary || ""
  ).trim();
  const scannerMarketBasis = String(
    result?.scanner?.marketBasisLabel || ""
  ).trim();
  const providerLabel = atlasChartProviderLabel({
    comparison: true,
    entries
  });

  let primarySummaryItems = [
    {
      className: "atlas-hud-detail",
      text: `${coverage} · ${providerLabel} EUR`
    }
  ];
  let secondarySummaryItems = [
    {
      className: "atlas-hud-oldest",
      label: "plus ancienne",
      value: oldestText,
      dateTime: true
    }
  ];

  if (scannerHistorySummary) {
    secondarySummaryItems.push({
      className: "atlas-hud-detail",
      text: `historiques ${scannerHistorySummary}`
    });
  }
  if (scannerMarketBasis) {
    secondarySummaryItems.push({
      className: "atlas-hud-detail",
      text: `classement ${scannerMarketBasis}`
    });
  }

  if (preset === "volume") {
    const valid = rows
      .filter(row => Number.isFinite(row.volume))
      .sort((a, b) => b.volume - a.volume);

    if (valid.length) {
      primarySummaryItems = [
        {
          className: "atlas-hud-leader",
          text:
            `Volume supérieur ${valid[0].symbol} `
            + fmtCompactEUR.format(valid[0].volume)
        }
      ];

      if (valid.length > 1) {
        primarySummaryItems.push({
          className: "atlas-hud-laggard",
          text:
            `inférieur ${valid[valid.length - 1].symbol} `
            + fmtCompactEUR.format(valid[valid.length - 1].volume)
        });
      }

      secondarySummaryItems = [
        {
          className: "atlas-hud-detail",
          text: coverage
        },
        {
          className: "atlas-hud-detail",
          text: `${providerLabel} EUR`
        },
        {
          className: "atlas-hud-oldest",
          label: "plus ancienne",
          value: oldestText,
          dateTime: true
        }
      ];
    }
  } else {
    const valid = rows
      .filter(row => Number.isFinite(row.change))
      .sort((a, b) => b.change - a.change);

    if (valid.length) {
      const max = valid[0].change;
      const min = valid[valid.length - 1].change;
      const leaders = valid
        .filter(row => Math.abs(row.change - max) < 0.005)
        .map(row => row.symbol)
        .join("/");
      const laggards = valid
        .filter(row => Math.abs(row.change - min) < 0.005)
        .map(row => row.symbol)
        .join("/");
      const gap = max - min;

      primarySummaryItems = [
        {
          className: "atlas-hud-leader",
          text: `Leader ${leaders} ${fmtPct(max)}`
        },
        {
          className: "atlas-hud-laggard",
          text: `retard ${laggards} ${fmtPct(min)}`
        },
        {
          className: "atlas-hud-detail",
          text: `écart ${gap.toFixed(2)} pt`
        }
      ];

      secondarySummaryItems = [
        {
          className: "atlas-hud-detail",
          text: coverage
        },
        {
          className: "atlas-hud-oldest",
          label: "plus ancienne",
          value: oldestText,
          dateTime: true
        }
      ];
    }
  }

  if (options.preserved) {
    secondarySummaryItems.push({
      className: "atlas-hud-detail",
      text:
        `mise à jour ${
          atlasChartPeriodLabel(
            Number(
              options.requestedPeriod
              || state.chartPeriodDays
              || period
            )
          )
        } en cours`
    });
  }

  const summaryItemHtml = item => {
    const className = escapeHtml(
      String(item?.className || "atlas-hud-detail")
    );

    if (item?.dateTime) {
      return `<span class="${className}">`
        + `${escapeHtml(String(item.label || ""))} `
        + `<time class="atlas-hud-datetime">`
        + `${escapeHtml(String(item.value || "horodatage inconnu"))}`
        + `</time></span>`;
    }

    return `<span class="${className}">`
      + `${escapeHtml(String(item?.text || ""))}`
      + `</span>`;
  };

  const summaryHtml =
    `<span class="atlas-hud-summary-row atlas-hud-summary-primary">`
      + primarySummaryItems.map(summaryItemHtml).join("")
    + `</span>`
    + `<span class="atlas-hud-summary-row atlas-hud-summary-secondary">`
      + secondarySummaryItems.map(summaryItemHtml).join("")
    + `</span>`;

  const truthLabel = String(truth.label || "source non mesurée");
  const displayedTruthLabel = options.preserved
    ? "historique conservé"
    : truthLabel;
  const displayedModeLabel = String(
    options.modeLabel || atlasChartOverlayModeLabel()
  );
  const titleHtml = atlasChartOverlayTitleHtml(
    `${displayedModeLabel} · ${periodLabel} · BASE 100`,
    `${scaleLabel} · ${entries.length}/${selectedCount} SÉRIES`,
    displayedTruthLabel
  );

  atlasChartOverlaySet(
    titleHtml,
    seriesLine || '<span class="atlas-hud-detail">Mesures non disponibles</span>',
    summaryHtml,
    options.preserved ? "cache retardé" : truthLabel,
    "comparison"
  );
}

function atlasChartOverlaySolo(chart, period, options = {}) {
  const result = chart?.result || {};
  const coin = result?.coin || getSelectedCoin() || {};
  const metrics = result?.integrity?.metrics || {};
  const periodLabel = atlasChartPeriodLabel(period);
  const view = String(options.viewLabel || (atlasChartV2EffectiveView() === "base100" ? "BASE 100" : "PRIX EUR"));
  const scaleLabel = String(options.scaleLabel || (atlasChartV2EffectiveScale() === "logarithmic" ? "LOG" : "NORMALE"));
  const truth = atlasChartOverlayTruth(result, period);

  const first = Number(metrics.firstPrice);
  const last = Number(metrics.lastPrice);
  const min = Number(metrics.minPrice);
  const max = Number(metrics.maxPrice);
  const change = Number(metrics.changePct);
  const points = Number(metrics.pointCount || result?.series?.length || 0);
  const lastTimestamp = Number(metrics.lastTimestamp || 0);
  const amplitude = Number.isFinite(min) && min > 0 && Number.isFinite(max)
    ? (max - min) / min * 100
    : null;

  const symbol = String(coin?.symbol || "ACTIF").toUpperCase();
  const name = String(coin?.name || "Analyse du marché");
  const truthLabel = String(truth.label || "source non mesurée");
  const displayedTruthLabel = options.preserved ? "historique conservé" : truthLabel;

  const seriesParts = [];
  if (Number.isFinite(last)) seriesParts.push(atlasFormatEUR(last));
  if (Number.isFinite(change)) seriesParts.push(fmtPct(change));
  if (Number.isFinite(min)) seriesParts.push(`bas ${atlasFormatEUR(min)}`);
  if (Number.isFinite(max)) seriesParts.push(`haut ${atlasFormatEUR(max)}`);
  if (Number.isFinite(amplitude)) seriesParts.push(`amplitude ${amplitude.toFixed(2)} %`);

  const summaryParts = [];
  if (Number.isFinite(first)) summaryParts.push(`départ ${atlasFormatEUR(first)}`);
  if (Number.isFinite(last)) summaryParts.push(`dernière ${atlasFormatEUR(last)}`);
  if (points) summaryParts.push(`${points} points`);
  if (lastTimestamp > 0) summaryParts.push(`série ${atlasExactTimestampLabel(lastTimestamp)}`);
  summaryParts.push(`${atlasChartProviderLabel(result)} EUR`);

  const soloTitleHtml = atlasChartOverlayTitleHtml(
    `${symbol} · ${name} · ${periodLabel}`,
    `${view} · ${scaleLabel}`,
    displayedTruthLabel
  );

  const soloColor = atlasChartOverlayCoinColor(coin, 0);
  const soloSeriesHtml = `<span class="atlas-hud-coin" style="--coin-color:${escapeHtml(soloColor)}">`
    + `<b>${escapeHtml(symbol)}</b><em>${escapeHtml(seriesParts.join(" · ") || "Mesures historiques non disponibles")}</em></span>`;

  if (options.preserved) {
    summaryParts.push(`mise à jour ${atlasChartPeriodLabel(Number(options.requestedPeriod || state.chartPeriodDays || period))} en cours`);
  }

  atlasChartOverlaySet(
    soloTitleHtml,
    soloSeriesHtml,
    `<span class="atlas-hud-detail">${escapeHtml(summaryParts.join(" · "))}</span>`,
    options.preserved ? "cache retardé" : truthLabel,
    "solo"
  );
}

function atlasChartOverlayUpdate() {
  const chart = state.dataBroker?.chart;
  const requestedPeriod = Number(state.chartPeriodDays || 1);
  const chartReady = !!chart
    && chart.status === "ready"
    && atlasChartContextMatches(chart)
    && !!chart.result;

  if (chartReady) {
    atlasChartOverlayCaptureReady(chart);
  }

  if (state.chartViewV2.analysis === false) {
    const overlay = document.getElementById("atlasChartInsightOverlay");
    if (overlay) {
      overlay.hidden = true;
      overlay.setAttribute("aria-hidden", "true");
    }
    return;
  }

  if (chartReady) {
    if (chart.result?.comparison && Array.isArray(chart.result.entries)) {
      atlasChartOverlayComparison(chart, Number(chart.period || requestedPeriod));
    } else {
      atlasChartOverlaySolo(chart, Number(chart.period || requestedPeriod));
    }
    atlasSyncTargetTopFiveCycleLabel();
    return;
  }

  const displayedChartStillVisible = !!state.chartEngineV2?.realChart;
  const preserved = displayedChartStillVisible ? atlasChartOverlayLastReady : null;

  if (preserved?.chart?.result) {
    const options = {
      preserved: true,
      requestedPeriod,
      preset: preserved.preset,
      selectedCount: preserved.count,
      modeLabel: preserved.modeLabel,
      viewLabel: preserved.viewLabel,
      scaleLabel: preserved.scaleLabel,
    };

    if (preserved.chart.result?.comparison && Array.isArray(preserved.chart.result.entries)) {
      atlasChartOverlayComparison(preserved.chart, preserved.period, options);
    } else {
      atlasChartOverlaySolo(preserved.chart, preserved.period, options);
    }
    return;
  }

  atlasChartOverlaySet(
    `<span class="atlas-hud-context">ANALYSE DU MARCHÉ</span> · <span class="atlas-hud-mode">${escapeHtml(atlasChartPeriodLabel(requestedPeriod))}</span><span class="atlas-hud-truth">EN ATTENTE</span>`,
    '<span class="atlas-hud-detail">Première série réelle en cours de chargement</span>',
    '<span class="atlas-hud-detail">Aucune courbe valide n’est encore affichée · CoinGecko EUR</span>',
    "attente",
    "empty"
  );
}

const atlasChartOverlayCaption = document.getElementById("chartCaption");

const ATLAS_WORKSPACE_LAST_VALID_GRAPH_KEY = "agent_crypto_erith_ia_workspace_last_valid_graph_v1";

function atlasWorkspaceCurrentGraphMode() {
  const mode = document.getElementById("market-zone")?.dataset?.graphMode;
  return ATLAS_ADMIN_GRAPH_MODES.includes(mode) ? mode : atlasAdminGraphRead();
}

function atlasWorkspaceStoredChartResult(coin, period) {
  if (!coin?.id) return null;
  const preferred = atlasChartPreferredSourceFamily(coin);
  const alternate = preferred === "binance" ? "coingecko" : "binance";
  return atlasGetStoredChartResult(coin, period, preferred)
    || atlasGetStoredChartResult(coin, period, alternate)
    || null;
}

function atlasWorkspaceRestoreCachedGraph(ids, period, preset) {
  const coins = (ids || [])
    .map(id => state.coins.find(coin => coin.id === id))
    .filter(Boolean);
  if (!coins.length || coins.length !== (ids || []).length) return false;

  if (coins.length === 1) {
    const coin = coins[0];
    const result = atlasWorkspaceStoredChartResult(coin, period);
    if (!result?.series?.length) return false;
    const chartKey = atlasExpectedChartContextKey([coin.id], period);
    state.selectedCoinId = coin.id;
    state.dataBroker.comparison.results = { [coin.id]: result };
    state.dataBroker.comparison.renderedIds = [coin.id];
    state.dataBroker.comparison.status = "ready";
    atlasRenderChartResult(coin, period, { ...result, coin }, chartKey, true);
    return true;
  }

  const rawEntries = coins.map(coin => {
    const result = atlasWorkspaceStoredChartResult(coin, period);
    if (!result?.series?.length) return null;
    const scannerPreset = ATLAS_SCANNER_PRESETS.has(preset);
    const metric = scannerPreset ? atlasScannerMarketMetric(preset, coin, period) : undefined;
    return {
      coin,
      result,
      source: "workspace-cache",
      atlasMarketMetric: metric,
      atlasMarketMetricLabel: scannerPreset ? atlasScannerMarketMetricLabel(preset, period) : undefined,
      atlasHistoryKind: atlasChartNeedsRefresh(result, period) ? "archive" : "cache",
      atlasMarketRank: Number(coin.rank || 0)
    };
  }).filter(Boolean);

  const strictWorkspacePreset = ATLAS_SCANNER_PRESETS.has(preset);
  if (strictWorkspacePreset && rawEntries.length !== coins.length) return false;
  const aligned = (strictWorkspacePreset
    ? atlasBuildAlignedComparisonEntries(rawEntries, period)
    : atlasBuildBestAlignedComparisonEntries(rawEntries, period, coins.length))
    .sort((a, b) => ids.indexOf(a.coin.id) - ids.indexOf(b.coin.id));
  if (!aligned.length || (strictWorkspacePreset && aligned.length !== coins.length)) return false;

  const chartKey = atlasExpectedChartContextKey(ids, period);
  const latestTimestamp = Math.max(...aligned.map(entry => Number(entry.result?.integrity?.metrics?.lastTimestamp || 0)));
  const pointCount = aligned.reduce((sum, entry) => sum + Number(entry.result?.series?.length || 0), 0);
  const result = {
    comparison: true,
    entries: aligned,
    periodDays: period,
    sourceMode: "comparison-base100",
    source: `${atlasChartProviderLabel({ comparison: true, entries: aligned })} · historiques EUR · Base 100`
  };

  const alignedIds = aligned.map(entry => entry.coin.id);
  const unavailableIds = ids.filter(id => !alignedIds.includes(id));
  state.dataBroker.comparison.results = Object.fromEntries(aligned.map(entry => [entry.coin.id, entry.result]));
  state.dataBroker.comparison.renderedIds = [...alignedIds];
  state.dataBroker.comparison.pendingIds = [];
  state.dataBroker.comparison.unavailableIds = unavailableIds;
  state.dataBroker.comparison.status = unavailableIds.length ? "partial" : "ready";
  state.dataBroker.comparison.error = null;
  state.dataBroker.chart = {
    status: "ready",
    coinId: ids[0],
    period,
    source: atlasChartProviderLabel(result),
    mode: "comparison-base100",
    timestamp: Number.isFinite(latestTimestamp) && latestTimestamp > 0 ? new Date(latestTimestamp).toISOString() : null,
    seriesTimestamp: Number.isFinite(latestTimestamp) && latestTimestamp > 0 ? new Date(latestTimestamp).toISOString() : null,
    spotPatchedAt: null,
    pointCount,
    latencyMs: null,
    retryCount: 0,
    contextKey: chartKey,
    result,
    error: null
  };

  const drawn = drawComparisonChart(els.mainChart, aligned, period, chartKey);
  if (!Array.isArray(drawn) || !drawn.length || (strictWorkspacePreset && drawn.length !== coins.length)) return false;
  state.dataBroker.comparison.renderedIds = drawn.map(entry => entry.coin.id);
  state.dataBroker.chart.result.entries = drawn;
  setText(els.selectedAssetTitle, `Comparaison ${drawn.map(entry => entry.coin.symbol).join(" + ")}`);
  atlasRenderComparisonDetail(drawn, period);
  atlasChartV2RenderLegend(drawn, { comparison: true });
  atlasRenderComparisonCaption(drawn, period, unavailableIds, coins.length);
  atlasRenderComparisonControls();
  atlasChartV2SyncControls();
  atlasChartOverlayUpdate();
  atlasRenderBrokerStrip();
  return true;
}

function atlasComparisonEndpointComposition(coins = [], chart = null) {
  const rows = (Array.isArray(coins) ? coins : [])
    .filter(Boolean)
    .map(coin => {
      const quote = atlasCurrentChartObservation(coin, chart);
      const timestamp = Number(quote?.timestamp);
      return {
        coin,
        quote,
        kind: atlasObservationKind(quote),
        timestamp: Number.isFinite(timestamp) && timestamp > 0 ? timestamp : null
      };
    });

  const count = kind => rows.filter(row => row.kind === kind).length;
  const timestamps = rows
    .map(row => row.timestamp)
    .filter(value => Number.isFinite(value) && value > 0);

  return {
    rows,
    total: rows.length,
    liveBinance: count("live-binance"),
    collected: count("collected"),
    conserved: count("conserved"),
    snapshot: count("snapshot"),
    direct: count("direct"),
    unavailable: count("unavailable"),
    latestTimestamp: timestamps.length ? Math.max(...timestamps) : null
  };
}

function atlasComparisonEndpointLabel(composition) {
  const parts = [];
  if (composition?.liveBinance) {
    parts.push(`${composition.liveBinance} live Binance`);
  }
  if (composition?.collected) {
    parts.push(`${composition.collected} collecté${composition.collected > 1 ? "s" : ""}`);
  }
  if (composition?.snapshot) {
    parts.push(`${composition.snapshot} snapshot${composition.snapshot > 1 ? "s" : ""}`);
  }
  if (composition?.conserved) {
    parts.push(`${composition.conserved} conservé${composition.conserved > 1 ? "s" : ""}`);
  }
  if (composition?.direct) {
    parts.push(`${composition.direct} direct${composition.direct > 1 ? "s" : ""}`);
  }
  if (composition?.unavailable) {
    parts.push(`${composition.unavailable} indisponible${composition.unavailable > 1 ? "s" : ""}`);
  }

  const timestamp = composition?.latestTimestamp
    ? atlasExactTimestampLabel(composition.latestTimestamp)
    : "heure inconnue";

  return parts.length
    ? `${parts.join(" · ")} · observation ${timestamp}`
    : "Aucune observation terminale disponible";
}

function atlasRefreshComparisonEndpointTruth(coins = null, chart = null) {
  const node = document.querySelector("[data-comparison-endpoint-truth]");
  if (!node) return false;

  const selectedCoins = Array.isArray(coins) && coins.length
    ? coins
    : atlasComparisonCoins();
  const composition = atlasComparisonEndpointComposition(
    selectedCoins,
    chart || state.chartEngineV2?.realChart || null
  );

  node.textContent = atlasComparisonEndpointLabel(composition);
  node.dataset.endpointState =
    composition.liveBinance
      ? "live"
      : composition.collected
        ? "collected"
        : composition.conserved || composition.snapshot
          ? "stored"
          : "unavailable";
  return true;
}

function atlasCurrentChartObservation(coin, chart = null) {
  const direct = atlasExchangeQuoteForCoin(coin?.id || "");
  const directPrice = Number(direct?.price);
  if (direct?.status === "live" && Number.isFinite(directPrice) && directPrice > 0) {
    return direct;
  }

  const preset = String(
    chart?.$atlasPreset || state.dataBroker?.comparison?.preset || "manual"
  );
  const collected = atlasScannerCollectorQuoteForCoin(coin, preset);
  if (collected) return collected;

  const current = atlasCurrentQuoteForCoin(coin, Date.now());
  const currentPrice = Number(current?.price);
  return Number.isFinite(currentPrice) && currentPrice > 0 ? current : null;
}

