const ATLAS_SCANNER_POOL_SIZE = 32;

const ATLAS_SCANNER_DIRECT_LIMIT = 18;

const ATLAS_SCANNER_TARGET = 5;

const ATLAS_SCANNER_SPACING_MS = 240;

let atlasScannerSequence = 0;

let atlasScannerQueuedRequest = null;

let atlasScannerUiState = {
  preset: null,
  status: "idle",
  message: "",
  updatedAt: 0
};

let atlasScannerCommitEpoch = 0;

function atlasScannerInvalidateChartWork(reason = "scanner") {
  atlasScannerCommitEpoch += 1;
  state.chartRenderToken += 1;
  state.comparisonRenderToken += 1;
  atlasClearChartRetryTimer();

  if (state.chartEngineV2?.controller) {
    try { state.chartEngineV2.controller.abort(); } catch {}
  }
  if (state.chartEngineV2) {
    state.chartEngineV2.controller = null;
    state.chartEngineV2.loading = false;
    state.chartEngineV2.activeRequestKey = null;
    state.chartEngineV2.retryKey = null;
  }

  return atlasScannerCommitEpoch;
}

function atlasScannerLabel(preset) {
  if (preset === "gainers") return "Hausses 5";
  if (preset === "losers") return "Baisses 5";
  if (preset === "volume") return "Volumes 5";
  return "Scanner 5";
}

function atlasScannerSetUiState(preset, status, message = "") {
  atlasScannerUiState = {
    preset: preset || null,
    status: status || "idle",
    message: String(message || ""),
    updatedAt: Date.now()
  };
}

function atlasScannerSetTransactionFlag(running) {
  const analyst = document.getElementById("analyste");
  if (!analyst) return;
  if (running) analyst.dataset.scannerTransaction = "running";
  else delete analyst.dataset.scannerTransaction;
}

function atlasScannerVisibleFailure(preset, message, detail = "") {
  const label = atlasScannerLabel(preset);
  const cleanMessage = String(message || `${label} non appliqué`);
  const cleanDetail = String(detail || "");
  console.warn(`${label} non appliqué`, cleanMessage, cleanDetail);

  atlasScannerSetTransactionFlag(false);
  atlasScannerSetUiState(preset, "failed", cleanMessage);

  const displayed = atlasScannerDisplayedGraphLabel();
  const caption =
    `${cleanMessage}. AFFICHÉ : ${displayed} · ancien graphique conservé.`
    + (cleanDetail ? ` Détail : ${cleanDetail}` : "");
  atlasSetChartCaptionText(caption);

  if (state.chartEngineV2?.realChart) {
    atlasShowChartRefresh(els.mainChart, caption);
    atlasUpdateChartRefresh(caption);
    window.setTimeout(() => {
      if (atlasScannerUiState?.status === "failed" && atlasScannerUiState?.preset === preset) {
        atlasHideChartRefresh();
      }
    }, 5200);
  }

  atlasRenderComparisonControls();

  window.setTimeout(() => {
    if (atlasScannerUiState?.status === "failed" && atlasScannerUiState?.preset === preset) {
      atlasScannerSetUiState(null, "idle", "");
      atlasRenderComparisonControls();
    }
  }, 6800);

  return false;
}

function atlasScannerResumeQueuedAfterDirect() {
  const queued = atlasScannerQueuedRequest;
  if (!queued || atlasScannerTransaction) return false;
  if (!state.liveOk || !state.coins.length) return false;
  if (!["direct", "github-public"].includes(String(state.sourceLock?.mode || state.dataBroker?.market?.mode || ""))) return false;
  atlasScannerQueuedRequest = null;
  return atlasScannerStart(queued.preset, 5, {
    period: queued.period,
    resumed: true
  });
}

function atlasScannerDisplayedGraphLabel() {
  const ids = Array.isArray(state.dataBroker?.comparison?.renderedIds)
    && state.dataBroker.comparison.renderedIds.length
      ? state.dataBroker.comparison.renderedIds
      : atlasComparisonIds();

  const symbols = ids
    .map(id => state.coins.find(coin => coin.id === id)?.symbol)
    .filter(Boolean)
    .map(symbol => String(symbol).toUpperCase());

  const preset = String(state.dataBroker?.comparison?.preset || "solo");
  const mode = preset === "rank-5"
    ? "Top 5"
    : preset === "rank-3"
      ? "Top 3"
      : preset === "gainers"
        ? "Hausses 5"
        : preset === "losers"
          ? "Baisses 5"
          : preset === "volume"
            ? "Volumes 5"
            : symbols.length > 1
              ? `${symbols.length} séries`
              : "Solo";

  return `${mode}${symbols.length ? ` · ${symbols.join("/")}` : ""}`;
}

function atlasScannerCurrent(tx) {
  return !!tx
    && atlasScannerTransaction === tx
    && !tx.cancelled
    && !tx.controller.signal.aborted;
}

function atlasScannerCancel(reason = "annulé", options = {}) {
  const tx = atlasScannerTransaction;
  if (tx) {
    tx.cancelled = true;
    tx.cancelReason = reason;
    try { tx.controller.abort(); } catch {}
  }

  if (tx || atlasScannerQueuedRequest) atlasScannerInvalidateChartWork(`cancel:${reason}`);

  atlasScannerTransaction = null;
  atlasScannerQueuedRequest = null;
  atlasScannerSetTransactionFlag(false);

  if (options.keepUi !== true) atlasScannerSetUiState(null, "idle", "");
  if (options.keepOverlay !== true) atlasHideChartRefresh();
  atlasRenderComparisonControls();
}

function atlasScannerMarketBasis(period) {
  const days = Number(period || 1);
  if (days === 1) {
    return {
      key: "change24h",
      label: "Market 24 h",
      metric(coin) { return Number(coin?.change24h); }
    };
  }
  if (days === 7) {
    return {
      key: "change7d",
      label: "Market 7 j",
      metric(coin) { return Number(coin?.change7d); }
    };
  }
  return {
    key: "change30d",
    label: days === 30 ? "Market 30 j" : `Market 30 j · courbes ${atlasChartPeriodLabel(days)}`,
    metric(coin) { return Number(coin?.change30d); }
  };
}

function atlasScannerPool(preset, period) {
  const frameCoins = atlasMarketFrameScannerCoins(preset, period);
  if (Array.isArray(frameCoins)) return frameCoins;

  const basis = atlasScannerMarketBasis(period);
  let rows = (state.coins || [])
    .filter(coin => Number.isFinite(Number(coin?.rank)))
    .filter(coin => Number(coin.rank) >= 1 && Number(coin.rank) <= 250)
    .filter(coin => Number.isFinite(Number(coin?.priceEur ?? coin?.price)));

  if (preset === "volume") {
    /*
      Volume 5 conserve les stablecoins : ils font réellement partie des plus
      gros volumes Market et étaient présents dans la version validée 28.1.62.
    */
    rows = rows
      .filter(coin => Number.isFinite(Number(coin?.volume24h)))
      .filter(coin => Number(coin.volume24h) > 0)
      .sort((a, b) => Number(b.volume24h) - Number(a.volume24h));
  } else {
    rows = rows
      .filter(coin => classifyAsset(coin) !== "Stablecoin")
      .filter(coin => Number.isFinite(basis.metric(coin)))
      .sort((a, b) => preset === "losers"
        ? basis.metric(a) - basis.metric(b)
        : basis.metric(b) - basis.metric(a));
  }

  const seen = new Set();
  return rows.filter(coin => {
    if (!coin?.id || seen.has(coin.id)) return false;
    seen.add(coin.id);
    return true;
  }).slice(0, ATLAS_SCANNER_POOL_SIZE);
}

function atlasScannerMarketMetric(preset, coin, period) {
  return preset === "volume"
    ? Number(coin?.volume24h)
    : atlasScannerMarketBasis(period).metric(coin);
}

function atlasScannerMarketMetricLabel(preset, period) {
  return preset === "volume"
    ? "Volume Market 24 h"
    : atlasScannerMarketBasis(period).label;
}

function atlasScannerHistoryKind(result, period, source = "") {
  if (source === "direct") return "direct";
  if (!result) return "missing";
  return atlasChartNeedsRefresh(result, period) ? "archive" : "cache";
}

function atlasScannerHistorySummary(entries) {
  const counts = { direct: 0, cache: 0, archive: 0 };
  entries.forEach(entry => {
    const kind = String(entry?.atlasHistoryKind || "archive");
    if (kind in counts) counts[kind] += 1;
  });

  return [
    counts.direct ? `${counts.direct} direct${counts.direct > 1 ? "s" : ""}` : null,
    counts.cache ? `${counts.cache} cache récent${counts.cache > 1 ? "s" : ""}` : null,
    counts.archive ? `${counts.archive} archive${counts.archive > 1 ? "s" : ""} datée${counts.archive > 1 ? "s" : ""}` : null
  ].filter(Boolean).join(" · ");
}

function atlasScannerDecorateEntry(tx, coin, result, source) {
  const historyKind = atlasScannerHistoryKind(result, tx.period, source);
  return {
    coin,
    result,
    source,
    atlasMarketMetric: atlasScannerMarketMetric(tx.preset, coin, tx.period),
    atlasMarketMetricLabel: atlasScannerMarketMetricLabel(tx.preset, tx.period),
    atlasHistoryKind: historyKind,
    atlasMarketRank: Number(coin?.rank || 0)
  };
}

function atlasScannerRowsWindowCount(rows, start, end) {
  let count = 0;
  for (const row of rows) {
    const timestamp = Number(row?.t);
    if (timestamp < start) continue;
    if (timestamp > end) break;
    count += 1;
  }
  return count;
}

function atlasScannerSubsetIsCompatible(prepared, period) {
  if (!prepared.length) return false;
  const minimum = atlasChartRules(period).minPoints;
  const commonStart = Math.max(...prepared.map(item => item.start));
  const commonEnd = Math.min(...prepared.map(item => item.end));
  if (!Number.isFinite(commonStart) || !Number.isFinite(commonEnd) || commonEnd <= commonStart) {
    return false;
  }
  return prepared.every(item =>
    atlasScannerRowsWindowCount(item.rows, commonStart, commonEnd) >= minimum
  );
}

function atlasScannerAligned(entries, period, candidateIds) {
  const order = new Map((candidateIds || []).map((id, index) => [id, index]));
  const minimum = atlasChartRules(period).minPoints;
  const prepared = (Array.isArray(entries) ? entries : [])
    .filter(entry => entry?.coin?.id && Array.isArray(entry?.result?.series))
    .map(entry => {
      const rows = atlasComparisonRows(entry);
      return {
        entry,
        rows,
        start: Number(rows[0]?.t),
        end: Number(rows[rows.length - 1]?.t),
        order: order.has(entry.coin.id) ? order.get(entry.coin.id) : Number.MAX_SAFE_INTEGER
      };
    })
    .filter(item =>
      item.rows.length >= minimum
      && Number.isFinite(item.start)
      && Number.isFinite(item.end)
      && item.end > item.start
    )
    .sort((a, b) => a.order - b.order);

  if (!prepared.length) return [];

  let bestPrepared = [];
  let exactResult = null;

  /*
    Recherche lexicographique : le premier groupe compatible de cinq conserve
    le meilleur rang Market possible. Les historiques incompatibles sont
    écartés au lieu de rendre tout le panier inutilisable.
  */
  const search = (startIndex, chosen) => {
    if (exactResult) return;
    if (chosen.length > bestPrepared.length) bestPrepared = [...chosen];
    if (chosen.length === ATLAS_SCANNER_TARGET) {
      const aligned = atlasBuildAlignedComparisonEntries(
        chosen.map(item => item.entry),
        period
      );
      if (aligned.length === ATLAS_SCANNER_TARGET) exactResult = aligned;
      return;
    }

    const remainingNeeded = ATLAS_SCANNER_TARGET - chosen.length;
    for (
      let index = startIndex;
      index <= prepared.length - remainingNeeded && !exactResult;
      index += 1
    ) {
      const candidate = prepared[index];
      const next = [...chosen, candidate];
      if (!atlasScannerSubsetIsCompatible(next, period)) continue;
      search(index + 1, next);
    }
  };

  search(0, []);
  if (exactResult) return exactResult;

  return bestPrepared.length
    ? atlasBuildAlignedComparisonEntries(bestPrepared.map(item => item.entry), period)
        .slice(0, ATLAS_SCANNER_TARGET)
    : [];
}

function atlasScannerProgress(tx, symbol = "") {
  if (!atlasScannerCurrent(tx)) return;

  const ready = Math.min(ATLAS_SCANNER_TARGET, Number(tx.validCount || 0));
  const displayed = atlasScannerDisplayedGraphLabel();
  const phase = String(tx.phase || "historique");
  const text =
    `${atlasScannerLabel(tx.preset)} · ${ready}/5 compatibles`
    + ` · cache ${Number(tx.cacheHits || 0)}`
    + ` · réseau ${Number(tx.directAttempts || 0)}/${Number(tx.directLimit || 0)}`
    + `${symbol ? ` · ${String(symbol).toUpperCase()}` : ""}`
    + ` · ${displayed} conservé`;

  atlasScannerSetUiState(tx.preset, "running", text);

  if (state.chartEngineV2?.realChart) {
    atlasShowChartRefresh(els.mainChart, text);
    atlasUpdateChartRefresh(text);
  }

  atlasSetChartCaptionText(
    `${atlasScannerLabel(tx.preset)} EN COURS · ${phase}`
    + ` · classement ${tx.marketBasisLabel}`
    + ` · ${ready}/5 historiques compatibles`
    + ` · cache ${Number(tx.cacheHits || 0)}`
    + ` · réseau ${Number(tx.directAttempts || 0)}/${Number(tx.directLimit || 0)}.`
    + ` AFFICHÉ : ${displayed} · inchangé jusqu’au commit.`
  );

  atlasRenderComparisonControls();
}

function atlasScannerStateSnapshot() {
  return {
    selectedCoinId: state.selectedCoinId,
    graphSelectionCleared: state.graphSelectionCleared,
    chartPeriodDays: state.chartPeriodDays,
    chart: state.dataBroker.chart,
    comparison: {
      ...state.dataBroker.comparison,
      ids: [...(state.dataBroker.comparison.ids || [])],
      pendingIds: [...(state.dataBroker.comparison.pendingIds || [])],
      unavailableIds: [...(state.dataBroker.comparison.unavailableIds || [])],
      renderedIds: [...(state.dataBroker.comparison.renderedIds || [])],
      results: { ...(state.dataBroker.comparison.results || {}) }
    },
    selectedTitle: els.selectedAssetTitle?.textContent || "",
    detailCollapsed: document.getElementById("analyste")?.classList.contains("detail-collapsed") === true
  };
}

function atlasScannerRestoreSnapshot(snapshot) {
  state.selectedCoinId = snapshot.selectedCoinId;
  state.graphSelectionCleared = snapshot.graphSelectionCleared;
  state.chartPeriodDays = snapshot.chartPeriodDays;
  state.dataBroker.chart = snapshot.chart;
  state.dataBroker.comparison = snapshot.comparison;

  if (els.selectedAssetTitle) els.selectedAssetTitle.textContent = snapshot.selectedTitle;

  atlasChartV2RedrawFromBroker();
  atlasRenderComparisonControls();
  atlasChartOverlayUpdate();
  atlasRenderBrokerStrip();
  atlasWorkspaceRenderStrip();
  atlasSetCleanLensCollapsed(snapshot.detailCollapsed, false);
}

function atlasScannerCommit(tx, finalEntries, rejected) {
  if (!atlasScannerCurrent(tx) || !Array.isArray(finalEntries) || !finalEntries.length) {
    return false;
  }

  const prevalidated = atlasScannerAligned(
    finalEntries,
    tx.period,
    tx.candidateIds
  );
  if (!prevalidated.length) return false;

  const ids = prevalidated.map(entry => entry.coin.id);
  const availableCount = ids.length;
  const missingCount = Math.max(0, ATLAS_SCANNER_TARGET - availableCount);
  const canonicalKey = atlasExpectedChartContextKey(ids, tx.period);
  const snapshot = tx.displayedSnapshot || atlasScannerStateSnapshot();
  const commitEpoch = atlasScannerInvalidateChartWork(`commit:${tx.preset}`);
  const historySummary = atlasScannerHistorySummary(prevalidated);
  const latestTimestamp = Math.max(...prevalidated.map(entry =>
    Number(entry.result?.integrity?.metrics?.lastTimestamp || 0)
  ));
  const pointCount = prevalidated.reduce(
    (sum, entry) => sum + Number(entry.result?.series?.length || 0),
    0
  );

  const nextComparison = {
    ...state.dataBroker.comparison,
    ids: [...ids],
    pendingIds: [],
    unavailableIds: [],
    results: Object.fromEntries(
      prevalidated.map(entry => [entry.coin.id, entry.result])
    ),
    renderedIds: [...ids],
    completionAttempt: 0,
    mode: availableCount > 1 ? "compare" : "single",
    preset: tx.preset,
    status: missingCount ? "partial" : "ready",
    error: missingCount
      ? `${missingCount} historique(s) compatible(s) manquant(s)`
      : null
  };

  const nextChart = {
    status: "ready",
    coinId: ids[0],
    period: tx.period,
    source: ATLAS_CANONICAL_MARKET_SOURCE,
    mode: availableCount > 1 ? "comparison-base100" : "single",
    timestamp: Number.isFinite(latestTimestamp) && latestTimestamp > 0
      ? new Date(latestTimestamp).toISOString()
      : null,
    seriesTimestamp: Number.isFinite(latestTimestamp) && latestTimestamp > 0
      ? new Date(latestTimestamp).toISOString()
      : null,
    spotPatchedAt: null,
    pointCount,
    latencyMs: null,
    retryCount: 0,
    contextKey: canonicalKey,
    marketFrameId: tx.marketFrameId,
    result: {
      comparison: availableCount > 1,
      entries: prevalidated,
      periodDays: tx.period,
      sourceMode: availableCount > 1
        ? "comparison-base100"
        : prevalidated[0]?.result?.sourceMode || "scanner-single",
      source: "Classement Market CoinGecko + historiques Bridge/Binance/CoinGecko EUR",
      scanner: {
        preset: tx.preset,
        marketBasisLabel: tx.marketBasisLabel,
        marketFrameId: tx.marketFrameId,
        marketFrameFingerprint: tx.marketFrameFingerprint,
        marketRequestedAssets: tx.marketRequestedAssets,
        marketValidatedAssets: tx.marketValidatedAssets,
        marketTimestamp: tx.marketTimestamp,
        marketMode: tx.marketMode,
        historySummary,
        displayedIds: [...ids],
        availableCount,
        targetCount: ATLAS_SCANNER_TARGET,
        rejected: [...rejected]
      }
    },
    error: missingCount
      ? `${missingCount} courbe(s) absente(s)`
      : null
  };

  try {
    state.selectedCoinId = ids[0];
    state.graphSelectionCleared = false;
    state.chartPeriodDays = tx.period;
    state.dataBroker.comparison = nextComparison;
    state.dataBroker.chart = nextChart;

    if (!atlasChartContextMatches(nextChart)) {
      throw new Error(`Clé canonique refusée : ${canonicalKey}`);
    }

    const drawn = drawComparisonChart(
      els.mainChart,
      prevalidated,
      tx.period,
      canonicalKey
    );

    if (commitEpoch !== atlasScannerCommitEpoch) {
      throw new Error("Commit graphique remplacé par une demande plus récente.");
    }

    if (!Array.isArray(drawn) || drawn.length !== availableCount) {
      throw new Error(
        `Dessin incohérent : ${drawn?.length || 0}/${availableCount}`
      );
    }

    const drawnIds = drawn.map(entry => entry.coin.id);
    if (drawnIds.some((id, index) => id !== ids[index])) {
      throw new Error("Ordre du canvas différent de la sélection.");
    }

    state.dataBroker.comparison.renderedIds = [...drawnIds];
    state.dataBroker.chart.result.entries = drawn;
    atlasScannerTransaction = null;
    atlasScannerQueuedRequest = null;
    atlasScannerSetTransactionFlag(false);
    atlasScannerSetUiState(
      tx.preset,
      "committed",
      `${atlasScannerLabel(tx.preset)} · ${availableCount}/5 appliquées`
    );

    setText(
      els.selectedAssetTitle,
      `${atlasScannerLabel(tx.preset)} · ${drawn.map(entry => entry.coin.symbol).join(" + ")} · ${availableCount}/5`
    );

    atlasRenderComparisonDetail(drawn, tx.period);
    atlasChartV2RenderLegend(drawn, { comparison: availableCount > 1 });
    atlasRenderComparisonControls();
    atlasChartV2SyncControls();
    atlasChartOverlayUpdate();
    atlasRenderBrokerStrip();
    renderMarketTable();
    renderDecisionBoard();
    renderMultiHorizon();
    if (typeof renderAtlasMathCore === "function") renderAtlasMathCore();

    atlasSetCleanLensCollapsed(snapshot.detailCollapsed, false);

    const marketValues = drawn.map(entry => {
      const metric = Number(entry.atlasMarketMetric);
      return tx.preset === "volume"
        ? `${entry.coin.symbol} ${Number.isFinite(metric) ? fmtCompactEUR.format(metric) : "—"}`
        : `${entry.coin.symbol} ${Number.isFinite(metric) ? fmtPct(metric) : "—"}`;
    }).join(" · ");

    atlasSetChartCaptionText(
      `${atlasScannerLabel(tx.preset)} · ${availableCount}/5 historiques compatibles`
      + `${missingCount ? ` · ${missingCount} manquant${missingCount > 1 ? "s" : ""}` : ""}`
      + ` · classement ${tx.marketBasisLabel}`
      + ` · ${marketValues}`
      + ` · historiques ${historySummary || "CoinGecko"}`
      + ` · marché ${tx.marketMode} ${atlasExactTimestampLabel(tx.marketTimestamp)}.`
    );

    const saved = atlasWorkspaceWrite();
    if (!saved) {
      console.warn(
        "Workspace scanner partiel non persisté ; graphique conservé en session."
      );
    }

    atlasHideChartRefresh();

    window.setTimeout(() => {
      if (atlasScannerUiState.status === "committed") {
        atlasScannerSetUiState(null, "idle", "");
        atlasRenderComparisonControls();
      }
    }, 1800);

    return true;
  } catch (error) {
    console.warn("Transaction scanner 28.2.57 annulée :", error);
    atlasScannerInvalidateChartWork(`rollback:${tx.preset}`);
    atlasScannerTransaction = null;
    atlasScannerSetTransactionFlag(false);
    atlasScannerRestoreSnapshot(snapshot);
    return atlasScannerVisibleFailure(
      tx.preset,
      `${atlasScannerLabel(tx.preset)} · transaction annulée · ancien graphe restauré`,
      String(error?.message || error || "erreur de commit")
    );
  }
}

function atlasScannerStoredHistory(coin, period) {
  const current = state.dataBroker?.comparison?.results?.[coin?.id];
  const candidates = [
    current && Array.isArray(current.series) && current.series.length ? current : null,
    atlasGetStoredChartResult(coin, period, "binance"),
    atlasGetStoredChartResult(coin, period, "coingecko")
  ].filter(Boolean);

  candidates.sort((a, b) => {
    const aTime = Number(a?.savedAt || a?.integrity?.metrics?.lastTimestamp || 0);
    const bTime = Number(b?.savedAt || b?.integrity?.metrics?.lastTimestamp || 0);
    return bTime - aTime;
  });
  return candidates[0] || null;
}

async function atlasScannerRun(tx) {
  const accepted = [];
  const rejected = [];
  const coins = tx.candidateIds
    .map(id => state.coins.find(coin => coin.id === id))
    .filter(Boolean);
  const networkQueue = [];

  try {
    tx.phase = "lecture des caches historiques";
    atlasScannerSetUiState(
      tx.preset,
      "warming",
      `${atlasScannerLabel(tx.preset)} · lecture des caches historiques`
    );
    atlasScannerSetTransactionFlag(true);
    atlasScannerProgress(tx);

    /*
      Phase 1 : tous les caches sont examinés avant la première requête réseau.
      Une petite capitalisation sans cache ne bloque donc plus les suivantes.
    */
    for (const coin of coins) {
      if (!atlasScannerCurrent(tx)) return false;

      tx.cacheChecked += 1;
      const stored = atlasScannerStoredHistory(coin, tx.period);
      if (stored && Array.isArray(stored.series) && stored.series.length) {
        accepted.push(
          atlasScannerDecorateEntry(
            tx,
            coin,
            stored,
            atlasChartNeedsRefresh(stored, tx.period) ? "archive" : "cache"
          )
        );
        tx.cacheHits += 1;
        tx.validCount = atlasScannerAligned(
          accepted,
          tx.period,
          tx.candidateIds
        ).length;
        atlasScannerProgress(tx, coin.symbol);

        if (tx.validCount >= ATLAS_SCANNER_TARGET) {
          const cachedFinal = atlasScannerAligned(
            accepted,
            tx.period,
            tx.candidateIds
          );
          return atlasScannerCommit(tx, cachedFinal, rejected);
        }
      } else {
        networkQueue.push(coin);
      }
    }

    tx.phase = "Bridge puis transports navigateur";
    let cursor = 0;

    const worker = async () => {
      while (atlasScannerCurrent(tx) && tx.validCount < ATLAS_SCANNER_TARGET) {
        if (tx.directAttempts >= tx.directLimit) return;
        const coin = networkQueue[cursor];
        cursor += 1;
        if (!coin) return;

        tx.directAttempts += 1;
        tx.examined += 1;
        atlasScannerProgress(tx, coin.symbol);

        let fetched;
        try {
          fetched = await atlasScannerFetchDirect(tx, coin);
        } catch (error) {
          if (atlasComparisonAbortError(error) || tx.controller.signal.aborted) return;
          fetched = { result: null, error };
        }

        if (!atlasScannerCurrent(tx)) return;

        if (
          fetched?.result
          && Array.isArray(fetched.result.series)
          && fetched.result.series.length
        ) {
          accepted.push(
            atlasScannerDecorateEntry(
              tx,
              coin,
              fetched.result,
              fetched.source === "cache" ? "cache" : "direct"
            )
          );
        } else {
          rejected.push({
            id: coin.id,
            symbol: coin.symbol,
            reason: String(fetched?.error?.message || "historique indisponible")
          });
        }

        const aligned = atlasScannerAligned(
          accepted,
          tx.period,
          tx.candidateIds
        );
        tx.validCount = Math.min(ATLAS_SCANNER_TARGET, aligned.length);
        atlasScannerProgress(tx, coin.symbol);

        if (tx.validCount >= ATLAS_SCANNER_TARGET) return;

        await atlasWaitWithSignal(
          ATLAS_SCANNER_SPACING_MS,
          tx.controller.signal
        ).catch(() => {});
      }
    };

    await Promise.all(
      Array.from(
        { length: Math.min(ATLAS_SCANNER_NETWORK_CONCURRENCY, networkQueue.length || 1) },
        () => worker()
      )
    );

    if (!atlasScannerCurrent(tx)) return false;

    const finalEntries = atlasScannerAligned(
      accepted,
      tx.period,
      tx.candidateIds
    );

    if (finalEntries.length >= 1) {
      return atlasScannerCommit(tx, finalEntries, rejected);
    }

    const detail = rejected
      .slice(0, 5)
      .map(row => `${String(row.symbol || row.id || "?").toUpperCase()} : ${row.reason}`)
      .join(" · ");

    atlasScannerTransaction = null;
    atlasScannerSetTransactionFlag(false);
    return atlasScannerVisibleFailure(
      tx.preset,
      `${atlasScannerLabel(tx.preset)} indisponible · 0/5 historique compatible`
      + ` · cache ${tx.cacheHits}/${tx.cacheChecked}`
      + ` · réseau ${tx.directAttempts}/${tx.directLimit}`,
      detail
    );
  } catch (error) {
    if (error?.name === "AbortError" || tx?.controller?.signal?.aborted) return false;
    console.error("Scanner 28.2.57 :", error);
    if (atlasScannerTransaction === tx) atlasScannerTransaction = null;
    atlasScannerSetTransactionFlag(false);
    return atlasScannerVisibleFailure(
      tx.preset,
      `${atlasScannerLabel(tx.preset)} interrompu par une erreur de traitement`,
      String(error?.message || error || "erreur inconnue")
    );
  }
}

function atlasScannerStart(preset = "gainers", limit = 5, options = {}) {
  const label = atlasScannerLabel(preset);

  try {
    if (!ATLAS_SCANNER_PRESETS.has(preset)) {
      return atlasScannerVisibleFailure(preset, `${label} refusé · preset inconnu`);
    }
    if (!state.liveOk) {
      return atlasScannerVisibleFailure(preset, `${label} refusé · Livecheck requis`);
    }
    if (!Array.isArray(state.coins) || !state.coins.length) {
      return atlasScannerVisibleFailure(preset, `${label} refusé · Market Snapshot vide`);
    }

    atlasScannerCancel("nouvelle demande", { keepUi: true });
    atlasScannerInvalidateChartWork(`start:${preset}`);
    const displayedSnapshot = atlasScannerStateSnapshot();

    const period = Number(options.period || state.chartPeriodDays || 1);
    const pool = atlasScannerPool(preset, period);

    if (pool.length < ATLAS_SCANNER_TARGET) {
      return atlasScannerVisibleFailure(
        preset,
        `${label} indisponible · ${pool.length}/5 actifs classables dans le Market`
      );
    }

    const marketFrame = atlasCurrentMarketFrame();
    if (!marketFrame) {
      return atlasScannerVisibleFailure(preset, `${label} refusé · Market Frame indisponible`);
    }
    const marketMode = String(
      marketFrame.mode
      || state.sourceLock?.mode
      || state.dataBroker?.market?.mode
      || "archive"
    );
    const marketBasisLabel = atlasScannerMarketMetricLabel(preset, period);

    const tx = {
      id: ++atlasScannerSequence,
      preset,
      period,
      universeSize: marketFrame.validatedAssets,
      marketFrameId: marketFrame.id,
      marketFrameFingerprint: marketFrame.fingerprint,
      marketRequestedAssets: marketFrame.requestedAssets,
      marketValidatedAssets: marketFrame.validatedAssets,
      marketTimestamp: marketFrame.timestamp,
      marketMode,
      marketBasisLabel,
      candidateIds: pool.map(coin => coin.id),
      cacheChecked: 0,
      cacheHits: 0,
      examined: 0,
      directAttempts: 0,
      validCount: 0,
      phase: "initialisation",
      displayedSnapshot,
      directLimit: Math.min(ATLAS_SCANNER_DIRECT_LIMIT, pool.length),
      cancelled: false,
      controller: new AbortController()
    };

    atlasScannerTransaction = tx;
    atlasScannerQueuedRequest = null;
    atlasScannerSetTransactionFlag(true);
    atlasScannerSetUiState(
      preset,
      "warming",
      `${label} · ${atlasMarketFrameShortId(marketFrame)} · classement ${marketBasisLabel} · démarrage`
    );
    atlasScannerProgress(tx);

    void atlasScannerRun(tx).catch(error => {
      if (error?.name === "AbortError") return;
      console.error("Scanner 28.2.57 non capturé :", error);
      if (atlasScannerTransaction === tx) atlasScannerTransaction = null;
      atlasScannerVisibleFailure(
        preset,
        `${label} interrompu`,
        String(error?.message || error || "erreur inconnue")
      );
    });
    return true;
  } catch (error) {
    console.error("Démarrage scanner 28.2.57 :", error);
    return atlasScannerVisibleFailure(
      preset,
      `${label} refusé par le contrôle de démarrage`,
      String(error?.message || error || "erreur inconnue")
    );
  }
}

function atlasHandleGainersClickV286(event) {
  event?.preventDefault?.();
  event?.stopPropagation?.();
  return atlasScannerStart("gainers", 5, {
    period: Number(state.chartPeriodDays || 1),
    source: "button-28.2.57"
  });
}

