function atlasBuildCryptoPageSnapshotCore() {
  const period = Number(state.chartPeriodDays || 1);
  const chart = state.dataBroker?.chart || {};
  const comparison = state.dataBroker?.comparison || {};
  const chartResult = chart.result || null;
  let chartTruth = null;
  try { chartTruth = atlasChartTruth(chartResult, period); } catch {}

  let comparisonIds = [];
  try { comparisonIds = atlasComparisonIds(); } catch {
    comparisonIds = Array.isArray(comparison.ids) ? comparison.ids : [];
  }

  const top5 = atlasTopFiveCoins()
    .map(coin => atlasLocalCompactCoin(coin, { quote: true }))
    .filter(Boolean);

  const sourceStatus = Array.isArray(state.sourceStatus)
    ? state.sourceStatus.slice(0, 10).map(item => ({
        name: item?.name || item?.source || item?.id || null,
        status: item?.status || item?.state || null,
        latency_ms: atlasLocalFinite(item?.latency ?? item?.latencyMs ?? item?.ms),
        message: item?.message || item?.detail || null
      }))
    : [];

  const selectedCoin = atlasSelectedCoin();
  const strictContract = atlasBuildStrictFactContract(
    period,
    chart,
    chartResult,
    comparisonIds,
    chartTruth
  );

  const snapshot = {
    schema: "atlas_crypto_page_snapshot_v2",
    generated_at: new Date().toISOString(),
    application: {
      release: ATLAS_RELEASE,
      mode: "private_local_read_only",
      page_url: location.href,
      selected_asset: selectedCoin
        ? `${selectedCoin.name} (${String(selectedCoin.symbol || "").toUpperCase()})`
        : null
    },
    safety: {
      observation_only: true,
      exchange_actions: false,
      wallet_actions: false,
      github_writes: false,
      automatic_orders: false,
      human_validation_required: true,
      analysis_human_validation_required: false,
      financial_action_human_validation_required: true,
      human_validation_scope: "Décision ou action financière réelle uniquement ; Atlas → NØX → Aerith reste automatique."
    },
    strict_contract: strictContract,
    raw_context: {
      source_status: {
        live_ok: !!state.liveOk,
        main_source: state.mainSource || null,
        market_timestamp: state.timestamp || null,
        market_snapshot_id: state.sourceLock?.snapshotId || state.dataBroker?.market?.snapshotId || state.dataBroker?.marketFrame?.id || null,
        diagnostics: sourceStatus
      },
      binance_top5: {
        feed_status: state.dataBroker?.exchangeFeed?.status || null,
        source: state.dataBroker?.exchangeFeed?.source || "Binance WebSocket",
        last_message_at: state.dataBroker?.exchangeFeed?.lastMessageAt || null,
        assets: top5
      },
      watchlist_intelligence_v4: typeof atlasProductWatchlistIntelligence === "function"
        ? atlasProductWatchlistIntelligence()
        : null,
      news_event_reaction_v1: typeof atlasProductNewsReaction === "function"
        ? atlasProductNewsReaction()
        : null,
      math_core_v4: state.math || null,
      historical_compare_v2: null,
      release_candidate_v1: {
        contract: ATLAS_RC_CONTRACT,
        static_audit: atlasRcStaticAudit()
      }
    }
  };

  snapshot.raw_context.historical_compare_v2 = atlasHistoryV2Compare(snapshot);

  snapshot.pedagogy = atlasPedagogyBuildContract(snapshot);
  atlasLocalDialogueState.lastSnapshot = snapshot;
  return snapshot;
}

let atlasStableResizeFrame = 0;

let atlasStableResizeTimer = 0;

function atlasSelectedCoin() {
  if (!Array.isArray(state.coins) || !state.coins.length) return null;
  return state.coins.find(coin => coin.id === state.selectedCoinId) || state.coins[0] || null;
}

function atlasPatchOpenMarketHelp(coinOrId) {
  const coin = typeof coinOrId === "string" ? state.coins.find(item => item.id === coinOrId) : coinOrId;
  if (!coin?.id) return false;

  const layer = document.getElementById("atlasHelpLayer");
  const dock = document.getElementById("atlasMarketCardDockHost");
  const dockOpen = !!dock && !dock.hidden && dock.dataset.marketHelpCoinId === coin.id;
  const layerOpen = !!layer && !layer.hidden && layer.getAttribute("aria-hidden") !== "true" && layer.dataset.marketHelpCoinId === coin.id;
  const surface = dockOpen ? dock : (layerOpen ? layer : null);
  if (!surface) return false;

  const snapshot = atlasMarketSnapshotSurface(coin);
  const priceNode = surface.querySelector('[data-help-live="price-eur"]');
  const change24Node = surface.querySelector('[data-help-live="change24h"]');
  const change7Node = surface.querySelector('[data-help-live="change7d"]');
  const change30Node = surface.querySelector('[data-help-live="change30d"]');
  const observedSourceNode = surface.querySelector('[data-help-live="observed-source"]');
  const marketReferenceNode = surface.querySelector('[data-help-live="market-reference"]');

  if (priceNode) priceNode.textContent = snapshot.quoteUsable ? atlasCurrentQuotePriceText(snapshot.quote) : atlasFormatEUR(snapshot.priceEur);
  if (change24Node) {
    change24Node.textContent = atlasMarketSnapshotChange24Text(snapshot);
    change24Node.classList.remove("pos", "neg", "neutral");
    change24Node.classList.add(clsPct(snapshot.change24h));
  }
  if (change7Node) {
    change7Node.textContent = fmtPct(snapshot.change7d);
    change7Node.classList.remove("pos", "neg", "neutral");
    change7Node.classList.add(clsPct(snapshot.change7d));
  }
  if (change30Node) {
    change30Node.textContent = fmtPct(snapshot.change30d);
    change30Node.classList.remove("pos", "neg", "neutral");
    change30Node.classList.add(clsPct(snapshot.change30d));
  }
  if (observedSourceNode) {
    observedSourceNode.textContent = `${snapshot.truthLabel} · ${snapshot.freshnessLabel}`;
    observedSourceNode.title = atlasCurrentQuoteTitle(snapshot.quote);
  }
  if (marketReferenceNode) {
    const marketChange = Number.isFinite(snapshot.marketChange24h) ? fmtPct(snapshot.marketChange24h) : "—";
    marketReferenceNode.textContent = `${marketChange} · ${snapshot.marketSourceLabel} · ${snapshot.marketFrameLabel}`;
  }
  surface.dataset.marketHelpCoinId = coin.id;
  return true;
}

const ATLAS_PARALLEL_MARKET_HOLD_MS = 720;

function atlasMarketRegistryArray(value) {
  return Array.isArray(value) ? value : [];
}

function atlasMarketRegistryAssetMeta(assetId) {
  const id = String(assetId || "");
  const loaded = atlasMarketRegistryArray(
    atlasMarketRegistryState.assets
  ).find(asset => String(asset?.id || "") === id);

  if (loaded) return loaded;

  return ATLAS_METALS_ASSETS.find(
    asset => asset.id === id
  ) || ATLAS_METALS_ASSETS[0];
}

function atlasMarketRegistryRenderCatalog() {
  atlasMetalsStructuralRenderCatalog();
}

function atlasMarketRegistryRender() {
  atlasMarketRegistryRenderCatalog();
  atlasMarketRegistryRenderSourceDock(
    atlasParallelMarketActiveMetal().id
  );

  const metals = atlasParallelMarketMetalsState();
  metals.registryStatus = atlasMarketRegistryState.status;
  metals.registryOrigin = atlasMarketRegistryState.origin;
}

function atlasMarketRegistryNormalizeAssets(payload) {
  const assets = atlasMarketRegistryArray(payload?.assets)
    .filter(asset => {
      return (
        typeof asset?.id === "string"
        && typeof asset?.name === "string"
        && typeof asset?.symbol === "string"
      );
    })
    .map(asset => {
      const fallback = ATLAS_METALS_ASSETS.find(
        item => item.id === asset.id
      ) || {};

      return Object.freeze({
        ...fallback,
        ...asset,
        unit:
          asset.display_unit
          || fallback.unit
          || "Unité à qualifier",
        family:
          String(
            asset.family_label
            || fallback.family
            || "Non qualifiée"
          ).toLowerCase()
      });
    });

  const knownIds = new Set(
    ATLAS_METALS_ASSETS.map(asset => asset.id)
  );

  if (
    assets.length !== ATLAS_METALS_ASSETS.length
    || assets.some(asset => !knownIds.has(asset.id))
  ) {
    throw new Error("Registre actifs incomplet");
  }

  return assets;
}

async function atlasMarketRegistryLoad() {
  atlasMarketRegistryState.status = "loading";
  atlasMarketRegistryState.error = null;
  atlasMarketRegistryRender();

  try {
    const [
      assetsPayload,
      sourcesPayload,
      contractPayload,
      bridgePayload
    ] = await Promise.all([
      atlasMarketRegistryFetchJson(
        ATLAS_MARKET_REGISTRY_PATHS.assets
      ),
      atlasMarketRegistryFetchJson(
        ATLAS_MARKET_REGISTRY_PATHS.sources
      ),
      atlasMarketRegistryFetchJson(
        ATLAS_MARKET_REGISTRY_PATHS.contract
      ),
      atlasMarketRegistryFetchJson(
        ATLAS_MARKET_REGISTRY_PATHS.bridge
      )
    ]);

    const assets = atlasMarketRegistryNormalizeAssets(
      assetsPayload
    );
    const sources = atlasMarketRegistryNormalizeSources(
      sourcesPayload
    );

    if (
      contractPayload?.schema
      !== "agent_crypto_market_data_contract_v1"
    ) {
      throw new Error("Contrat de données incompatible");
    }

    if (
      bridgePayload?.schema
      !== "agent_crypto_bridge_market_adapter_contract_v1"
    ) {
      throw new Error("Contrat Bridge incompatible");
    }

    atlasMarketRegistryState.status = "loaded";
    atlasMarketRegistryState.origin = "json_local";
    atlasMarketRegistryState.assets = assets;
    atlasMarketRegistryState.sources = sources;
    atlasMarketRegistryState.contract = {
      schema: contractPayload.schema,
      states: atlasMarketRegistryArray(
        contractPayload.states
      ),
      cache_namespaces: atlasMarketRegistryArray(
        contractPayload.cache_namespaces
      ).filter(name => String(name).startsWith(
        "cache_metals_"
      ))
    };
    atlasMarketRegistryState.bridge = bridgePayload;
    atlasMarketRegistryState.loadedAt =
      new Date().toISOString();
    atlasMarketRegistryState.error = null;
  } catch (error) {
    atlasMarketRegistryState.status = "fallback";
    atlasMarketRegistryState.origin = "fallback_intégré";
    atlasMarketRegistryState.assets = ATLAS_METALS_ASSETS;
    atlasMarketRegistryState.sources =
      ATLAS_METALS_SOURCE_FALLBACK;
    atlasMarketRegistryState.contract =
      ATLAS_MARKET_CONTRACT_FALLBACK;
    atlasMarketRegistryState.bridge = {
      schema:
        "agent_crypto_bridge_market_adapter_contract_v1",
      routes: []
    };
    atlasMarketRegistryState.error =
      String(error?.message || error || "Erreur registre");
  }

  atlasMarketRegistryRender();
  atlasParallelMarketRenderMetals();
  return atlasMarketRegistryState.status;
}

function atlasSyncMarketUniverseControls() {
  const count = Number(state.coins?.length || 0);
  const limit = ATLAS_MARKET_VIEW_LIMITS.includes(Number(state.marketVisibleLimit)) ? Number(state.marketVisibleLimit) : 50;
  document.querySelectorAll("[data-market-limit]").forEach(button => {
    const requested = Number(button.dataset.marketLimit);
    const active = requested === limit;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
    if (requested === 250) button.textContent = count > 0 && count < 250 ? `Tous (${count})` : "250";
  });
  const status = document.getElementById("marketUniverseStatus");
  if (status) {
    const frame = atlasCurrentMarketFrame();
    status.textContent = `Univers CoinGecko : ${count}/${frame?.requestedAssets || 250} actifs validés · ${atlasMarketFrameShortId(frame)}`;
  }
}

async function atlasEnrichUsdVisible(limit) {
  const wanted = Math.min(Number(limit || 50), state.coins.length);
  const missing = state.coins.slice(0, wanted).filter(coin => !atlasHasPositiveQuote(coin.priceUsd));
  for (let offset = 0; offset < missing.length; offset += 50) {
    const batch = missing.slice(offset, offset + 50);
    try {
      const result = await SourceAdapter.coingeckoUsdForIds(batch.map(coin => coin.id));
      for (const coin of batch) {
        const usd = result.prices.get(coin.id);
        if (atlasHasPositiveQuote(usd)) coin.priceUsd = Number(usd);
      }
      renderMarketTable();
    } catch { break; }
    if (offset + 50 < missing.length) await atlasWaitWithSignal(700).catch(() => {});
  }
}

function atlasBrokerCommitMarket(snapshot, mode) {
  const result = atlasBrokerCommitMarketCore(snapshot, mode);
  atlasScannerCollectorSchedule(`market-${String(mode || "unknown")}`);
  return result;
}

function atlasBuildCryptoPageSnapshot() {
  const snapshot = atlasBuildCryptoPageSnapshotCore();
  const envelope = atlasAnalyticalBuildEnvelope(snapshot);
  snapshot.schema = "atlas_crypto_page_snapshot_v3_truth_evidence";
  snapshot.analytical_state = envelope;
  snapshot.fingerprint = `sha256:${envelope.fingerprint.value}`;
  atlasAnalyticalTruthState.currentEnvelope = envelope;
  atlasAnalyticalTruthState.currentFingerprint = snapshot.fingerprint;
  atlasAnalyticalTruthRender(envelope);
  atlasCurrentOnSnapshot(snapshot);
  return snapshot;
}

