function atlasSourceDockNewsUrl(coin) {
  if (!coin) return null;
  const query = `${coin.name || ""} ${coin.symbol || ""} crypto`.trim();
  return atlasSourceDockSafeUrl(`https://news.google.com/search?q=${encodeURIComponent(query)}&hl=fr&gl=FR&ceid=FR%3Afr`);
}

function newsPlanPayload() { return { rule: "News never triggers buy/sell automatically.", global_press: ["Reuters", "AP", "AFP", "BBC", "Le Monde", "Financial Times"], crypto_press: ["CoinDesk", "The Block", "Decrypt", "Cointelegraph"], institutions: ["AMF", "ESMA", "BCE", "SEC", "CFTC", "central banks"], exchanges: ["Kraken announcements", "Bybit announcements", "Binance announcements", "exchange status pages"], classification: [ "source_identified", "reliability_estimated", "possible_market_impact", "missing_verifications", "action: ignore | monitor | verify | wait" ] };
}

function atlasLocalCompactNews() {
  let lead = null;
  let counts = null;
  try { lead = newsFeedLeadEvent(); } catch {}
  try { counts = newsFeedCounts24h(); } catch {}
  return {
    status: typeof newsFeedState !== "undefined" ? newsFeedState.status : null,
    archive_time: typeof newsFeedState !== "undefined"
      ? (newsFeedState.payload?.generated_at || newsFeedState.payload?.updated_at || null)
      : null,
    counts_24h: counts || null,
    event_reaction: typeof atlasProductNewsReaction === "function" ? atlasProductNewsReaction(lead) : null,
    lead: lead ? {
      headline: lead.headline || null,
      event_label: lead.event_label || null,
      event_time: lead.event_time || null,
      source_name: lead.source_name || lead.source_host || null,
      source_count: atlasLocalFinite(lead.source_count),
      evidence: lead.evidence || null,
      impact: lead.impact || null,
      assets: Array.isArray(lead.assets) ? lead.assets.slice(0, 12) : [],
      sectors: Array.isArray(lead.sectors) ? lead.sectors.slice(0, 12) : [],
      decision: lead.decision || null
    } : null
  };
}

function atlasStrictNewsContract() {
  const compact = atlasLocalCompactNews();
  return {
    status: compact?.status || null,
    archive_time: atlasStrictTimestamp(compact?.archive_time),
    counts_24h: compact?.counts_24h || null,
    lead_event: compact?.lead || null,
    rule: "Les limites générales de données ne constituent pas une actualité ni une alerte News Sentinel."
  };
}

