const WATCH_ALERT_MAX = 48;

const WATCH_ALERT_HISTORY_MAX = 160;

const WATCH_ALERT_COOLDOWN_MS = 15 * 60 * 1000;

function atlasWatchReadJson(key, fallback) {
  try {
    const parsed = JSON.parse(localStorage.getItem(key) || "null");
    return parsed ?? fallback;
  } catch {
    return fallback;
  }
}

function atlasWatchWriteJson(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
    return true;
  } catch {
    return false;
  }
}

function atlasWatchReadProfiles() {
  const value = atlasWatchReadJson(WATCH_PROFILE_STORAGE_KEY, {});
  return value && typeof value === "object" && !Array.isArray(value) ? value : {};
}

function atlasWatchWriteProfiles(profiles) {
  atlasWatchWriteJson(WATCH_PROFILE_STORAGE_KEY, profiles || {});
}

function atlasWatchReadAlerts() {
  const value = atlasWatchReadJson(WATCH_ALERT_STORAGE_KEY, []);
  return Array.isArray(value) ? value.slice(0, WATCH_ALERT_MAX) : [];
}

function atlasWatchWriteAlerts(alerts) {
  atlasWatchWriteJson(WATCH_ALERT_STORAGE_KEY, (alerts || []).slice(0, WATCH_ALERT_MAX));
}

function atlasWatchReadHistory() {
  const value = atlasWatchReadJson(WATCH_ALERT_HISTORY_KEY, []);
  return Array.isArray(value) ? value.slice(-WATCH_ALERT_HISTORY_MAX) : [];
}

function atlasWatchWriteHistory(history) {
  atlasWatchWriteJson(WATCH_ALERT_HISTORY_KEY, (history || []).slice(-WATCH_ALERT_HISTORY_MAX));
}

function atlasWatchMetricDefinition(metric) {
  const definitions = {
    price_eur: { label: "Prix EUR", unit: "€" },
    change_24h: { label: "Variation 24 h", unit: "%" },
    math_score: { label: "Score Math", unit: "/100" },
    volume_24h: { label: "Volume 24 h EUR", unit: "€" }
  };
  return definitions[metric] || definitions.price_eur;
}

function atlasWatchMetricValue(coin, metric) {
  if (!coin) return null;
  if (metric === "price_eur") {
    const value = Number(coin.priceEur ?? coin.price);
    return Number.isFinite(value) ? value : null;
  }
  if (metric === "change_24h") {
    const value = Number(coin.change24h);
    return Number.isFinite(value) ? value : null;
  }
  if (metric === "math_score") {
    const value = Number(scoreCoin(coin)?.score);
    return Number.isFinite(value) ? value : null;
  }
  if (metric === "volume_24h") {
    const value = Number(coin.volume);
    return Number.isFinite(value) ? value : null;
  }
  return null;
}

function atlasWatchFormatMetric(metric, value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return "—";
  if (metric === "price_eur") return atlasFormatEUR(number);
  if (metric === "change_24h") return `${number >= 0 ? "+" : ""}${number.toFixed(2)} %`;
  if (metric === "math_score") return `${Math.round(number)}/100`;
  if (metric === "volume_24h") {
    return new Intl.NumberFormat("fr-FR", {
      style: "currency",
      currency: "EUR",
      notation: "compact",
      maximumFractionDigits: 2
    }).format(number);
  }
  return String(number);
}

function atlasWatchOperatorLabel(operator) {
  return operator === "lte" ? "≤" : "≥";
}

function atlasWatchConditionReached(operator, current, threshold) {
  if (!Number.isFinite(Number(current)) || !Number.isFinite(Number(threshold))) return false;
  return operator === "lte"
    ? Number(current) <= Number(threshold)
    : Number(current) >= Number(threshold);
}

function atlasWatchSyncProfiles() {
  const profiles = atlasWatchReadProfiles();
  const now = new Date().toISOString();

  (state.watchIds || []).forEach((coinId, order) => {
    const coin = watchCoinById(coinId);
    const previous = profiles[coinId] || {};
    profiles[coinId] = {
      id: coinId,
      addedAt: previous.addedAt || now,
      note: String(previous.note || "").slice(0, 120),
      order,
      lastSeenAt: coin ? now : previous.lastSeenAt || null,
      lastPriceEur: coin ? atlasWatchMetricValue(coin, "price_eur") : previous.lastPriceEur ?? null,
      lastChange24h: coin ? atlasWatchMetricValue(coin, "change_24h") : previous.lastChange24h ?? null,
      lastMathScore: coin ? atlasWatchMetricValue(coin, "math_score") : previous.lastMathScore ?? null,
      lastVolume24h: coin ? atlasWatchMetricValue(coin, "volume_24h") : previous.lastVolume24h ?? null
    };
  });

  Object.keys(profiles).forEach(coinId => {
    if (!(state.watchIds || []).includes(coinId)) delete profiles[coinId];
  });

  atlasWatchWriteProfiles(profiles);
  return profiles;
}

function atlasWatchSetProfileNote(coinId, note) {
  const profiles = atlasWatchReadProfiles();
  const current = profiles[coinId] || { id: coinId, addedAt: new Date().toISOString() };
  profiles[coinId] = { ...current, note: String(note || "").trim().slice(0, 120) };
  atlasWatchWriteProfiles(profiles);
}

function atlasWatchAddHistory(entry) {
  const history = atlasWatchReadHistory();
  history.push(entry);
  atlasWatchWriteHistory(history);
}

function atlasWatchEvaluateAlerts() {
  const alerts = atlasWatchReadAlerts();
  const history = atlasWatchReadHistory();
  const now = Date.now();
  let changed = false;
  let triggeredNow = 0;

  for (const alert of alerts) {
    if (!alert.enabled) {
      if (alert.lastState !== "disabled") {
        alert.lastState = "disabled";
        changed = true;
      }
      continue;
    }

    const coin = watchCoinById(alert.coinId);
    const current = atlasWatchMetricValue(coin, alert.metric);

    if (!Number.isFinite(Number(current))) {
      if (alert.lastState !== "unavailable") {
        alert.lastState = "unavailable";
        alert.lastEvaluatedAt = new Date(now).toISOString();
        changed = true;
      }
      continue;
    }

    const reached = atlasWatchConditionReached(alert.operator, current, alert.threshold);
    const previousReached = alert.lastState === "reached";
    alert.lastValue = Number(current);
    alert.lastEvaluatedAt = new Date(now).toISOString();
    alert.lastState = reached ? "reached" : "watching";

    if (reached && !previousReached) {
      const previousTrigger = Date.parse(alert.lastTriggeredAt || "") || 0;
      if (now - previousTrigger >= WATCH_ALERT_COOLDOWN_MS) {
        alert.lastTriggeredAt = new Date(now).toISOString();
        const definition = atlasWatchMetricDefinition(alert.metric);
        const symbol = String(coin?.symbol || alert.coinId).toUpperCase();
        history.push({
          id: `watch_trigger_${now}_${Math.random().toString(36).slice(2, 8)}`,
          alertId: alert.id,
          coinId: alert.coinId,
          symbol,
          metric: alert.metric,
          metricLabel: definition.label,
          operator: alert.operator,
          threshold: Number(alert.threshold),
          observed: Number(current),
          note: String(alert.note || ""),
          source: state.mainSource || "marché chargé",
          marketTimestamp: state.timestamp || null,
          triggeredAt: new Date(now).toISOString()
        });
        triggeredNow += 1;
      }
    }

    changed = true;
  }

  if (changed) atlasWatchWriteAlerts(alerts);
  if (triggeredNow) atlasWatchWriteHistory(history);

  return {
    alerts,
    history: triggeredNow ? history.slice(-WATCH_ALERT_HISTORY_MAX) : atlasWatchReadHistory(),
    triggeredNow
  };
}

function atlasWatchPopulateAlertCoins() {
  const select = $("watchAlertCoin");
  if (!select) return;
  const previous = select.value;
  const profiles = atlasWatchReadProfiles();

  select.innerHTML = (state.watchIds || []).map(coinId => {
    const coin = watchCoinById(coinId);
    const symbol = String(coin?.symbol || coinId).toUpperCase();
    const name = coin?.name || coinId;
    const note = profiles[coinId]?.note ? ` · ${profiles[coinId].note}` : "";
    return `<option value="${escapeHtml(coinId)}">${escapeHtml(symbol)} · ${escapeHtml(name)}${escapeHtml(note)}</option>`;
  }).join("");

  if ([...select.options].some(option => option.value === previous)) select.value = previous;
}

function atlasWatchAlertStateLabel(alert) {
  if (!alert.enabled) return { label: "Désactivée", tone: "disabled" };
  if (alert.lastState === "reached") return { label: "Condition atteinte", tone: "reached" };
  if (alert.lastState === "unavailable") return { label: "Donnée indisponible", tone: "unavailable" };
  return { label: "En surveillance", tone: "watching" };
}

function atlasWatchRenderStatus(evaluation = null) {
  const alerts = evaluation?.alerts || atlasWatchReadAlerts();
  const history = evaluation?.history || atlasWatchReadHistory();
  const enabled = alerts.filter(alert => alert.enabled).length;
  const reached = alerts.filter(alert => alert.enabled && alert.lastState === "reached").length;
  const profiles = atlasWatchReadProfiles();

  setText($("watchMemoryCount"), `${Object.keys(profiles).length}`);
  setText($("watchConditionCount"), `${enabled}`);
  setText($("watchTriggeredCount"), `${reached}`);
  setText($("watchLastEvaluation"), new Date().toLocaleTimeString("fr-FR"));
  setText($("watchHistoryCount"), `${history.length} déclenchement${history.length > 1 ? "s" : ""}`);

  const memoryStatus = $("watchMemoryStatus");
  if (memoryStatus) {
    memoryStatus.textContent = `${Object.keys(profiles).length} actifs mémorisés`;
    memoryStatus.className = "pill ok";
  }

  const alertStatus = $("watchAlertStatus");
  if (alertStatus) {
    alertStatus.textContent = reached
      ? `${reached} condition${reached > 1 ? "s" : ""} atteinte${reached > 1 ? "s" : ""}`
      : `${enabled} condition${enabled > 1 ? "s" : ""} active${enabled > 1 ? "s" : ""}`;
    alertStatus.className = `pill ${reached ? "warn" : enabled ? "ok" : ""}`;
  }
}

function atlasWatchRenderMemoryAssets() {
  const container = $("watchMemoryAssets");
  if (!container) return;
  const profiles = atlasWatchReadProfiles();
  const rows = (state.watchIds || []).map(coinId => profiles[coinId]).filter(Boolean);

  if (!rows.length) {
    container.innerHTML = '<p class="watch-empty">Aucun actif mémorisé.</p>';
    return;
  }

  container.innerHTML = rows.map(profile => {
    const coin = watchCoinById(profile.id);
    const symbol = String(coin?.symbol || profile.id).toUpperCase();
    return `
      <article class="watch-memory-asset">
        <div>
          <b>${escapeHtml(symbol)}</b>
          <span>${escapeHtml(coin?.name || profile.id)}</span>
        </div>
        <strong>${escapeHtml(atlasWatchFormatMetric("price_eur", profile.lastPriceEur))}</strong>
        <small>24 h ${escapeHtml(atlasWatchFormatMetric("change_24h", profile.lastChange24h))} · Math ${escapeHtml(atlasWatchFormatMetric("math_score", profile.lastMathScore))}</small>
        <em>${profile.note ? escapeHtml(profile.note) : "Aucune note"}</em>
        <button type="button" data-watch-remove="${escapeHtml(profile.id)}" aria-label="Retirer ${escapeHtml(symbol)}">Retirer</button>
      </article>`;
  }).join("");
}

function atlasWatchRenderAlerts(evaluation = null) {
  const container = $("watchAlertList");
  if (!container) return;
  const alerts = evaluation?.alerts || atlasWatchReadAlerts();

  if (!alerts.length) {
    container.innerHTML = '<p class="watch-empty">Aucune condition enregistrée.</p>';
    return;
  }

  container.innerHTML = alerts.map(alert => {
    const coin = watchCoinById(alert.coinId);
    const symbol = String(coin?.symbol || alert.coinId).toUpperCase();
    const definition = atlasWatchMetricDefinition(alert.metric);
    const stateInfo = atlasWatchAlertStateLabel(alert);
    return `
      <article class="watch-alert-card" data-state="${stateInfo.tone}">
        <div class="watch-alert-card-head">
          <b>${escapeHtml(symbol)} · ${escapeHtml(definition.label)}</b>
          <span>${escapeHtml(stateInfo.label)}</span>
        </div>
        <strong>${escapeHtml(atlasWatchOperatorLabel(alert.operator))} ${escapeHtml(atlasWatchFormatMetric(alert.metric, alert.threshold))}</strong>
        <small>Observé : ${escapeHtml(atlasWatchFormatMetric(alert.metric, alert.lastValue))} · ${alert.lastEvaluatedAt ? new Date(alert.lastEvaluatedAt).toLocaleTimeString("fr-FR") : "non évalué"}</small>
        <em>${alert.note ? escapeHtml(alert.note) : "Aucune note"}</em>
        <div class="watch-alert-card-actions">
          <button type="button" data-watch-alert-toggle="${escapeHtml(alert.id)}">${alert.enabled ? "Pause" : "Activer"}</button>
          <button type="button" data-watch-alert-delete="${escapeHtml(alert.id)}">Supprimer</button>
        </div>
      </article>`;
  }).join("");
}

function atlasWatchRenderHistory(evaluation = null) {
  const container = $("watchHistoryList");
  if (!container) return;
  const history = evaluation?.history || atlasWatchReadHistory();

  if (!history.length) {
    container.innerHTML = '<p class="watch-empty">Aucun déclenchement mémorisé.</p>';
    return;
  }

  container.innerHTML = [...history].reverse().slice(0, 40).map(entry => `
    <article class="watch-history-item">
      <b>${escapeHtml(entry.symbol || entry.coinId)} · ${escapeHtml(entry.metricLabel || atlasWatchMetricDefinition(entry.metric).label)}</b>
      <span>${escapeHtml(atlasWatchOperatorLabel(entry.operator))} ${escapeHtml(atlasWatchFormatMetric(entry.metric, entry.threshold))} · observé ${escapeHtml(atlasWatchFormatMetric(entry.metric, entry.observed))}</span>
      <small>${new Date(entry.triggeredAt).toLocaleString("fr-FR")} · ${escapeHtml(String(entry.source || "marché chargé"))}</small>
      <em>${entry.note ? escapeHtml(entry.note) : "Décision humaine requise · aucun ordre automatique"}</em>
    </article>`).join("");
}

function atlasWatchRefreshV3() {
  atlasWatchSyncProfiles();
  atlasWatchPopulateAlertCoins();
  const evaluation = atlasWatchEvaluateAlerts();
  atlasWatchRenderStatus(evaluation);
  atlasWatchRenderMemoryAssets();
  atlasWatchRenderAlerts(evaluation);
  atlasWatchRenderHistory(evaluation);
  return evaluation;
}

function atlasWatchAddCondition() {
  const coinId = normalizeWatchId($("watchAlertCoin")?.value);
  const metric = String($("watchAlertMetric")?.value || "price_eur");
  const operator = $("watchAlertOperator")?.value === "lte" ? "lte" : "gte";
  const threshold = Number($("watchAlertThreshold")?.value);
  const note = String($("watchAlertNote")?.value || "").trim().slice(0, 140);

  if (!coinId || !(state.watchIds || []).includes(coinId)) return;
  if (!Number.isFinite(threshold)) {
    const input = $("watchAlertThreshold");
    input?.focus();
    return;
  }

  const alerts = atlasWatchReadAlerts();
  alerts.unshift({
    id: `watch_alert_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    coinId,
    metric,
    operator,
    threshold,
    note,
    enabled: true,
    createdAt: new Date().toISOString(),
    lastEvaluatedAt: null,
    lastTriggeredAt: null,
    lastState: "watching",
    lastValue: null
  });
  atlasWatchWriteAlerts(alerts.slice(0, WATCH_ALERT_MAX));

  if ($("watchAlertThreshold")) $("watchAlertThreshold").value = "";
  if ($("watchAlertNote")) $("watchAlertNote").value = "";
  atlasWatchRefreshV3();
}

function atlasWatchToggleCondition(alertId) {
  const alerts = atlasWatchReadAlerts();
  const alert = alerts.find(item => item.id === alertId);
  if (!alert) return;
  alert.enabled = !alert.enabled;
  alert.lastState = alert.enabled ? "watching" : "disabled";
  atlasWatchWriteAlerts(alerts);
  atlasWatchRefreshV3();
}

function atlasWatchDeleteCondition(alertId) {
  const alerts = atlasWatchReadAlerts().filter(item => item.id !== alertId);
  atlasWatchWriteAlerts(alerts);
  atlasWatchRefreshV3();
}

function atlasWatchRemoveAsset(coinId) {
  state.watchIds = (state.watchIds || []).filter(id => id !== coinId);
  saveWatchIds();

  const profiles = atlasWatchReadProfiles();
  delete profiles[coinId];
  atlasWatchWriteProfiles(profiles);

  atlasWatchWriteAlerts(atlasWatchReadAlerts().filter(alert => alert.coinId !== coinId));
  renderWatchlist();
  renderAutoReader();
}

function atlasWatchClearHistory() {
  if (!confirm("Vider l’historique local des conditions Watchlist ?")) return;
  localStorage.removeItem(WATCH_ALERT_HISTORY_KEY);
  atlasWatchRenderHistory({ history: [] });
  atlasWatchRenderStatus({ alerts: atlasWatchReadAlerts(), history: [] });
}


/* ============================================================
   29.4.00 — PRODUCT ADVANCE
   Atlas stops being only a cockpit: it ranks, compares and explains.
   No buy/sell recommendation is produced here.
   ============================================================ */

function atlasProductFinite(value) {
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function atlasProductCoinProfile(coin) {
  if (!coin) return null;
  const change24h = atlasProductFinite(coin.change24h);
  const change7d = atlasProductFinite(coin.change7d);
  const rank = atlasProductFinite(coin.rank);
  const marketCap = atlasProductFinite(coin.marketCap);
  const volume24h = atlasProductFinite(coin.volume24h);
  const ratio = marketCap > 0 && volume24h >= 0 ? (volume24h / marketCap) * 100 : null;
  const score = atlasProductFinite(scoreCoin(coin)?.score);

  let family = "À qualifier";
  let tone = "wait";
  const abs24 = Math.abs(change24h ?? 0);

  if (rank !== null && rank <= 10 && score !== null && score >= 50 && abs24 <= 12) {
    family = "Socle de marché";
    tone = "calm";
  } else if (change24h !== null && change24h >= 4 && abs24 <= 12) {
    family = "Dynamique";
    tone = "hot";
  } else if (change24h !== null && change24h <= -4) {
    family = "Sous pression";
    tone = "cold";
  } else if (abs24 > 12 || (ratio !== null && ratio > 35)) {
    family = "Spéculatif / très nerveux";
    tone = "warn";
  } else if (rank !== null && rank > 100) {
    family = "Secondaire / plus fragile";
    tone = "warn";
  } else {
    family = "Observation normale";
    tone = "calm";
  }

  const cautions = [];
  if (abs24 > 12) cautions.push("mouvement 24 h très vertical");
  if (ratio !== null && ratio > 35) cautions.push("volume très élevé face à la capitalisation");
  if (rank !== null && rank > 100) cautions.push("capitalisation/rang plus secondaire");
  if (score !== null && score < 45) cautions.push("qualité de lecture Atlas faible");

  return {
    id: coin.id,
    symbol: String(coin.symbol || "").toUpperCase(),
    name: coin.name || coin.id,
    rank,
    score,
    change24h,
    change7d,
    volumeMarketCapPct: ratio,
    family,
    tone,
    cautions
  };
}

function atlasProductWatchlistIntelligence() {
  const profiles = (state.watchIds || [])
    .map(id => watchCoinById(id))
    .filter(Boolean)
    .map(atlasProductCoinProfile)
    .filter(Boolean);

  const byChange = profiles
    .filter(p => p.change24h !== null)
    .slice()
    .sort((a, b) => b.change24h - a.change24h);

  const byScore = profiles
    .filter(p => p.score !== null)
    .slice()
    .sort((a, b) => b.score - a.score);

  const leaders = byChange.filter(p => p.change24h > 0).slice(0, 5);
  const laggards = byChange.filter(p => p.change24h < 0).slice(-5).reverse();
  const foundations = byScore.filter(p => p.family === "Socle de marché").slice(0, 6);
  const speculative = profiles
    .filter(p => p.family.includes("Spéculatif") || p.family.includes("fragile"))
    .sort((a, b) => Math.abs(b.change24h || 0) - Math.abs(a.change24h || 0))
    .slice(0, 6);

  return {
    schema: "atlas_watchlist_intelligence_v4",
    generated_at: new Date().toISOString(),
    observed: profiles.length,
    leaders,
    laggards,
    foundations,
    speculative,
    profiles,
    limitation: "Classement descriptif fondé sur le snapshot courant. Ce n’est pas une recommandation d’investissement."
  };
}

function atlasProductProfilesLine(items, empty = "aucun actif qualifié") {
  if (!Array.isArray(items) || !items.length) return empty;
  return items.map(item => {
    const move = item.change24h === null
      ? "24 h —"
      : `${item.change24h >= 0 ? "+" : ""}${item.change24h.toFixed(2)} %`;
    return `${item.symbol} ${move}`;
  }).join(" · ");
}

function atlasProductNewsReaction(event = null) {
  const current = event || (typeof newsFeedLeadEvent === "function" ? newsFeedLeadEvent() : null);
  if (!current) {
    return {
      schema: "atlas_news_event_reaction_v1",
      status: "no-event",
      summary: "Aucun événement News Sentinel qualifié.",
      assets: [],
      causal_claim: false
    };
  }

  const symbols = Array.isArray(current.assets) ? current.assets : [];
  const rows = symbols.map(symbol => {
    const upper = String(symbol || "").toUpperCase();
    const coin = state.coins.find(c => String(c.symbol || "").toUpperCase() === upper);
    if (!coin) return { symbol: upper, status: "missing", change24h: null, family: "INFORMATION MANQUANTE" };
    const profile = atlasProductCoinProfile(coin);
    return {
      symbol: upper,
      id: coin.id,
      status: "observed",
      change24h: profile?.change24h ?? null,
      change7d: profile?.change7d ?? null,
      family: profile?.family || "À qualifier",
      score: profile?.score ?? null
    };
  });

  const observed = rows.filter(row => row.status === "observed" && row.change24h !== null);
  let reaction = "Réaction non démontrée";
  if (observed.length) {
    const avg = observed.reduce((sum, row) => sum + row.change24h, 0) / observed.length;
    const direction = String(current.direction || "").toLowerCase();
    if (direction.includes("positive") || direction.includes("haus")) {
      reaction = avg >= 2 ? "Mouvement cohérent avec l’orientation annoncée, causalité non établie"
        : avg <= -2 ? "Divergence entre l’orientation de la news et le marché observé"
        : "Réaction faible / indéterminée";
    } else if (direction.includes("negative") || direction.includes("baiss")) {
      reaction = avg <= -2 ? "Mouvement cohérent avec l’orientation annoncée, causalité non établie"
        : avg >= 2 ? "Divergence entre l’orientation de la news et le marché observé"
        : "Réaction faible / indéterminée";
    } else {
      reaction = Math.abs(avg) >= 2
        ? "Mouvement notable observé sur les actifs cités, causalité non établie"
        : "Réaction faible / indéterminée";
    }
  }

  return {
    schema: "atlas_news_event_reaction_v1",
    status: observed.length ? "observed" : "insufficient-data",
    event_id: current.event_id || current.id || null,
    headline: current.headline || null,
    evidence: current.evidence || null,
    impact: current.impact || null,
    direction: current.direction || null,
    reaction,
    assets: rows,
    causal_claim: false,
    limitation: "La concordance temporelle ou directionnelle ne prouve jamais que la news a causé le mouvement."
  };
}

function atlasProductNewsReactionLine(reaction) {
  if (!reaction || reaction.status === "no-event") return "Réaction marché : aucun événement qualifié.";
  const assets = (reaction.assets || [])
    .map(row => row.change24h === null
      ? `${row.symbol} : donnée manquante`
      : `${row.symbol} ${row.change24h >= 0 ? "+" : ""}${row.change24h.toFixed(2)} % / 24 h`)
    .join(" · ");
  return `${reaction.reaction}. ${assets || "Aucun actif correspondant dans le snapshot."}`;
}

function renderWatchlist() {
  if (!els.watchCards) return;

  const selectedCount = (state.watchIds || []).length;
  const intelligence = atlasProductWatchlistIntelligence();
  state.watchlistIntelligence = intelligence;

  if (els.watchBasketSummary) {
    els.watchBasketSummary.textContent = `Atlas Watchlist V4 · ${selectedCount} actifs mémorisés · lecture autonome leaders / retardataires / socle / spéculatif.`;
  }

  atlasWatchRefreshV3();

  if (!state.liveOk || !state.coins.length) {
    els.watchCards.innerHTML = '<div class="mini-card muted">Livecheck requis. La mémoire et les conditions restent conservées, sans inventer de prix.</div>';
    return;
  }

  const topMovers = state.coins
    .filter(coin => (state.watchIds || []).includes(coin.id))
    .filter(coin => typeof coin.change24h === "number")
    .slice()
    .sort((a, b) => Math.abs(b.change24h) - Math.abs(a.change24h))
    .slice(0, 6)
    .map(coin => `${escapeHtml(coin.symbol)} <b class="${clsPct(coin.change24h)}">${atlasFmtMarketPct(coin.change24h)}</b>`)
    .join(" · ");

  const basketRows = ATLAS_WATCH_BASKETS.map(basket => {
    const coins = watchBasketCoins(basket);
    const status = basketStatus(coins);
    const leaders = coins
      .slice()
      .sort((a, b) => Math.abs(Number(b.change24h) || 0) - Math.abs(Number(a.change24h) || 0))
      .slice(0, 4);
    const leaderText = leaders.length
      ? leaders.map(coin => `${escapeHtml(coin.symbol)} <b class="${clsPct(coin.change24h)}">${atlasFmtMarketPct(coin.change24h)}</b>`).join(" · ")
      : "aucun actif suivi visible";
    return `
      <article class="watch-compact-row ${status.mode}">
        <div>
          <b>${escapeHtml(basket.label)}</b>
          <span>${escapeHtml(basket.role)}</span>
        </div>
        <strong>${status.label}${typeof status.avg === "number" ? ` · ${fmtPct(status.avg)}` : ""}</strong>
        <em>${leaderText}</em>
        <small>${coins.length}/${basket.ids.filter(id => (state.watchIds || []).includes(id)).length || 0} actifs suivis visibles</small>
      </article>`;
  }).join("");

  const leaderLine = atlasProductProfilesLine(intelligence.leaders);
  const laggardLine = atlasProductProfilesLine(intelligence.laggards);
  const foundationLine = intelligence.foundations.length
    ? intelligence.foundations.map(item => `${item.symbol} · score ${Math.round(item.score ?? 0)}`).join(" · ")
    : "aucun socle qualifié dans le snapshot";
  const speculativeLine = intelligence.speculative.length
    ? intelligence.speculative.map(item => `${item.symbol} · ${escapeHtml(item.family)}`).join(" · ")
    : "aucun actif signalé";

  els.watchCards.innerHTML = [
    `<div class="watch-v2-diagnostic compact">
      <b>Atlas Watchlist Intelligence V4</b>
      <span>${selectedCount} actifs mémorisés · ${state.coins.length} actifs marché chargés.</span>
      <span><b>Leaders 24 h :</b> ${escapeHtml(leaderLine)}</span>
      <span><b>Sous pression :</b> ${escapeHtml(laggardLine)}</span>
      <span><b>Socle de marché :</b> ${escapeHtml(foundationLine)}</span>
      <span><b>Spéculatif / fragile :</b> ${escapeHtml(speculativeLine)}</span>
      <small>Lecture descriptive du snapshot courant · aucune recommandation d’achat/vente.</small>
    </div>`,
    `<div class="watch-compact-list">${basketRows}</div>`
  ].join("");
}

function renderRiskGrid() { if (!els.riskGrid) return; els.riskGrid.innerHTML = ` <div class="risk ${state.liveOk ? "ok" : "wait"}"><span>Marché</span><b>${state.sourceLock?.valid ? "Source Lock CoinGecko" : "Source canonique absente"}</b></div> <div class="risk warn"><span>Sécurité</span><b>${ATLAS_RELEASE}</b></div> <div class="risk warn"><span>Social</span><b>Non vérifié</b></div> <div class="risk warn"><span>On-chain</span><b>Non vérifié</b></div>`;
}

function atlasDecisionBriefText() {
  if (!atlasAnalysisLiveReady()) return "ATLAS DECISION BRIEF\nSnapshot public trop ancien ou incomplet : conclusion active et simulation suspendues. L’indice de veille Atlas historique et les prix conservés restent consultables.";
  const tone = atlasMarketTone();
  const nonStable = state.coins.filter(c => classifyAsset(c) !== "Stablecoin" && typeof c.change24h === "number");
  const hot = nonStable.slice().sort((a, b) => b.change24h - a.change24h).filter(c => c.change24h > 3);
  const cold = nonStable.slice().sort((a, b) => a.change24h - b.change24h).filter(c => c.change24h < -3);
  const hotText = hot.length ? atlasTopSymbols(hot, 5) : "aucun mouvement haussier majeur";
  const coldText = cold.length ? atlasTopSymbols(cold, 4) : "aucun décrochage majeur dans le top chargé";
  const fx = atlasMarketFxContext();
  const publicMode = state.sourceLock?.mode === "github-public";
  const snapshotSourceLine = publicMode
    ? `Snapshot marché : CoinGecko Top 250 USD collecté par GitHub Actions, publié en JSON et converti en EUR avec le taux BCE du ${fx?.sourceDate || "—"} · ${atlasExactTimestampLabel(state.timestamp)}.`
    : fx
      ? `Snapshot marché : CoinGecko Top 250 USD direct, valeurs monétaires converties en EUR au taux BCE du ${fx.sourceDate} · ${atlasExactTimestampLabel(state.timestamp)}.`
      : `Snapshot marché : CoinGecko Top 250 EUR direct · ${atlasExactTimestampLabel(state.timestamp)}.`;
  const priceSourceLine = fx
    ? `Prix, capitalisations, volumes et bornes 24 h : USD CoinGecko convertis avec 1 USD = ${Number(fx.eurPerUsd).toFixed(6)} EUR. Variations en pourcentage : base USD CoinGecko.`
    : "Prix EUR : marché CoinGecko.";
  return [
    "ATLAS DECISION BRIEF",
    `État : ${tone.label}.`,
    snapshotSourceLine,
    priceSourceLine,
    "Graphique Top 5 : chandelles Binance EUR ; autres actifs : historique CoinGecko à la demande. Le snapshot public ne déclenche aucun ordre.",
    `À observer : ${hotText}.`,
    `À protéger : ${coldText}.`,
    "Décision de travail : observer / comparer. Pas d’achat automatique, pas de FOMO, pas d’ordre réel."
  ].join("\n");
}

function renderTrustLock(live = false) {
  if (!els.trustLockText) return;
  const locked = !!live && atlasAnalysisLiveReady();
  const fx = atlasMarketFxContext();
  const publicMode = state.sourceLock?.mode === "github-public";
  els.trustLockText.classList.toggle("ok-lock", locked);
  els.trustLockText.classList.toggle("warn-lock", !locked);
  if (locked && publicMode && fx) {
    els.trustLockText.textContent = `SOURCE CANONIQUE PUBLIQUE · CoinGecko USD collecté par GitHub Actions. Le navigateur lit le JSON publié ; valeurs monétaires converties en EUR avec le taux BCE du ${fx.sourceDate} : 1 USD = ${Number(fx.eurPerUsd).toFixed(6)} EUR. ` +
      "Les variations restent celles de CoinGecko en base USD. Binance alimente les prix et graphiques compatibles ; aucune requête Top 250 CoinGecko n’est demandée à Firefox.";
  } else if (locked && fx) {
    els.trustLockText.textContent = `SOURCE CANONIQUE · CoinGecko USD. Valeurs monétaires converties en EUR avec le taux BCE du ${fx.sourceDate}. Les variations restent en base USD CoinGecko.`;
  } else if (locked) {
    els.trustLockText.textContent = "SOURCE CANONIQUE · CoinGecko. Snapshot validé et décision sous validation humaine.";
  } else {
    els.trustLockText.textContent = "Snapshot public Crypto absent, trop ancien ou incomplet. Les prix conservés et l’indice historique restent consultables ; conclusion active et simulation suspendues. Firefox ne tente plus de charger le Top 250 directement depuis CoinGecko.";
  }
}

function renderColdRead(live = false) { renderTrustLock(live); if (!els.coldRead) return; const box = els.coldRead.closest(".cold-read"); if (box) { box.classList.toggle("live", live); box.classList.toggle("offline", !live); } if (live) { els.coldRead.textContent = atlasDecisionBriefText(); } else { els.coldRead.textContent = "ATLAS DECISION BRIEFLivecheck absent. L’observatoire refuse d’afficher un tableau chiffré et ne donne aucune lecture de marché."; }
}

function analyzeFomo() { const text = els.fomoInput?.value.trim() || ""; if (!text) { setText(els.fomoOutput, "Écris ce qui déclenche la FOMO."); return; } const hasBigMove = /\+\s?\d{2,}|explos|pump|rate|raté|peur|vite|maintenant/i.test(text); setText( els.fomoOutput, `MODE NO-FOMO\n\nSignal émotionnel : ${hasBigMove ? "élevé" : "à vérifier"}\nDécision : position théorique interdite tant que l’analyse froide n’est pas faite.\n\nQuestions :\n1. La hausse est-elle déjà pricée ?\n2. Qui vend si tu entres maintenant ?\n3. Quelle source primaire confirme le signal ?\n4. Où est l’invalidation ?\n5. La perte maximale est-elle acceptée ?\n\nConclusion : une occasion ratée ne coûte rien. Une mauvaise position peut coûter très cher.` );
}

const WATCH_STORAGE_KEY = "agent_crypto_erith_ia_watchlist_v2_alpha_26_8";

const ATLAS_WATCH_BASKETS = [ { key: "core", label: "Socle marché", role: "Repères marché.", ids: ["bitcoin", "ethereum", "solana", "binancecoin", "ripple"] }, { key: "liquidity", label: "Stablecoins / liquidité", role: "Flux et stabilité.", ids: ["tether", "usd-coin", "usds"] }, { key: "majors", label: "Grands actifs solides", role: "Grandes capitalisations.", ids: ["cardano", "tron", "dogecoin", "chainlink", "toncoin", "avalanche-2", "polkadot", "litecoin"] }, { key: "defi", label: "DeFi / oracles / RWA", role: "Infrastructure et tokenisation.", ids: ["chainlink", "uniswap", "aave", "ondo-finance", "maker", "pendle"] }, { key: "ai", label: "IA / compute / data", role: "Narratif IA et calcul.", ids: ["near", "bittensor", "render-token", "internet-computer"] }, { key: "l1l2", label: "Layer 1 / Layer 2", role: "Écosystèmes et scalabilité.", ids: ["sui", "aptos", "arbitrum", "optimism", "polygon-ecosystem-token"] }, { key: "speculative", label: "Spéculatif liquide", role: "Température du risque.", ids: ["dogecoin", "shiba-inu", "pepe"] }, { key: "privacy", label: "Privacy / risque réglementaire", role: "Flux atypiques.", ids: ["monero", "zcash"] }
];

const WATCH_ALIAS = { btc: "bitcoin", bitcoin: "bitcoin", eth: "ethereum", ethereum: "ethereum", sol: "solana", solana: "solana", bnb: "binancecoin", binance: "binancecoin", binancecoin: "binancecoin", xrp: "ripple", ripple: "ripple", usdt: "tether", tether: "tether", usdc: "usd-coin", "usd-coin": "usd-coin", usds: "usds", dai: "dai", ada: "cardano", cardano: "cardano", trx: "tron", tron: "tron", doge: "dogecoin", dogecoin: "dogecoin", link: "chainlink", chainlink: "chainlink", ton: "toncoin", toncoin: "toncoin", avax: "avalanche-2", avalanche: "avalanche-2", dot: "polkadot", polkadot: "polkadot", ltc: "litecoin", litecoin: "litecoin", uni: "uniswap", uniswap: "uniswap", aave: "aave", ondo: "ondo-finance", "ondo-finance": "ondo-finance", mkr: "maker", maker: "maker", sky: "maker", pendle: "pendle", near: "near", tao: "bittensor", bittensor: "bittensor", render: "render-token", rndr: "render-token", "render-token": "render-token", icp: "internet-computer", "internet-computer": "internet-computer", sui: "sui", apt: "aptos", aptos: "aptos", arb: "arbitrum", arbitrum: "arbitrum", op: "optimism", optimism: "optimism", pol: "polygon-ecosystem-token", matic: "polygon-ecosystem-token", polygon: "polygon-ecosystem-token", shib: "shiba-inu", "shiba-inu": "shiba-inu", pepe: "pepe", xmr: "monero", monero: "monero", zec: "zcash", zcash: "zcash"
};

function atlasWatchDefaultIds() { return [...new Set(ATLAS_WATCH_BASKETS.flatMap(b => b.ids))];
}

function normalizeWatchId(value) { const raw = String(value || "").trim().toLowerCase(); if (!raw) return ""; return WATCH_ALIAS[raw] || raw.replace(/\s+/g, "-");
}

function saveWatchIds() { try { localStorage.setItem(WATCH_STORAGE_KEY, JSON.stringify(state.watchIds)); } catch {}
}

function loadWatchIds() {
  try {
    const raw = localStorage.getItem(WATCH_STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : null;
    if (Array.isArray(parsed)) {
      const ids = [...new Set(parsed.map(normalizeWatchId).filter(Boolean))].slice(0, 48);
      if (ids.length) {
        state.watchIds = ids;
        atlasWatchSyncProfiles();
        return;
      }
    }
  } catch {}
  state.watchIds = atlasWatchDefaultIds();
  saveWatchIds();
  atlasWatchSyncProfiles();
}

function addWatch() {
  const id = normalizeWatchId(els.watchInput?.value);
  if (!id) return;

  if (!state.watchIds.includes(id)) state.watchIds.push(id);
  state.watchIds = [...new Set(state.watchIds)].slice(0, 48);
  saveWatchIds();

  const note = String($("watchNoteInput")?.value || "").trim();
  atlasWatchSyncProfiles();
  if (note) atlasWatchSetProfileNote(id, note);

  if (els.watchInput) els.watchInput.value = "";
  if ($("watchNoteInput")) $("watchNoteInput").value = "";

  renderWatchlist();
  renderAutoReader();
}

function seedWatch() {
  state.watchIds = atlasWatchDefaultIds();
  saveWatchIds();
  atlasWatchSyncProfiles();
  renderWatchlist();
  renderAutoReader();
}

function watchCoinById(id) { return state.coins.find(c => c.id === id) || null;
}

function watchBasketCoins(basket) { return basket.ids.filter(id => (state.watchIds || []).includes(id)).map(watchCoinById).filter(Boolean);
}

function basketStatus(coins) { if (!coins.length) return { label: "À charger", mode: "wait", avg: null }; const avg = coins.reduce((s, c) => s + (Number(c.change24h) || 0), 0) / coins.length; const mode = avg > 3 ? "hot" : avg < -3 ? "cold" : "calm"; const label = mode === "hot" ? "En hausse" : mode === "cold" ? "Sous pression" : "Calme"; return { label, mode, avg };
}

/* ============================================================
   32.0 — DEVICE ROLE GATE · TRANSFORMER BOOK STOP
   Per-browser role. Market data remain live in observer mode, while
   Atlas/Aerith/Ollama calls and Bridge health polling are disabled.
   ============================================================ */

const ATLAS_DEVICE_COMPUTE_ROLE_KEY = "agent_crypto_device_compute_role_v1";
const ATLAS_DEVICE_COMPUTE_ROLES = Object.freeze({
  PRODUCTION: "production",
  OBSERVER: "observer"
});

function atlasDeviceComputeSuggestedRole() {
  try {
    const collector = String(typeof getCollectorId === "function" ? getCollectorId() : "").toLocaleLowerCase("fr-FR");
    if (/transformer[\s_-]*book/.test(collector)) return ATLAS_DEVICE_COMPUTE_ROLES.OBSERVER;
  } catch (_) {}
  return ATLAS_DEVICE_COMPUTE_ROLES.PRODUCTION;
}

function atlasDeviceComputeRoleRead() {
  try {
    const stored = String(localStorage.getItem(ATLAS_DEVICE_COMPUTE_ROLE_KEY) || "").trim();
    if (stored === ATLAS_DEVICE_COMPUTE_ROLES.PRODUCTION || stored === ATLAS_DEVICE_COMPUTE_ROLES.OBSERVER) return stored;
  } catch (_) {}
  return atlasDeviceComputeSuggestedRole();
}

function atlasDeviceComputeAllowed() {
  return atlasDeviceComputeRoleRead() === ATLAS_DEVICE_COMPUTE_ROLES.PRODUCTION;
}

function atlasDeviceComputeSetStatus(message, tone = "idle") {
  const status = document.getElementById("atlasDeviceComputeStatus");
  if (status) {
    status.textContent = message;
    status.dataset.tone = tone;
  }
}

function atlasDeviceComputeApply(options = {}) {
  const role = atlasDeviceComputeRoleRead();
  const production = role === ATLAS_DEVICE_COMPUTE_ROLES.PRODUCTION;
  const control = document.getElementById("atlasDeviceComputeControl");
  if (control) control.dataset.computeRole = role;

  document.querySelectorAll("[data-atlas-compute-role]").forEach(button => {
    const active = button.dataset.atlasComputeRole === role;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });

  const localActions = [
    "btnAtlasLocalAsk",
    "btnAtlasLocalConclusion",
    "btnAtlasLocalRunAll",
    "btnLocalBridgeProbe"
  ];
  localActions.forEach(id => {
    const node = document.getElementById(id);
    if (!node) return;
    if (!production) {
      node.dataset.computeRoleDisabled = "1";
      node.disabled = true;
    } else if (node.dataset.computeRoleDisabled === "1") {
      delete node.dataset.computeRoleDisabled;
      if (id === "btnLocalBridgeProbe" || id === "btnAtlasLocalAsk" || id === "btnAtlasLocalRunAll") node.disabled = false;
    }
  });
  document.querySelectorAll("[data-atlas-local-summary]").forEach(button => {
    if (!production) {
      button.dataset.computeRoleDisabled = "1";
      button.disabled = true;
    } else if (button.dataset.computeRoleDisabled === "1") {
      delete button.dataset.computeRoleDisabled;
      button.disabled = false;
    }
  });

  if (production) {
    atlasDeviceComputeSetStatus("PRODUCTION · Atlas/Aerith/Ollama autorisés sur ce poste.", "ready");
    setText(document.getElementById("atlasLocalRuntime"), atlasLocalDialogueState.connected
      ? "RYZEN · ollama · gpt-oss:20b-32k · production locale"
      : "Production locale autorisée · Bridge en attente");
    if (options.restart === true) {
      atlasLocalReportsOpenAutomaticCycle("device-production-enabled");
      atlasLocalBridgeAutoSync("device-production-enabled");
      atlasCurrentSyncFromLiveGate("device-production-enabled");
      atlasLocalReportsScheduleAutomatic("snapshot", { delayMs: 900 });
    }
  } else {
    atlasLocalReportsClearAutoTimer();
    atlasLocalReportsState.deferredRetryReason = "";
    atlasLocalReportsState.deferredRetryDelayMs = 0;
    atlasLocalReportsState.deferredRetryRequestedAt = 0;
    atlasLocalBridgeAutoStop();
    atlasExchangeStableGateCancelTimer();
    atlasDeviceComputeSetStatus("LECTURE SEULE · STOP calcul local sur ce poste · marché live conservé.", "stop");
    setText(document.getElementById("atlasLocalRuntime"), "Lecture seule · STOP calcul local sur ce poste");
    setText(document.getElementById("atlasLocalDialogueStatus"), "Ce poste est en lecture seule : aucun appel Atlas/Aerith/Ollama n’est envoyé au Bridge.");
    atlasAnalysisProgressRender(0, "observer", "Marché live actif · aucun calcul Atlas/Aerith/Ollama depuis ce navigateur. Réactive Production seulement sur le poste producteur.");
  }
  try { atlasBookReadOnlyKnowledgeRefresh(); } catch (_) {}
  return role;
}

function atlasDeviceComputeSetRole(role) {
  const next = role === ATLAS_DEVICE_COMPUTE_ROLES.OBSERVER
    ? ATLAS_DEVICE_COMPUTE_ROLES.OBSERVER
    : ATLAS_DEVICE_COMPUTE_ROLES.PRODUCTION;
  try { localStorage.setItem(ATLAS_DEVICE_COMPUTE_ROLE_KEY, next); } catch (_) {}
  return atlasDeviceComputeApply({ restart: next === ATLAS_DEVICE_COMPUTE_ROLES.PRODUCTION });
}

function atlasDeviceComputeInit() {
  document.querySelectorAll("[data-atlas-compute-role]").forEach(button => {
    button.addEventListener("click", () => atlasDeviceComputeSetRole(button.dataset.atlasComputeRole));
  });
  atlasDeviceComputeApply({ restart: false });
}

function atlasDeviceComputeBlockedMessage() {
  return "Calcul local désactivé sur ce poste · mode lecture seule. Le marché live reste actif.";
}

let atlasLocalBridgeAutoTimer = 0;
let atlasLocalBridgeProbeInFlight = false;

let atlasLocalBridgeProbePending = null;

let atlasLocalBridgeLastAutoProbeAt = 0;

let atlasLocalBridgeLastHealthSignature = "";

// 38.6 — Bridge Health Stability Lock.
// Bridge V1.9.5 /health can legitimately take ~4 s because it probes Ollama
// twice (provider inventory, then provider selection). A 3.5 s browser abort
// therefore created false disconnects. Keep a wider client deadline and ignore
// at most two transient silent-probe failures after a recent proven success.
const ATLAS_LOCAL_BRIDGE_HEALTH_TIMEOUT_386_MS = 8_000;
const ATLAS_LOCAL_BRIDGE_HEALTH_GRACE_386_MS = 120_000;
const ATLAS_LOCAL_BRIDGE_HEALTH_FAILURE_LIMIT_386 = 3;
const ATLAS_LOCAL_BRIDGE_REQUEST_TIMEOUT_386_MS = 255_000;
let atlasLocalBridgeLastReadyAt386 = 0;
let atlasLocalBridgeConsecutiveHealthFailures386 = 0;

function atlasLocalBridgeMarkReady386() {
  atlasLocalBridgeLastReadyAt386 = Date.now();
  atlasLocalBridgeConsecutiveHealthFailures386 = 0;
  return atlasLocalBridgeLastReadyAt386;
}

function atlasLocalBridgeTransientHealthAllowed386(silent, wasConnected) {
  if (!silent || !wasConnected || !atlasLocalBridgeLastReadyAt386) return false;
  const age = Date.now() - atlasLocalBridgeLastReadyAt386;
  return age >= 0
    && age <= ATLAS_LOCAL_BRIDGE_HEALTH_GRACE_386_MS
    && atlasLocalBridgeConsecutiveHealthFailures386 < ATLAS_LOCAL_BRIDGE_HEALTH_FAILURE_LIMIT_386;
}

function atlasLocalBridgeAdministratorActive() {
  // Local Bridge supervision belongs to the authorized operator session.
  // It must continue regardless of Basic / Intermediate / Advanced display mode.
  return atlasAccessIsAuthorized() && atlasDeviceComputeAllowed();
}

function atlasLocalBridgeAutoEligible() {
  // 29.3.04: the local Bridge belongs to the authorized operator session,
  // not to the currently displayed Basic/Intermediate/Advanced view.
  // This lets the readiness chain arm itself as soon as the page is loaded
  // and the operator is authorized, while remaining fully local/read-only.
  return atlasAccessIsAuthorized()
    && atlasDeviceComputeAllowed()
    && !atlasLocalDialogueState.busy;
}

function atlasLocalBridgeAutoStop() {
  if (atlasLocalBridgeAutoTimer) {
    window.clearInterval(atlasLocalBridgeAutoTimer);
    atlasLocalBridgeAutoTimer = 0;
  }
}

function atlasLocalBridgeHealthTransition(signature, silent) {
  const next = String(signature || "unknown");
  const changed = next !== atlasLocalBridgeLastHealthSignature;
  atlasLocalBridgeLastHealthSignature = next;
  return !silent || changed;
}

function atlasLocalBridgeAutoTick(reason = "interval") {
  if (!atlasLocalBridgeAutoEligible() || atlasLocalBridgeProbeInFlight) return false;

  const now = Date.now();
  if (
    reason !== "interval"
    && atlasLocalBridgeLastAutoProbeAt
    && now - atlasLocalBridgeLastAutoProbeAt < 2500
  ) {
    return false;
  }

  atlasLocalBridgeLastAutoProbeAt = now;
  atlasLocalBridgeProbeInFlight = true;

  Promise.resolve(atlasLocalBridgeProbe({ silent: true, reason }))
    .catch(() => null)
    .finally(() => {
      atlasLocalBridgeProbeInFlight = false;
    });

  return true;
}

function atlasLocalBridgeAutoStart(options = {}) {
  atlasLocalBridgeAutoStop();
  if (!atlasLocalBridgeAdministratorActive()) return false;

  if (options.immediate !== false) {
    window.setTimeout(
      () => atlasLocalBridgeAutoTick(options.reason || "administration-open"),
      120
    );
  }

  atlasLocalBridgeAutoTimer = window.setInterval(() => {
    atlasLocalBridgeAutoTick("interval");
  }, ATLAS_LOCAL_BRIDGE_AUTO_INTERVAL_MS);

  return true;
}

function atlasLocalBridgeAutoSync(reason = "sync") {
  if (atlasLocalBridgeAdministratorActive()) {
    return atlasLocalBridgeAutoStart({ immediate: true, reason });
  }
  atlasLocalBridgeAutoStop();
  return false;
}

async function atlasLocalBridgeProbe(options = {}) {
  const silent = options?.silent === true;
  if (!atlasDeviceComputeAllowed()) {
    if (!silent) {
      atlasLocalDialogueSetConnection(false, atlasDeviceComputeBlockedMessage());
      atlasDeviceComputeApply({ restart: false });
    }
    return false;
  }

  if (atlasLocalBridgeProbePending) {
    return atlasLocalBridgeProbePending;
  }

  const run = async () => {
    const wasConnectedAtStart386 = atlasLocalDialogueState.connected === true;
    const badge = document.getElementById("localBridgeStatus");
    const detail = document.getElementById("localBridgeDetail");
    const button = document.getElementById("btnLocalBridgeProbe");

    if (!silent) {
      if (button) button.disabled = true;
      if (badge) {
        badge.textContent = "Test du Bridge local…";
        badge.className = "pill warn";
      }
      atlasLocalDialogueSetConnection(false, "Test du Bridge local…");
    }

    const controller = new AbortController();
    const timer = window.setTimeout(() => controller.abort(), ATLAS_LOCAL_BRIDGE_HEALTH_TIMEOUT_386_MS);

    try {
      const response = await fetch(`${ATLAS_LOCAL_BRIDGE_BASE}/health`, {
        cache: "no-store",
        signal: controller.signal,
        headers: { "Accept": "application/json" }
      });

      const payload = await response.json().catch(() => ({}));

      if (!response.ok || payload?.ok === false) {
        throw new Error(payload?.error || `HTTP ${response.status}`);
      }

      atlasStableStackUpdateBridge(payload);
      atlasLocalDialogueState.provider = payload.provider || null;
      atlasLocalDialogueState.model =
        payload.model || payload.required_model || null;

      if (payload.ready === false || payload.model_ready === false) {
        atlasLocalBridgeConsecutiveHealthFailures386 = ATLAS_LOCAL_BRIDGE_HEALTH_FAILURE_LIMIT_386;
        atlasLocalDialogueState.connected = false;
        const required = payload.required_model || "gpt-oss:20b-32k";
        const announce = atlasLocalBridgeHealthTransition(
          `model-missing:${required}`,
          silent
        );

        if (badge) {
          badge.textContent = `${required} requis`;
          badge.className = "pill warn";
        }
        if (detail) {
          detail.textContent =
            `Bridge connecté · modèle ${required} absent. `
            + `Lance CREATE_GPT_OSS_20B_32K.bat ou vérifie le modèle : ${required}`;
        }

        atlasLocalDialogueSetConnection(
          false,
          announce
            ? `Bridge détecté, mais ${required} doit être installé dans Ollama.`
            : ""
        );
        return payload;
      }

      atlasLocalBridgeMarkReady386();
      atlasLocalDialogueState.connected = true;
      const provider = payload.provider || "ollama";
      const model = payload.model || "gpt-oss:20b-32k";
      const announce = atlasLocalBridgeHealthTransition(
        `ready:${provider}:${model}`,
        silent
      );

      if (badge) {
        badge.textContent = "Bridge Ryzen connecté";
        badge.className = "pill ok";
      }
      if (detail) {
        detail.textContent = `Lecture seule · ${provider} · ${model}`;
      }

      atlasLocalDialogueSetConnection(
        true,
        announce
          ? `Dialogue local prêt avec ${model}.`
          : ""
      );
      if (
        announce
        || [
          "administration-open",
          "initial",
          "visibility-return",
          "window-focus",
          "network-online",
          "request-failure",
          "health-retry-386"
        ].includes(String(options?.reason || ""))
      ) {
        atlasLocalReportsState.autoRetryCount = 0;
        atlasLocalReportsClearAutoTimer();
        atlasLocalReportsScheduleAutomatic("bridge-ready", { delayMs: 500 });
      }

      return payload;
    } catch (error) {
      atlasLocalBridgeConsecutiveHealthFailures386 += 1;
      const transient386 = atlasLocalBridgeTransientHealthAllowed386(
        silent,
        wasConnectedAtStart386
      );

      if (transient386) {
        // A single slow /health response must not revoke a connection that was
        // just proven by /health or by a successful model request. The scheduler
        // may continue; a real /summary failure remains definitive.
        atlasLocalDialogueState.connected = true;
        if (badge) {
          badge.textContent = "Bridge Ryzen · contrôle retardé";
          badge.className = "pill warn";
        }
        if (detail) {
          detail.textContent = `Dernier état prêt conservé · contrôle silencieux ${atlasLocalBridgeConsecutiveHealthFailures386}/${ATLAS_LOCAL_BRIDGE_HEALTH_FAILURE_LIMIT_386} · nouvelle vérification automatique.`;
        }
        atlasLocalDialogueSetConnection(
          true,
          `Bridge Ryzen déjà validé · contrôle /health retardé (${atlasLocalBridgeConsecutiveHealthFailures386}/${ATLAS_LOCAL_BRIDGE_HEALTH_FAILURE_LIMIT_386}) · aucune remise à zéro du gate.`
        );
        window.setTimeout(() => atlasLocalBridgeAutoTick("health-retry-386"), 3000);
        return {
          ok: true,
          ready: true,
          model_ready: true,
          transient_health_warning: true,
          retained_from_recent_success: true
        };
      }

      atlasStableStackUpdateBridge(null, error);
      atlasLocalDialogueState.connected = false;
      atlasLocalDialogueState.provider = null;
      atlasLocalDialogueState.model = null;
      const failure = error?.name === "AbortError" ? "timeout" : "offline";
      const announce = atlasLocalBridgeHealthTransition(failure, silent);

      if (badge) {
        badge.textContent = "Bridge local non connecté";
        badge.className = "pill warn";
      }
      if (detail) {
        detail.textContent =
          "Le cockpit reste fonctionnel. Lance START_BRIDGE.bat "
          + "et autorise l’accès local dans Firefox.";
      }

      atlasLocalDialogueSetConnection(
        false,
        announce
          ? (error?.name === "AbortError"
              ? `Bridge local sans réponse après ${Math.round(ATLAS_LOCAL_BRIDGE_HEALTH_TIMEOUT_386_MS / 1000)} s.`
              : "Bridge local non connecté.")
          : ""
      );

      return null;
    } finally {
      window.clearTimeout(timer);
      if (!silent && button) button.disabled = false;
    }
  };

  atlasLocalBridgeProbePending = run();

  try {
    return await atlasLocalBridgeProbePending;
  } finally {
    atlasLocalBridgeProbePending = null;
  }
}

