function atlasLocalFinite(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function atlasLocalText(value, fallback = null) {
  const text = String(value ?? "").trim();
  return text || fallback;
}

function atlasLocalCompactCoin(coin, options = {}) {
  if (!coin) return null;
  const quote = options.quote ? atlasCurrentQuoteForCoin(coin) : null;
  let score = null;
  try { score = scoreCoin(coin)?.score ?? null; } catch {}
  return {
    id: coin.id || null,
    symbol: String(coin.symbol || "").toUpperCase() || null,
    name: coin.name || null,
    rank: atlasLocalFinite(coin.rank),
    price_eur: quote ? atlasLocalFinite(quote.price) : atlasLocalFinite(coin.priceEur ?? coin.price),
    quote_status: quote?.status || null,
    quote_source: quote?.source || coin.source || state.mainSource || null,
    quote_time: quote?.timestamp ? new Date(quote.timestamp).toISOString() : null,
    change_24h_pct: quote && Number.isFinite(Number(quote.change24h))
      ? Number(quote.change24h)
      : atlasLocalFinite(coin.change24h),
    change_7d_pct: atlasLocalFinite(coin.change7d),
    change_30d_pct: atlasLocalFinite(coin.change30d),
    market_cap_eur: atlasLocalFinite(coin.marketCap),
    volume_24h_eur: atlasLocalFinite(coin.volume24h ?? coin.volume),
    score_atlas: atlasLocalFinite(score),
    category: (() => { try { return classifyAsset(coin); } catch { return null; } })()
  };
}

function atlasStrictContradictions(contract) {
  const issues = [];

  if (!contract.canonical_top5.complete) {
    issues.push({
      level: "confirmé",
      code: "top5_incomplet",
      text: `Target Top 5 incomplet : ${contract.canonical_top5.missing_symbols.join(", ")}`
    });
  }

  if (contract.market.assets_loaded !== null && contract.market.assets_loaded < contract.market.target_assets) {
    issues.push({
      level: "confirmé",
      code: "univers_partiel",
      text: `Univers CoinGecko partiel : ${contract.market.assets_loaded}/${contract.market.target_assets} actifs`
    });
  }

  if (!contract.graph.status || contract.graph.status !== "ready") {
    issues.push({
      level: "confirmé",
      code: "graph_non_pret",
      text: "Le graphique actif n’est pas dans l’état ready."
    });
  }

  if (contract.graph.truth_source !== "direct") {
    issues.push({
      level: "à vérifier",
      code: "graph_non_direct",
      text: `Historique graphique non direct : ${contract.graph.truth_label || "état inconnu"}`
    });
  }

  if (!String(contract.math.risk_global || "").startsWith("Partiel")) {
    issues.push({
      level: "confirmé",
      code: "risque_global_absent",
      text: "Le risque global historique n’est pas évalué par Math Core V3."
    });
  }

  if (!contract.news.lead_event) {
    issues.push({
      level: "à vérifier",
      code: "news_sans_evenement_directeur",
      text: "Aucun événement directeur News Sentinel n’est disponible dans le contrat."
    });
  }

  return issues;
}

function atlasBuildStrictFactContractCore(period, chart, chartResult, comparisonIds, chartTruth) {
  const market = {
    snapshot_id: state.sourceLock?.snapshotId || state.dataBroker?.market?.snapshotId || state.dataBroker?.marketFrame?.id || null,
    source: state.dataBroker?.market?.source || "CoinGecko",
    mode: state.dataBroker?.market?.mode || null,
    status: state.dataBroker?.market?.status || null,
    timestamp: atlasStrictTimestamp(state.dataBroker?.market?.timestamp || state.timestamp),
    assets_loaded: atlasStrictNumber(
      state.dataBroker?.market?.assetsCount ?? state.coins?.length,
      0
    ),
    target_assets: 250,
    quote_currency: "EUR",
    breadth_24h: atlasStrictMarketBreadth()
  };

  const contract = {
    schema: "atlas_crypto_fact_contract_v2",
    generated_at: new Date().toISOString(),
    release: ATLAS_RELEASE,
    rules: {
      market_list_is_not_portfolio: true,
      canonical_top5_symbols: ["BTC", "ETH", "BNB", "XRP", "SOL"],
      no_missing_value_to_zero: true,
      no_visual_position_inference: true,
      no_unlisted_math_measure: true,
      no_news_from_generic_limit: true,
      no_financial_instruction: true
    },
    sources: {
      binance: {
        role: "prix live et historiques compatibles du Target Top 5",
        feed_status: state.dataBroker?.exchangeFeed?.status || null,
        source: state.dataBroker?.exchangeFeed?.source || "Binance WebSocket",
        last_message_at: atlasStrictTimestamp(state.dataBroker?.exchangeFeed?.lastMessageAt),
        direct_pairs: atlasStrictNumber(state.dataBroker?.exchangeFeed?.directCount, 0),
        derived_pairs: atlasStrictNumber(state.dataBroker?.exchangeFeed?.derivedCount, 0),
        stable_5_5_ready: state.dataBroker?.exchangeFeed?.atlasStableReady === true,
        stable_5_5_since: atlasStrictTimestamp(
          state.dataBroker?.exchangeFeed?.directReadySince
            ? new Date(state.dataBroker.exchangeFeed.directReadySince)
            : null
        ),
        stable_5_5_checks: atlasStrictNumber(state.dataBroker?.exchangeFeed?.directReadyChecks, 0),
        stable_5_5_required_ms: ATLAS_DIRECT_5_5_STABLE_MS
      },
      coingecko: {
        role: "marché global, Market Flow, classement et historiques non-Binance",
        status: market.status,
        mode: market.mode,
        timestamp: market.timestamp
      }
    },
    canonical_top5: atlasStrictCanonicalTop5(),
    market,
    graph: atlasStrictGraphContract(period, chart, chartResult, comparisonIds, chartTruth),
    math: atlasStrictMathContract(),
    news: atlasStrictNewsContract(),
    watchlist: {
      configured_count: atlasStrictNumber((state.watchIds || []).length, 0),
      note: "Une watchlist est une liste d’observation, pas un portefeuille."
    },
    stop_point: {
      meaning: "Arrêter l’analyse lorsque les données ne soutiennent plus une conclusion.",
      duration_days: null
    }
  };

  contract.contradictions = atlasStrictContradictions(contract);
  return contract;
}

function atlasLocalDialogueSetConnection(connected, message = "") {
  atlasLocalDialogueState.connected = !!connected;
  const badge = document.getElementById("atlasLocalDialogueBadge");
  const runtime = document.getElementById("atlasLocalRuntime");
  const status = document.getElementById("atlasLocalDialogueStatus");

  if (badge) {
    badge.textContent = connected ? "Dialogue local prêt" : "Bridge à tester";
    badge.className = `pill ${connected ? "ok" : "warn"}`;
  }
  if (runtime) {
    runtime.textContent = connected
      ? `Lecture seule · ${atlasLocalDialogueState.provider || "moteur local"} · ${atlasLocalDialogueState.model || "modèle actif"}`
      : "Lecture seule · moteur local en attente";
  }
  if (message && status) status.textContent = message;
}

function atlasLocalDialogueSelectProfile(profile = "atlas") {
  const next = profile === "aerith" ? "aerith" : "atlas";
  atlasLocalDialogueState.profile = next;
  document.querySelectorAll("[data-atlas-local-profile]").forEach(button => {
    const active = button.dataset.atlasLocalProfile === next;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
  const ask = document.getElementById("btnAtlasLocalAsk");
  if (ask) ask.textContent = next === "atlas" ? "Interroger Atlas-10" : "Interroger Aerith-10";
}

function atlasLocalDialogueSetBusy(busy, message = "") {
  atlasLocalDialogueState.busy = !!busy;
  const computeBlocked = !atlasDeviceComputeAllowed();
  document.querySelectorAll(
    "#btnAtlasLocalAsk, [data-atlas-local-summary], #btnLocalBridgeProbe, #btnAtlasLocalRunAll"
  ).forEach(button => { button.disabled = !!busy || computeBlocked; });
  document.querySelectorAll("[data-atlas-local-profile]").forEach(button => { button.disabled = !!busy; });
  const status = document.getElementById("atlasLocalDialogueStatus");
  if (status && message) status.textContent = message;
  const badge = document.getElementById("atlasLocalDialogueBadge");
  if (badge && busy) {
    badge.textContent = "Analyse locale en cours…";
    badge.className = "pill warn";
  } else if (badge) {
    badge.textContent = atlasLocalDialogueState.connected ? "Dialogue local prêt" : "Bridge à tester";
    badge.className = `pill ${atlasLocalDialogueState.connected ? "ok" : "warn"}`;
  }
}


function atlasLocalBridgeRequestFailureKind(error) {
  if (error?.name === "AbortError" || error?.name === "AtlasBridgeTimeoutError") return "timeout";
  if (error?.name === "TypeError") return "offline";
  const message = String(error?.message || "").toLowerCase();
  if (message.includes("networkerror") || message.includes("failed to fetch") || message.includes("network")) return "offline";
  return "bridge-error";
}

function atlasLocalBridgeRequestFailure(error, path = "") {
  const kind = atlasLocalBridgeRequestFailureKind(error);
  if (!["timeout", "offline"].includes(kind)) return kind;

  atlasLocalDialogueState.connected = false;
  const label = kind === "timeout"
    ? "Bridge local trop lent ou sans réponse · supervision automatique active."
    : "Bridge local momentanément indisponible · supervision automatique active.";

  atlasLocalDialogueSetConnection(false, label);

  // Make the automatic health watcher responsible for recovery.
  atlasLocalBridgeAutoStart({ immediate: true, reason: "request-failure" });
  atlasLocalReportsScheduleAutomatic("bridge-ready", { delayMs: 3500 });
  return kind;
}

async function atlasLocalBridgeRequest(path, payload, timeoutMs = ATLAS_LOCAL_BRIDGE_REQUEST_TIMEOUT_386_MS) {
  if (!atlasDeviceComputeAllowed()) {
    const error = new Error(atlasDeviceComputeBlockedMessage());
    error.name = "AtlasDeviceObserverError";
    throw error;
  }
  const controller = new AbortController();
  let timedOut = false;
  const timer = window.setTimeout(() => {
    timedOut = true;
    controller.abort();
  }, timeoutMs);

  try {
    const response = await fetch(`${ATLAS_LOCAL_BRIDGE_BASE}${path}`, {
      method: "POST",
      cache: "no-store",
      signal: controller.signal,
      headers: {
        "Accept": "application/json",
        "Content-Type": "application/json; charset=utf-8"
      },
      body: JSON.stringify(payload)
    });

    const result = await response.json().catch(() => ({}));
    if (!response.ok || result?.ok === false) {
      throw new Error(result?.error || `Bridge HTTP ${response.status}`);
    }

    // A successful model request is stronger evidence than a periodic probe.
    atlasLocalBridgeMarkReady386();
    atlasLocalDialogueState.connected = true;
    return result;
  } catch (error) {
    let raised = error;
    if (timedOut || error?.name === "AbortError") {
      raised = new Error(`Bridge timeout après ${Math.round(timeoutMs / 1000)} s`);
      raised.name = "AtlasBridgeTimeoutError";
      raised.cause = error;
    }

    atlasLocalBridgeRequestFailure(raised, path);
    throw raised;
  } finally {
    window.clearTimeout(timer);
  }
}

function atlasLocalEscapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function atlasLocalInlineMarkup(value) {
  return atlasLocalEscapeHtml(value)
    .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
    .replace(/`(.+?)`/g, "<code>$1</code>");
}

function atlasLocalReportHtml(markdown) {
  const source = String(markdown || "").replace(/\r\n?/g, "\n").trim();
  if (!source) {
    return '<p class="atlas-local-response-empty">Réponse locale vide.</p>';
  }

  const lines = source.split("\n");
  const html = [];
  let listOpen = false;

  const closeList = () => {
    if (listOpen) {
      html.push("</ul>");
      listOpen = false;
    }
  };

  for (const rawLine of lines) {
    const line = rawLine.trim();

    if (!line) {
      closeList();
      continue;
    }

    const heading = line.match(/^\*\*(.+?)\*\*$/);
    if (heading) {
      closeList();
      html.push(`<h4>${atlasLocalInlineMarkup(heading[1])}</h4>`);
      continue;
    }

    if (/^[-*]\s+/.test(line)) {
      if (!listOpen) {
        html.push("<ul>");
        listOpen = true;
      }
      html.push(`<li>${atlasLocalInlineMarkup(line.replace(/^[-*]\s+/, ""))}</li>`);
      continue;
    }

    closeList();
    html.push(`<p>${atlasLocalInlineMarkup(line)}</p>`);
  }

  closeList();
  return html.join("");
}

function atlasNormalizeAnalyticalSafetyLanguage(value = "") {
  return String(value || "")
    .replace(/(^|\n)\s*[-*]\s*Validation humaine obligatoire\.?(?=\n|$)/gi,
      "$1- Chaîne analytique automatique : aucune validation humaine n’est requise entre Atlas, NØX et Aerith. Validation humaine uniquement avant une décision ou action financière réelle.")
    .replace(/(^|\n)\s*Validation humaine obligatoire\.?(?=\n|$)/gi,
      "$1Validation humaine uniquement avant une décision ou action financière réelle ; jamais pour autoriser la synthèse Atlas → NØX → Aerith.")
    .replace(/Toute interprétation causale doit être confirmée par validation humaine\.?/gi,
      "Toute interprétation causale non démontrée reste classée à confirmer. Validation humaine uniquement avant une décision ou action financière réelle.")
    .replace(/Human validation is required before any interpretation or action\.?/gi,
      "La chaîne analytique reste automatique ; validation humaine uniquement avant une décision ou action financière réelle.")
    .replace(/Validation humaine requise\.(?![^\n]*décision ou action financière réelle)/gi,
      "Validation humaine requise uniquement avant une décision ou action financière réelle.");
}

function atlasLocalSetReport(node, markdown) {
  if (!node) return false;
  const source = atlasNormalizeAnalyticalSafetyLanguage(markdown).trim();
  if (!source) return false;
  node.innerHTML = atlasLocalReportHtml(source);
  if (!String(node.textContent || "").trim()) {
    node.textContent = source;
  }
  return !!String(node.textContent || "").trim();
}

function atlasLocalCommentFilterStatus(warnings) {
  const items = Array.isArray(warnings) ? warnings.filter(Boolean) : [];
  if (!items.length) {
    return "Rapport factuel terminé. Commentaire local accepté. La chaîne analytique continue automatiquement ; validation humaine uniquement avant une décision financière réelle.";
  }
  return "Rapport factuel terminé. Le commentaire local n’a pas passé le filtre et a été remplacé par le repli sûr.";
}

function atlasLocalReportSnapshotLabel(snapshot) {
  const timestamp = snapshot?.strict_contract?.market?.timestamp
    || snapshot?.raw_context?.source_status?.market_timestamp
    || snapshot?.generated_at;
  if (!timestamp) return "snapshot courant";
  const date = new Date(timestamp);
  return Number.isFinite(date.getTime())
    ? date.toLocaleString("fr-FR")
    : String(timestamp);
}

function atlasLocalReportResult(mode) {
  return atlasLocalReportsState.reports?.[mode] || null;
}

function atlasLocalReportAnswer(result) {
  return String(result?.answer || "").replace(/\r\n?/g, "\n").trim();
}

function atlasLocalReportAnswerIsMeaningful(mode, result) {
  const answer = atlasLocalReportAnswer(result);
  if (answer.length < 120) return false;
  if (/^(?:réponse locale vide|aucun rapport généré|undefined|null)$/i.test(answer)) return false;
  const markers = {
    market: ["État des sources", "Lecture globale déterministe", "Stop point"],
    top5: ["Target Top 5 canonique", "Graphique lié au Top 5", "Stop point"],
    math: ["Math Core", "mesures réellement calculées", "Stop point"],
    contradictions: ["Verrous du contrat", "Contradictions détectées", "Stop point"]
  }[mode] || ["Stop point"];
  return markers.filter(marker => answer.toLocaleLowerCase("fr-FR").includes(marker.toLocaleLowerCase("fr-FR"))).length >= 2;
}

function atlasLocalReportsReadiness(snapshot) {
  const contract = snapshot?.strict_contract || {};
  const market = contract.market || {};
  const binance = contract.sources?.binance || {};
  const graph = contract.graph || {};
  const marketCount = Number(market.assets_loaded || 0);
  const directPairs = Number(binance.direct_pairs || 0);
  const binanceTime = Date.parse(binance.last_message_at || "");
  const binanceFresh = Number.isFinite(binanceTime) && (Date.now() - binanceTime) <= 120000;
  const graphRows = Array.isArray(graph.series) ? graph.series.filter(Boolean) : [];
  const graphReady = graph.status === "ready" && graphRows.length > 0;
  const marketReady = state.liveOk === true && marketCount >= 200 && !!market.timestamp;
  const bridgeReady = atlasLocalDialogueState.connected === true;
  const derivedPairs = Number(binance.derived_pairs || 0);
  const stableReady = binance.stable_5_5_ready === true;
  const stableSince = Date.parse(binance.stable_5_5_since || "");
  const stableAgeMs = Number.isFinite(stableSince) ? Math.max(0, Date.now() - stableSince) : 0;
  const binanceReady = binance.feed_status === "ready"
    && directPairs === 5
    && derivedPairs === 0
    && binanceFresh
    && stableReady;
  return {
    ready: bridgeReady && marketReady && binanceReady && graphReady,
    bridgeReady,
    marketReady,
    binanceReady,
    graphReady,
    marketCount,
    directPairs,
    derivedPairs,
    stableReady,
    stableAgeMs
  };
}

function atlasLocalReportsReadinessLabel(readiness) {
  if (!readiness.bridgeReady) return "État LIVE de déclenchement · Atlas en attente · Bridge local non prêt.";
  if (!readiness.marketReady) return "État LIVE de déclenchement · Atlas en attente · snapshot CoinGecko exploitable requis.";
  if (readiness.directPairs < 5) return `État LIVE actuel, distinct du snapshot CURRENT conservé · Atlas en attente · prix disponibles ${Math.min(5, Number(readiness.directPairs || 0) + Number(readiness.derivedPairs || 0))}/5 · Binance ${readiness.directPairs}/5 directes · ${Number(readiness.derivedPairs || 0)} secours · aucun départ avant 5/5 directes stables.`;
  if (!readiness.stableReady) return `État LIVE de déclenchement · Atlas armé · Binance 5/5 directes détectées mais encore instables · confirmation continue ${Math.min(ATLAS_DIRECT_5_5_STABLE_MS / 1000, Math.floor(Number(readiness.stableAgeMs || 0) / 1000))}/${ATLAS_DIRECT_5_5_STABLE_MS / 1000}s.`;
  if (!readiness.graphReady) return "État LIVE de déclenchement · Atlas en attente · graphique exploitable requis.";
  return "État LIVE de déclenchement qualifié · 5/5 Binance directes stables · 0 secours · sources prêtes · démarrage Atlas autorisé.";
}

