function atlasLocalReportStoreCore(mode, result, snapshot, options = {}) {
  if (!ATLAS_LOCAL_REPORT_MODES.includes(mode)) return null;
  if (!atlasLocalReportAnswerIsMeaningful(mode, result)) return null;
  const answer = atlasLocalReportAnswer(result);

  const report = {
    mode,
    label: ATLAS_LOCAL_REPORT_LABELS[mode],
    answer,
    profile: result?.profile || "atlas",
    provider: result?.provider || atlasLocalDialogueState.provider || "local",
    model: result?.model || atlasLocalDialogueState.model || "modèle local",
    time: result?.time || new Date().toISOString(),
    snapshotLabel: atlasLocalReportSnapshotLabel(snapshot),
    fingerprint: atlasLocalReportSnapshotFingerprint(snapshot),
    quality: result?.quality || "strict_contract_v2",
    modelCommentUsed: result?.model_comment_used === true
  };

  const ids = ATLAS_LOCAL_REPORT_IDS[mode];
  const contentNode = document.getElementById(ids.content);
  if (!atlasLocalSetReport(contentNode, report.answer)) return null;

  atlasLocalReportsState.reports[mode] = report;
  setText(document.getElementById(ids.meta), `${report.snapshotLabel} · ${report.model}`);
  atlasLocalReportSetCardState(mode, "Prêt", "ready");
  document.querySelector(`[data-atlas-report-copy="${mode}"]`)?.removeAttribute("disabled");
  document.querySelector(`[data-atlas-report-export="${mode}"]`)?.removeAttribute("disabled");

  if (options.open === true) {
    document.querySelector(`[data-atlas-report-card="${mode}"]`)?.setAttribute("open", "");
  }
  return report;
}

function atlasAnalysisProgressRender(completed = 0, phase = "idle", message = "") {
  const card = document.getElementById("atlasAnalysisProgressCard");
  if (!card) return false;

  if (!atlasDeviceComputeAllowed() && phase !== "done") {
    completed = 0;
    phase = "observer";
    message = "Marché live actif · aucun calcul Atlas/Aerith/Ollama depuis ce navigateur. Réactive Production seulement sur le poste producteur.";
  }

  const safeCompleted = Math.max(0, Math.min(4, Number(completed) || 0));
  const percent = (phase === "nox" || phase === "aerith" || phase === "done")
    ? 100
    : atlasLocalReportsProgressPercent(safeCompleted, 4);
  card.dataset.phase = phase;

  const bar = document.getElementById("atlasAnalysisProgressBar");
  const pct = document.getElementById("atlasAnalysisProgressPercent");
  const title = document.getElementById("atlasAnalysisProgressTitle");
  const detail = document.getElementById("atlasAnalysisProgressDetail");
  const stateNode = document.getElementById("atlasAnalysisProgressState");
  if (bar) bar.style.width = `${percent}%`;
  if (pct) pct.textContent = `${percent} %`;

  document.querySelectorAll("[data-atlas-progress-node]").forEach(node => {
    const key = String(node.dataset.atlasProgressNode || "");
    const n = Number(key);
    const isAtlas = Number.isFinite(n) && n >= 1 && n <= 4;
    const isNox = key === "nox";
    const isAerith = key === "aerith";
    const done = isAtlas ? n <= safeCompleted
      : isNox ? ["nox", "aerith", "done"].includes(phase)
      : isAerith ? phase === "done"
      : false;
    const active = isAtlas ? phase === "atlas" && n === Math.min(4, safeCompleted + 1)
      : isNox ? phase === "nox"
      : isAerith ? phase === "aerith"
      : false;
    node.classList.toggle("is-done", done);
    node.classList.toggle("is-active", active);
  });

  const labels = {
    idle: "Atlas-10 prêt à analyser",
    history: "Historique disponible · CURRENT à produire",
    observer: "Lecture seule · calcul local STOP sur ce poste",
    atlas: `Atlas-10 · ${safeCompleted}/4 rapports CURRENT`,
    nox: "NØX · contrôle No-FOMO et contradictions",
    aerith: "Aerith-10 · synthèse complète et vulgarisation",
    done: "CURRENT validé · moteur local au repos",
    error: "Cycle arrêté proprement · résultat incomplet"
  };
  if (title) title.textContent = labels[phase] || labels.idle;
  if (detail) detail.textContent = message || (phase === "done"
    ? "Les prix live continuent ; Atlas/Aerith restent au repos jusqu’au prochain snapshot canonique qualifié ou à une relance opérateur explicite."
    : "Un seul snapshot figé est utilisé pour les rapports et la conclusion.");
  if (stateNode) stateNode.textContent = phase === "done" ? "REPOS" : phase === "history" ? "HISTORIQUE" : phase === "observer" ? "STOP POSTE" : phase.toUpperCase();
  return true;
}

function atlasLocalReportsSetSuiteStatus(message, tone = "idle") {
  const status = document.getElementById("atlasLocalReportsStatus");
  if (status) {
    status.textContent = message;
    status.dataset.tone = tone;
  }
}

function atlasLocalReportsSetBusy(busy) {
  atlasLocalReportsState.running = !!busy;
  atlasLocalDialogueState.busy = !!busy;
  const computeBlocked = !atlasDeviceComputeAllowed();
  document.querySelectorAll(
    "#btnAtlasLocalAsk, #btnAtlasQuestionAtlas37, #btnAtlasQuestionAerith37, #btnAtlasQuestionChain37, [data-atlas-local-summary], #btnLocalBridgeProbe"
  ).forEach(button => { button.disabled = !!busy || computeBlocked; });
  document.querySelectorAll("[data-atlas-local-profile]").forEach(button => { button.disabled = !!busy; });
  const button = document.getElementById("btnAtlasLocalRunAll");
  if (button) {
    button.disabled = !!busy || computeBlocked;
    button.setAttribute("aria-busy", busy ? "true" : "false");
    button.textContent = busy ? "Analyse en cours…" : "Analyse complète";
  }
  document.querySelectorAll("[data-atlas-report-copy], [data-atlas-report-export]").forEach(button => {
    if (busy) button.setAttribute("data-was-disabled", button.disabled ? "1" : "0");
    if (busy) button.disabled = true;
    else if (button.dataset.wasDisabled === "0") button.disabled = false;
    if (!busy) button.removeAttribute("data-was-disabled");
  });
}

function atlasLocalReportsValidSnapshot(snapshot) {
  return atlasLocalReportsReadiness(snapshot).ready;
}

function atlasLocalReportsWait(ms) {
  return new Promise(resolve => window.setTimeout(resolve, Math.max(0, Number(ms) || 0)));
}


function atlasTextEnglishMarkerScore(text) {
  const value = String(text || "").toLocaleLowerCase("en-US");
  const markers = [
    "snapshot shows", "sources are", "sources binance and coingecko", "observations must", "the market", "market breadth",
    "data gaps", "graph data", "evidence is limited", "no causal", "reports are not", "are unavailable",
    "is unavailable", "must be treated", "coverage is", "preclude definitive", "conclusions are therefore",
    "human validation is required", "warrants continued observation", "no causal link"
  ];
  const phraseScore = markers.reduce((score, marker) => score + (value.includes(marker) ? 1 : 0), 0);
  const englishTokens = [
    " the ", " and ", " are ", " is ", " with ", " but ", " yet ", " before ", " required ",
    " evidence ", " coverage ", " market ", " sources ", " data ", " human ", " confirmed "
  ];
  const padded = ` ${value.replace(/[^a-zà-ÿ0-9]+/g, " ")} `;
  const tokenScore = englishTokens.reduce((score, token) => score + (padded.includes(token) ? 1 : 0), 0);
  return phraseScore + (tokenScore >= 4 ? 1 : 0);
}

function atlasMarkdownReplaceNamedSection(text, headingLabel, replacement) {
  const source = String(text || "").replace(/\r\n?/g, "\n");
  const heading = new RegExp(`^####\\s+\\d+\\.\\s+${headingLabel}\\s*$`, "mi");
  const match = heading.exec(source);
  if (!match) return source;
  const start = match.index;
  const afterHeading = start + match[0].length;
  const tail = source.slice(afterHeading);
  const nextHeading = /\n####\s+\d+\./m.exec(tail);
  const end = nextHeading ? afterHeading + nextHeading.index + 1 : source.length;
  return `${source.slice(0, start)}${replacement.trim()}\n\n${source.slice(end)}`.trim();
}

function atlasLocalFrenchCommentFallback(mode, snapshot) {
  const contract = snapshot?.strict_contract || {};
  const market = contract.market || {};
  const breadth = market.breadth_24h || {};
  const math = contract.math || {};
  const risk = math.historical_risk || {};
  const contradictions = Array.isArray(contract.contradictions) ? contract.contradictions : [];
  const top5 = contract.canonical_top5 || {};
  const assets = Array.isArray(top5.assets) ? top5.assets : [];
  const directions = atlasTop5DirectionCounts(assets, 0);
  const lines = [];
  if (mode === "math") {
    lines.push(`- Lecture Atlas-10 : Math Core décrit ${math.asset || "l’actif courant"} sur ${math.active_window?.period_label || "la fenêtre active"} ; risque global ${math.risk_global || "non évalué"}.`);
    lines.push(`- Prudence : volatilité, drawdown, VaR et Expected Shortfall décrivent l’historique observé ; ils ne prédisent pas la direction future.`);
    lines.push(`- Limites : ${math.limitation || "les limites publiées par Math Core restent applicables"}.`);
  } else if (mode === "contradictions") {
    lines.push(`- Lecture Atlas-10 : ${contradictions.length} contradiction${contradictions.length > 1 ? "s" : ""} factuelle${contradictions.length > 1 ? "s" : ""} enregistrée${contradictions.length > 1 ? "s" : ""} ; aucune causalité n’est ajoutée.`);
    lines.push(`- Prudence : une source manquante, une couverture partielle ou un historique en cache réduisent le niveau de certitude sans invalider automatiquement les autres faits.`);
    lines.push(`- Limites : les contradictions restent classées selon leur état confirmé / à vérifier ; aucune action financière n’en est déduite.`);
  } else if (mode === "top5") {
    lines.push(`- Lecture Atlas-10 : Target Top 5 couvert ${assets.filter(row => row?.available).length}/${assets.length || 5} · ${directions.positive} positifs · ${directions.negative} négatifs · ${directions.stable} stables.`);
    lines.push(`- Prudence : cette répartition décrit seulement le snapshot courant et ne constitue ni prévision ni classement d’investissement.`);
    lines.push(`- Limites : la qualité de lecture dépend des cotations et historiques qualifiés pour chaque actif.`);
  } else {
    lines.push(`- Lecture Atlas-10 : largeur 24 h ${atlasSharedSynthesisNumber(breadth.positive, "—")} hausses · ${atlasSharedSynthesisNumber(breadth.negative, "—")} baisses · ${atlasSharedSynthesisNumber(breadth.stable, "—")} stables.`);
    lines.push(`- Prudence : cette largeur décrit le Market Snapshot ; elle ne donne pas la direction future.`);
    lines.push(`- Limites : couverture ${atlasSharedSynthesisNumber(market.assets_loaded, "—")}/${atlasSharedSynthesisNumber(market.target_assets, "250")} et limites de sources conservées telles quelles.`);
  }
  return `#### ${mode === "market" ? "8" : mode === "top5" ? "4" : mode === "math" ? "3" : "4"}. Commentaire local borné\n\n${lines.join("\n")}`;
}

function atlasLocalReportTruthPolish(mode, result, snapshot) {
  if (!result || typeof result !== "object") return result;
  let answer = atlasNormalizeAnalyticalSafetyLanguage(String(result.answer || "").replace(/\r\n?/g, "\n"));
  const heading = /^####\s+\d+\.\s+Commentaire local borné\s*$/mi;
  const match = heading.exec(answer);
  if (match) {
    const tail = answer.slice(match.index + match[0].length);
    const next = /\n####\s+\d+\./m.exec(tail);
    const body = next ? tail.slice(0, next.index) : tail;
    if (atlasTextEnglishMarkerScore(body) >= 1) {
      answer = atlasMarkdownReplaceNamedSection(answer, "Commentaire local borné", atlasLocalFrenchCommentFallback(mode, snapshot));
    }
  }

  // One evidence vocabulary everywhere. Raw scores remain secondary metadata only.
  const contract = snapshot?.strict_contract || {};
  const evidenceLayer = contract.evidence_v2 || snapshot?.analytical_state?.evidence || atlasEvidenceLayerBuild(contract);
  const evidence = evidenceLayer?.events?.[0] || null;
  const lead = contract.news?.lead_event || null;
  if (evidence && lead?.headline) {
    const proofScore = Number(lead?.evidence?.score ?? lead?.evidence_score);
    const impactScore = Number(lead?.impact?.score ?? lead?.impact_score);
    const scores = [];
    if (Number.isFinite(proofScore)) scores.push(`preuve ${proofScore}/100`);
    if (Number.isFinite(impactScore)) scores.push(`impact ${impactScore}/100`);
    const secondary = scores.length ? ` · scores secondaires ${scores.join(" · ")}` : "";
    const canonicalLine = `- Événement directeur : ${lead.headline} · preuve ${evidence.proof_quality} · impact ${evidence.impact_potential} · confiance ${evidence.confidence}${secondary}.`;
    answer = answer.replace(/^[-*]\s+Événement directeur\s*:\s*.*$/mi, canonicalLine);
  }

  answer = atlasNormalizeAnalyticalSafetyLanguage(answer);
  return { ...result, answer, language_normalized: true, evidence_normalized: !!evidence };
}

function atlasLocalConclusionEvidenceSection(snapshot) {
  const contract = snapshot?.strict_contract || {};
  const evidenceLayer = contract.evidence_v2 || snapshot?.analytical_state?.evidence || atlasEvidenceLayerBuild(contract);
  const evidence = evidenceLayer?.events?.[0] || null;
  const lead = contract.news?.lead_event || null;
  if (!evidence) return "";
  const source = evidence.source_name || lead?.source_name || "source non précisée";
  const scope = [...(Array.isArray(evidence.assets) ? evidence.assets : []), ...(Array.isArray(evidence.sectors) ? evidence.sectors : [])].filter(Boolean);
  const proofScore = Number(lead?.evidence?.score ?? lead?.evidence_score);
  const impactScore = Number(lead?.impact?.score ?? lead?.impact_score);
  const scoreParts = [];
  if (Number.isFinite(proofScore)) scoreParts.push(`preuve ${proofScore}/100`);
  if (Number.isFinite(impactScore)) scoreParts.push(`impact ${impactScore}/100`);
  return [
    "#### 5. News Sentinel — événement et preuve",
    "",
    `- Événement directeur : ${evidence.headline || lead?.headline || "événement non nommé"}.`,
    `- Source : ${source} · preuve ${evidence.proof_quality || "INCONNUE"}.`,
    `- Impact potentiel : ${evidence.impact_potential || "INCONNU"}${scope.length ? ` · actifs/secteurs : ${scope.join(", ")}` : " · portée à qualifier"}.`,
    `- Confiance : ${evidence.confidence || "À_VÉRIFIER"} · ${Number(evidence.independent_sources || 0)} source(s) indépendante(s) sur ${Number(evidence.reported_sources || 0)} reprise(s).`,
    scoreParts.length ? `- Scores source secondaires : ${scoreParts.join(" · ")} · ils ne remplacent pas la taxonomie preuve / impact / confiance.` : "- Aucun score source secondaire disponible.",
    "- Action : observation uniquement ; aucun ordre automatique.",
    "- La proximité temporelle entre une actualité et un mouvement de prix ne démontre pas la causalité."
  ].join("\n");
}

function atlasLocalConclusionTruthPolish(answer, snapshot) {
  let text = String(answer || "").replace(/\r\n?/g, "\n").trim();
  const evidenceSection = atlasLocalConclusionEvidenceSection(snapshot);
  if (evidenceSection) text = atlasMarkdownReplaceNamedSection(text, "News Sentinel — événement et preuve", evidenceSection);
  return text;
}

async function atlasLocalReportRequestReliable(mode, snapshot, token) {
  let lastError = null;
  for (let attempt = 1; attempt <= 2; attempt += 1) {
    if (token !== atlasLocalReportsState.runToken) return null;
    try {
      const result = await atlasLocalBridgeRequest("/summary", {
        profile: "atlas",
        mode,
        snapshot,
        response_language: "fr-FR",
        language_lock: "french_only_except_standard_crypto_acronyms"
      });
      if (token !== atlasLocalReportsState.runToken) return null;
      const polished = atlasLocalReportTruthPolish(mode, result, snapshot);
      if (atlasLocalReportAnswerIsMeaningful(mode, polished)) return polished;
      lastError = new Error("Rapport local vide ou incomplet");
    } catch (error) {
      lastError = error;
      const failureKind = atlasLocalBridgeRequestFailureKind(error);
      if (["timeout", "offline"].includes(failureKind)) {
        // Fast fail: do not hammer the same endpoint a second time while
        // the Bridge recovery watchdog is already taking ownership.
        throw error;
      }
    }
    if (attempt < 2) await atlasLocalReportsWait(650);
  }
  throw lastError || new Error("Rapport local non généré");
}

async function atlasLocalReportsRunAll(options = {}) {
  if (!atlasDeviceComputeAllowed()) {
    atlasDeviceComputeApply({ restart: false });
    return false;
  }
  if (!atlasAccessIsAuthorized()) {
    atlasAccessOpen("#local-ai-hub");
    return false;
  }
  if (
    atlasLocalReportsState.running
    || atlasLocalDialogueState.busy
    || atlasLocalConclusionState.running
  ) return false;
  if (!atlasLocalDialogueState.connected) {
    atlasLocalReportsSetSuiteStatus("Bridge local à vérifier avant l’analyse complète.", "wait");
    return false;
  }

  const snapshot = options.snapshot || atlasBuildCryptoPageSnapshot();
  const readiness = atlasLocalReportsReadiness(snapshot);
  if (!readiness.ready) {
    atlasLocalReportsSetSuiteStatus(atlasLocalReportsReadinessLabel(readiness), "wait");
    return false;
  }

  const fingerprint = options.fingerprint || atlasLocalReportSnapshotFingerprint(snapshot);
  if (options.automatic === true) {
    atlasLocalReportsState.automaticModelRunAttempts = Number(atlasLocalReportsState.automaticModelRunAttempts || 0) + 1;
    if (atlasLocalReportsState.automaticModelRunAttempts > Number(atlasLocalReportsState.automaticModelRunMax || 2)) {
      atlasLocalReportsCloseAutomaticCycle(fingerprint, "atlas-run-attempt-limit");
      atlasAnalysisProgressRender(0, "error", "Deux tentatives automatiques de génération ont déjà été effectuées · moteur arrêté pour éviter toute boucle.");
      atlasLocalReportsSetSuiteStatus("Cycle automatique arrêté après deux tentatives de génération · relance opérateur requise.", "wait");
      return false;
    }
  }
  const token = ++atlasLocalReportsState.runToken;
  atlasLocalReportsState.lastAutoAttemptFingerprint = options.automatic === true ? fingerprint : atlasLocalReportsState.lastAutoAttemptFingerprint;
  atlasLocalReportsState.lastAutoAttemptAt = Date.now();
  atlasLocalReportsSetBusy(true);
  atlasLocalReportsState.transactionFingerprint = fingerprint;
  atlasLocalReportsState.transactionStartedAt = Date.now();
  atlasCurrentStage(snapshot, "ATLAS_RUNNING", options.reason || "atlas_start", {
    completed: 0,
    snapshot_frozen: true,
    transaction_fingerprint: fingerprint
  });
  atlasLocalReportsSetSuiteStatus(atlasLocalReportsProgressLabel(0, 4), "loading");
  atlasAnalysisProgressRender(0, "atlas", "Résumé du marché en préparation · snapshot CURRENT figé.");
  setText(
    document.getElementById("atlasLocalDialogueStatus"),
    "Dialogue local prêt avec gpt-oss:20b-32k · Atlas-10 démarre automatiquement · progression 0 %."
  );
  atlasLocalResponseSelectView("conclusion");
  setText(
    document.getElementById("atlasLocalReportsMeta"),
    `Snapshot ${atlasLocalReportSnapshotLabel(snapshot)} · quatre tâches séquentielles · lecture seule`
  );

  let completed = 0;
  try {
    for (let index = 0; index < ATLAS_LOCAL_REPORT_MODES.length; index += 1) {
      if (token !== atlasLocalReportsState.runToken) return false;
      const mode = ATLAS_LOCAL_REPORT_MODES[index];
      const label = ATLAS_LOCAL_REPORT_LABELS[mode];
      const existingCurrent = atlasLocalReportResult(mode);

      if (
        existingCurrent?.answer
        && existingCurrent.fingerprint === fingerprint
      ) {
        completed += 1;
        atlasLocalReportSetCardState(mode, "Prêt", "ready");
        atlasCurrentStage(snapshot, "ATLAS_RUNNING", `atlas_${mode}_reused`, {
          completed,
          reused: true
        });
        atlasLocalReportsSetSuiteStatus(
          `${atlasLocalReportsProgressLabel(completed, 4)} · ${label} déjà valide pour ce snapshot`,
          "loading"
        );
        atlasAnalysisProgressRender(completed, "atlas", `${label} déjà CURRENT pour ce snapshot · poursuite sans recalcul.`);
        setText(
          document.getElementById("atlasLocalDialogueStatus"),
          `Dialogue local prêt avec gpt-oss:20b-32k · Atlas-10 ${atlasLocalReportsProgressPercent(completed, 4)} % · Aerith-10 attend automatiquement 4/4.`
        );
        if (atlasLocalDialogueState.activeResponseView === "conclusion") {
          atlasLocalResponseRenderStored("conclusion");
        }
        continue;
      }

      atlasLocalReportSetLoading(mode, index + 1, ATLAS_LOCAL_REPORT_MODES.length);
      atlasLocalReportsSetSuiteStatus(`Analyse Atlas-10 · ${completed}/4 prêts · ${label}`, "loading");

      try {
        const result = await atlasLocalReportRequestReliable(mode, snapshot, token);
        if (token !== atlasLocalReportsState.runToken) return false;
        atlasLocalDialogueState.connected = true;
        atlasLocalDialogueState.provider = result?.provider || atlasLocalDialogueState.provider;
        atlasLocalDialogueState.model = result?.model || atlasLocalDialogueState.model;
        const stored = atlasLocalReportStore(mode, result, snapshot, { open: true });
        if (stored) {
          completed += 1;
          atlasCurrentStage(snapshot, "ATLAS_RUNNING", `atlas_${mode}_ready`, { completed });
          atlasLocalReportsSetSuiteStatus(atlasLocalReportsProgressLabel(completed, 4), "loading");
          atlasAnalysisProgressRender(completed, "atlas", `${label} terminé · ${completed}/4 rapports CURRENT.`);
          setText(
            document.getElementById("atlasLocalDialogueStatus"),
            `Dialogue local prêt avec gpt-oss:20b-32k · Atlas-10 ${atlasLocalReportsProgressPercent(completed, 4)} % · ${completed}/4 rapports prêts.`
          );
          if (atlasLocalDialogueState.activeResponseView === "conclusion") {
            atlasLocalResponseRenderStored("conclusion");
          }
        } else throw new Error("Rapport local vide ou non affichable");
      } catch (error) {
        const previous = atlasLocalReportResult(mode);
        const ids = ATLAS_LOCAL_REPORT_IDS[mode];
        if (previous?.answer) {
          const previousCurrent = previous.fingerprint === fingerprint;
          atlasLocalReportSetCardState(
            mode,
            previousCurrent ? "Conservé" : "Historique",
            previousCurrent ? "ready" : "wait"
          );
          setText(
            document.getElementById(ids.meta),
            previousCurrent
              ? `${previous.snapshotLabel} · dernier rapport conservé`
              : `${previous.snapshotLabel} · HISTORIQUE · fingerprint différent`
          );
          atlasLocalSetReport(document.getElementById(ids.content), previous.answer);
        } else {
          atlasLocalReportSetCardState(mode, "À relancer", "wait");
          setText(document.getElementById(ids.meta), "Rapport non généré");
          document.querySelector(`[data-atlas-report-copy="${mode}"]`)?.setAttribute("disabled", "");
          document.querySelector(`[data-atlas-report-export="${mode}"]`)?.setAttribute("disabled", "");
        }
        const bridgeFailure = atlasLocalBridgeRequestFailureKind(error);
        if (["timeout", "offline"].includes(bridgeFailure)) {
          atlasLocalReportsSetSuiteStatus(
            `${completed}/4 rapports prêts · pause locale · Bridge en récupération automatique · reprise sans perdre les rapports valides.`,
            completed ? "partial" : "wait"
          );
          // atlasLocalBridgeRequestFailure() already owns Bridge recovery.
          break;
        }
      }

      atlasLocalReportsSetSuiteStatus(`${completed}/4 rapports prêts.`, completed ? "partial" : "loading");
    }

    if (completed === ATLAS_LOCAL_REPORT_MODES.length) {
      atlasLocalReportsSetSuiteStatus("4/4 rapports prêts.", "ready");
      atlasLocalReportsState.lastCompletedSnapshot = snapshot;
      atlasLocalReportsState.lastCompletedFingerprint = fingerprint;
      atlasCurrentStage(snapshot, "ATLAS_4_4_READY", "atlas_4_4_ready", { completed: 4, snapshot_frozen: true });
      if (snapshot?.strict_contract?.nox_no_fomo_v1) {
        atlasCurrentStage(snapshot, "NOX_READY", "nox_no_fomo_ready", { completed: 4 });
      }
      atlasLocalReportsOpenAll();
      document.getElementById("btnAtlasLocalConclusion")?.removeAttribute("disabled");
      atlasAnalysisProgressRender(4, "nox", "Atlas 4/4 CURRENT · NØX contrôle FOMO, contradictions et causalités avant transmission à Aerith.");
      atlasLocalDialogueSetConnection(
        true,
        "Atlas 4/4 terminé · NØX No-FOMO validé · Aerith-10 démarre automatiquement maintenant."
      );
      atlasLocalResponseSelectView("conclusion");

      const conclusionOk = await atlasLocalConclusionRun({
        automatic: true,
        snapshot,
        fingerprint,
        force: options.automatic !== true
      });

      if (!conclusionOk && options.automatic === true) {
        atlasLocalReportsScheduleAutomatic(options.reason || "snapshot", { delayMs: 7000 });
      }
      return conclusionOk;
    }

    atlasLocalReportsSetSuiteStatus(
      completed
        ? `${completed}/4 rapports prêts · reprise automatique des rapports manquants.`
        : "0/4 rapport prêt · nouvelle tentative automatique programmée.",
      completed ? "partial" : "wait"
    );

    if (options.automatic === true) {
      // A partial run is not a completed attempt. Allow an immediate bounded retry.
      atlasLocalReportsState.lastAutoAttemptFingerprint = "";
      atlasLocalReportsState.lastAutoAttemptAt = 0;
      atlasLocalReportsClearAutoTimer();
      atlasLocalReportsScheduleAutomatic(options.reason || "snapshot", { delayMs: 6000 });
    }

    return completed > 0;
  } finally {
    if (token === atlasLocalReportsState.runToken) {
      atlasLocalReportsSetBusy(false);
      atlasLocalReportsState.transactionFingerprint = "";
      atlasLocalReportsState.transactionStartedAt = 0;
      atlasLocalReportsFlushDeferredRetry();
    }
  }
}


function atlasLocalReportsClearAutoTimer() {
  if (atlasLocalReportsState.autoTimer) {
    window.clearTimeout(atlasLocalReportsState.autoTimer);
    atlasLocalReportsState.autoTimer = 0;
  }
}

function atlasLocalReportsQueueDeferredRetry(reason = "snapshot", options = {}) {
  if (!atlasDeviceComputeAllowed()) return false;
  const delay = Number.isFinite(Number(options.delayMs))
    ? Math.max(0, Number(options.delayMs))
    : 3000;

  atlasLocalReportsState.deferredRetryReason = String(
    reason || atlasLocalReportsState.pendingReason || "snapshot"
  );
  atlasLocalReportsState.deferredRetryDelayMs = delay;
  atlasLocalReportsState.deferredRetryRequestedAt = Date.now();
  return true;
}

function atlasLocalReportsFlushDeferredRetry() {
  if (atlasLocalReportsState.automaticCycleClosed) {
    atlasLocalReportsState.deferredRetryReason = "";
    atlasLocalReportsState.deferredRetryDelayMs = 0;
    atlasLocalReportsState.deferredRetryRequestedAt = 0;
    return false;
  }

  if (
    atlasLocalReportsState.running
    || atlasLocalConclusionState.running
    || atlasLocalReportsState.transactionFingerprint
  ) {
    return false;
  }

  const reason = String(atlasLocalReportsState.deferredRetryReason || "");
  if (!reason) return false;

  const delayMs = Math.max(0, Number(atlasLocalReportsState.deferredRetryDelayMs || 0));
  atlasLocalReportsState.deferredRetryReason = "";
  atlasLocalReportsState.deferredRetryDelayMs = 0;
  atlasLocalReportsState.deferredRetryRequestedAt = 0;

  return atlasLocalReportsScheduleAutomatic(reason, { delayMs });
}

function atlasLocalReportsResetAutomaticState(options = {}) {
  atlasLocalReportsClearAutoTimer();
  atlasLocalReportsState.autoRetryCount = 0;
  atlasLocalReportsState.pendingReason = "";
  atlasLocalReportsState.pendingSince = 0;
  atlasLocalReportsState.lastAutoAttemptFingerprint = "";
  atlasLocalReportsState.lastAutoAttemptAt = 0;
  atlasLocalReportsState.deferredRetryReason = "";
  atlasLocalReportsState.deferredRetryDelayMs = 0;
  atlasLocalReportsState.deferredRetryRequestedAt = 0;
  if (options.keepLastSuccess !== true) {
    atlasLocalReportsState.lastAutoFingerprint = "";
  }
}

function atlasLocalReportsManualCycleReason(reason = "") {
  return new Set([
    "manual-livecheck",
    "manual-market-refresh",
    "manual-auto-reader"
  ]).has(String(reason || ""));
}

function atlasLocalReportsOpenAutomaticCycle(reason = "") {
  atlasLocalReportsState.automaticCycleClosed = false;
  atlasLocalReportsState.automaticCycleClosedAt = 0;
  atlasLocalReportsState.automaticCycleFingerprint = "";
  atlasLocalReportsState.automaticCycleCloseReason = String(reason || "manual");
  atlasLocalReportsState.automaticModelRunAttempts = 0;
  atlasLocalConclusionState.automaticValidationRetryCount = 0;
}

function atlasLocalReportsCloseAutomaticCycle(fingerprint = "", reason = "current-complete") {
  atlasLocalReportsState.automaticCycleClosed = true;
  atlasLocalReportsState.automaticCycleClosedAt = Date.now();
  atlasLocalReportsState.automaticCycleFingerprint = String(fingerprint || "");
  atlasLocalReportsState.automaticCycleCloseReason = String(reason || "current-complete");
  atlasLocalReportsState.deferredRetryReason = "";
  atlasLocalReportsState.deferredRetryDelayMs = 0;
  atlasLocalReportsState.deferredRetryRequestedAt = 0;
  atlasLocalReportsClearAutoTimer();
}

function atlasLocalReportsAutoReasonAllowed(reason) {
  return new Set([
    "snapshot",
    "startup",
    "livecheck",
    "manual-livecheck",
    "manual-market-refresh",
    "manual-auto-reader",
    "binance-ready",
    "bridge-ready",
    "request-failure"
  ]).has(String(reason || ""));
}

function atlasLocalReportsAutoRetry(reason, message = "", options = {}) {
  if (atlasLocalReportsState.automaticCycleClosed) return false;

  atlasLocalReportsState.autoRetryCount = Math.min(
    30,
    Number(atlasLocalReportsState.autoRetryCount || 0) + 1
  );
  if (message) atlasLocalReportsSetSuiteStatus(message, "wait");

  // Persistent readiness wait, but with only one live timer.
  // atlasLocalReportsScheduleAutomatic() always replaces the previous timer,
  // so repeated error paths cannot create a retry storm.
  const retryDelay = Number.isFinite(Number(options.delayMs))
    ? Math.max(500, Number(options.delayMs))
    : Math.min(15000, 3000 + atlasLocalReportsState.autoRetryCount * 1000);

  return atlasLocalReportsScheduleAutomatic(
    reason || atlasLocalReportsState.pendingReason || "snapshot",
    { delayMs: retryDelay }
  );
}

function atlasLocalReportsScheduleAutomatic(reason = "snapshot", options = {}) {
  if (!atlasDeviceComputeAllowed()) {
    atlasLocalReportsClearAutoTimer();
    return false;
  }
  const nextReason = String(reason || "snapshot");
  if (!atlasLocalReportsAutoReasonAllowed(nextReason)) return false;

  if (atlasLocalReportsManualCycleReason(nextReason)) {
    atlasLocalReportsOpenAutomaticCycle(nextReason);
  } else if (atlasLocalReportsState.automaticCycleClosed) {
    atlasLocalReportsClearAutoTimer();
    atlasLocalReportsState.deferredRetryReason = "";
    atlasLocalReportsState.deferredRetryDelayMs = 0;
    atlasLocalReportsState.deferredRetryRequestedAt = 0;
    atlasLocalReportsSetSuiteStatus(
      "Cycle terminé · Atlas/Aerith au repos · les prix live continuent · attente du prochain snapshot canonique qualifié.",
      "ready"
    );
    return false;
  }

  if (
    atlasLocalReportsState.running
    || atlasLocalConclusionState.running
    || atlasLocalReportsState.transactionFingerprint
  ) {
    return atlasLocalReportsQueueDeferredRetry(nextReason, options);
  }

  const now = Date.now();
  if (!atlasLocalReportsState.pendingSince) {
    atlasLocalReportsState.pendingSince = now;
    atlasLocalReportsState.autoRetryCount = 0;
  }
  atlasLocalReportsState.pendingReason = nextReason;
  atlasLocalReportsClearAutoTimer();

  const explicitDelay = Number(options.delayMs);
  const eventDelay = nextReason === "binance-ready" ? 600
    : nextReason === "bridge-ready" ? 500
    : nextReason === "request-failure" ? 5000
    : atlasLocalReportsState.autoRetryCount ? 5000 : 3000;
  const delay = Number.isFinite(explicitDelay) ? Math.max(0, explicitDelay) : eventDelay;

  atlasLocalReportsState.autoTimer = window.setTimeout(async () => {
    atlasLocalReportsState.autoTimer = 0;

    // The analysis is authorized by the operator session, not by which UI view
    // is currently open. This preserves automatic production after page load.
    if (!atlasAccessIsAuthorized()) return;
    if (!atlasLocalDialogueState.connected) {
      atlasLocalReportsAutoRetry(nextReason, "Atlas armé · Bridge local en attente.");
      return;
    }
    if (atlasLocalDialogueState.busy || atlasLocalReportsState.running || atlasLocalConclusionState.running) {
      atlasLocalReportsAutoRetry(nextReason, "Atlas/Aerith termine l’opération locale en cours · supervision automatique active.", { delayMs: 2500 });
      return;
    }

    const snapshot = atlasBuildCryptoPageSnapshot();
    const readiness = atlasLocalReportsReadiness(snapshot);
    if (!readiness.ready) {
      atlasCurrentSyncFromLiveGate("scheduler-prerequisite-wait");
      atlasLocalReportsAutoRetry(nextReason, atlasLocalReportsReadinessLabel(readiness));
      return;
    }

    atlasCurrentStage(snapshot, "PENDING_ANALYSIS", "all-prerequisites-ready", {
      readiness_label: atlasLocalReportsReadinessLabel(readiness),
      bridge_ready: readiness.bridgeReady,
      market_ready: readiness.marketReady,
      graph_ready: readiness.graphReady,
      binance_ready: readiness.binanceReady
    });

    const fingerprint = atlasLocalReportSnapshotFingerprint(snapshot);
    if (!fingerprint) {
      atlasLocalReportsAutoRetry(nextReason, "Atlas armé · empreinte analytique en attente.", { delayMs: 3000 });
      return;
    }

    const atlasReportsCurrent =
      fingerprint === atlasLocalReportsState.lastCompletedFingerprint
      && atlasLocalReportsReadyForFingerprint(fingerprint);

    const aerithCurrent =
      atlasLocalDialogueState.conclusionResponse?.fingerprint === fingerprint
      && !!atlasLocalDialogueState.conclusionResponse?.answer;

    const completedCurrentFingerprint = atlasReportsCurrent && aerithCurrent;

    if (completedCurrentFingerprint) {
      atlasLocalReportsState.lastAutoFingerprint = fingerprint;
      atlasLocalReportsState.autoRetryCount = 0;
      atlasLocalReportsState.pendingSince = 0;
      atlasLocalReportsState.pendingReason = "";
      atlasLocalReportsSetSuiteStatus("4/4 rapports et conclusion déjà valides pour ce snapshot.", "ready");
      return;
    }

    if (atlasReportsCurrent && !aerithCurrent) {
      atlasLocalReportsSetSuiteStatus("Atlas 4/4 déjà valide · relance automatique Aerith-10.", "loading");
      const conclusionOk = await atlasLocalConclusionRun({
        automatic: true,
        snapshot: atlasLocalReportsState.lastCompletedSnapshot || snapshot,
        fingerprint,
        force: true
      });
      if (!conclusionOk) {
        atlasLocalReportsAutoRetry(nextReason, "Atlas 4/4 conservé · relance Aerith mise en file et déclenchée dès libération de la transaction.", { delayMs: 7000 });
      } else {
        atlasLocalReportsState.autoRetryCount = 0;
        atlasLocalReportsState.pendingSince = 0;
        atlasLocalReportsState.pendingReason = "";
      }
      return;
    }

    if (
      fingerprint === atlasLocalReportsState.lastAutoAttemptFingerprint
      && (Date.now() - atlasLocalReportsState.lastAutoAttemptAt) < 90000
    ) {
      atlasLocalReportsAutoRetry(nextReason, "Atlas armé · transaction récente ; nouvelle vérification programmée sans dupliquer les rapports déjà valides.", { delayMs: 5000 });
      return;
    }

    atlasLocalReportsState.autoRetryCount = 0;
    atlasLocalReportsState.pendingSince = 0;
    atlasLocalReportsState.pendingReason = "";
    atlasLocalReportsSetSuiteStatus("Binance 5/5 directes · lancement automatique Atlas-10.", "loading");
    await atlasLocalReportsRunAll({
      automatic: true,
      snapshot,
      fingerprint,
      openFirst: false,
      reason: nextReason
    });
  }, delay);
  return true;
}

async function atlasLocalReportsCopy(mode) {
  const report = atlasLocalReportResult(mode);
  if (!report?.answer) return;
  try {
    await navigator.clipboard.writeText(report.answer);
  } catch {
    const area = document.createElement("textarea");
    area.value = report.answer;
    area.style.position = "fixed";
    area.style.opacity = "0";
    document.body.appendChild(area);
    area.select();
    document.execCommand("copy");
    area.remove();
  }
  atlasLocalReportsSetSuiteStatus(`${report.label} copié.`, "ready");
}

function atlasLocalReportsExport(mode) {
  const report = atlasLocalReportResult(mode);
  if (!report?.answer) return;
  const lines = [
    `# Atlas-10 Crypto — ${report.label}`,
    "",
    `- Version Agent-Crypto : ${ATLAS_RELEASE}`,
    `- Snapshot : ${report.snapshotLabel}`,
    `- Date du rapport : ${report.time}`,
    `- Moteur : ${report.provider} · ${report.model}`,
    "- Mode : lecture seule",
    "",
    report.answer,
    "",
    "## Limite",
    "",
    "Analyse descriptive locale. La chaîne Atlas → NØX → Aerith est automatique ; validation humaine uniquement avant toute décision ou action financière réelle. Aucun ordre financier, wallet ou accès GitHub."
  ];
  const filename = `agent_crypto_atlas_${mode}_${new Date().toISOString().replace(/[:.]/g, "-")}.md`;
  downloadTextFile(filename, "text/markdown;charset=utf-8", lines.join("\n"));
  atlasLocalReportsSetSuiteStatus(`${report.label} exporté.`, "ready");
}

function atlasLocalReportsOpenAll() {
  document.querySelectorAll("[data-atlas-report-card]").forEach(card => card.setAttribute("open", ""));
}

function atlasLocalReportsReadyForFingerprint(fingerprint = "") {
  const fp = String(fingerprint || "").trim();
  if (!fp) return false;
  return ATLAS_LOCAL_REPORT_MODES.every(mode => {
    const report = atlasLocalReportResult(mode);
    return !!report?.answer && String(report.fingerprint || "") === fp;
  });
}


function atlasLocalReportsProgressForFingerprint(fingerprint = "") {
  const fp = String(
    fingerprint
    || atlasLocalReportsState.transactionFingerprint
    || atlasLocalReportsState.lastCompletedFingerprint
    || ""
  ).trim();
  const readyModes = fp
    ? ATLAS_LOCAL_REPORT_MODES.filter(mode => {
        const report = atlasLocalReportResult(mode);
        return !!report?.answer && report.fingerprint === fp;
      })
    : [];
  return {
    fingerprint: fp,
    completed: readyModes.length,
    total: ATLAS_LOCAL_REPORT_MODES.length,
    ready_modes: readyModes
  };
}

function atlasLocalReportsHistoricalCount(currentFingerprint = "") {
  const currentFp = String(currentFingerprint || "").trim();
  return ATLAS_LOCAL_REPORT_MODES.filter(mode => {
    const report = atlasLocalReportResult(mode);
    if (!report?.answer) return false;
    return !currentFp || String(report.fingerprint || "") !== currentFp;
  }).length;
}

function atlasLocalReportsProgressPercent(completed = 0, total = 4) {
  const safeTotal = Math.max(1, Number(total) || 4);
  const safeCompleted = Math.max(0, Math.min(safeTotal, Number(completed) || 0));
  return Math.round((safeCompleted / safeTotal) * 100);
}

function atlasLocalReportsProgressLabel(completed = 0, total = 4) {
  const pct = atlasLocalReportsProgressPercent(completed, total);
  return `Analyse Atlas-10 · ${pct} % · ${completed}/${total} rapports prêts`;
}


function atlasLocalConclusionPhase() {
  if (atlasLocalConclusionState.running) return "AERITH_RUNNING";
  if (atlasLocalReportsState.running) return "ATLAS_RUNNING";

  const fingerprint = atlasLocalReportsState.lastCompletedFingerprint || "";
  const progress = atlasLocalReportsProgressForFingerprint(fingerprint);
  if (fingerprint && progress.completed === ATLAS_LOCAL_REPORT_MODES.length) {
    const response = atlasLocalDialogueState.conclusionResponse;
    if (response?.answer && response.fingerprint === fingerprint) return "CURRENT";
    return "ATLAS_4_4_READY";
  }
  return progress.completed > 0 ? "ATLAS_PARTIAL" : "WAITING_ATLAS";
}

function atlasLocalConclusionBridgeContract(result, fingerprint) {
  const answer = String(result?.answer || "").replace(/\r\n?/g, "\n").trim();
  const expectedModel = String(ATLAS_STABLE_STACK?.model || "gpt-oss:20b-32k");
  const actualModel = String(result?.model || "").trim();
  const resultFingerprint = String(result?.report_fingerprint || "").trim();
  const checks = {
    bridge_ok: result?.ok === true,
    profile_aerith: String(result?.profile || "").toLowerCase() === "aerith",
    source_reports_4: Number(result?.source_reports || 0) === 4,
    reports_re_read: result?.reports_re_read === true,
    fingerprint_match: !!fingerprint && resultFingerprint === fingerprint,
    read_only: result?.read_only === true,
    model_match: actualModel === expectedModel,
    answer_present: answer.length >= 120
  };

  return {
    schema: "aerith_conclusion_bridge_contract_v1",
    pass: Object.values(checks).every(Boolean),
    checks,
    expected_model: expectedModel,
    actual_model: actualModel || null,
    fingerprint_expected: fingerprint || null,
    fingerprint_received: resultFingerprint || null,
    answer_length: answer.length
  };
}

function atlasLocalConclusionContractFailureLabel(contract) {
  if (!contract) return "contrat de conclusion inconnu";
  const failed = Object.entries(contract.checks || {})
    .filter(([, ok]) => !ok)
    .map(([name]) => name);
  if (!failed.length) return "contrat valide";
  if (failed.includes("model_match")) {
    return `modèle inattendu : ${contract.actual_model || "inconnu"} au lieu de ${contract.expected_model}`;
  }
  if (failed.includes("fingerprint_match")) return "fingerprint de conclusion différent du snapshot Atlas";
  if (failed.includes("source_reports_4")) return "la réponse ne confirme pas les quatre rapports Atlas";
  if (failed.includes("reports_re_read")) return "le Bridge ne confirme pas la relecture réelle des quatre rapports Atlas CURRENT";
  if (failed.includes("answer_present")) return "réponse Aerith réellement vide ou trop courte";
  return `contrat Aerith incomplet : ${failed.join(", ")}`;
}

function atlasLocalResponseStored(view) {
  if (view === "question") return atlasLocalDialogueState.questionResponse;
  if (atlasLocalDialogueState.conclusionResponse?.answer) return atlasLocalDialogueState.conclusionResponse;
  const shared = atlasSharedSynthesisMainConclusionResponse?.(atlasSharedSynthesisState?.package, atlasSharedSynthesisState?.source || "stored");
  return shared?.answer ? shared : null;
}

function atlasLocalResponsePlaceholder(view) {
  if (view === "question") {
    return {
      eyebrow: "RÉPONSE À LA QUESTION LIBRE",
      title: "Aucune réponse libre générée",
      body: "Interroge Atlas-10 ou Aerith-10 depuis la zone de gauche.",
      meta: "Lecture seule · analyse automatique · aucune exécution financière réelle"
    };
  }
  const fingerprint = atlasLocalReportsState.transactionFingerprint
    || atlasLocalReportsState.lastCompletedFingerprint
    || "";
  const progress = atlasLocalReportsProgressForFingerprint(fingerprint);
  const historicalCount = atlasLocalReportsHistoricalCount(fingerprint);
  const phase = atlasLocalConclusionPhase();
  const reportsReady =
    !!atlasLocalReportsState.lastCompletedFingerprint
    && atlasLocalReportsReadyForFingerprint(atlasLocalReportsState.lastCompletedFingerprint);

  if (phase === "ATLAS_RUNNING") {
    return {
      eyebrow: "CONCLUSION AERITH-10 CRYPTO",
      title: `Atlas en cours · ${atlasLocalReportsProgressPercent(progress.completed, 4)} % · ${progress.completed}/4 rapports prêts`,
      body: "Aerith-10 ne démarre pas encore : elle attend automatiquement les quatre rapports Atlas-10 du même snapshot.",
      meta: "Lecture seule · pipeline automatique Atlas → NØX → Aerith · aucune validation manuelle requise"
    };
  }

  if (phase === "ATLAS_PARTIAL") {
    return {
      eyebrow: "CONCLUSION AERITH-10 CRYPTO",
      title: `Atlas CURRENT partiel · ${progress.completed}/4 rapports prêts`,
      body: "La synthèse Aerith reste en attente normale tant que les quatre rapports Atlas-10 du même snapshot CURRENT ne sont pas prêts.",
      meta: historicalCount ? `Lecture seule · CURRENT ${progress.completed}/4 · ${historicalCount}/4 rapport(s) historique(s) exclus du compteur` : "Lecture seule · reprise Atlas automatique · aucune validation manuelle requise"
    };
  }

  if (!fingerprint && historicalCount) {
    return {
      eyebrow: "CONCLUSION AERITH-10 CRYPTO",
      title: `CURRENT 0/4 · historique ${historicalCount}/4 disponible`,
      body: "Les rapports restaurés restent consultables, mais aucun rapport historique ne compte pour le snapshot CURRENT. Atlas produira quatre rapports neufs avant Aerith.",
      meta: "Lecture seule · séparation stricte HISTORIQUE / CURRENT · aucune validation manuelle requise"
    };
  }

  return {
    eyebrow: "CONCLUSION AERITH-10 CRYPTO",
    title: atlasLocalConclusionState.running
      ? "Conclusion Aerith-10 en cours…"
      : reportsReady
        ? "Atlas 4/4 prêt · Aerith-10 doit produire la synthèse automatiquement"
        : "En attente des quatre rapports Atlas-10",
    body: atlasLocalConclusionState.running
      ? "Aerith-10 Crypto relit les quatre rapports Atlas-10, News Sentinel et le filtre NØX No-FOMO."
      : reportsReady
        ? "Les quatre rapports Atlas-10 sont valides. La génération Aerith est automatique ; aucun clic de validation n’est requis."
        : "La conclusion Aerith-10 Crypto apparaîtra automatiquement ici lorsque les quatre rapports Atlas-10 seront prêts.",
    meta: reportsReady
      ? "Lecture seule · Atlas 4/4 · génération Aerith automatique · aucune exécution financière réelle"
      : "Lecture seule · conclusion automatique après Atlas 4/4 · aucune exécution financière réelle"
  };
}

function atlasLocalResponseRenderStored(view) {
  const response = atlasLocalResponseStored(view);
  const placeholder = atlasLocalResponsePlaceholder(view);
  const panel = document.querySelector(".atlas-local-response-panel");
  if (panel) panel.dataset.atlasResponseView = view;
  setText(document.getElementById("atlasLocalResponseEyebrow"), response?.eyebrow || placeholder.eyebrow);
  const latestSnapshot = atlasLocalDialogueState.lastSnapshot || atlasLocalReportsState.lastCompletedSnapshot;
  const staleConclusion = view === "conclusion" && response?.answer && atlasCurrentConclusionIsStale(response, latestSnapshot);
  setText(
    document.getElementById("atlasLocalResponseTitle"),
    staleConclusion
      ? `Historique — ${String(response?.label || placeholder.title).replace(/^Historique\s*[—-]\s*/i, "")}`
      : String(response?.label || placeholder.title).replace(/^Historique\s*[—-]\s*/i, "")
  );
  atlasLocalSetReport(document.getElementById("atlasLocalResponse"), response?.answer || placeholder.body);
  setText(
    document.getElementById("atlasLocalResponseMeta"),
    staleConclusion
      ? `${response?.meta || placeholder.meta} · HISTORIQUE : ne correspond pas au snapshot courant`
      : (response?.meta || placeholder.meta)
  );
  atlasLocalDialogueState.lastResponse = response || null;
  const hasAnswer = !!String(response?.answer || "").trim();
  document.getElementById("btnAtlasLocalCopy")?.toggleAttribute("disabled", !hasAnswer);
  document.getElementById("btnAtlasLocalExport")?.toggleAttribute("disabled", !hasAnswer);
  document.querySelectorAll("[data-atlas-response-tab]").forEach(button => {
    const active = button.dataset.atlasResponseTab === view;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", active ? "true" : "false");
  });

  if (view === "conclusion") {
    atlasCurrentDecorateConclusion(latestSnapshot, response || null);
  }
}

function atlasLocalResponseSelectView(view = "conclusion") {
  const next = view === "question" ? "question" : "conclusion";
  atlasLocalDialogueState.activeResponseView = next;
  atlasLocalResponseRenderStored(next);
}

function atlasLocalConclusionSetBusy(busy) {
  atlasLocalConclusionState.running = !!busy;
  const button = document.getElementById("btnAtlasLocalConclusion");
  if (button) {
    const currentFingerprint = String(
      atlasLocalReportsState.lastCompletedFingerprint
      || atlasLocalReportsState.transactionFingerprint
      || ""
    ).trim();
    button.disabled = !!busy || !atlasDeviceComputeAllowed() || !atlasLocalReportsReadyForFingerprint(currentFingerprint);
    button.setAttribute("aria-busy", busy ? "true" : "false");
    button.textContent = busy ? "Conclusion…" : "Régénérer";
  }
  if (atlasLocalDialogueState.activeResponseView === "conclusion") atlasLocalResponseRenderStored("conclusion");
}

async function atlasLocalConclusionRun(options = {}) {
  if (!atlasDeviceComputeAllowed()) {
    atlasDeviceComputeApply({ restart: false });
    return false;
  }
  if (!atlasAccessIsAuthorized()) {
    atlasAccessOpen("#local-ai-hub");
    return false;
  }
  if (atlasLocalConclusionState.running || !atlasLocalDialogueState.connected) return false;
  const snapshot = options.snapshot || atlasLocalReportsState.lastCompletedSnapshot || atlasBuildCryptoPageSnapshot();
  const fingerprint = options.fingerprint || atlasLocalReportsState.lastCompletedFingerprint || atlasLocalReportSnapshotFingerprint(snapshot);
  if (!fingerprint || !atlasLocalReportsReadyForFingerprint(fingerprint)) {
    atlasLocalResponseSelectView("conclusion");
    const progress = atlasLocalReportsProgressForFingerprint(
      atlasLocalReportsState.transactionFingerprint || fingerprint
    );
    setText(
      document.getElementById("atlasLocalResponseTitle"),
      atlasLocalReportsState.running
        ? `Atlas en cours · ${atlasLocalReportsProgressPercent(progress.completed, 4)} % · ${progress.completed}/4 rapports prêts`
        : `Quatre rapports Atlas-10 requis · ${progress.completed}/4 prêts`
    );
    return false;
  }
  if (!options.force && fingerprint === atlasLocalConclusionState.lastFingerprint) {
    atlasLocalResponseSelectView("conclusion");
    return true;
  }
  if (
    !options.force
    && fingerprint === atlasLocalConclusionState.lastAttemptFingerprint
    && (Date.now() - atlasLocalConclusionState.lastAttemptAt) < 90000
  ) return false;

  const conclusionToken = ++atlasLocalConclusionState.runToken;
  atlasLocalConclusionState.activeFingerprint = fingerprint;
  atlasLocalConclusionState.lastAttemptFingerprint = fingerprint;
  atlasLocalConclusionState.lastAttemptAt = Date.now();
  atlasAnalysisProgressRender(4, "aerith", "Aerith relit le snapshot CURRENT, les quatre rapports Atlas, NØX, News Sentinel, Watchlist, Math Core et contradictions.");
  atlasCurrentStage(snapshot, "AERITH_RUNNING", "aerith_conclusion_start", {
    completed: 4,
    conclusion_token: conclusionToken,
    transaction_fingerprint: fingerprint
  });
  atlasLocalResponseSelectView("conclusion");
  const previousConclusion = atlasLocalDialogueState.conclusionResponse && atlasLocalDialogueState.conclusionResponse.answer
    ? atlasSharedSynthesisClone(atlasLocalDialogueState.conclusionResponse)
    : null;
  atlasLocalConclusionSetBusy(true);
  try {
    const result = await atlasLocalBridgeRequest("/conclusion", {
      profile: "aerith",
      snapshot,
      report_fingerprint: fingerprint,
      report_modes: ATLAS_LOCAL_REPORT_MODES.slice(),
      reports: Object.fromEntries(ATLAS_LOCAL_REPORT_MODES.map(mode => {
        const report = atlasLocalReportResult(mode);
        return [mode, report ? {
          mode,
          label: report.label,
          answer: report.answer,
          fingerprint: report.fingerprint,
          model: report.model,
          time: report.time
        } : null];
      })),
      nox_audit: snapshot?.strict_contract?.nox_no_fomo_v1 || null,
      pedagogy_contract: snapshot?.pedagogy || null,
      requested_reading: "whole_page_simple_detailed_expert_full_glossary",
      required_sections: [
        "whole_page_reading",
        "market_and_sources",
        "top5",
        "graph",
        "math_core",
        "news_and_watchlist",
        "four_atlas_reports",
        "contradictions",
        "nox_no_fomo",
        "plain_french_explanation",
        "full_crypto_bank_trading_glossary",
        "limits_and_stop_point"
      ]
    });

    const conclusionSuperseded =
      conclusionToken !== atlasLocalConclusionState.runToken
      || atlasLocalConclusionState.activeFingerprint !== fingerprint
      || (
        atlasLocalReportsState.transactionFingerprint
        && atlasLocalReportsState.transactionFingerprint !== fingerprint
      )
      || atlasLocalReportsState.lastCompletedFingerprint !== fingerprint
      || !atlasLocalReportsReadyForFingerprint(fingerprint);

    if (conclusionSuperseded) {
      const error = new Error("Conclusion supersédée par une transaction plus récente");
      error.name = "AtlasSupersededError";
      throw error;
    }

    const bridgeContract = atlasLocalConclusionBridgeContract(result, fingerprint);
    const lexicalDiagnostic = atlasLocalConclusionMeaningful(result);

    if (!bridgeContract.pass) {
      const error = new Error(
        `Conclusion Aerith refusée : ${atlasLocalConclusionContractFailureLabel(bridgeContract)}`
      );
      error.name = "AtlasAerithContractError";
      error.bridgeContract = bridgeContract;
      throw error;
    }

    // Lexical validation is now informative, not a blocker:
    // Bridge V1.9.5 returns a deterministic conclusion contract and confirms actual rereading of the 4 Atlas CURRENT reports.
    const bridgeAnswer = atlasLocalConclusionTruthPolish(atlasNormalizeAnalyticalSafetyLanguage(result.answer || "").trim(), snapshot);
    const pedagogyAppendix = atlasPedagogyV2FullGlossaryMarkdown(snapshot);
    const answer = pedagogyAppendix
      ? `${bridgeAnswer}\n${pedagogyAppendix}`.trim()
      : bridgeAnswer;
    const response = {
      answer,
      profile: "aerith",
      provider: result?.provider || atlasLocalDialogueState.provider || "local",
      model: result?.model || atlasLocalDialogueState.model || "modèle local",
      time: result?.time || new Date().toISOString(),
      label: "Conclusion Aerith-10 Crypto",
      eyebrow: "CONCLUSION AERITH-10 CRYPTO",
      quality: result?.quality || "strict_contract_v2",
      modelCommentUsed: result?.model_comment_used === true,
      fingerprint,
      bridgeContract,
      lexicalDiagnostic,
      meta: `Aerith-10 · ${result?.provider || atlasLocalDialogueState.provider || "local"} · ${result?.model || atlasLocalDialogueState.model || "modèle local"} · snapshot ${atlasLocalReportSnapshotLabel(snapshot)} · 4 rapports Atlas-10 · contrat Bridge validé`
    };
    const transactionStillCurrent =
      conclusionToken === atlasLocalConclusionState.runToken
      && atlasLocalConclusionState.activeFingerprint === fingerprint
      && atlasLocalReportsState.lastCompletedFingerprint === fingerprint
      && atlasLocalReportsReadyForFingerprint(fingerprint);

    if (!transactionStillCurrent) {
      const error = new Error("Promotion CURRENT annulée : fingerprint transactionnel remplacé");
      error.name = "AtlasSupersededError";
      throw error;
    }

    atlasLocalDialogueState.conclusionResponse = response;
    atlasCurrentPromoteIfComplete(snapshot, atlasLocalReportsState.reports, response);
    if (options.automatic === true) atlasLocalReportsState.lastAutoFingerprint = fingerprint;
    atlasLocalReportsResetAutomaticState({ keepLastSuccess: true });
    atlasLocalReportsState.lastAutoFingerprint = fingerprint;
    atlasLocalConclusionState.automaticValidationRetryCount = 0;
    atlasLocalReportsCloseAutomaticCycle(fingerprint, "current-complete");
    atlasHistoryV2RememberCurrent(snapshot);
    atlasLocalConclusionState.lastFingerprint = fingerprint;
    atlasLocalResponseSelectView("conclusion");
    atlasSharedSynthesisBuildAndStore(snapshot, fingerprint);
    atlasAnalysisProgressRender(4, "done", "Synthèse CURRENT enregistrée · moteur GPT-OSS au repos · prix live toujours actifs · prochain cycle uniquement sur nouveau snapshot canonique qualifié.");
    atlasLocalDialogueSetConnection(
      true,
      `Chaîne terminée : Atlas 4/4 → NØX → Aerith · ${response.model} · synthèse CURRENT validée · MOTEUR LOCAL AU REPOS. Les prix live continuent ; un nouveau CURRENT partira seulement sur un nouveau snapshot canonique qualifié.`
    );
    return true;
  } catch (error) {
    if (error?.name === "AtlasSupersededError") {
      atlasCurrentStage(snapshot, "PENDING_ANALYSIS", "transaction_superseded", {
        completed: 4,
        superseded_fingerprint: fingerprint
      });
      atlasLocalDialogueSetConnection(
        true,
        "Ancienne transaction terminée sans promotion CURRENT · une analyse plus récente conserve la priorité."
      );
      atlasLocalReportsClearAutoTimer();
      atlasLocalReportsQueueDeferredRetry("snapshot", { delayMs: 1200 });
      return false;
    }

    const bridgeFailure = atlasLocalBridgeRequestFailureKind(error);
    const validationFailure =
      error?.name === "AtlasAerithContractError"
      || String(error?.message || "").includes("Conclusion Aerith refusée");

    if (["timeout", "offline"].includes(bridgeFailure)) {
      // Bridge recovery was already armed by atlasLocalBridgeRequestFailure().
      // Keep only the analytical retry timer here.
      atlasLocalReportsScheduleAutomatic("request-failure", { delayMs: 5000 });
    } else if (validationFailure && options.automatic === true) {
      atlasLocalConclusionState.automaticValidationRetryCount =
        Number(atlasLocalConclusionState.automaticValidationRetryCount || 0) + 1;

      if (atlasLocalConclusionState.automaticValidationRetryCount <= 1) {
        // Keep Atlas 4/4 and retry Aerith once only.
        atlasLocalConclusionState.lastAttemptFingerprint = "";
        atlasLocalConclusionState.lastAttemptAt = 0;
        atlasLocalReportsQueueDeferredRetry("snapshot", { delayMs: 6500 });
      } else {
        // Persistent contract/model mismatch must never heat the Ryzen forever.
        atlasLocalReportsCloseAutomaticCycle(fingerprint, "aerith-validation-stop");
        atlasAnalysisProgressRender(4, "error", "Aerith n’a pas validé son contrat après la reprise bornée · moteur arrêté sans boucle.");
        atlasLocalReportsSetSuiteStatus(
          "Aerith non validée après la reprise automatique · moteur arrêté · corriger le Bridge/modèle puis relancer manuellement.",
          "wait"
        );
      }
    }

    if (previousConclusion?.answer) {
      atlasLocalDialogueState.conclusionResponse = previousConclusion;
      atlasLocalConclusionState.lastFingerprint = previousConclusion.fingerprint || atlasLocalConclusionState.lastFingerprint;
      atlasLocalResponseSelectView("conclusion");
      setText(document.getElementById("atlasLocalResponseTitle"), "Conclusion conservée");
      atlasLocalSetReport(document.getElementById("atlasLocalResponse"), previousConclusion.answer);
      setText(
        document.getElementById("atlasLocalResponseMeta"),
        `${previousConclusion.meta || "Dernière conclusion validée"} · nouvelle tentative échouée, état précédent conservé`
      );
      atlasCurrentStage(snapshot, "ERROR", `Aerith : ${error?.message || "Bridge indisponible"}`, { completed: 4 });
      atlasLocalDialogueSetConnection(true, `Nouvelle conclusion non validée : ${error?.message || "Bridge indisponible"}. La conclusion précédente reste disponible uniquement comme historique.`);
    } else {
      atlasLocalDialogueState.conclusionResponse = null;
      atlasLocalResponseSelectView("conclusion");
      setText(
        document.getElementById("atlasLocalResponseTitle"),
        validationFailure && options.automatic === true
          ? "Atlas 4/4 conservé · reprise Aerith automatique"
          : "Conclusion à relancer"
      );
      atlasLocalSetReport(
        document.getElementById("atlasLocalResponse"),
        validationFailure && options.automatic === true
          ? "La première réponse Aerith n’a pas satisfait le contrat de conclusion. Atlas 4/4 reste intact ; une nouvelle tentative Aerith seule est programmée."
          : "La conclusion locale n’a pas été générée. Les quatre rapports Atlas-10 restent disponibles et inchangés."
      );
      setText(
        document.getElementById("atlasLocalResponseMeta"),
        validationFailure && options.automatic === true
          ? "Lecture seule · Atlas 4/4 conservé · reprise Aerith seule automatique"
          : "Lecture seule · rapports Atlas-10 conservés · relance manuelle disponible"
      );
      atlasCurrentStage(snapshot, "ERROR", `Aerith : ${error?.message || "Bridge indisponible"}`, { completed: 4 });
      atlasLocalDialogueSetConnection(
        true,
        validationFailure
          ? `Aerith-10 : réponse reçue mais refusée par le contrat · ${error?.message || "cause inconnue"}`
          : `Conclusion Aerith non générée : ${error?.message || "Bridge indisponible"}`
      );
    }
    atlasAnalyticalTruthRender();
    return false;
  } finally {
    if (conclusionToken === atlasLocalConclusionState.runToken) {
      atlasLocalConclusionState.activeFingerprint = "";
      atlasLocalConclusionSetBusy(false);
      atlasLocalReportsFlushDeferredRetry();
    }
  }
}

function atlasLocalDialogueRender(result, label, options = {}) {
  const answer = atlasNormalizeAnalyticalSafetyLanguage(result?.answer || "").trim();
  atlasLocalDialogueState.connected = true;
  atlasLocalDialogueState.provider = result?.provider || atlasLocalDialogueState.provider;
  atlasLocalDialogueState.model = result?.model || atlasLocalDialogueState.model;
  const response = {
    answer,
    profile: result?.profile || atlasLocalDialogueState.profile,
    provider: atlasLocalDialogueState.provider,
    model: atlasLocalDialogueState.model,
    time: result?.time || new Date().toISOString(),
    label,
    eyebrow: "RÉPONSE À LA QUESTION LIBRE",
    quality: result?.quality || "strict_contract_v2",
    modelCommentUsed: result?.model_comment_used === true
  };
  atlasLocalDialogueState.questionResponse = response;
  atlasLocalDialogueState.lastResponse = response;
  atlasLocalDialogueState.activeResponseView = "question";

  setText(document.getElementById("atlasLocalResponseEyebrow"), response.eyebrow);
  setText(document.getElementById("atlasLocalResponseTitle"), label);
  atlasLocalSetReport(
    document.getElementById("atlasLocalResponse"),
    answer || "Réponse locale vide."
  );

  const quality = result?.quality === "strict_contract_v2"
    ? "contrat factuel V2"
    : (result?.quality || "lecture locale");

  const comment = result?.model_comment_used === true
    ? "commentaire local accepté"
    : "repli déterministe";

  response.meta = `${result?.profile === "aerith" ? "Aerith-10" : "Atlas-10"} · `
    + `${atlasLocalDialogueState.provider || "local"} · `
    + `${atlasLocalDialogueState.model || "modèle"} · ${quality} · ${comment}`;
  setText(document.getElementById("atlasLocalResponseMeta"), response.meta);

  document.getElementById("btnAtlasLocalCopy")?.removeAttribute("disabled");
  document.getElementById("btnAtlasLocalExport")?.removeAttribute("disabled");
  atlasLocalResponseSelectView("question");

  const warnings = Array.isArray(result?.validation_warnings)
    ? result.validation_warnings.filter(Boolean)
    : [];

  atlasLocalDialogueSetConnection(
    true,
    atlasLocalCommentFilterStatus(warnings)
  );
}

async function atlasLocalDialogueRunSummary(mode = "market") {
  if (!atlasDeviceComputeAllowed()) {
    atlasDeviceComputeApply({ restart: false });
    return false;
  }
  if (!atlasAccessIsAuthorized()) {
    atlasAccessOpen("#local-ai-hub");
    return;
  }
  const labels = {
    market: "Synthèse du marché",
    top5: "Analyse du Top 5",
    math: "Explication du Math Core",
    contradictions: "Contrôle des contradictions"
  };
  const label = labels[mode] || labels.market;
  atlasLocalDialogueSetBusy(true, `${label} avec ${atlasLocalDialogueState.profile === "aerith" ? "Aerith-10" : "Atlas-10"}…`);
  try {
    const snapshot = atlasBuildCryptoPageSnapshot();
    const result = await atlasLocalBridgeRequest("/summary", {
      profile: atlasLocalDialogueState.profile,
      mode,
      snapshot,
      response_language: "fr-FR",
      language_lock: "french_only_except_standard_crypto_acronyms"
    });
    atlasLocalDialogueRender(result, label);
    if (atlasLocalDialogueState.profile === "atlas") {
      const stored = atlasLocalReportStore(mode, result, snapshot, { open: true });
      if (!stored) {
        atlasLocalReportSetCardState(mode, "À relancer", "wait");
        atlasLocalReportsSetSuiteStatus(`${ATLAS_LOCAL_REPORT_LABELS[mode]} non généré.`, "wait");
      }
    }
  } catch (error) {
    atlasLocalDialogueState.connected = false;
    atlasLocalDialogueSetConnection(false, error?.name === "AbortError"
      ? "Le modèle local a dépassé le délai de réponse."
      : `Échec local : ${error?.message || "Bridge indisponible"}`);
  } finally {
    atlasLocalDialogueSetBusy(false);
  }
}

async function atlasLocalDialogueAsk() {
  if (!atlasDeviceComputeAllowed()) {
    atlasDeviceComputeApply({ restart: false });
    return false;
  }
  if (!atlasAccessIsAuthorized()) {
    atlasAccessOpen("#local-ai-hub");
    return;
  }
  const input = document.getElementById("atlasLocalQuestion");
  const question = String(input?.value || "").trim();
  if (!question) {
    setText(document.getElementById("atlasLocalDialogueStatus"), "Écris une question avant de lancer le dialogue.");
    input?.focus();
    return;
  }
  atlasLocalDialogueSetBusy(true, `Question transmise à ${atlasLocalDialogueState.profile === "aerith" ? "Aerith-10" : "Atlas-10"}…`);
  try {
    const snapshot = atlasBuildCryptoPageSnapshot();
    const questionContract = atlasPedagogyV2QuestionContract(question, snapshot);
    const currentReports = Object.fromEntries(
      ATLAS_LOCAL_REPORT_MODES.map(mode => [
        mode,
        atlasLocalReportsState.reports?.[mode]?.fingerprint === snapshot.fingerprint
          ? atlasLocalReportsState.reports[mode]
          : null
      ])
    );

    const result = await atlasLocalBridgeRequest("/chat", {
      profile: atlasLocalDialogueState.profile,
      question,
      snapshot,
      pedagogy_contract: questionContract,
      current_reports: currentReports,
      current_conclusion:
        atlasLocalDialogueState.conclusionResponse?.fingerprint === snapshot.fingerprint
          ? atlasLocalDialogueState.conclusionResponse
          : null,
      historical_memory_v2: {
        recent: atlasHistoryV2Read().slice(-10),
        compare: atlasHistoryV2Compare(snapshot)
      },
      release_candidate_v1: {
        contract: ATLAS_RC_CONTRACT,
        static_audit: atlasRcStaticAudit(),
        runtime_audit: atlasRcRuntimeAudit(snapshot)
      },
      request_scope: "question_only_no_pipeline_restart",
      response_language: "fr-FR",
      language_lock: "french_only_except_standard_crypto_acronyms",
      requested_reading: "whole_page_simple_detailed_expert",
      pedagogy_v2: atlasPedagogyV2QuestionContract(question, snapshot)
    });
    atlasLocalDialogueRender(result, "Réponse à la question libre");
    setText(
      document.getElementById("atlasLocalDialogueStatus"),
      `${atlasLocalDialogueState.profile === "aerith" ? "Aerith-10" : "Atlas-10"} · question libre · snapshot courant + historique + Watchlist + News + Math Core transmis.`
    );
  } catch (error) {
    atlasLocalDialogueState.connected = false;
    atlasLocalDialogueSetConnection(false, error?.name === "AbortError"
      ? "Le modèle local a dépassé le délai de réponse."
      : `Échec local : ${error?.message || "Bridge indisponible"}`);
  } finally {
    atlasLocalDialogueSetBusy(false);
  }
}

function atlasLocalDialogueClear() {
  const input = document.getElementById("atlasLocalQuestion");
  if (input) input.value = "";
  atlasLocalDialogueState.questionResponse = null;
  atlasLocalResponseSelectView("question");
  setText(document.getElementById("atlasLocalDialogueStatus"), "Question libre vidée. La conclusion Aerith-10 Crypto est conservée.");
}

async function atlasLocalDialogueCopy() {
  const text = atlasLocalDialogueState.lastResponse?.answer || "";
  if (!text) return;
  try {
    await navigator.clipboard.writeText(text);
    setText(document.getElementById("atlasLocalDialogueStatus"), "Réponse copiée.");
  } catch {
    const area = document.createElement("textarea");
    area.value = text;
    area.style.position = "fixed";
    area.style.opacity = "0";
    document.body.appendChild(area);
    area.select();
    document.execCommand("copy");
    area.remove();
    setText(document.getElementById("atlasLocalDialogueStatus"), "Réponse copiée.");
  }
}

function atlasLocalDialogueExport() {
  const response = atlasLocalDialogueState.lastResponse;
  if (!response?.answer) return;
  const profileLabel = response.profile === "aerith" ? "Aerith-10 Crypto" : "Atlas-10 Crypto";
  const lines = [
    `# ${profileLabel} — ${response.label || "Synthèse locale"}`,
    "",
    `- Version Agent-Crypto : ${ATLAS_RELEASE}`,
    `- Date : ${response.time || new Date().toISOString()}`,
    `- Moteur : ${response.provider || "local"} · ${response.model || "modèle local"}`,
    "- Mode : lecture seule",
    "",
    response.answer,
    "",
    "## Limite",
    "",
    "Analyse locale descriptive. Atlas → NØX → Aerith reste automatique. Validation humaine uniquement avant toute décision ou action financière réelle. Aucun ordre financier, wallet ou accès GitHub."
  ];
  const filename = `agent_crypto_${response.profile || "atlas"}_resume_${new Date().toISOString().replace(/[:.]/g, "-")}.md`;
  if (typeof downloadTextFile === "function") {
    downloadTextFile(filename, "text/markdown;charset=utf-8", lines.join("\n"));
  } else {
    const blob = new Blob([lines.join("\n")], { type: "text/markdown;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = filename;
    link.click();
    window.setTimeout(() => URL.revokeObjectURL(url), 1500);
  }
  setText(document.getElementById("atlasLocalDialogueStatus"), "Résumé Markdown exporté.");
}

function atlasV2DecisionLockRefresh() {
  const chartReady = state.dataBroker?.chart?.status === "ready";
  const newsReady = ["ok", "partial"].includes(newsFeedState?.status);
  const marketReady = !!state.liveOk && !!state.coins?.length;

  const marketMode = state.sourceLock?.mode || "none";
  const fxFallback = ["direct", "github-public"].includes(marketMode) && !!atlasMarketFxContext();
  const dataLabel = !marketReady
    ? "Marché en attente"
    : marketMode === "github-public"
      ? (atlasAnalysisLiveReady() ? "Snapshot public CoinGecko récent" : "Snapshot public CoinGecko daté")
      : marketMode === "direct"
        ? (fxFallback ? "CoinGecko USD → EUR BCE" : "CoinGecko EUR direct")
        : marketMode === "direct-conserved"
          ? "Dernière lecture conservée"
          : "Snapshot archivé chargé";
  setText(document.getElementById("decisionLockData"), dataLabel);
  setText(document.getElementById("decisionLockChart"), chartReady ? "Série vérifiée" : "Graphe à confirmer");
  setText(
    document.getElementById("decisionLockNews"),
    newsReady
      ? `${newsFeedState.events.length} événement${newsFeedState.events.length > 1 ? "s" : ""}`
      : "Archive à confirmer"
  );
  setText(document.getElementById("decisionLockHuman"), "Validation humaine");
}

function computeAtlasDataQuality(coin) {
  const missing = [];
  if (!coin) missing.push("actif");
  if (coin && typeof coin.price !== "number") missing.push("prix EUR");
  if (coin && typeof coin.volume24h !== "number") missing.push("volume 24h");
  if (coin && !atlasCanonicalCoin(coin)) missing.push("source canonique");
  if (!state.sourceLock?.valid) missing.push("Source Lock");
  if (coin && !coin.timestamp) missing.push("timestamp");
  const score = clamp(0, 100, 100 - missing.length * 24);
  return {
    score,
    status: score >= 80 ? "ok" : score >= 50 ? "faible" : "refus",
    missing
  };
}

function atlasObservationKind(quote = null) {
  const status = String(quote?.status || "").toLowerCase();
  const source = String(quote?.source || "").toLowerCase();
  const kind = String(quote?.kind || "").toLowerCase();

  if (status === "live" && source.includes("binance")) return "live-binance";
  if (
    status === "collected"
    || kind.includes("scanner-")
    || source.includes("collect")
  ) return "collected";
  if (status === "conserved") return "conserved";
  if (status === "snapshot") return "snapshot";
  if (["direct", "live"].includes(status)) return "direct";
  return "unavailable";
}

function atlasBuildStrictFactContractScannerLayer(period, chart, chartResult, comparisonIds, chartTruth) {
  const contract = atlasBuildStrictFactContractCore(period, chart, chartResult, comparisonIds, chartTruth);
  const latest = atlasScannerCollectorEffectiveLatest();
  contract.scanner_collector = latest ? {
    status: "available",
    schema: latest.schema,
    collected_at: latest.collected_at,
    market_timestamp: latest.market?.timestamp || null,
    market_mode: latest.market?.mode || null,
    baskets: latest.baskets || null,
    note: "Classements CoinGecko ; cotations observées Binance lorsqu'elles sont sûres, sinon CoinGecko."
  } : {
    status: "empty",
    note: "La collecte commence automatiquement dès qu'un Market Snapshot est disponible."
  };
  return contract;
}

const ATLAS_ANALYTICAL_STATE_SCHEMA = "agent_crypto_analytical_state_v2";

const ATLAS_EVIDENCE_SCHEMA = "agent_crypto_evidence_layer_v2";

const ATLAS_CONTRADICTION_SCHEMA = "agent_crypto_contradictions_v2";

const atlasAnalyticalTruthState = {
  currentEnvelope: null,
  currentFingerprint: "",
  analysisFingerprint: "",
  lastRenderedFingerprint: "",
  initialized: false,
  timer: 0
};

function atlasCanonicalNormalize(value) {
  if (value === null || value === undefined) return null;
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value === "string" || typeof value === "boolean") return value;
  if (Array.isArray(value)) return value.map(atlasCanonicalNormalize);
  if (typeof value === "object") {
    const output = {};
    Object.keys(value).sort().forEach(key => {
      if (value[key] !== undefined && typeof value[key] !== "function") {
        output[key] = atlasCanonicalNormalize(value[key]);
      }
    });
    return output;
  }
  return String(value);
}

function atlasCanonicalStringify(value) {
  return JSON.stringify(atlasCanonicalNormalize(value));
}

function atlasEvidenceNormalizeLevel(value, fallback = "INCONNU") {
  const raw = value && typeof value === "object"
    ? (value.level ?? value.label ?? value.quality ?? "")
    : value;
  const text = String(raw || "").toLocaleLowerCase("fr-FR");
  if (/primaire|primary/.test(text)) return "PRIMAIRE";
  if (/critique|fort|élev|strong|high|confirm/.test(text)) return "FORTE";
  if (/moyen|modér|medium|moderate|corrobor/.test(text)) return "MOYENNE";
  if (/faible|weak|low|rumor|rumeur/.test(text)) return "FAIBLE";
  return fallback;
}

function atlasEvidenceLayerBuild(contract) {
  const lead = contract?.news?.lead_event || null;
  if (!lead) {
    return {
      schema: ATLAS_EVIDENCE_SCHEMA,
      events: [],
      counts: { CONFIRMÉE: 0, CORROBORÉE: 0, SIGNALÉE: 0, À_VÉRIFIER: 0 },
      rule: "Impact potentiel et certitude restent séparés."
    };
  }
  const reportedSources = Math.max(0, Number(lead.source_count || 0));
  const independent = Number.isFinite(Number(lead.independent_source_count))
    ? Math.max(0, Number(lead.independent_source_count))
    : (reportedSources > 0 ? 1 : 0);
  const proof = atlasEvidenceNormalizeLevel(lead.evidence, "FAIBLE");
  const impact = atlasEvidenceNormalizeLevel(lead.impact, "INCONNU");
  let confidence = "À_VÉRIFIER";
  if ((proof === "PRIMAIRE" || proof === "FORTE") && independent >= 2) confidence = "CONFIRMÉE";
  else if ((proof === "FORTE" || proof === "MOYENNE") && independent >= 2) confidence = "CORROBORÉE";
  else if (proof !== "FAIBLE" || reportedSources > 0) confidence = "SIGNALÉE";
  const event = {
    id: atlasSha256(atlasCanonicalStringify({ headline: lead.headline || "", event_time: lead.event_time || "", source: lead.source_name || "" })).slice(0, 20),
    headline: lead.headline || "Événement non nommé",
    event_time: atlasStrictTimestamp(lead.event_time),
    source_name: lead.source_name || null,
    impact_potential: impact,
    confidence,
    proof_quality: proof,
    reported_sources: reportedSources,
    independent_sources: independent,
    assets: Array.isArray(lead.assets) ? lead.assets : [],
    sectors: Array.isArray(lead.sectors) ? lead.sectors : [],
    action: "OBSERVATION_UNIQUEMENT",
    limitation: independent < reportedSources ? "Les reprises ne prouvent pas une indépendance éditoriale." : null
  };
  const counts = { CONFIRMÉE: 0, CORROBORÉE: 0, SIGNALÉE: 0, À_VÉRIFIER: 0 };
  counts[confidence] = 1;
  return {
    schema: ATLAS_EVIDENCE_SCHEMA,
    events: [event],
    counts,
    rule: "Deux liens ou deux domaines ne prouvent pas deux sources indépendantes."
  };
}

function atlasContradictionsV2Build(contract, sourceTruth, mathQuality, evidence) {
  const rows = [];
  const severityMap = { "confirmé": "MEDIUM", "à vérifier": "LOW", "stop": "STOP" };
  (Array.isArray(contract?.contradictions) ? contract.contradictions : []).forEach(item => rows.push({
    id: item.code || atlasSha256(item.text || "contradiction").slice(0, 16),
    severity: severityMap[String(item.level || "").toLocaleLowerCase("fr-FR")] || "INFO",
    status: String(item.level || "").toLocaleLowerCase("fr-FR").includes("vérifier") ? "TO_VERIFY" : "CONFIRMED",
    statement: item.text || item.code || "Contradiction non détaillée",
    affects: [],
    stop_gate: String(item.level || "").toLocaleLowerCase("fr-FR") === "stop"
  }));
  const blocked = Number(mathQuality?.counts?.BLOCKED || 0);
  if (blocked > 0) rows.push({
    id: "math-measures-blocked",
    severity: blocked >= 4 ? "HIGH" : "MEDIUM",
    status: "CONFIRMED",
    statement: `${blocked} mesure${blocked > 1 ? "s" : ""} Math Core bloquée${blocked > 1 ? "s" : ""} par les Quality Gates.`,
    affects: ["math_core", "atlas", "aerith"],
    stop_gate: false
  });
  const unavailable = Number(sourceTruth?.counts?.[ATLAS_SOURCE_TRUTH_MODES.UNAVAILABLE] || 0);
  if (unavailable > 0) rows.push({
    id: "sources-unavailable",
    severity: "MEDIUM",
    status: "CONFIRMED",
    statement: `${unavailable} source${unavailable > 1 ? "s" : ""} indisponible${unavailable > 1 ? "s" : ""}.`,
    affects: ["source_truth"],
    stop_gate: false
  });
  const event = evidence?.events?.[0];
  if (event && event.reported_sources > event.independent_sources) rows.push({
    id: "news-syndication-not-independence",
    severity: "LOW",
    status: "ACCEPTED_LIMIT",
    statement: `${event.reported_sources} reprises News, mais ${event.independent_sources} source indépendante démontrée.`,
    affects: ["news_sentinel", "atlas", "aerith"],
    stop_gate: false
  });
  return {
    schema: ATLAS_CONTRADICTION_SCHEMA,
    items: rows,
    counts: {
      total: rows.length,
      stop: rows.filter(row => row.stop_gate).length,
      high: rows.filter(row => row.severity === "HIGH").length,
      to_verify: rows.filter(row => row.status === "TO_VERIFY").length
    }
  };
}

function atlasAnalyticalTargetMode() {
  const preset = String(state.dataBroker?.comparison?.preset || document.getElementById("targetTop5Cycle")?.dataset?.cyclePreset || "rank-5");
  return preset;
}

function atlasAnalyticalFingerprintPayload(envelope) {
  const targetAssets = Array.isArray(envelope?.target?.assets) ? envelope.target.assets : [];
  const sourceDescriptors = Array.isArray(envelope?.source_truth?.descriptors) ? envelope.source_truth.descriptors : [];
  return {
    schema: envelope.schema,
    application: envelope.application,
    market: {
      timestamp: envelope.market?.timestamp || null,
      assets_loaded: envelope.market?.assets_loaded || 0,
      target_assets: envelope.market?.target_assets || 250,
      quote_currency: envelope.market?.quote_currency || "EUR",
      mode: envelope.market?.mode || null,
      breadth_24h: envelope.market?.breadth_24h || null
    },
    target: {
      mode: envelope.target?.mode || null,
      symbols: targetAssets.map(row => row?.symbol || null),
      availability: targetAssets.map(row => !!row?.available),
      source_status: targetAssets.map(row => row?.quote_status || row?.source || null)
    },
    graph: {
      period_days: envelope.graph?.period_days || null,
      view: envelope.graph?.view || null,
      scale: envelope.graph?.scale || null,
      selected_ids: envelope.graph?.selected_ids || [],
      selected_symbols: envelope.graph?.selected_symbols || [],
      status: envelope.graph?.status || null,
      timestamp: envelope.graph?.timestamp || null,
      series: (envelope.graph?.series || []).map(row => ({
        symbol: row?.symbol || null,
        points: row?.points || 0,
        first_time: row?.first_time || null,
        last_time: row?.last_time || null,
        source_mode: row?.source_mode || null
      }))
    },
    scanner: envelope.scanner,
    math_core: {
      asset: envelope.math_core?.asset || null,
      active_window: envelope.math_core?.active_window || null,
      historical_risk: envelope.math_core?.historical_risk || null,
      quality_counts: envelope.quality_gates?.counts || null,
      method_version: envelope.quality_gates?.schema || null
    },
    news_sentinel: {
      status: envelope.news_sentinel?.status || null,
      archive_time: envelope.news_sentinel?.archive_time || null,
      event_ids: (envelope.evidence?.events || []).map(row => row.id),
      confidence: (envelope.evidence?.events || []).map(row => row.confidence)
    },
    watchlist: envelope.watchlist,
    source_truth: sourceDescriptors.map(row => ({
      id: row.id,
      provider: row.provider,
      mode: row.mode,
      freshness: row.freshness,
      instrument: row.instrument
    })),
    contradictions: (envelope.contradictions?.items || []).map(row => ({
      id: row.id,
      severity: row.severity,
      status: row.status,
      stop_gate: row.stop_gate
    }))
  };
}

function atlasAnalyticalBuildEnvelope(snapshot) {
  const contract = snapshot?.strict_contract || {};
  const sourceTruth = contract.source_truth_v2 || atlasSourceTruthBuild(contract);
  const evidence = contract.evidence_v2 || atlasEvidenceLayerBuild(contract);
  const quality = contract.math_quality_gates_v2 || atlasMathQualityGatesBuild(contract.math || {});
  const contradictions = contract.contradictions_v2 || atlasContradictionsV2Build(contract, sourceTruth, quality, evidence);
  const envelope = {
    schema: ATLAS_ANALYTICAL_STATE_SCHEMA,
    generated_at: snapshot?.generated_at || new Date().toISOString(),
    application: {
      interface_release: ATLAS_RELEASE,
      bridge_release: ATLAS_STABLE_STACK.bridge,
      control_center_release: ATLAS_STABLE_STACK.controlCenter,
      model: ATLAS_STABLE_STACK.model,
      fact_contract: contract.schema || null,
      fingerprint_version: ATLAS_ANALYTICAL_FINGERPRINT_VERSION
    },
    market: atlasSharedSynthesisClone(contract.market || {}),
    target: {
      mode: atlasAnalyticalTargetMode(),
      ...atlasSharedSynthesisClone(contract.canonical_top5 || {})
    },
    graph: atlasSharedSynthesisClone(contract.graph || {}),
    scanner: atlasSharedSynthesisClone(contract.scanner_collector || { status: "empty" }),
    math_core: atlasSharedSynthesisClone(contract.math || {}),
    news_sentinel: atlasSharedSynthesisClone(contract.news || {}),
    watchlist: atlasSharedSynthesisClone(contract.watchlist || {}),
    source_truth: atlasSharedSynthesisClone(sourceTruth),
    evidence: atlasSharedSynthesisClone(evidence),
    quality_gates: atlasSharedSynthesisClone(quality),
    contradictions: atlasSharedSynthesisClone(contradictions),
    safety: atlasSharedSynthesisClone(snapshot?.safety || {})
  };
  const canonicalPayload = atlasAnalyticalFingerprintPayload(envelope);
  envelope.fingerprint = {
    algorithm: "SHA-256",
    canonical_payload_version: "v2",
    value: atlasSha256(atlasCanonicalStringify(canonicalPayload))
  };
  return envelope;
}

function atlasAnalyticalSetText(id, value) {
  setText(document.getElementById(id), value);
}

function atlasAnalyticalList(id, rows, empty = "Aucune donnée.") {
  const node = document.getElementById(id);
  if (!node) return;
  const safe = Array.isArray(rows) && rows.length ? rows : [empty];
  node.innerHTML = safe.map(row => `<li>${atlasLocalEscapeHtml(row)}</li>`).join("");
}

function atlasAnalyticalSourceSummary(sourceTruth) {
  const counts = sourceTruth?.counts || {};
  const descriptors = Array.isArray(sourceTruth?.descriptors) ? sourceTruth.descriptors.length : 0;
  const direct = Number(counts[ATLAS_SOURCE_TRUTH_MODES.DIRECT] || 0) + Number(counts[ATLAS_SOURCE_TRUTH_MODES.DERIVED_DIRECT] || 0);
  const conserved = Number(counts[ATLAS_SOURCE_TRUTH_MODES.DIRECT_CONSERVED] || 0);
  const cached = Number(counts[ATLAS_SOURCE_TRUTH_MODES.CACHE_RECENT] || 0) + Number(counts[ATLAS_SOURCE_TRUTH_MODES.CACHE_DATED] || 0);
  const archived = Number(counts[ATLAS_SOURCE_TRUTH_MODES.ARCHIVE] || 0);
  const unavailable = Number(counts[ATLAS_SOURCE_TRUTH_MODES.UNAVAILABLE] || 0);
  const parts = [`${descriptors} descripteur${descriptors > 1 ? "s" : ""}`, `${direct} direct${direct > 1 ? "es" : "e"}`];
  if (conserved) parts.push(`${conserved} conservée${conserved > 1 ? "s" : ""}`);
  if (cached) parts.push(`${cached} cache${cached > 1 ? "s" : ""}`);
  if (archived) parts.push(`${archived} archive${archived > 1 ? "s" : ""}`);
  if (unavailable) parts.push(`${unavailable} indisponible${unavailable > 1 ? "s" : ""}`);
  return parts.join(" · ");
}

function atlasAnalyticalTruthRender(envelope = null) {
  const panel = document.getElementById("atlasAnalyticalTruth");
  if (!panel) return false;
  const pkg = atlasSharedSynthesisState?.package || null;
  const current = envelope || atlasAnalyticalTruthState.currentEnvelope || pkg?.analytical_state || null;
  const analysisFingerprint = atlasLocalDialogueState?.conclusionResponse?.fingerprint || pkg?.fingerprint || atlasAnalyticalTruthState.analysisFingerprint || "";
  const currentFingerprint = current?.fingerprint?.value ? `sha256:${current.fingerprint.value}` : "";
  atlasAnalyticalTruthState.analysisFingerprint = analysisFingerprint;
  let stateName = "waiting";
  let badge = "En attente";
  let context = "En attente";
  let contextDetail = "Aucun snapshot analytique V2 calculé.";
  let analysis = "Non produite";
  let analysisDetail = "Les quatre rapports et la conclusion restent transactionnels.";
  if (current) {
    context = "Cohérent";
    contextDetail = `${current.graph?.period_label || "Période inconnue"} · ${current.graph?.selected_symbols?.join(" · ") || current.target?.symbols?.join(" · ") || "sélection courante"}`;
    stateName = "ready";
    badge = "Vérifiée";
    if (analysisFingerprint) {
      const normalizedAnalysis = String(analysisFingerprint).replace(/^sha256:/, "");
      if (normalizedAnalysis === current.fingerprint?.value) {
        analysis = "Actuelle";
        analysisDetail = "Rapports 4/4 et conclusion liés à cette empreinte.";
      } else {
        analysis = "Conservée";
        analysisDetail = "Le contexte affiché a changé ; l’analyse précédente reste intacte.";
        stateName = "conserved";
        badge = "Conservée";
      }
    } else if (pkg) {
      analysis = "Conservée";
      analysisDetail = "Synthèse restaurée en lecture ; moteur local non requis.";
      stateName = "reading";
      badge = "Lecture";
    }
  } else if (pkg) {
    stateName = "reading";
    badge = "Lecture legacy";
    context = "Non vérifié";
    contextDetail = "Synthèse antérieure sans Analytical State V2.";
    analysis = "Conservée";
    analysisDetail = "Import lisible, empreinte V2 absente.";
  }
  panel.dataset.state = stateName;
  const badgeNode = document.getElementById("atlasAnalyticalTruthBadge");
  if (badgeNode) {
    badgeNode.textContent = badge;
    badgeNode.className = `pill ${["ready", "reading"].includes(stateName) ? "ok" : "warn"}`;
  }
  atlasAnalyticalSetText("atlasTruthContext", context);
  atlasAnalyticalSetText("atlasTruthContextDetail", contextDetail);
  atlasAnalyticalSetText("atlasTruthFingerprint", currentFingerprint ? `${currentFingerprint.slice(0, 20)}…` : "—");
  atlasAnalyticalSetText("atlasTruthFingerprintDetail", currentFingerprint ? "SHA-256 canonique · contexte analytique V2" : "SHA-256 canonique.");
  const sourceTruth = current?.source_truth || null;
  atlasAnalyticalSetText("atlasTruthSources", sourceTruth ? atlasAnalyticalSourceSummary(sourceTruth) : "—");
  atlasAnalyticalSetText("atlasTruthSourcesDetail", sourceTruth ? "Comptage des descripteurs de provenance (marché, Binance, séries, News), distinct du compteur 5/5 des paires Binance." : "Aucune source normalisée.");
  const evidenceEvent = current?.evidence?.events?.[0] || null;
  atlasAnalyticalSetText("atlasTruthNews", evidenceEvent ? `${evidenceEvent.confidence} · preuve ${evidenceEvent.proof_quality}` : "Aucun événement");
  atlasAnalyticalSetText("atlasTruthNewsDetail", evidenceEvent ? `Impact ${evidenceEvent.impact_potential} · ${evidenceEvent.independent_sources} source indépendante.` : "Impact séparé de la confiance.");
  const quality = current?.quality_gates || null;
  const q = quality?.counts || {};
  atlasAnalyticalSetText("atlasTruthMath", quality ? `${q.PUBLISHED || 0} publiées · ${q.DEGRADED || 0} dégradées · ${q.BLOCKED || 0} bloquées` : "—");
  atlasAnalyticalSetText("atlasTruthMathDetail", quality ? `${quality.returns_count || 0} rendements · complétude ${Number(quality.completeness_pct || 0).toFixed(1)} %.` : "Aucune mesure évaluée.");
  const contradictions = current?.contradictions || null;
  atlasAnalyticalSetText("atlasTruthContradictions", contradictions ? `${contradictions.counts?.total || 0} enregistrées` : "—");
  atlasAnalyticalSetText("atlasTruthContradictionsDetail", contradictions ? `${contradictions.counts?.stop || 0} stop gate · ${contradictions.counts?.to_verify || 0} à vérifier.` : "Limites et stop gates structurés.");
  atlasAnalyticalSetText("atlasTruthAnalysis", analysis);
  atlasAnalyticalSetText("atlasTruthAnalysisDetail", analysisDetail);
  atlasAnalyticalList("atlasTruthContextList", current ? [
    `Interface : ${current.application?.interface_release || ATLAS_RELEASE}`,
    `Graphique : ${current.graph?.period_label || "—"} · ${current.graph?.view || "—"} · ${current.graph?.scale || "—"}`,
    `Séries : ${(current.graph?.selected_symbols || []).join(" · ") || "—"}`,
    `Scanner : ${current.scanner?.status || "—"} · ${current.scanner?.collected_at || "aucun snapshot"}`,
    `Empreinte : ${currentFingerprint || "—"}`
  ] : []);
  atlasAnalyticalList("atlasTruthSourceList", sourceTruth?.descriptors?.map(row => `${row.provider} · ${row.mode} · ${row.freshness}${row.instrument ? ` · ${row.instrument}` : ""}`) || []);
  atlasAnalyticalList("atlasTruthEvidenceList", evidenceEvent ? [
    `${evidenceEvent.headline}`,
    `Impact potentiel : ${evidenceEvent.impact_potential}`,
    `Confiance : ${evidenceEvent.confidence}`,
    `Preuve : ${evidenceEvent.proof_quality}`,
    `Sources : ${evidenceEvent.reported_sources} reprise(s) · ${evidenceEvent.independent_sources} indépendante(s)`,
    "Action : observation uniquement"
  ] : []);
  atlasAnalyticalList("atlasTruthMathList", quality?.gates?.map(gate => `${gate.metric} · ${gate.status} · ${gate.reason}`) || []);
  atlasAnalyticalList("atlasTruthContradictionList", contradictions?.items?.map(row => `[${row.severity}] ${row.statement}${row.stop_gate ? " · STOP" : ""}`) || []);
  atlasAnalyticalSetText(
    "atlasAnalyticalTruthStatus",
    current
      ? `${analysis} · empreinte ${currentFingerprint ? "vérifiée" : "absente"} · aucune prévision ni action financière.`
      : "Empreinte V2 en attente · aucune action financière."
  );
  atlasAnalyticalTruthState.lastRenderedFingerprint = currentFingerprint;
  return true;
}

function atlasNoxNumber(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function atlasBuildNoxNoFomoAudit(contract) {
  const market = contract?.market || {};
  const news = contract?.news || {};
  const lead = news?.lead_event || null;
  const quality = contract?.math_quality_gates_v2 || {};
  const contradictions = contract?.contradictions_v2 || {};
  const sourceTruth = contract?.source_truth_v2 || {};
  const issues = Array.isArray(contradictions?.items) ? contradictions.items : [];
  const gates = Array.isArray(quality?.gates) ? quality.gates : [];
  const stopGates = issues.filter(item => item?.stop_gate === true);
  const blockedMath = gates.filter(item => String(item?.status || '').toUpperCase() === 'BLOCKED');
  const degradedMath = gates.filter(item => String(item?.status || '').toUpperCase() === 'DEGRADED');
  const sourceFailures = atlasNoxNumber(sourceTruth?.public_source_failures) || 0;
  const coverage = atlasNoxNumber(market?.assets_loaded);
  const target = atlasNoxNumber(market?.target_assets);

  let pressure = 0;
  const flags = [];
  if (stopGates.length) {
    pressure += 4;
    flags.push(`${stopGates.length} stop gate(s) analytique(s)`);
  }
  if (blockedMath.length) {
    pressure += 3;
    flags.push(`${blockedMath.length} mesure(s) Math Core bloquée(s)`);
  }
  if (degradedMath.length) {
    pressure += 1;
    flags.push(`${degradedMath.length} mesure(s) Math Core dégradée(s)`);
  }
  if (sourceFailures > 0) {
    pressure += 2;
    flags.push(`${sourceFailures} source(s) publique(s) indisponible(s)`);
  }
  if (coverage !== null && target && coverage < target) {
    pressure += 1;
    flags.push(`univers partiel ${coverage}/${target}`);
  }
  if (lead) {
    const proofText = `${lead?.evidence?.label || lead?.evidence || ''} ${lead?.evidence?.score || ''}`.toLowerCase();
    const impactText = `${lead?.impact?.label || lead?.impact || ''} ${lead?.impact?.score || ''}`.toLowerCase();
    const proofScore = atlasNoxNumber(lead?.evidence?.score ?? lead?.evidence_score);
    const impactScore = atlasNoxNumber(lead?.impact?.score ?? lead?.impact_score);
    const lowProof = (proofScore !== null && proofScore < 60) || /faible|rumeur|incertain/.test(proofText);
    const highImpact = (impactScore !== null && impactScore >= 80) || /critique|élevé|fort/.test(impactText);
    if (lowProof && highImpact) {
      pressure += 3;
      flags.push('actualité à fort impact potentiel mais preuve insuffisante');
    } else if (highImpact) {
      pressure += 1;
      flags.push('actualité à fort impact potentiel : causalité marché à confirmer');
    }
  }

  const status = pressure >= 6 ? 'STOP' : pressure >= 2 ? 'PRUDENCE' : 'CALME';
  const decision = status === 'STOP'
    ? 'STOP DÉCISIONNEL — l’analyse descriptive et pédagogique reste autorisée ; aucune conclusion décisionnelle tant que les stop gates ou preuves insuffisantes ne sont pas levés.'
    : status === 'PRUDENCE'
      ? 'CONTINUER À OBSERVER et demander confirmation avant toute interprétation causale.'
      : 'CONTINUER EN OBSERVATION sans transformer le contexte en signal d’exécution.';

  return {
    schema: 'agent_crypto_nox_no_fomo_v1',
    generated_at: new Date().toISOString(),
    status,
    pressure_score: pressure,
    fomo: status === 'CALME' ? 'faible' : status === 'PRUDENCE' ? 'à refroidir' : 'élevé / décision suspendue',
    causal_inference: lead ? 'NON ÉTABLIE — mesurer séparément la réaction du marché.' : 'AUCUNE ACTUALITÉ DIRECTRICE — ne pas fabriquer de causalité.',
    flags,
    decision,
    rules: [
      'Une actualité ne devient jamais un signal d’achat ou de vente.',
      'Une corrélation temporelle ne prouve pas la causalité.',
      'Une donnée absente reste INFORMATION MANQUANTE.',
      'Validation humaine uniquement avant toute décision ou action financière réelle ; la chaîne analytique reste automatique.'
    ]
  };
}

function atlasNoxNoFomoRender(audit) {
  const panel = document.getElementById('atlasNoFomoMathPanel');
  if (!panel || !audit) return false;
  const flags = Array.isArray(audit.flags) && audit.flags.length
    ? audit.flags.slice(0, 2).join(' · ')
    : 'aucun verrou critique détecté';
  panel.innerHTML = `<b>NØX No-FOMO · ${escapeHtml(audit.status || '—')}</b><span>${escapeHtml(audit.decision || '')} · ${escapeHtml(flags)}</span>`;
  return true;
}

function atlasBuildStrictFactContract(period, chart, chartResult, comparisonIds, chartTruth) {
  const contract = atlasBuildStrictFactContractScannerLayer(period, chart, chartResult, comparisonIds, chartTruth);
  const sourceTruth = atlasSourceTruthBuild(contract);
  const evidence = atlasEvidenceLayerBuild(contract);
  const quality = atlasMathQualityGatesBuild(contract.math || {});
  contract.math = atlasMathApplyQualityGates(contract.math || {}, quality);
  contract.source_truth_v2 = sourceTruth;
  contract.evidence_v2 = evidence;
  contract.math_quality_gates_v2 = quality;
  contract.contradictions_v2 = atlasContradictionsV2Build(contract, sourceTruth, quality, evidence);
  contract.nox_no_fomo_v1 = atlasBuildNoxNoFomoAudit(contract);
  contract.schema = "atlas_crypto_fact_contract_v3_truth_evidence";
  contract.rules = {
    ...(contract.rules || {}),
    analytical_fingerprint_v2: true,
    source_truth_v2: true,
    evidence_independence_required: true,
    metric_quality_gates: true,
    transactional_conclusion: true
  };
  return contract;
}

function atlasLocalReportSnapshotFingerprint(snapshot) {
  if (!snapshot) return "";
  if (!snapshot.analytical_state) snapshot.analytical_state = atlasAnalyticalBuildEnvelope(snapshot);
  const value = snapshot?.analytical_state?.fingerprint?.value;
  return value ? `sha256:${value}` : "";
}

function atlasLocalConclusionMeaningful(result) {
  const answer = String(result?.answer || "").replace(/\r\n?/g, "\n").trim();
  if (answer.length < 160) return false;

  const lower = answer.toLocaleLowerCase("fr-FR");
  const families = [
    ["situation générale", "situation du marché", "état général", "marché"],
    ["signal dominant", "lecture dominante", "signal principal", "tendance observée"],
    ["points de vigilance", "vigilance", "risques observés", "risque"],
    ["contradictions importantes", "contradictions", "points contradictoires"],
    ["surveiller ensuite", "surveillance suivante", "à surveiller", "observer"],
    ["limites et stop point", "limites", "stop point", "données manquantes"]
  ];

  const matched = families.filter(group => group.some(marker => lower.includes(marker))).length;
  const hasMarketFacts =
    /(binance|coingecko|btc|eth|bnb|xrp|sol|math core|watchlist|news sentinel)/i.test(answer);
  const hasRiskOrLimits =
    /(risque|prudence|limite|contradiction|donnée[s]? manquante[s]?|incertitude)/i.test(answer);
  const hasCore = matched >= 3 || (hasMarketFacts && hasRiskOrLimits);

  const safetyExplicit =
    lower.includes("validation humaine")
    || lower.includes("décision financière réelle")
    || lower.includes("aucun ordre")
    || lower.includes("aucune action financière")
    || lower.includes("ne constitue pas") && lower.includes("signal");

  const forbidden = /(acheter maintenant|vendre maintenant|ordre automatique|garanti|gain certain)/i.test(answer);
  return hasCore && safetyExplicit && !forbidden;
}

function atlasLocalReportStore(mode, result, snapshot, options = {}) {
  const report = atlasLocalReportStoreCore(mode, result, snapshot, options);
  if (report) {
    report.fingerprint_version = ATLAS_ANALYTICAL_FINGERPRINT_VERSION;
    report.analytical_state_schema = snapshot?.analytical_state?.schema || null;
    atlasAnalyticalTruthState.analysisFingerprint = report.fingerprint || atlasAnalyticalTruthState.analysisFingerprint;
    atlasAnalyticalTruthRender(snapshot?.analytical_state || null);
  }
  return report;
}

function atlasAnalyticalTruthIsBusy() {
  return !!atlasScannerTransaction
    || !!atlasScannerQueuedRequest
    || !!state.chartEngineV2?.loading
    || !!atlasLocalReportsState.running
    || !!atlasLocalConclusionState.running;
}

function atlasAnalyticalTruthSchedule(delay = 650) {
  if (atlasAnalyticalTruthState.timer) window.clearTimeout(atlasAnalyticalTruthState.timer);
  atlasAnalyticalTruthState.timer = window.setTimeout(() => {
    atlasAnalyticalTruthState.timer = 0;
    if (document.visibilityState !== "visible") return;
    if (atlasAnalyticalTruthIsBusy()) {
      atlasAnalyticalTruthSchedule(900);
      return;
    }
    if (Array.isArray(state.coins) && state.coins.length) {
      try { atlasBuildCryptoPageSnapshot(); }
      catch (error) {
        console.warn("Vérité analytique différée :", error);
        atlasAnalyticalTruthRender();
      }
    } else {
      atlasAnalyticalTruthRender();
    }
  }, Math.max(0, Number(delay) || 0));
  return true;
}

function atlasAnalyticalTruthInit() {
  if (atlasAnalyticalTruthState.initialized) return true;
  atlasAnalyticalTruthState.initialized = true;
  atlasAnalyticalTruthRender();

  window.addEventListener("online", () => atlasAnalyticalTruthSchedule(500));
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") atlasAnalyticalTruthSchedule(500);
  });

  /* Additif uniquement : les fonctions Target, Scanner, Graphique,
     Market Flow et leurs transactions restent celles de la 28.1.96.
     L'empreinte attend la fin de toute transaction avant de lire l'état. */
  document.addEventListener("click", () => atlasAnalyticalTruthSchedule(700), true);
  document.addEventListener("change", () => atlasAnalyticalTruthSchedule(700), true);

  atlasAnalyticalTruthSchedule(2200);
  return true;
}

