function atlasLearningClone(value) {
  if (value === undefined) return undefined;
  try { return structuredClone(value); } catch {}
  return JSON.parse(JSON.stringify(value));
}

function atlasLearningStorageJson(key, fallback = null) {
  if (atlasLearningNotebookCache) {
    if (key === ATLAS_LEARNING_COCKPIT_KEY) return atlasLearningClone(atlasLearningNotebookCache.cockpit ?? fallback);
    if (key === ATLAS_LEARNING_HISTORY_KEY) return atlasLearningClone(atlasLearningNotebookCache.history ?? fallback);
    if (key === ATLAS_EXPERT_ROADMAP_KEY) return atlasLearningClone(atlasLearningNotebookCache.roadmap ?? fallback);
    if (key === ATLAS_LEARNING_RECOVERY_AUDIT_KEY) return atlasLearningClone(atlasLearningNotebookCache.recovery ?? fallback);
    if (key === ATLAS_LEARNING_MIGRATION_KEY) return atlasLearningClone(atlasLearningNotebookCache.migration ?? fallback);
  }
  try {
    const raw = localStorage.getItem(key);
    if (raw === null) return fallback;
    return JSON.parse(raw);
  } catch { return fallback; }
}

function atlasLearningStorageWriteVerified(key, value) {
  if ([ATLAS_LEARNING_COCKPIT_KEY, ATLAS_LEARNING_HISTORY_KEY, ATLAS_EXPERT_ROADMAP_KEY, ATLAS_LEARNING_RECOVERY_AUDIT_KEY, ATLAS_LEARNING_MIGRATION_KEY].includes(key)) {
    if (!atlasLearningCanMutate()) return { ok:false, key, backend:"IndexedDB", blocked:true };
    if (!atlasLearningNotebookCache) atlasLearningNotebookCache = atlasLearningSeedFromLocalStorage();
    if (key === ATLAS_LEARNING_COCKPIT_KEY) atlasLearningNotebookCache.cockpit = atlasLearningClone(value);
    if (key === ATLAS_LEARNING_HISTORY_KEY) atlasLearningNotebookCache.history = atlasLearningClone(value);
    if (key === ATLAS_EXPERT_ROADMAP_KEY) atlasLearningNotebookCache.roadmap = atlasLearningClone(value);
    if (key === ATLAS_LEARNING_RECOVERY_AUDIT_KEY) atlasLearningNotebookCache.recovery = atlasLearningClone(value);
    if (key === ATLAS_LEARNING_MIGRATION_KEY) atlasLearningNotebookCache.migration = atlasLearningClone(value);
    atlasLearningSchedulePersist(`compat:${key}`);
    return { ok:true, key, backend:"IndexedDB", queued:true };
  }
  const raw = typeof value === "string" ? value : JSON.stringify(value);
  try {
    localStorage.setItem(key, raw);
    const readBack = localStorage.getItem(key);
    if (readBack !== raw) return { ok:false, key, error_name:"StorageVerificationError", error_message:"La valeur relue ne correspond pas à la valeur écrite.", bytes:raw.length * 2 };
    return { ok:true, key, bytes:raw.length * 2, backend:"localStorage" };
  } catch (error) {
    const name = String(error?.name || "StorageError");
    const message = String(error?.message || error || "Écriture locale impossible");
    return { ok:false, key, error_name:name, error_message:message, quota:/quota|exceed/i.test(`${name} ${message}`), bytes:raw.length * 2, backend:"localStorage" };
  }
}

function atlasLegacyLearningHash(value) {
  const text = String(value || "");
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, "0");
}

function atlasLearningDbRequest(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error("requête IndexedDB refusée"));
  });
}

function atlasLearningDbTransactionDone(transaction) {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve(true);
    transaction.onerror = () => reject(transaction.error || new Error("transaction IndexedDB refusée"));
    transaction.onabort = () => reject(transaction.error || new Error("transaction IndexedDB annulée"));
  });
}

function atlasLearningDbOpen() {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === "undefined") return reject(new Error("IndexedDB indisponible dans ce navigateur"));
    const request = indexedDB.open(ATLAS_LEARNING_DB_NAME, ATLAS_LEARNING_DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(ATLAS_LEARNING_DB_STORE)) db.createObjectStore(ATLAS_LEARNING_DB_STORE, { keyPath:"id" });
    };
    request.onsuccess = () => {
      const db = request.result;
      db.onversionchange = () => db.close();
      resolve(db);
    };
    request.onerror = () => reject(request.error || new Error("ouverture IndexedDB refusée"));
    request.onblocked = () => reject(new Error("IndexedDB bloquée par un autre onglet"));
  });
}

async function atlasLearningDbReadRecord() {
  const db = await atlasLearningDbOpen();
  try {
    const tx = db.transaction(ATLAS_LEARNING_DB_STORE, "readonly");
    const done = atlasLearningDbTransactionDone(tx);
    const request = tx.objectStore(ATLAS_LEARNING_DB_STORE).get(ATLAS_LEARNING_DB_RECORD_ID);
    const record = await atlasLearningDbRequest(request);
    await done;
    return record || null;
  } finally { db.close(); }
}

function atlasLearningNotebookPayload(record = atlasLearningNotebookCache) {
  const safe = record && typeof record === "object" ? record : {};
  const previousPersistence = safe.persistence && typeof safe.persistence === "object" ? safe.persistence : {};
  return {
    id:ATLAS_LEARNING_DB_RECORD_ID,
    schema:ATLAS_LEARNING_NOTEBOOK_SCHEMA,
    build:ATLAS_BUILD,
    versions:{ notebook:2, cockpit:2, history:1, roadmap:1, module_pedagogy:atlasLearningClone(ATLAS_FOUNDATION_MODULE_BUILDS), simulation:"separate_local_store" },
    cockpit:atlasLearningClone(safe.cockpit || null),
    history:atlasLearningClone(Array.isArray(safe.history) ? safe.history.slice(0,200) : []),
    roadmap:atlasLearningClone(safe.roadmap || null),
    recovery:atlasLearningClone(safe.recovery || {}),
    migration:atlasLearningClone(safe.migration || {}),
    reset:atlasLearningClone(safe.reset || {}),
    persistence:{
      schema:ATLAS_LEARNING_PERSISTENCE_SCHEMA,
      last_attempt_at:previousPersistence.last_attempt_at || null,
      last_verified_at:previousPersistence.last_verified_at || null,
      last_verified_digest:previousPersistence.last_verified_digest || null,
      pending_digest:previousPersistence.pending_digest || null,
      pending_at:previousPersistence.pending_at || null,
      last_reason:previousPersistence.last_reason || null,
      last_error:previousPersistence.last_error || null
    },
    last_reset_backup:atlasLearningClone(safe.last_reset_backup || null),
    updated_at:new Date().toISOString()
  };
}

function atlasLearningNotebookDigest(record) {
  const comparable = atlasLearningNotebookPayload(record);
  delete comparable.updated_at;
  if (comparable.persistence) {
    delete comparable.persistence.last_attempt_at;
    delete comparable.persistence.last_verified_at;
    delete comparable.persistence.last_verified_digest;
    delete comparable.persistence.pending_digest;
    delete comparable.persistence.pending_at;
    delete comparable.persistence.last_error;
  }
  return atlasLegacyLearningHash(JSON.stringify(comparable));
}

function atlasLearningPersistenceErrorCode(error, phase = "write") {
  const name = String(error?.name || "IndexedDBError");
  const message = String(error?.message || error || "IndexedDB indisponible");
  const text = `${name} ${message}`;
  if (/quota|exceed/i.test(text)) return "LEARNING-STORAGE-QUOTA";
  if (/blocked|bloqu/i.test(text) || phase === "blocked") return "LEARNING-IDB-BLOCKED";
  if (phase === "open") return "LEARNING-IDB-OPEN";
  if (phase === "read") return "LEARNING-IDB-READ";
  if (phase === "verify") return "LEARNING-IDB-VERIFY";
  return "LEARNING-IDB-WRITE";
}

async function atlasLearningDbPutRecord(record) {
  const db = await atlasLearningDbOpen();
  try {
    const tx = db.transaction(ATLAS_LEARNING_DB_STORE, "readwrite");
    const done = atlasLearningDbTransactionDone(tx);
    const request = tx.objectStore(ATLAS_LEARNING_DB_STORE).put(record);
    await atlasLearningDbRequest(request);
    await done;
    return true;
  } finally { db.close(); }
}

async function atlasLearningDbWriteVerified(record = atlasLearningNotebookCache, options = {}) {
  const reason = String(options.reason || "save");
  const attemptAt = new Date().toISOString();
  const pending = atlasLearningNotebookPayload(record);
  pending.persistence = {
    ...(pending.persistence || {}),
    schema:ATLAS_LEARNING_PERSISTENCE_SCHEMA,
    last_attempt_at:attemptAt,
    last_verified_at:null,
    last_verified_digest:null,
    pending_digest:null,
    pending_at:attemptAt,
    last_reason:reason,
    last_error:null
  };
  const expected = atlasLearningNotebookDigest(pending);
  pending.persistence.pending_digest = expected;
  let phase = "write";
  try {
    await atlasLearningDbPutRecord(pending);
    phase = "read";
    const readBack = await atlasLearningDbReadRecord();
    phase = "verify";
    const actual = readBack ? atlasLearningNotebookDigest(readBack) : "";
    if (!readBack || actual !== expected) {
      const failure = new Error("relecture IndexedDB différente de l’écriture");
      failure.name = "StorageVerificationError";
      throw failure;
    }
    phase = "commit";
    const verified = atlasLearningClone(readBack);
    verified.persistence = {
      ...(verified.persistence || {}),
      schema:ATLAS_LEARNING_PERSISTENCE_SCHEMA,
      last_attempt_at:attemptAt,
      last_verified_at:new Date().toISOString(),
      last_verified_digest:expected,
      pending_digest:null,
      pending_at:null,
      last_reason:reason,
      last_error:null
    };
    await atlasLearningDbPutRecord(verified);
    const bytes = new Blob([JSON.stringify(verified)]).size;
    return { ok:true, backend:"IndexedDB", bytes, digest:expected, reason, verified_at:verified.persistence.last_verified_at, record:verified };
  } catch (error) {
    const name = String(error?.name || "IndexedDBError");
    const message = String(error?.message || error || "écriture IndexedDB impossible");
    return {
      ok:false,
      backend:"IndexedDB",
      error_code:atlasLearningPersistenceErrorCode(error, phase === "commit" ? "write" : phase),
      error_name:name,
      error_message:message,
      phase,
      reason,
      quota:/quota|exceed/i.test(`${name} ${message}`)
    };
  }
}

function atlasLearningNormalizeRoadmap(data) {
  const source = data && typeof data === "object" ? data : {};
  const modules = {};
  ATLAS_EXPERT_ROADMAP_MODULES.forEach(module => {
    const previous = source.modules?.[module.key] || {};
    modules[module.key] = {
      status:ATLAS_EXPERT_STATUS_META[previous.status] ? previous.status : "new",
      note:String(previous.note || ""),
      updated_at:previous.updated_at || null
    };
  });
  return { schema:"agent_crypto_expert_roadmap_v1", horizon_months:24, modules };
}

function atlasLearningNormalizeCockpit(data, historyLength = 0) {
  const source = data && typeof data === "object" ? data : {};
  const moduleKey = ATLAS_EXPERT_ROADMAP_MODULES.some(module => module.key === source.module_key) ? source.module_key : null;
  const expectedFoundationBuild = foundationPathBuildForModule(moduleKey);
  const normalized = {
    schema:"agent_crypto_learning_journey_cockpit_v2",
    session_id:source.session_id || `LEARN-${Date.now().toString(36).toUpperCase()}`,
    started_at:source.started_at || new Date().toISOString(),
    completed_at:source.completed_at || null,
    completed_sessions:historyLength,
    module_key:moduleKey,
    steps:Object.fromEntries(ATLAS_LEARNING_SESSION_STEPS.map(key => [key, source.steps?.[key] === true])),
    lesson_read_at:source.lesson_read_at || null,
    notes_free:String(source.notes_free ?? source.note ?? ""),
    takeaway:String(source.takeaway ?? ""),
    practice_proof_id:source.practice_proof_id || null,
    practice_completed_at:source.practice_completed_at || null,
    verify_completed_at:source.verify_completed_at || null,
    practice_evidence:source.practice_evidence && typeof source.practice_evidence === "object" ? atlasLearningClone(source.practice_evidence) : {},
    last_target:source.last_target || null,
    last_action:source.last_action || null,
    flow_build:source.flow_build || null,
    restart_build:source.restart_build || ATLAS_LEARNING_FLOW_BUILD,
    legacy_signature:source.legacy_signature || null,
    legacy_source:source.legacy_source || null,
    migration_build:source.migration_build || null,
    foundation_path_build:source.foundation_path_build || expectedFoundationBuild
  };

  if (!source.completed_at && expectedFoundationBuild && source.foundation_path_build !== expectedFoundationBuild) {
    const evidenceKey = foundationGuidedEvidenceKey(normalized.module_key);

    // The only still-supported destructive migration is the historical Module 03
    // scenario correction introduced by 28.3.07. Every other unchanged module
    // keeps its active draft intact when the application Build changes.
    if (normalized.module_key === "risk") {
      const scenarios = Array.isArray(normalized.practice_evidence?.scenarios) ? normalized.practice_evidence.scenarios : [];
      const results = normalized.practice_evidence?.risk_scenario_results && typeof normalized.practice_evidence.risk_scenario_results === "object" ? normalized.practice_evidence.risk_scenario_results : {};
      const stableScenarioEvidence = [-3, 5].every(pct => results[String(pct)]?.model === "entry_anchored_simplified");
      if (scenarios.length && !stableScenarioEvidence) {
        normalized.practice_evidence.scenarios = [];
        delete normalized.practice_evidence.risk_scenario_results;
        delete normalized.practice_evidence.risk_guided_conclusion;
        delete normalized.practice_evidence.risk_guided_summary;
        delete normalized.practice_evidence.risk_guided_answer;
        normalized.steps.verify = false;
        normalized.verify_completed_at = null;
        normalized.steps.note = false;
        normalized.takeaway = "";
        normalized.last_action = "risk_scenarios_refresh_required";
      } else if (!evidenceKey || normalized.practice_evidence?.[evidenceKey] !== true) {
        normalized.steps.note = false;
      }
    } else if (["market", "spot"].includes(normalized.module_key) && (!evidenceKey || normalized.practice_evidence?.[evidenceKey] !== true)) {
      normalized.steps.note = false;
    }

    normalized.foundation_path_build = expectedFoundationBuild;
  }
  return normalized;
}

function atlasLearningSeedFromLocalStorage() {
  const historyValue = (() => { try { return JSON.parse(localStorage.getItem(ATLAS_LEARNING_HISTORY_KEY) || "[]"); } catch { return []; } })();
  const history = Array.isArray(historyValue) ? historyValue : [];
  const cockpitValue = (() => { try { return JSON.parse(localStorage.getItem(ATLAS_LEARNING_COCKPIT_KEY) || "null"); } catch { return null; } })();
  const roadmapValue = (() => { try { return JSON.parse(localStorage.getItem(ATLAS_EXPERT_ROADMAP_KEY) || "null"); } catch { return null; } })();
  return {
    id:ATLAS_LEARNING_DB_RECORD_ID,
    schema:ATLAS_LEARNING_NOTEBOOK_SCHEMA,
    build:ATLAS_BUILD,
    versions:{ notebook:2, cockpit:2, history:1, roadmap:1, module_pedagogy:atlasLearningClone(ATLAS_FOUNDATION_MODULE_BUILDS), simulation:"separate_local_store" },
    cockpit:atlasLearningNormalizeCockpit(cockpitValue, history.length),
    history:history.slice(0,200),
    roadmap:atlasLearningNormalizeRoadmap(roadmapValue),
    recovery:{ status:"pending", verified:false, backend:"IndexedDB", source_keys_preserved:true },
    migration:{},
    reset:{},
    persistence:{ schema:ATLAS_LEARNING_PERSISTENCE_SCHEMA, last_attempt_at:null, last_verified_at:null, last_verified_digest:null, pending_digest:null, pending_at:null, last_reason:null, last_error:null },
    last_reset_backup:null,
    updated_at:new Date().toISOString()
  };
}

function atlasLearningRetiredLocalStorageSnapshot() {
  const keys = [
    ATLAS_LEARNING_COCKPIT_KEY,
    ATLAS_LEARNING_HISTORY_KEY,
    ATLAS_EXPERT_ROADMAP_KEY,
    ATLAS_LEARNING_MIGRATION_KEY,
    ATLAS_LEARNING_MIGRATION_BACKUP_KEY,
    ATLAS_LEARNING_RECOVERY_AUDIT_KEY
  ];
  const records = [];
  for (const key of keys) {
    try {
      const raw = localStorage.getItem(key);
      if (raw !== null) records.push({ key, raw, bytes:new Blob([raw]).size });
    } catch {}
  }
  return records;
}

function atlasLearningReleaseRetiredLocalStorage(records = []) {
  const removed = [], failed = [];
  for (const item of records) {
    try {
      localStorage.removeItem(item.key);
      if (localStorage.getItem(item.key) === null) removed.push(item.key);
      else failed.push({ key:item.key, error:"clé encore présente" });
    } catch (error) {
      failed.push({ key:item.key, error:String(error?.message || error) });
    }
  }
  return {
    removed,
    failed,
    bytes_released:records.filter(item => removed.includes(item.key)).reduce((sum, item) => sum + Number(item.bytes || 0), 0),
    source_keys_preserved:[ATLAS_LEARNING_PREVIOUS_COCKPIT_KEY, ATLAS_LEARNING_PREVIOUS_ROADMAP_KEY]
  };
}

function atlasLearningNormalizeNotebook(record) {
  const history = Array.isArray(record?.history) ? record.history.slice(0,200) : [];
  const incomingPersistence = record?.persistence && typeof record.persistence === "object" ? record.persistence : {};
  return {
    id:ATLAS_LEARNING_DB_RECORD_ID,
    schema:ATLAS_LEARNING_NOTEBOOK_SCHEMA,
    build:ATLAS_BUILD,
    versions:{
      notebook:2,
      cockpit:2,
      history:1,
      roadmap:1,
      module_pedagogy:atlasLearningClone(ATLAS_FOUNDATION_MODULE_BUILDS),
      simulation:"separate_local_store"
    },
    cockpit:atlasLearningNormalizeCockpit(record?.cockpit, history.length),
    history,
    roadmap:atlasLearningNormalizeRoadmap(record?.roadmap),
    recovery:record?.recovery && typeof record.recovery === "object" ? atlasLearningClone(record.recovery) : {},
    migration:record?.migration && typeof record.migration === "object" ? atlasLearningClone(record.migration) : {},
    reset:record?.reset && typeof record.reset === "object" ? atlasLearningClone(record.reset) : {},
    persistence:{
      schema:String(incomingPersistence.schema || ATLAS_LEARNING_PERSISTENCE_SCHEMA),
      last_attempt_at:incomingPersistence.last_attempt_at || null,
      last_verified_at:incomingPersistence.last_verified_at || null,
      last_verified_digest:incomingPersistence.last_verified_digest || null,
      pending_digest:incomingPersistence.pending_digest || null,
      pending_at:incomingPersistence.pending_at || null,
      last_reason:incomingPersistence.last_reason || null,
      last_error:incomingPersistence.last_error || null
    },
    last_reset_backup:record?.last_reset_backup && typeof record.last_reset_backup === "object" ? atlasLearningClone(record.last_reset_backup) : null,
    updated_at:record?.updated_at || new Date().toISOString()
  };
}

function atlasLearningStorageBlockedResult(reason = "save") {
  const code = atlasLearningStorageReadBlocked ? "LEARNING-IDB-READ-BLOCKED" : "LEARNING-RESET-IN-PROGRESS";
  return { ok:false, backend:"IndexedDB", error_code:code, error_name:code, error_message:atlasLearningStorageReadBlocked ? "Lecture initiale IndexedDB non confirmée : aucune écriture autorisée." : "Réinitialisation en cours : sauvegarde différée refusée.", phase:"guard", reason };
}

function atlasLearningCanMutate() {
  if (!atlasLearningStorageReadBlocked && !atlasLearningStorageResetting) return true;
  const result = atlasLearningStorageBlockedResult("mutation_guard");
  atlasLearningStorageLastResult = result;
  window.__atlasLearningNotebookPersist = result;
  renderLearningPersistenceNotice(result);
  return false;
}

function atlasLearningQueueRecordWrite(snapshot, options = {}) {
  const reason = String(options.reason || "save");
  const generationAtQueue = Number.isFinite(options.generation) ? options.generation : atlasLearningStorageGeneration;
  const allowDuringReset = options.allowDuringReset === true;
  const execute = async () => {
    if (generationAtQueue !== atlasLearningStorageGeneration) return { ok:false, skipped:true, backend:"IndexedDB", error_code:"LEARNING-STALE-GENERATION", reason };
    if (atlasLearningStorageReadBlocked) return atlasLearningStorageBlockedResult(reason);
    if (atlasLearningStorageResetting && !allowDuringReset) return atlasLearningStorageBlockedResult(reason);
    return atlasLearningDbWriteVerified(snapshot, { reason });
  };
  atlasLearningStorageWriteChain = atlasLearningStorageWriteChain.catch(() => null).then(execute);
  return atlasLearningStorageWriteChain;
}

async function atlasLearningPersistNow(reason = "save", options = {}) {
  if (!atlasLearningNotebookCache) return { ok:false, backend:"IndexedDB", error_code:"LEARNING-CACHE-UNAVAILABLE", error_name:"LearningCacheUnavailable", error_message:"Carnet non initialisé" };
  clearTimeout(atlasLearningStoragePersistTimer);
  atlasLearningStoragePersistTimer = 0;
  atlasLearningStorageDirty = false;
  if (atlasLearningStorageReadBlocked || (atlasLearningStorageResetting && options.allowDuringReset !== true)) {
    const blocked = atlasLearningStorageBlockedResult(reason);
    atlasLearningStorageLastResult = blocked;
    renderLearningPersistenceNotice(blocked);
    return blocked;
  }
  const revisionAtQueue = atlasLearningStorageRevision;
  const generationAtQueue = Number.isFinite(options.generation) ? options.generation : atlasLearningStorageGeneration;
  const snapshot = atlasLearningClone(options.record || atlasLearningNotebookCache);
  const result = await atlasLearningQueueRecordWrite(snapshot, { reason, generation:generationAtQueue, allowDuringReset:options.allowDuringReset === true });
  atlasLearningStorageLastResult = { ...result, reason, at:new Date().toISOString(), revision:revisionAtQueue, generation:generationAtQueue };
  if (result.ok && generationAtQueue === atlasLearningStorageGeneration && revisionAtQueue === atlasLearningStorageRevision) atlasLearningNotebookCache = atlasLearningNormalizeNotebook(result.record);
  window.__atlasLearningNotebookPersist = atlasLearningStorageLastResult;
  renderLearningPersistenceNotice(result);
  return result;
}

function atlasLearningSchedulePersist(reason = "save") {
  if (atlasLearningStorageReadBlocked || atlasLearningStorageResetting) return atlasLearningStorageBlockedResult(reason);
  atlasLearningStorageRevision += 1;
  atlasLearningStorageDirty = true;
  clearTimeout(atlasLearningStoragePersistTimer);
  atlasLearningStoragePersistTimer = setTimeout(() => { atlasLearningPersistNow(reason); }, 180);
  return { ok:true, queued:true, reason };
}

function atlasLearningFlushScheduledPersist(reason = "pagehide") {
  if (!atlasLearningStorageDirty || atlasLearningStorageReadBlocked || atlasLearningStorageResetting || !atlasLearningNotebookCache) return Promise.resolve({ ok:false, skipped:true, reason });
  clearTimeout(atlasLearningStoragePersistTimer);
  atlasLearningStoragePersistTimer = 0;
  return atlasLearningPersistNow(reason);
}

function renderLearningPersistenceNotice(result = atlasLearningStorageLastResult) {
  const noticeTitle = document.getElementById("learningMigrationNoticeTitle");
  const noticeText = document.getElementById("learningMigrationNoticeText");
  if (!noticeTitle || !noticeText || !result) return;
  if (result.ok) {
    noticeTitle.textContent = "Carnet IndexedDB vérifié";
    noticeText.textContent = `Dernière écriture relue avec succès · ${result.reason || "sauvegarde"} · ${result.digest || "preuve disponible"}.`;
    return;
  }
  const code = result.error_code || atlasLearningPersistenceErrorCode(result, result.phase || "write");
  noticeTitle.textContent = atlasLearningStorageReadBlocked ? "Carnet en lecture seule" : "Carnet non sauvegardé";
  noticeText.textContent = `${code} · ${result.error_name || "IndexedDB"}. L’ancien état enregistré reste intact ; aucune donnée n’a été effacée automatiquement.`;
}

async function atlasLearningInitializeCache() {
  if (atlasLearningStorageReady) return atlasLearningNotebookCache;
  if (atlasLearningStorageInitPromise) return atlasLearningStorageInitPromise;
  atlasLearningStorageInitPromise = (async () => {
    try {
      const stored = await atlasLearningDbReadRecord();
      atlasLearningStorageReadBlocked = false;
      atlasLearningNotebookCache = stored ? atlasLearningNormalizeNotebook(stored) : atlasLearningSeedFromLocalStorage();
      atlasLearningStorageReady = true;
      return atlasLearningNotebookCache;
    } catch (error) {
      atlasLearningStorageReadBlocked = true;
      atlasLearningNotebookCache = atlasLearningSeedFromLocalStorage();
      atlasLearningStorageReady = true;
      atlasLearningStorageLastResult = { ok:false, backend:"IndexedDB", error_code:"LEARNING-IDB-READ-BLOCKED", error_name:String(error?.name || "IndexedDBError"), error_message:String(error?.message || error), status:"read_blocked", phase:"read" };
      window.__atlasLearningNotebookPersist = atlasLearningStorageLastResult;
      document.documentElement.dataset.learningStorageMode = "read-blocked";
      return atlasLearningNotebookCache;
    }
  })();
  return atlasLearningStorageInitPromise;
}

function atlasLearningStepsAreOrdered(steps = {}) {
  let gap = false;
  for (const key of ATLAS_LEARNING_SESSION_STEPS) {
    const done = steps?.[key] === true;
    if (!done) gap = true;
    else if (gap) return false;
  }
  return true;
}

function atlasLearningIntegrityReportFromRecord(record, options = {}) {
  const checkedAt = new Date().toISOString();
  const notebook = atlasLearningNormalizeNotebook(record || {});
  const history = Array.isArray(notebook.history) ? notebook.history : [];
  const cockpit = notebook.cockpit || defaultLearningCockpitState();
  const roadmapModules = notebook.roadmap?.modules || {};
  const archiveIds = history.map(entry => String(entry?.session_id || "")).filter(Boolean);
  const duplicateArchiveIds = [...new Set(archiveIds.filter((id, index) => archiveIds.indexOf(id) !== index))];
  const completeArchives = history.filter(entry => entry?.completed_at && ATLAS_LEARNING_SESSION_STEPS.every(key => entry.steps?.[key] === true));
  const archiveCounts = Object.fromEntries(ATLAS_EXPERT_ROADMAP_MODULES.map(module => [module.key, completeArchives.filter(entry => entry.module_key === module.key).length]));
  const archivedModuleKeys = ATLAS_EXPERT_ROADMAP_MODULES.filter(module => archiveCounts[module.key] > 0).map(module => module.key);
  const practicedModuleKeys = ATLAS_EXPERT_ROADMAP_MODULES.filter(module => roadmapModules[module.key]?.status === "practiced").map(module => module.key);
  const missingRoadmapPractice = archivedModuleKeys.filter(key => !practicedModuleKeys.includes(key));
  const missingArchiveForPractice = practicedModuleKeys.filter(key => !archivedModuleKeys.includes(key));
  const consistentModuleKeys = ATLAS_EXPERT_ROADMAP_MODULES.filter(module => practicedModuleKeys.includes(module.key) && archivedModuleKeys.includes(module.key)).map(module => module.key);
  const activeArchive = cockpit.completed_at ? history.find(entry => entry?.session_id === cockpit.session_id && entry?.completed_at) : null;
  const digest = record ? atlasLearningNotebookDigest(record) : null;
  const expectedDigest = record?.persistence?.last_verified_digest || null;
  const pendingDigest = record?.persistence?.pending_digest || null;
  const simulationKeysInsideNotebook = ["sim", "simulation", "positions", "transaction_proofs", "proofs"].filter(key => Object.prototype.hasOwnProperty.call(record || {}, key));
  const failures = [];
  const warnings = [];
  if (!record) failures.push({ code:"LEARNING-IDB-READ", message:"Aucun carnet IndexedDB n’a été relu." });
  if (record && record.id !== ATLAS_LEARNING_DB_RECORD_ID) failures.push({ code:"LEARNING-IDB-RECORD", message:"Identifiant du carnet inattendu." });
  if (record && record.schema !== ATLAS_LEARNING_NOTEBOOK_SCHEMA) warnings.push({ code:"LEARNING-SCHEMA-LEGACY", message:"Le carnet relu utilise encore le schéma précédent ; la prochaine sauvegarde normale effectuera la migration vérifiée." });
  if (record && pendingDigest) warnings.push({ code:"LEARNING-EVIDENCE-PENDING", message:"Une écriture a été engagée mais sa preuve finale n’a pas été confirmée." });
  if (record && !expectedDigest) warnings.push({ code:"LEARNING-EVIDENCE-MISSING", message:"Ce carnet ne possède pas encore d’empreinte vérifiée ; aucune intégrité complète n’est affirmée." });
  if (record && (!record.versions || typeof record.versions !== "object")) warnings.push({ code:"LEARNING-VERSION-METADATA", message:"Les métadonnées de version séparées seront ajoutées lors de la prochaine sauvegarde normale." });
  if (!ATLAS_FOUNDATION_MODULE_KEYS.includes(cockpit.module_key)) failures.push({ code:"LEARNING-COCKPIT-MODULE", message:"Module actif inconnu." });
  if (!atlasLearningStepsAreOrdered(cockpit.steps)) failures.push({ code:"LEARNING-STEP-ORDER", message:"Les étapes du module actif ne suivent pas 1 → 5." });
  if (duplicateArchiveIds.length) failures.push({ code:"LEARNING-ARCHIVE-DUPLICATE", message:`Archives dupliquées : ${duplicateArchiveIds.join(", ")}.` });
  if (cockpit.completed_at && !activeArchive) failures.push({ code:"LEARNING-ACTIVE-ARCHIVE", message:"La session marquée terminée n’existe pas dans l’historique relu." });
  if (missingRoadmapPractice.length) failures.push({ code:"LEARNING-ROADMAP-MISMATCH", message:`Archives sans statut Pratiqué : ${missingRoadmapPractice.join(", ")}.` });
  if (missingArchiveForPractice.length) failures.push({ code:"LEARNING-ARCHIVE-MISSING", message:`Statuts Pratiqué sans archive complète : ${missingArchiveForPractice.join(", ")}.` });
  if (simulationKeysInsideNotebook.length) failures.push({ code:"LEARNING-SIMULATION-SEPARATION", message:`Données de simulation trouvées dans le carnet : ${simulationKeysInsideNotebook.join(", ")}.` });
  if (expectedDigest && digest !== expectedDigest) failures.push({ code:"LEARNING-IDB-VERIFY", message:"L’empreinte relue ne correspond pas à la dernière empreinte vérifiée." });
  if (history.some(entry => entry?.completed_at && !ATLAS_LEARNING_SESSION_STEPS.every(key => entry.steps?.[key] === true))) warnings.push({ code:"LEARNING-LEGACY-ARCHIVE", message:"Une archive historique ne possède pas les cinq preuves du format actuel." });
  const journeyComplete = consistentModuleKeys.length === ATLAS_EXPERT_ROADMAP_MODULES.length && !missingRoadmapPractice.length && !missingArchiveForPractice.length;
  const nextModule = journeyComplete ? null : ATLAS_EXPERT_ROADMAP_MODULES.find(module => !consistentModuleKeys.includes(module.key)) || null;
  const status = failures.length ? "error" : warnings.length ? "warning" : "ok";
  return {
    schema:ATLAS_LEARNING_DIAGNOSTIC_SCHEMA,
    build:ATLAS_BUILD,
    checked_at:checkedAt,
    status,
    persistence:{ backend:"IndexedDB", record_found:Boolean(record), schema:record?.schema || null, record_build:record?.build || null, updated_at:record?.updated_at || null, digest, expected_digest:expectedDigest, pending_digest:pendingDigest, digest_verified:Boolean(expectedDigest && digest === expectedDigest && !pendingDigest), last_verified_at:record?.persistence?.last_verified_at || null, last_reason:record?.persistence?.last_reason || null, bytes:Number(options.bytes || 0) || null },
    cockpit:{ session_id:cockpit.session_id, module_key:cockpit.module_key, completed_at:cockpit.completed_at || null, completed_sessions:Number(cockpit.completed_sessions || 0), steps:atlasLearningClone(cockpit.steps || {}), step_order_valid:atlasLearningStepsAreOrdered(cockpit.steps) },
    archives:{ total:history.length, complete_current_format:completeArchives.length, unique_ids:duplicateArchiveIds.length === 0, duplicate_ids:duplicateArchiveIds, counts_by_module:archiveCounts },
    roadmap:{ practiced:practicedModuleKeys.length, total:ATLAS_EXPERT_ROADMAP_MODULES.length, practiced_module_keys:practicedModuleKeys, archived_module_keys:archivedModuleKeys, consistent_module_keys:consistentModuleKeys, missing_practice_for_archives:missingRoadmapPractice, missing_archives_for_practice:missingArchiveForPractice },
    journey:{ complete:journeyComplete, next_module:nextModule?.key || null },
    separation:{ simulation_inside_notebook:simulationKeysInsideNotebook.length > 0, unexpected_keys:simulationKeysInsideNotebook, simulation_storage:"separate" },
    failures,
    warnings
  };
}

function renderLearningIntegrityReport(report = atlasLearningIntegrityLastReport) {
  const panel = document.getElementById("learningIntegrityPanel");
  const badge = document.getElementById("learningIntegrityBadge");
  const summary = document.getElementById("learningIntegritySummary");
  const details = document.getElementById("learningIntegrityDetails");
  const exportButton = document.getElementById("btnExportLearningIntegrity");
  if (!panel || !badge || !summary || !details) return;
  if (!report) { panel.hidden = true; return; }
  panel.hidden = false;
  const statusLabel = report.status === "ok" ? "INTÈGRE" : report.status === "warning" ? "À RELIRE" : "ERREUR";
  badge.textContent = statusLabel;
  badge.className = report.status === "ok" ? "pill ok" : "pill warn";
  summary.innerHTML = [
    `<article><b>IndexedDB</b><span>${report.persistence.record_found ? "Carnet relu" : "Non relu"}</span><em>${escapeHtml(report.persistence.digest_verified ? "Empreinte vérifiée" : "Empreinte non confirmée")}</em></article>`,
    `<article><b>Module actif</b><span>${escapeHtml(String(report.cockpit.module_key || "—"))}</span><em>${ATLAS_LEARNING_SESSION_STEPS.filter(key => report.cockpit.steps?.[key]).length}/5 étapes · ordre ${report.cockpit.step_order_valid ? "valide" : "incohérent"}</em></article>`,
    `<article><b>Archives</b><span>${report.archives.total}</span><em>${report.archives.unique_ids ? "Aucun doublon" : "Doublon détecté"}</em></article>`,
    `<article><b>Feuille de route</b><span>${report.roadmap.practiced}/${report.roadmap.total}</span><em>${report.journey.complete ? "Parcours terminé" : "Parcours en cours"}</em></article>`
  ].join("");
  const messages = [...report.failures, ...report.warnings];
  details.textContent = messages.length
    ? messages.map(item => `${item.code} · ${item.message}`).join("\n")
    : `Aucune incohérence détectée.\nDernière écriture : ${report.persistence.last_verified_at || "—"}\nMotif : ${report.persistence.last_reason || "—"}`;
  if (exportButton) exportButton.disabled = false;
}

async function verifyLearningIntegrity() {
  const button = document.getElementById("btnVerifyLearningIntegrity");
  if (button) { button.disabled = true; button.textContent = "Vérification…"; }
  try {
    // Diagnostic strictement en lecture seule : attendre une écriture déjà engagée,
    // puis relire IndexedDB sans créer de nouvelle transaction d'écriture.
    await atlasLearningStorageWriteChain.catch(() => null);
    const record = await atlasLearningDbReadRecord().catch(() => null);
    const bytes = record ? new Blob([JSON.stringify(record)]).size : 0;
    const report = atlasLearningIntegrityReportFromRecord(record, { bytes });
    report.status = report.failures.length ? "error" : report.warnings.length ? "warning" : "ok";
    if (navigator.storage?.estimate) {
      try { const estimate = await navigator.storage.estimate(); report.storage_estimate = { usage:Number(estimate.usage || 0), quota:Number(estimate.quota || 0) }; } catch {}
    }
    atlasLearningIntegrityLastReport = report;
    window.__atlasLearningIntegrityLastReport = atlasLearningClone(report);
    renderLearningIntegrityReport(report);
    scrollToLearningTarget("learningIntegrityPanel");
    setActionFeedback(report.status === "ok" ? "ok" : "warn", report.status === "ok" ? "Intégrité du parcours vérifiée" : "Diagnostic du parcours disponible", report.status === "ok" ? "IndexedDB, brouillon, archives et feuille de route sont cohérents." : "Aucun reset ni effacement n’a été effectué. Lis les codes affichés dans le diagnostic.", document.getElementById("learningIntegrityPanel"));
    return report;
  } catch (error) {
    const report = { schema:ATLAS_LEARNING_DIAGNOSTIC_SCHEMA, build:ATLAS_BUILD, checked_at:new Date().toISOString(), status:"error", failures:[{ code:atlasLearningPersistenceErrorCode(error,"read"), message:String(error?.message || error) }], warnings:[] };
    atlasLearningIntegrityLastReport = report;
    window.__atlasLearningIntegrityLastReport = atlasLearningClone(report);
    renderLearningIntegrityReport(report);
    return report;
  } finally {
    if (button) { button.disabled = false; button.textContent = "Vérifier l’intégrité du parcours"; }
  }
}

function exportLearningIntegrityReport() {
  if (!atlasLearningIntegrityLastReport) return verifyLearningIntegrity().then(() => exportLearningIntegrityReport());
  const blob = new Blob([JSON.stringify(atlasLearningIntegrityLastReport, null, 2) + "\n"], { type:"application/json;charset=utf-8" });
  const link = document.createElement("a");
  link.href = URL.createObjectURL(blob);
  link.download = `agent_crypto_learning_integrity_${ATLAS_BUILD.replaceAll(".", "_")}.json`;
  document.body.appendChild(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(link.href), 1500);
}

function legacyLearningSnapshot() {
  let cockpitRaw = "", roadmapRaw = "";
  try {
    cockpitRaw = localStorage.getItem(ATLAS_LEARNING_PREVIOUS_COCKPIT_KEY) || "";
    roadmapRaw = localStorage.getItem(ATLAS_LEARNING_PREVIOUS_ROADMAP_KEY) || "";
  } catch {}
  let cockpit = null, roadmap = null;
  try { cockpit = cockpitRaw ? JSON.parse(cockpitRaw) : null; } catch {}
  try { roadmap = roadmapRaw ? JSON.parse(roadmapRaw) : null; } catch {}
  const steps = Object.fromEntries(ATLAS_LEARNING_SESSION_STEPS.map(key => [key, cockpit?.steps?.[key] === true]));
  const note = String(cockpit?.note || "");
  const modules = ATLAS_EXPERT_ROADMAP_MODULES.map(module => {
    const item = roadmap?.modules?.[module.key] || {};
    const status = ATLAS_EXPERT_STATUS_META[item.status] ? item.status : "new";
    return { key:module.key, title:module.title, status, note:String(item.note || ""), updated_at:item.updated_at || null };
  });
  const progressed = modules.filter(item => item.status !== "new");
  const completedSessions = Math.max(0, Math.trunc(atlasFiniteNumber(cockpit?.completed_sessions, 0)));
  const hasCockpit = Boolean(cockpit && typeof cockpit === "object" && (note || cockpit.module_key || cockpit.completed_at || completedSessions || Object.values(steps).some(Boolean)));
  const hasRoadmap = progressed.length > 0 || modules.some(item => item.note);
  const signature = atlasLegacyLearningHash(`${cockpitRaw}\n---ROADMAP---\n${roadmapRaw}`);
  return {
    has_data:hasCockpit || hasRoadmap,
    signature,
    cockpit_raw:cockpitRaw,
    roadmap_raw:roadmapRaw,
    cockpit,
    roadmap,
    steps,
    note,
    note_length:learningTextCount(note),
    completed_sessions:completedSessions,
    module_key:ATLAS_EXPERT_ROADMAP_MODULES.some(module => module.key === cockpit?.module_key) ? cockpit.module_key : null,
    progressed_modules:progressed,
    all_modules:modules
  };
}

function legacyLearningMigrationMarker() {
  return atlasLearningClone(atlasLearningNotebookCache?.migration || {});
}

function legacyLearningRecoveryAuditMarker() {
  return atlasLearningClone(atlasLearningNotebookCache?.recovery || {});
}

function legacyLearningMigrationPreview(snapshot = legacyLearningSnapshot()) {
  if (!snapshot.has_data) return "Aucune donnée pédagogique ancienne détectée.";
  const checked = ATLAS_LEARNING_SESSION_STEPS.filter(key => snapshot.steps[key]).length;
  const module = learningModuleByKey(snapshot.module_key || "market");
  const lines = [
    "MÉMOIRE PÉDAGOGIQUE ANCIENNE DÉTECTÉE",
    "",
    `Empreinte : ${snapshot.signature}`,
    `Session courante ancienne : ${module.title}`,
    `Sessions déclarées : ${snapshot.completed_sessions}`,
    `Étapes cochées dans le brouillon : ${checked}/5`,
    `Texte conservé dans l’ancien champ : ${snapshot.note_length} caractère${snapshot.note_length > 1 ? "s" : ""}`,
    `Modules avec progression : ${snapshot.progressed_modules.length}`,
    "",
    "PROGRESSION RETROUVÉE",
    ...(snapshot.progressed_modules.length ? snapshot.progressed_modules.map(item => `- ${item.title} : ${ATLAS_EXPERT_STATUS_META[item.status]?.label || item.status}`) : ["- Aucune progression de module retrouvée."]),
    "",
    "TEXTE RETROUVÉ DANS LE BROUILLON",
    snapshot.note || "Aucun texte dans l’ancien brouillon.",
    "",
    "STOCKAGE CIBLE",
    "IndexedDB — le localStorage saturé n’est plus utilisé pour le nouveau carnet.",
    "Les anciennes clés restent intactes."
  ];
  return lines.join("\n");
}

function learningMigrationCurrentIsPristine(current, history) {
  return !current.completed_at && !String(current.notes_free || "").trim() && !String(current.takeaway || "").trim() && !ATLAS_LEARNING_SESSION_STEPS.some(key => current.steps?.[key]) && history.length === 0;
}

function legacyLearningProgressRecord(module, item, signature, index) {
  const stamp = item.updated_at || new Date().toISOString();
  return {
    schema:"agent_crypto_learning_journey_cockpit_v2",
    session_id:`LEGACY-PROGRESS-${module.key}-${signature}-${index + 1}`,
    started_at:stamp,
    completed_at:stamp,
    archived_at:new Date().toISOString(),
    completed_sessions:0,
    module_key:module.key,
    module_title:module.title,
    steps:{ read:false, open:false, practice:false, verify:false, note:false },
    lesson:ATLAS_GUIDED_LESSONS[module.key] || ATLAS_GUIDED_LESSONS.market,
    profile_label:"Profil fictif historique — détail non enregistré",
    simulation:null,
    interface_facts:[`Progression ${ATLAS_EXPERT_STATUS_META[item.status]?.label || item.status} retrouvée dans le parcours 28.2.79.`, "Le détail des cases, de la simulation et du texte de cette ancienne séance n’était pas archivé par l’ancien format."],
    notes_free:item.note || "Progression récupérée. Le texte détaillé de cette séance n’était pas conservé dans l’ancien format.",
    takeaway:item.note || "",
    legacy_progress_only:true,
    legacy_status:item.status,
    legacy_signature:signature,
    migration_build:ATLAS_LEARNING_RECOVERY_BUILD
  };
}

function legacyLearningTargetAudit(snapshot = legacyLearningSnapshot(), notebook = atlasLearningNotebookCache) {
  const cockpit = notebook?.cockpit || null;
  const history = Array.isArray(notebook?.history) ? notebook.history : [];
  const roadmap = notebook?.roadmap || null;
  const progressChecks = snapshot.progressed_modules.map(item => {
    const targetStatus = roadmap?.modules?.[item.key]?.status || "new";
    const sourceScore = ATLAS_EXPERT_STATUS_META[item.status]?.score ?? 0;
    const targetScore = ATLAS_EXPERT_STATUS_META[targetStatus]?.score ?? 0;
    return { key:item.key, source:item.status, target:targetStatus, ok:targetScore >= sourceScore };
  });
  const legacyHistory = history.filter(entry => entry?.legacy_signature === snapshot.signature);
  const expectedHistory = Math.max(snapshot.completed_sessions, snapshot.progressed_modules.length ? 1 : 0);
  const noteContainers = [String(cockpit?.notes_free || ""), String(cockpit?.takeaway || ""), ...history.flatMap(entry => [String(entry?.notes_free || ""), String(entry?.takeaway || "")])];
  const noteOk = !snapshot.note || noteContainers.some(value => value.includes(snapshot.note));
  const sourceDraft = Boolean(snapshot.cockpit && !snapshot.cockpit.completed_at && snapshot.module_key);
  const recoveredDraft = legacyHistory.find(entry => entry?.module_key === snapshot.module_key && entry?.legacy_draft === true);
  const moduleOk = !sourceDraft || cockpit?.module_key === snapshot.module_key || Boolean(recoveredDraft);
  const compatibleSteps = ["read", "open", "practice", "verify"];
  const recoveredStepsSource = cockpit?.module_key === snapshot.module_key ? cockpit?.steps : recoveredDraft?.steps;
  const stepsOk = !sourceDraft || compatibleSteps.every(key => !snapshot.steps[key] || recoveredStepsSource?.[key] === true);
  const historyOk = legacyHistory.length >= expectedHistory;
  const progressOk = progressChecks.every(item => item.ok);
  const verified = Boolean(snapshot.has_data && cockpit && roadmap && noteOk && moduleOk && stepsOk && historyOk && progressOk);
  return {
    verified,
    signature:snapshot.signature,
    note_ok:noteOk,
    module_ok:moduleOk,
    steps_ok:stepsOk,
    history_ok:historyOk,
    progress_ok:progressOk,
    expected_history:expectedHistory,
    recovered_history:legacyHistory.length,
    module_expected:snapshot.module_key,
    module_actual:cockpit?.module_key || null,
    notes_expected:snapshot.note_length,
    notes_recovered:noteOk ? snapshot.note_length : 0,
    checked_steps_expected:compatibleSteps.filter(key => snapshot.steps[key]).length,
    checked_steps_recovered:compatibleSteps.filter(key => recoveredStepsSource?.[key]).length,
    progress_checks:progressChecks,
    backend:"IndexedDB"
  };
}

function legacyLearningRecoveryPlan(snapshot = legacyLearningSnapshot()) {
  const currentBefore = loadLearningCockpitState();
  const historyBefore = loadLearningHistory();
  const roadmapBefore = loadExpertRoadmap();
  const history = historyBefore.slice();
  const roadmap = atlasLearningClone(roadmapBefore);
  let progressRecordsAdded = 0;

  snapshot.progressed_modules.forEach((legacyItem, index) => {
    const module = learningModuleByKey(legacyItem.key);
    const currentItem = roadmap.modules[module.key] || { status:"new", note:"", updated_at:null };
    const currentScore = ATLAS_EXPERT_STATUS_META[currentItem.status]?.score ?? 0;
    const legacyScore = ATLAS_EXPERT_STATUS_META[legacyItem.status]?.score ?? 0;
    const status = legacyScore > currentScore ? legacyItem.status : currentItem.status;
    const note = [String(currentItem.note || "").trim(), String(legacyItem.note || "").trim()].filter(Boolean).filter((value, pos, array) => array.indexOf(value) === pos).join("\n\n");
    roadmap.modules[module.key] = { ...currentItem, status, note, updated_at:currentItem.updated_at || legacyItem.updated_at || new Date().toISOString() };
    const recordId = `LEGACY-PROGRESS-${module.key}-${snapshot.signature}-${index + 1}`;
    if (!history.some(entry => entry?.session_id === recordId || (entry?.legacy_signature === snapshot.signature && entry?.module_key === module.key && entry?.legacy_progress_only))) {
      history.push(legacyLearningProgressRecord(module, legacyItem, snapshot.signature, index));
      progressRecordsAdded += 1;
    }
  });

  while (history.filter(entry => entry?.legacy_signature === snapshot.signature).length < snapshot.completed_sessions) {
    const index = history.filter(entry => entry?.legacy_signature === snapshot.signature).length;
    const module = ATLAS_EXPERT_ROADMAP_MODULES[index] || ATLAS_EXPERT_ROADMAP_MODULES[0];
    history.push(legacyLearningProgressRecord(module, { status:"discovered", note:"", updated_at:snapshot.cockpit?.started_at || null }, snapshot.signature, index));
    progressRecordsAdded += 1;
  }

  const legacyRecommended = recommendedLearningModule() || ATLAS_EXPERT_ROADMAP_MODULES[0];
  const legacyModule = learningModuleByKey(snapshot.module_key || legacyRecommended.key);
  const oldSteps = { read:snapshot.steps.read, open:snapshot.steps.open, practice:snapshot.steps.practice, verify:snapshot.steps.verify, note:false };
  const pristine = learningMigrationCurrentIsPristine(currentBefore, historyBefore);
  let cockpit = { ...currentBefore };

  if (snapshot.cockpit?.completed_at) {
    const completedId = `LEGACY-COMPLETE-${snapshot.signature}`;
    if (!history.some(entry => entry?.session_id === completedId)) {
      history.push({ ...defaultLearningCockpitState(), session_id:completedId, started_at:snapshot.cockpit.started_at || snapshot.cockpit.completed_at, completed_at:snapshot.cockpit.completed_at, archived_at:new Date().toISOString(), module_key:legacyModule.key, module_title:legacyModule.title, steps:{...snapshot.steps}, lesson:ATLAS_GUIDED_LESSONS[legacyModule.key] || ATLAS_GUIDED_LESSONS.market, notes_free:"", takeaway:snapshot.note, legacy_signature:snapshot.signature, legacy_source:"cockpit_28_2_81", migration_build:ATLAS_LEARNING_RECOVERY_BUILD });
    }
  } else if (pristine) {
    cockpit = { ...currentBefore, session_id:snapshot.cockpit?.session_id || `LEGACY-DRAFT-${snapshot.signature}`, started_at:snapshot.cockpit?.started_at || new Date().toISOString(), completed_at:null, completed_sessions:Math.max(snapshot.completed_sessions, history.length), module_key:legacyModule.key, steps:oldSteps, lesson_read_at:snapshot.steps.read ? (snapshot.cockpit?.started_at || new Date().toISOString()) : null, notes_free:snapshot.note, takeaway:"", practice_proof_id:null, legacy_signature:snapshot.signature, legacy_source:"cockpit_28_2_81", migration_build:ATLAS_LEARNING_RECOVERY_BUILD, restart_build:ATLAS_LEARNING_RECOVERY_BUILD };
  } else {
    const recovered = snapshot.note.trim();
    if (recovered && !String(cockpit.notes_free || "").includes(recovered)) cockpit.notes_free = [String(cockpit.notes_free || "").trim(), `---\nBrouillon récupéré du Cockpit 28.2.81\n\n${recovered}`].filter(Boolean).join("\n\n");
    const currentWasBlank = !ATLAS_LEARNING_SESSION_STEPS.some(key => currentBefore.steps?.[key]) && !String(currentBefore.notes_free || "").trim() && !String(currentBefore.takeaway || "").trim();
    if (currentWasBlank) {
      cockpit.module_key = legacyModule.key;
      cockpit.steps = Object.fromEntries(ATLAS_LEARNING_SESSION_STEPS.map(key => [key, key === "note" ? Boolean(cockpit.takeaway?.trim()) : Boolean(cockpit.steps?.[key] || oldSteps[key])]));
    } else {
      const draftId = `LEGACY-DRAFT-${snapshot.signature}`;
      if (!history.some(entry => entry?.session_id === draftId)) history.push({ ...defaultLearningCockpitState(), session_id:draftId, started_at:snapshot.cockpit?.started_at || new Date().toISOString(), completed_at:null, archived_at:new Date().toISOString(), module_key:legacyModule.key, module_title:legacyModule.title, steps:oldSteps, lesson:ATLAS_GUIDED_LESSONS[legacyModule.key] || ATLAS_GUIDED_LESSONS.market, notes_free:snapshot.note, takeaway:"", legacy_signature:snapshot.signature, legacy_source:"cockpit_28_2_81", legacy_draft:true, migration_build:ATLAS_LEARNING_RECOVERY_BUILD });
    }
    cockpit.completed_sessions = Math.max(snapshot.completed_sessions, history.length);
    cockpit.legacy_signature = snapshot.signature;
    cockpit.legacy_source = "cockpit_28_2_81";
    cockpit.migration_build = ATLAS_LEARNING_RECOVERY_BUILD;
    cockpit.restart_build = ATLAS_LEARNING_RECOVERY_BUILD;
  }
  return { cockpit:atlasLearningNormalizeCockpit(cockpit, history.length), history:history.slice(0,200), roadmap:atlasLearningNormalizeRoadmap(roadmap), progress_records_added:progressRecordsAdded, legacy_module:legacyModule };
}

function learningRecoveryFailureText(result) {
  if (!result) return "Erreur inconnue.";
  if (result.backend === "IndexedDB") return `IndexedDB : ${result.error_name || "erreur"} — ${result.error_message || "écriture impossible"}. Les anciennes données restent intactes.`;
  if (result.quota) return `Stockage local saturé (${result.error_name}). Les anciennes données restent intactes.`;
  return `${result.error_name || "StorageError"} : ${result.error_message || "écriture impossible"}. Les anciennes données restent intactes.`;
}

function saveLearningRecoveryAudit(data) {
  if (!atlasLearningCanMutate()) return { ok:false, blocked:true };
  if (!atlasLearningNotebookCache) atlasLearningNotebookCache = atlasLearningSeedFromLocalStorage();
  const payload = { schema:"agent_crypto_learning_legacy_recovery_audit_v2", build:ATLAS_LEARNING_RECOVERY_BUILD, backend:"IndexedDB", ...data };
  atlasLearningNotebookCache.recovery = payload;
  window.__atlasLearningRecoveryLastResult = payload;
  return { ok:true, backend:"IndexedDB", queued:true };
}

async function applyLegacyLearningRecovery(options = {}) {
  const automatic = options.automatic === true;
  await atlasLearningInitializeCache();
  const snapshot = legacyLearningSnapshot();
  const resetMarker = atlasLearningNotebookCache?.reset || {};
  const resetBlocksLegacy = resetMarker.status === "active"
    && resetMarker.block_legacy_reimport === true
    && resetMarker.legacy_signature === snapshot.signature;
  if (resetBlocksLegacy) {
    const result = {
      status:"skipped_after_user_reset",
      verified:true,
      backend:"IndexedDB",
      reset_at:resetMarker.reset_at || null,
      reset_build:resetMarker.build || ATLAS_LEARNING_FULL_RESET_BUILD,
      legacy_signature:snapshot.signature,
      reason:"Le parcours a été volontairement recommencé depuis le Module 01. L’ancienne récupération ne doit pas recréer les sessions effacées."
    };
    window.__atlasLearningRecoveryLastResult = result;
    renderExpertRoadmap();
    renderLearningJourneyCockpit();
    renderLegacyLearningMigration(true);
    if (!automatic) setActionFeedback("info", "Ancien parcours non réimporté", "Le reset complet est actif. Le Module 01 reste à 0/5 et l’ancienne mémoire ne sera pas restaurée automatiquement.");
    return result;
  }
  if (!snapshot.has_data) {
    saveLearningRecoveryAudit({ status:"no_data", verified:false, checked_at:new Date().toISOString() });
    const persisted = await atlasLearningPersistNow("no_legacy_data");
    renderLegacyLearningMigration();
    return { status:"no_data", verified:false, persisted };
  }

  const existingRecovery = atlasLearningNotebookCache?.recovery || {};
  const existingMigration = atlasLearningNotebookCache?.migration || {};
  if (existingRecovery.verified === true
      && existingRecovery.signature === snapshot.signature
      && existingRecovery.backend === "IndexedDB"
      && existingMigration.status === "imported"
      && existingMigration.signature === snapshot.signature) {
    renderExpertRoadmap();
    renderLearningJourneyCockpit();
    renderLegacyLearningMigration(true);
    if (!automatic) setActionFeedback("ok", "Récupération déjà terminée", "Le carnet IndexedDB est déjà vérifié. Aucun doublon n’a été créé.");
    return atlasLearningClone(existingRecovery);
  }

  const before = legacyLearningTargetAudit(snapshot);
  if (before.verified) {
    saveLearningRecoveryAudit({ status:"verified", verified:true, repaired:false, signature:snapshot.signature, verified_at:new Date().toISOString(), audit:before, source_keys_preserved:true });
    const persisted = await atlasLearningPersistNow("verify_existing_recovery");
    if (!persisted.ok) {
      saveLearningRecoveryAudit({ status:"error", verified:false, signature:snapshot.signature, failed_at:new Date().toISOString(), failed_write:persisted, source_keys_preserved:true });
    }
    renderExpertRoadmap(); renderLearningJourneyCockpit(); renderLegacyLearningMigration(true);
    return atlasLearningClone(atlasLearningNotebookCache.recovery);
  }

  const backup = atlasLearningClone(atlasLearningNotebookCache);
  const plan = legacyLearningRecoveryPlan(snapshot);
  atlasLearningNotebookCache.cockpit = plan.cockpit;
  atlasLearningNotebookCache.history = plan.history;
  atlasLearningNotebookCache.roadmap = plan.roadmap;
  atlasLearningNotebookCache.migration = { schema:"agent_crypto_learning_legacy_migration_indexeddb_v1", status:"pending", signature:snapshot.signature, started_at:new Date().toISOString(), old_keys_preserved:true };
  saveLearningRecoveryAudit({ status:"writing", verified:false, signature:snapshot.signature, started_at:new Date().toISOString(), source_keys_preserved:true });

  const write = await atlasLearningPersistNow("legacy_recovery_indexeddb");
  if (!write.ok) {
    atlasLearningNotebookCache = backup;
    saveLearningRecoveryAudit({ status:"error", verified:false, repaired:false, signature:snapshot.signature, failed_at:new Date().toISOString(), failed_write:write, source_keys_preserved:true });
    atlasLearningStorageLastResult = write;
    renderExpertRoadmap(); renderLearningJourneyCockpit(); renderLegacyLearningMigration(true);
    if (!automatic) setActionFeedback("warn", "Récupération non appliquée", learningRecoveryFailureText(write));
    return atlasLearningClone(atlasLearningNotebookCache.recovery);
  }

  atlasLearningNotebookCache = atlasLearningNormalizeNotebook(write.record);
  const after = legacyLearningTargetAudit(snapshot, atlasLearningNotebookCache);
  const result = {
    status:after.verified ? "verified" : "verification_failed",
    verified:after.verified,
    repaired:true,
    signature:snapshot.signature,
    verified_at:new Date().toISOString(),
    note_characters_recovered:after.notes_recovered,
    completed_sessions_declared:snapshot.completed_sessions,
    progress_records_added:plan.progress_records_added,
    module_recovered:plan.legacy_module.key,
    audit:after,
    recovery_proof:{
      source_signature:snapshot.signature,
      source_note_hash:atlasLegacyLearningHash(snapshot.note),
      source_note_length:snapshot.note_length,
      source_module_key:snapshot.module_key,
      source_checked_steps:ATLAS_LEARNING_SESSION_STEPS.filter(key => snapshot.steps[key]),
      source_progress:snapshot.progressed_modules.map(item => ({ key:item.key, status:item.status }))
    },
    source_keys_preserved:true,
    backend:"IndexedDB"
  };
  const retiredLocalStorage = atlasLearningRetiredLocalStorageSnapshot();
  atlasLearningNotebookCache.recovery = result;
  atlasLearningNotebookCache.migration = {
    schema:"agent_crypto_learning_legacy_migration_indexeddb_v1",
    status:after.verified ? "imported" : "verification_failed",
    signature:snapshot.signature,
    imported_at:new Date().toISOString(),
    verified_by_build:ATLAS_LEARNING_RECOVERY_BUILD,
    old_keys_preserved:true,
    backend:"IndexedDB",
    retired_localstorage_backup:retiredLocalStorage
  };
  const finalWrite = await atlasLearningPersistNow("legacy_recovery_audit");
  if (!finalWrite.ok) {
    atlasLearningNotebookCache.recovery = { status:"error", verified:false, signature:snapshot.signature, failed_at:new Date().toISOString(), failed_write:finalWrite, source_keys_preserved:true, backend:"IndexedDB" };
  } else if (after.verified) {
    const cleanup = atlasLearningReleaseRetiredLocalStorage(retiredLocalStorage);
    atlasLearningNotebookCache.recovery = { ...atlasLearningNotebookCache.recovery, localstorage_cleanup:cleanup };
    atlasLearningNotebookCache.migration = { ...atlasLearningNotebookCache.migration, localstorage_cleanup:cleanup };
    await atlasLearningPersistNow("retired_localstorage_cleanup_audit");
  }
  renderExpertRoadmap(); renderLearningJourneyCockpit(); renderLegacyLearningMigration(true);
  if (!automatic) {
    if (after.verified && finalWrite.ok) setActionFeedback("ok", "Récupération terminée", `${snapshot.note_length} caractères · ${after.checked_steps_recovered}/5 étapes · ${learningModuleByKey(snapshot.module_key || "market").title}.`);
    else setActionFeedback("warn", "Récupération non validée", learningRecoveryFailureText(finalWrite.ok ? { backend:"IndexedDB", error_name:"VerificationError", error_message:"les éléments relus ne correspondent pas" } : finalWrite));
  }
  return atlasLearningClone(atlasLearningNotebookCache.recovery);
}

async function initializeLearningNotebookStorage() {
  await atlasLearningInitializeCache();
  if (atlasLearningStorageReadBlocked) {
    renderExpertRoadmap();
    renderLearningJourneyCockpit();
    renderLegacyLearningMigration(true);
    renderLearningPersistenceNotice(atlasLearningStorageLastResult);
    return { status:"read_blocked", verified:false, error_code:"LEARNING-IDB-READ-BLOCKED", writes_performed:0 };
  }
  const result = await applyLegacyLearningRecovery({ automatic:true });
  await atlasCollectorInitializeStorage();
  reconcileRoadmapFromArchivedLearningHistory();
  await atlasLearningPersistNow("roadmap_practice_reconciliation_28_2_88");
  renderExpertRoadmap();
  renderLearningJourneyCockpit();
  renderLegacyLearningMigration(true);
  await syncArchivedLearningMemoryToCollector({ source:"startup_backfill" });
  return result;
}

function runLegacyLearningRecoveryAtStartup() {
  return initializeLearningNotebookStorage();
}

function importLegacyLearningData() {
  return applyLegacyLearningRecovery({ automatic:false });
}

function ignoreLegacyLearningData() {
  if (!atlasLearningCanMutate()) return;
  if (!atlasLearningNotebookCache) return;
  atlasLearningNotebookCache.recovery = { ...(atlasLearningNotebookCache.recovery || {}), status:"hidden", hidden_at:new Date().toISOString(), source_keys_preserved:true, backend:"IndexedDB" };
  atlasLearningSchedulePersist("hide_recovery_diagnostic");
  const panel = document.getElementById("learningLegacyRecoveryPanel");
  if (panel) panel.hidden = true;
  setActionFeedback("info", "Diagnostic masqué", "Le carnet IndexedDB et les anciennes données restent intacts.");
}

function restoreLegacyLearningRecovery() {
  const snapshot = legacyLearningSnapshot();
  if (!snapshot.has_data) {
    setActionFeedback("info", "Aucune mémoire ancienne", "Aucune donnée 28.2.81/82 n’est présente dans ce Firefox.");
    return;
  }
  renderLegacyLearningMigration(true);
  document.getElementById("learningLegacyRecoveryPanel")?.scrollIntoView({ behavior:"smooth", block:"center" });
}

function renderLegacyLearningMigration(forceOpen = false) {
  const panel = document.getElementById("learningLegacyRecoveryPanel");
  const status = document.getElementById("learningLegacyRecoveryStatus");
  const summary = document.getElementById("learningLegacyRecoverySummary");
  const preview = document.getElementById("learningLegacyRecoveryPreview");
  const resultBox = document.getElementById("learningLegacyRecoveryResult");
  const importButton = document.getElementById("btnImportLegacyLearning");
  const restoreButton = document.getElementById("btnRestoreLegacyLearningRecovery");
  const noticeTitle = document.getElementById("learningMigrationNoticeTitle");
  const noticeText = document.getElementById("learningMigrationNoticeText");
  if (!panel) return;
  const snapshot = legacyLearningSnapshot();
  const resetMarker = atlasLearningNotebookCache?.reset || {};
  const resetBlocksLegacy = resetMarker.status === "active"
    && resetMarker.block_legacy_reimport === true
    && resetMarker.legacy_signature === snapshot.signature;
  if (resetBlocksLegacy) {
    panel.hidden = true;
    if (restoreButton) restoreButton.hidden = true;
    if (noticeTitle) noticeTitle.textContent = "Parcours pédagogique recommencé depuis le Module 01";
    if (noticeText) {
      const resetDate = resetMarker.reset_at ? new Date(resetMarker.reset_at).toLocaleString("fr-FR") : "date non disponible";
      noticeText.textContent = `Reset complet vérifié le ${resetDate}. Le carnet précédent a été sauvegardé avant effacement. Market, Métaux, Bridge, simulateur et collecteurs sont restés intacts.`;
    }
    return;
  }
  const auditMarker = legacyLearningRecoveryAuditMarker();
  const audit = snapshot.has_data ? legacyLearningTargetAudit(snapshot) : { verified:false };
  const verified = snapshot.has_data
    && auditMarker.verified === true
    && auditMarker.signature === snapshot.signature
    && auditMarker.backend === "IndexedDB";
  const displayAudit = verified && auditMarker.audit ? auditMarker.audit : audit;
  const recoveredModule = learningModuleByKey(snapshot.module_key || "market");
  const currentCockpit = loadLearningCockpitState();
  const currentModule = learningModuleByKey(currentCockpit.module_key || "market");
  const currentChecked = ATLAS_LEARNING_SESSION_STEPS.filter(key => currentCockpit.steps?.[key]).length;
  const currentStateLabel = currentCockpit.completed_at ? "session archivée" : `${currentChecked}/5 étapes`;
  const failed = auditMarker.status === "error" || auditMarker.status === "verification_failed";
  const pending = snapshot.has_data && !verified && !failed;
  if (restoreButton) restoreButton.hidden = !snapshot.has_data;
  if (!snapshot.has_data) {
    panel.hidden = true;
    const archivedCount = loadLearningHistory().filter(entry => entry?.completed_at).length;
    if (noticeTitle) noticeTitle.textContent = archivedCount ? "Carnet pédagogique IndexedDB vérifié" : "Carnet pédagogique IndexedDB prêt";
    if (noticeText) noticeText.textContent = archivedCount
      ? `${archivedCount} séance${archivedCount > 1 ? "s" : ""} archivée${archivedCount > 1 ? "s" : ""} et relue${archivedCount > 1 ? "s" : ""} depuis IndexedDB.`
      : "Aucune séance archivée n’a encore été créée. Le carnet utilise IndexedDB.";
    return;
  }
  if (noticeTitle) noticeTitle.textContent = verified ? "Ton ancien parcours est restauré" : failed ? "La récupération a échoué" : "Récupération automatique en cours";
  if (noticeText) noticeText.textContent = verified
    ? `Archive source récupérée : ${recoveredModule.title} · ${snapshot.note_length} caractères · IndexedDB vérifiée.`
    : failed
      ? "Ne clique sur aucune leçon. Les anciennes données restent intactes ; le diagnostic indique l’erreur IndexedDB."
      : "Aucun clic nécessaire. Le carnet est copié dans IndexedDB puis relu pour contrôle.";
  if (status) {
    status.textContent = verified ? "RÉCUPÉRATION TERMINÉE" : failed ? "ÉCHEC INDEXEDDB" : "RÉCUPÉRATION EN COURS";
    status.className = verified ? "pill ok" : "pill warn";
  }
  const checked = ATLAS_LEARNING_SESSION_STEPS.filter(key => snapshot.steps[key]).length;
  if (summary) summary.innerHTML = [
    `<b>${snapshot.completed_sessions} session${snapshot.completed_sessions > 1 ? "s" : ""} retrouvée${snapshot.completed_sessions > 1 ? "s" : ""}</b>`,
    `<span>${snapshot.progressed_modules.length} module${snapshot.progressed_modules.length > 1 ? "s" : ""} avec progression</span>`,
    `<span>${snapshot.note_length} caractère${snapshot.note_length > 1 ? "s" : ""} retrouvé${snapshot.note_length > 1 ? "s" : ""}</span>`,
    `<span>${checked}/5 étapes dans l’ancien brouillon récupéré</span>`
  ].join("");
  if (preview) preview.textContent = legacyLearningMigrationPreview(snapshot);
  if (resultBox) {
    const module = learningModuleByKey(snapshot.module_key || "market");
    const lines = verified ? [
      `<b>Ton parcours est prêt</b>`,
      `<span>Module 01 : ${escapeHtml(ATLAS_EXPERT_STATUS_META[atlasLearningNotebookCache?.roadmap?.modules?.market?.status]?.label || "restauré")}</span>`,
      `<span>Archive source : ${escapeHtml(module.title)}</span>`,
      `<span>Parcours courant : ${escapeHtml(currentModule.title)} · ${escapeHtml(currentStateLabel)}</span>`,
      `<span>Étapes historiques récupérées : ${displayAudit.checked_steps_recovered}/${displayAudit.checked_steps_expected}</span>`,
      `<span>Notes récupérées : ${displayAudit.notes_recovered}/${displayAudit.notes_expected} caractères</span>`,
      `<span>Stockage : IndexedDB vérifiée</span>`,
      `<span>Espace local libéré : ${Math.max(0, Math.round(Number(auditMarker.localstorage_cleanup?.bytes_released || 0) / 1024))} Ko</span>`,
      `<span>Sources 28.2.81/79 : intactes</span>`
    ] : failed ? [
      `<b>La récupération n’a pas été appliquée</b>`,
      `<span>${escapeHtml(learningRecoveryFailureText(auditMarker.failed_write || atlasLearningStorageLastResult))}</span>`,
      `<span>Ne supprime pas les données du site.</span>`
    ] : [
      `<b>Copie et vérification automatiques</b>`,
      `<span>La page écrit le carnet dans IndexedDB puis le relit. Aucun bouton n’est nécessaire.</span>`
    ];
    resultBox.innerHTML = lines.join("");
    resultBox.dataset.state = verified ? "ok" : failed ? "error" : "pending";
  }
  if (importButton) {
    importButton.hidden = verified || pending;
    importButton.disabled = pending;
    importButton.textContent = "Relancer uniquement en cas d’échec";
  }
  panel.hidden = !(forceOpen || verified || failed || auditMarker.status !== "hidden");
}

function toggleLegacyLearningPreview() {
  const preview = document.getElementById("learningLegacyRecoveryPreview");
  if (!preview) return;
  preview.hidden = !preview.hidden;
  const button = document.getElementById("btnPreviewLegacyLearning");
  if (button) button.textContent = preview.hidden ? "Voir le diagnostic technique" : "Masquer le diagnostic technique";
}

function learningHelpMode() {
  try {
    const saved = localStorage.getItem(ATLAS_LEARNING_HELP_MODE_KEY);
    return ["off", "short", "detailed"].includes(saved) ? saved : "short";
  } catch { return "short"; }
}

function saveLearningHelpMode(mode) {
  const next = ["off", "short", "detailed"].includes(mode) ? mode : "short";
  try { localStorage.setItem(ATLAS_LEARNING_HELP_MODE_KEY, next); } catch {}
  renderLearningHelpMode();
}

function renderLearningHelpMode() {
  const mode = learningHelpMode();
  if (els.learningHelpMode) els.learningHelpMode.value = mode;
  if (els.learningHelpModeHint) {
    els.learningHelpModeHint.textContent = mode === "off"
      ? "Les boutons ⓘ restent visibles mais n’ouvrent aucune aide."
      : mode === "short"
        ? "Définition et valeur actuelle, sans panneau long."
        : "Définition, état actuel et règle de prudence complète.";
  }
  document.documentElement.dataset.learningHelpMode = mode;
  if (mode === "off") closeAtlasPedagogy();
}

function defaultLearningCockpitState() {
  return {
    schema:"agent_crypto_learning_journey_cockpit_v2",
    session_id:`LEARN-${Date.now().toString(36).toUpperCase()}`,
    started_at:new Date().toISOString(),
    completed_at:null,
    completed_sessions:Array.isArray(atlasLearningNotebookCache?.history) ? atlasLearningNotebookCache.history.length : 0,
    module_key:null,
    steps:{ read:false, open:false, practice:false, verify:false, note:false },
    lesson_read_at:null,
    notes_free:"",
    takeaway:"",
    practice_proof_id:null,
    practice_completed_at:null,
    verify_completed_at:null,
    practice_evidence:{},
    last_target:null,
    last_action:"read",
    flow_build:ATLAS_LEARNING_FLOW_BUILD,
    restart_build:ATLAS_LEARNING_FLOW_BUILD
  };
}

function loadLearningHistory() {
  if (Array.isArray(atlasLearningNotebookCache?.history)) return atlasLearningClone(atlasLearningNotebookCache.history);
  try {
    const parsed = JSON.parse(localStorage.getItem(ATLAS_LEARNING_HISTORY_KEY) || "[]");
    return Array.isArray(parsed) ? parsed : [];
  } catch { return []; }
}

function saveLearningHistory(history) {
  if (!atlasLearningCanMutate()) return { ok:false, blocked:true };
  if (!atlasLearningNotebookCache) atlasLearningNotebookCache = atlasLearningSeedFromLocalStorage();
  atlasLearningNotebookCache.history = Array.isArray(history) ? atlasLearningClone(history.slice(0,200)) : [];
  if (atlasLearningNotebookCache.cockpit) atlasLearningNotebookCache.cockpit.completed_sessions = atlasLearningNotebookCache.history.length;
  atlasLearningSchedulePersist("learning_history");
}

function loadLearningCockpitState() {
  const historyLength = loadLearningHistory().length;
  const data = atlasLearningNotebookCache?.cockpit || atlasLearningStorageJson(ATLAS_LEARNING_COCKPIT_KEY, null);
  return atlasLearningNormalizeCockpit(data, historyLength);
}

function saveLearningCockpitState(data) {
  if (!atlasLearningCanMutate()) return { ok:false, blocked:true };
  if (!atlasLearningNotebookCache) atlasLearningNotebookCache = atlasLearningSeedFromLocalStorage();
  const validated = foundationApplyConclusionValidation(data);
  atlasLearningNotebookCache.cockpit = atlasLearningNormalizeCockpit(validated, loadLearningHistory().length);
  atlasLearningSchedulePersist("learning_cockpit");
}

function learningTextCount(value) { return Array.from(String(value || "")).length; }

function renderLearningTextCounters(cockpit) {
  const visibleNotes = foundationIsActive(cockpit.module_key) ? foundationNotebookParts(cockpit).personal_notes : cockpit.notes_free;
  if (els.learningNotesCounter) els.learningNotesCounter.textContent = `${learningTextCount(visibleNotes)} caractère${learningTextCount(visibleNotes) > 1 ? "s" : ""} · sauvegarde IndexedDB complète`;
  if (els.learningTakeawayCounter) {
    els.learningTakeawayCounter.textContent = foundationIsActive(cockpit.module_key)
      ? foundationConclusionGuidance(cockpit)
      : `${learningTextCount(cockpit.takeaway)} caractère${learningTextCount(cockpit.takeaway) > 1 ? "s" : ""} · sauvegarde IndexedDB complète`;
  }
}

function currentLearningInterfaceFacts(moduleKey) {
  if (!state.sim) loadSimulation();
  const totals = getSimulationTotals();
  const costs = readSimCostInputs();
  const btc = state.coins?.find?.(coin => coin.id === "bitcoin");
  const latest = latestLearningProof();
  const map = {
    market:[
      btc && Number.isFinite(Number(btc.price)) ? `BTC : ${fmtEUR.format(Number(btc.price))} · 24 h ${atlasSignedPct(btc.change24h)} · 7 j ${atlasSignedPct(btc.change7d)}` : "BTC : donnée momentanément indisponible.",
      `Source principale affichée : ${state.mainSource || "non disponible"}.`,
      `Actifs actuellement chargés : ${state.coins?.length || 0}.`
    ],
    spot:[
      `Profil actif : ${SIM_PROFILE.label} · ticket conseillé ${fmtEUR.format(SIM_PROFILE.defaultAmount)}.`,
      `Argent disponible : ${fmtEUR.format(state.sim.cash)} · montant placé : ${fmtEUR.format(totals.positionsValue)}.`,
      latest ? `Dernière preuve : ${proofTypeLabel(latest.type)} ${latest.symbol || "—"} ${Number.isFinite(Number(latest.amount_eur)) ? fmtEUR.format(Number(latest.amount_eur)) : ""}.` : "Aucune preuve de simulation pour cette nouvelle session."
    ],
    risk:[
      `Exposition : ${fmtEUR.format(totals.positionsValue)} sur ${fmtEUR.format(SIM_PROFILE.maxExposure)}.`,
      `Hypothèse de coût aller-retour : ${getSimRoundTripCostPct(costs).toFixed(2)} %.`,
      `Gain ou perte avant frais : ${atlasSignedEUR(totals.pnl)}.`
    ],
    account:["Simulation locale : aucun compte exchange connecté.","Levier et ordres réels : bloqués.","Le Security Gate distingue les données conformes, manquantes et bloquantes."],
    wallet:[`Actif de démonstration : ${String(els.withdrawAsset?.value || "BTC").toUpperCase()}.`,`Réseau de démonstration : ${String(els.withdrawNetwork?.value || "Bitcoin")}.`,"Aucune adresse réelle n’est demandée dans le laboratoire."],
    tokenomics:["Le parcours expert conserve les notes localement.","Aucune valorisation de jeton n’est transformée en recommandation.","Le prix unitaire doit être comparé à l’offre et à la FDV."],
    defi:["Aucun wallet et aucun smart contract ne sont connectés.","Le laboratoire reste entièrement fictif.","Les autorisations illimitées incomprises doivent être refusées."],
    yield:["Aucun rendement réel n’est activé.","Le Cockpit compare rendement nominal, inflation et risque.","Les récompenses en jetons ne garantissent pas un gain en euros."],
    derivatives:["Profil Spot uniquement.","Levier, marge, futures et short : bloqués.","Exposition maximale du profil : " + fmtEUR.format(SIM_PROFILE.maxExposure) + "."],
    scams:["Le Scam Sentinel analyse uniquement les cases cochées.","Il ne certifie aucun site ni aucune personne.","Une alerte rouge impose l’arrêt de la simulation."],
    records:[`Preuves locales conservées : ${transactionProofEntries("all").length}.`,`Sessions pédagogiques archivées : ${loadLearningHistory().length}.`,"Les exports restent locaux et ne publient rien automatiquement."]
  };
  return map[moduleKey] || map.market;
}

function foundationPathForModule(moduleKey) { return ATLAS_FOUNDATION_LEARNING_PATHS[moduleKey] || null; }

function foundationIsActive(moduleKey) { return ATLAS_FOUNDATION_MODULE_KEYS.includes(moduleKey); }

function foundationStepStatus(cockpit, key) { return cockpit.steps?.[key] === true ? "Preuve enregistrée" : "À faire"; }

function foundationStepsBeforeConclusionComplete(cockpit) {
  return ["read", "open", "practice", "verify"].every(key => cockpit?.steps?.[key] === true);
}

function foundationGuidedEvidenceKey(moduleKey) {
  const map = { market:"market_guided_conclusion", spot:"spot_guided_conclusion", risk:"risk_guided_conclusion", account:"account_guided_conclusion", wallet:"wallet_guided_conclusion", tokenomics:"tokenomics_guided_conclusion", defi:"defi_guided_conclusion", yield:"yield_guided_conclusion", derivatives:"derivatives_guided_conclusion", scams:"scams_guided_conclusion", records:"records_guided_conclusion" };
  return map[moduleKey] || null;
}

function foundationGuidedConclusionReady(cockpit) {
  const key = foundationGuidedEvidenceKey(cockpit?.module_key);
  return Boolean(key && foundationStepsBeforeConclusionComplete(cockpit) && cockpit?.practice_evidence?.[key] === true);
}

function foundationConclusionReady(cockpit) {
  return foundationIsActive(cockpit?.module_key) && foundationGuidedConclusionReady(cockpit);
}

function foundationApplyConclusionValidation(cockpit) {
  if (!cockpit || !foundationIsActive(cockpit.module_key) || cockpit.completed_at) return cockpit;
  cockpit.practice_evidence = cockpit.practice_evidence && typeof cockpit.practice_evidence === "object" ? cockpit.practice_evidence : {};
  const ready = foundationGuidedConclusionReady(cockpit);
  cockpit.practice_evidence.foundation_conclusion_ready = ready;
  cockpit.practice_evidence.foundation_conclusion_mode = `guided_${cockpit.module_key}_answer`;
  cockpit.practice_evidence.foundation_validation_build = ATLAS_FOUNDATION_VALIDATION_BUILD;
  cockpit.steps.note = ready;
  return cockpit;
}

function foundationConclusionGuidance(cockpit) {
  if (!foundationStepsBeforeConclusionComplete(cockpit)) return "Étape 5 disponible après les étapes 1 à 4";
  if (foundationGuidedConclusionReady(cockpit)) return "Synthèse guidée comprise · réponse pédagogique enregistrée";
  const map = {
    market:"Lis la synthèse guidée puis réponds à la question de prédiction",
    spot:"Lis la synthèse d’exécution puis réponds à la question sur l’ordre limite",
    risk:"Lis la comparaison brut / net puis réponds à la question sur les frais",
    account:"Lis le plan de sécurité puis réponds à la question sur les secrets et l’accès distant",
    wallet:"Lis le trajet de retrait puis réponds à la question sur la compatibilité du réseau",
    tokenomics:"Lis la synthèse de valorisation puis réponds à la question sur le prix unitaire",
    defi:"Lis la synthèse d’interaction puis réponds à la question sur la signature",
    yield:"Lis la synthèse de rendement puis réponds à la question sur le gain en euros",
    derivatives:"Lis la synthèse de levier puis réponds à la question sur la perte sur marge",
    scams:"Lis le protocole anti-arnaque puis réponds à la question sur les listes noires",
    records:"Lis la synthèse de traçabilité puis réponds à la question sur la déclaration"
  };
  return map[cockpit?.module_key] || "Réponse guidée requise";
}

function foundationButton(label, action, disabled = false) {
  return `<button class="btn small ${disabled ? "" : "primary"}" type="button" data-foundation-action="${escapeHtml(action)}" ${disabled ? "disabled" : ""}>${escapeHtml(label)}</button>`;
}

function foundationHelpBubble(text, label = "Aide contextuelle") {
  return `<span class="learning-help-bubble" tabindex="0" role="note" aria-label="${escapeHtml(label)}" data-learning-help="${escapeHtml(text)}">ⓘ</span>`;
}

function foundationMarketGuidedSummary(cockpitInput = null) {
  const cockpit = cockpitInput || loadLearningCockpitState();
  const evidence = cockpit?.practice_evidence && typeof cockpit.practice_evidence === "object" ? cockpit.practice_evidence : {};
  const readProof = evidence.market_btc_read && typeof evidence.market_btc_read === "object" ? evidence.market_btc_read : null;
  const provenanceProof = evidence.market_source_time && typeof evidence.market_source_time === "object" ? evidence.market_source_time : null;
  const btc = state.coins?.find?.(coin => coin.id === "bitcoin");
  const liveSource = String(state.mainSource || els.sourceName?.textContent || "non disponible").trim();
  const liveTime = String(els.sourceTime?.textContent || "—").trim();
  const liveReady = Boolean(state.liveOk && btc && liveSource && liveTime && liveTime !== "—");
  const price = String(readProof?.price || (liveReady ? fmtEUR.format(Number(btc.price)) : "—"));
  const change24 = String(readProof?.change_24h || (liveReady ? atlasSignedPct(btc.change24h) : "—"));
  const change7 = String(readProof?.change_7d || (liveReady ? atlasSignedPct(btc.change7d) : "—"));
  const source = String(provenanceProof?.source || liveSource || "non disponible").trim();
  const time = String(provenanceProof?.time || liveTime || "—").trim();
  const valuesFrozen = Boolean(readProof);
  const provenanceFrozen = Boolean(provenanceProof);
  const valuesReady = valuesFrozen || Boolean(liveReady && price !== "—" && change24 !== "—" && change7 !== "—");
  const provenanceReady = provenanceFrozen || Boolean(liveReady && source && source !== "non disponible" && time && time !== "—");
  const ready = Boolean(valuesReady && provenanceReady);
  const observationText = ready
    ? `Preuves observées : Bitcoin ${price} · 24 h ${change24} · 7 j ${change7}. Source « ${source} » · heure ${time}. Ces valeurs sont figées pour cette session même si le marché live évolue ensuite.`
    : "Les preuves observées apparaîtront après Livecheck, sans valeur inventée.";
  const explanationText = ready
    ? "Ces données décrivent un état observé à un instant donné. Elles peuvent aider à comparer des horizons et à vérifier une source, mais elles ne permettent pas de prédire avec certitude le prochain mouvement de Bitcoin. Le prix spot Binance de la fiche active reste une donnée distincte du Market Snapshot pédagogique."
    : "L’explication sera disponible après la collecte des preuves.";
  const text = ready ? `${observationText} ${explanationText}` : "La synthèse sera construite uniquement après Livecheck, sans inventer de valeur.";
  return { ready, btc, source, time, price, change24, change7, observationText, explanationText, text, valuesFrozen, provenanceFrozen };
}

