const SIM_PROFILES = Object.freeze({
  solo_progression_1000_v1: Object.freeze({ key: "solo_progression_1000_v1", label: "Solo Progression 1 000 €", startCash: 1000, allowedSymbols: ["BTC", "ETH", "SOL"], defaultAmount: 50, maxPerOperation: 100, maxExposure: 300, minReserve: 700 }),
  solo_beginner_100_v1_1_alpha_13: Object.freeze({ key: "solo_beginner_100_v1_1_alpha_13", label: "Solo Débutant 100 €", startCash: 100, allowedSymbols: ["BTC", "ETH", "SOL"], defaultAmount: 5, maxPerOperation: 10, maxExposure: 30, minReserve: 70 })
});

const SIM_DEFAULT_PROFILE_KEY = "solo_progression_1000_v1";

const SIM_ACTIVE_PROFILE_STORAGE_KEY = "agent_crypto_erith_ia_active_sim_profile_28_2_80";

const SIM_LEGACY_STORAGE_KEY = "agent_crypto_erith_ia_sim_v1_1_alpha_13";

const SIM_STORAGE_PREFIX = "agent_crypto_erith_ia_sim_profile_28_2_80_";

function getStoredSimulationProfileKey() {
  try {
    const key = localStorage.getItem(SIM_ACTIVE_PROFILE_STORAGE_KEY);
    if (key && SIM_PROFILES[key]) return key;
  } catch {}
  return SIM_DEFAULT_PROFILE_KEY;
}

let SIM_PROFILE = SIM_PROFILES[getStoredSimulationProfileKey()] || SIM_PROFILES[SIM_DEFAULT_PROFILE_KEY];

function simulationStorageKey(profile = SIM_PROFILE) { return `${SIM_STORAGE_PREFIX}${profile.key}`; }

const SIM_COST_STORAGE_KEY = "agent_crypto_erith_ia_sim_costs_28_2_80";

const SIM_COST_STORAGE_KEY_PREVIOUS = "agent_crypto_erith_ia_sim_costs_28_2_79";

const SIM_COST_DEFAULTS = { buyFeePct: 0, sellFeePct: 0, entryImpactPct: 0, exitImpactPct: 0, confirmed: false, source: "manual" };

let atlasSimulationScenarioPct = 0;

function loadSimCostAssumptions() {
  let costs = { ...SIM_COST_DEFAULTS };
  try {
    const parsed = JSON.parse(localStorage.getItem(SIM_COST_STORAGE_KEY) || localStorage.getItem(SIM_COST_STORAGE_KEY_PREVIOUS) || "null");
    if (parsed && typeof parsed === "object") costs = { ...costs, ...parsed };
  } catch {}
  costs.buyFeePct = atlasClampPercent(costs.buyFeePct);
  costs.sellFeePct = atlasClampPercent(costs.sellFeePct);
  costs.entryImpactPct = atlasClampPercent(costs.entryImpactPct);
  costs.exitImpactPct = atlasClampPercent(costs.exitImpactPct);
  costs.confirmed = costs.confirmed === true;
  return costs;
}

function readSimCostInputs() {
  const costs = loadSimCostAssumptions();
  return {
    buyFeePct: atlasClampPercent(els.simBuyFeePct?.value ?? costs.buyFeePct),
    sellFeePct: atlasClampPercent(els.simSellFeePct?.value ?? costs.sellFeePct),
    entryImpactPct: atlasClampPercent(els.simEntryImpactPct?.value ?? costs.entryImpactPct),
    exitImpactPct: atlasClampPercent(els.simExitImpactPct?.value ?? costs.exitImpactPct),
    confirmed: els.simCostsConfirmed ? els.simCostsConfirmed.checked : costs.confirmed,
    source: costs.source || "manual"
  };
}

function saveSimCostAssumptions(source = "manual") {
  const costs = { ...readSimCostInputs(), source };
  try { localStorage.setItem(SIM_COST_STORAGE_KEY, JSON.stringify(costs)); } catch {}
  renderSimulationEducation();
  return costs;
}

function hydrateSimCostInputs() {
  const costs = loadSimCostAssumptions();
  if (els.simBuyFeePct) els.simBuyFeePct.value = String(costs.buyFeePct);
  if (els.simSellFeePct) els.simSellFeePct.value = String(costs.sellFeePct);
  if (els.simEntryImpactPct) els.simEntryImpactPct.value = String(costs.entryImpactPct);
  if (els.simExitImpactPct) els.simExitImpactPct.value = String(costs.exitImpactPct);
  if (els.simCostsConfirmed) els.simCostsConfirmed.checked = costs.confirmed;
}

function getSimRoundTripCostPct(costs = readSimCostInputs()) {
  return costs.buyFeePct + costs.sellFeePct + costs.entryImpactPct + costs.exitImpactPct;
}

function migrateSimulationState(sim) {
  const next = sim && typeof sim === "object" ? sim : {};
  next.cash = atlasFiniteNumber(next.cash, SIM_PROFILE.startCash);
  next.initialCash = atlasFiniteNumber(next.initialCash, SIM_PROFILE.startCash);
  next.profileKey = SIM_PROFILE.key;
  next.positions = next.positions && typeof next.positions === "object" ? next.positions : {};
  next.logs = Array.isArray(next.logs) ? next.logs : [];
  next.nextLogSequence = Math.max(1, Math.trunc(atlasFiniteNumber(next.nextLogSequence, next.logs.length + 1)));
  next.logs = next.logs.map((entry, index) => {
    const safe = entry && typeof entry === "object" ? { ...entry } : { type: "INFO", message: String(entry || "") };
    if (!safe.proof_id) {
      const stamp = String(safe.time || new Date().toISOString()).replace(/[^0-9]/g, "").slice(0, 14) || "legacy";
      safe.proof_id = `SIM-${stamp}-${String(next.logs.length - index).padStart(4, "0")}`;
      safe.proof_schema = ATLAS_PROOF_SCHEMA;
    }
    return safe;
  });
  next.realizedPnl = atlasFiniteNumber(next.realizedPnl, 0);
  Object.keys(next.positions).forEach(symbol => {
    const pos = next.positions[symbol] || {};
    pos.qty = Math.max(0, atlasFiniteNumber(pos.qty, 0));
    pos.invested = Math.max(0, atlasFiniteNumber(pos.invested, 0));
    pos.avgPrice = Math.max(0, atlasFiniteNumber(pos.avgPrice, 0));
    pos.lastPrice = Math.max(0, atlasFiniteNumber(pos.lastPrice, pos.avgPrice));
    pos.buyFeesEur = Math.max(0, atlasFiniteNumber(pos.buyFeesEur, 0));
    pos.entryImpactEur = Math.max(0, atlasFiniteNumber(pos.entryImpactEur, 0));
    next.positions[symbol] = pos;
  });
  return next;
}

function migrateLegacySimulationProfile() {
  const beginner = SIM_PROFILES.solo_beginner_100_v1_1_alpha_13;
  const targetKey = simulationStorageKey(beginner);
  try {
    if (localStorage.getItem(targetKey)) return;
    const raw = localStorage.getItem(SIM_LEGACY_STORAGE_KEY);
    if (!raw) return;
    const parsed = JSON.parse(raw);
    if (parsed && typeof parsed.cash === "number" && parsed.positions) {
      const previousProfile = SIM_PROFILE;
      SIM_PROFILE = beginner;
      const migrated = migrateSimulationState(parsed);
      SIM_PROFILE = previousProfile;
      localStorage.setItem(targetKey, JSON.stringify(migrated));
    }
  } catch {}
}

function loadSimulation() {
  migrateLegacySimulationProfile();
  try {
    const raw = localStorage.getItem(simulationStorageKey());
    if (raw) {
      const parsed = JSON.parse(raw);
      if (parsed && typeof parsed.cash === "number" && parsed.positions && parsed.profileKey === SIM_PROFILE.key) {
        state.sim = migrateSimulationState(parsed);
        return;
      }
    }
  } catch {}
  state.sim = migrateSimulationState({ cash: SIM_PROFILE.startCash, initialCash: SIM_PROFILE.startCash, profileKey: SIM_PROFILE.key, positions: {}, logs: [{ time: new Date().toISOString(), type: "PROFILE", message: `Profil ${SIM_PROFILE.label} chargé.` }] });
}

function saveSimulation() { try { localStorage.setItem(simulationStorageKey(), JSON.stringify(state.sim)); } catch {} }

function resetSimulation(options = {}) {
  state.sim = migrateSimulationState({ cash: SIM_PROFILE.startCash, initialCash: SIM_PROFILE.startCash, profileKey: SIM_PROFILE.key, positions: {}, realizedPnl: 0, logs: [{ time: new Date().toISOString(), type: "RESET", message: `Simulation réinitialisée sur profil ${SIM_PROFILE.label}.` }] });
  saveSimulation();
  if (options.render !== false) renderSimulation();
}

function switchSimulationProfile(profileKey) {
  const nextProfile = SIM_PROFILES[profileKey];
  if (!nextProfile) return;
  if (state.sim) saveSimulation();
  SIM_PROFILE = nextProfile;
  try { localStorage.setItem(SIM_ACTIVE_PROFILE_STORAGE_KEY, SIM_PROFILE.key); } catch {}
  state.sim = null;
  loadSimulation();
  setSimManualFields("BTC", SIM_PROFILE.defaultAmount);
  renderSimulation();
  renderSchoolProfileLabels();
  renderSchoolResult("neutral", `Profil actif : ${SIM_PROFILE.label}`, "Le portefeuille de ce profil est séparé et conservé localement.", [ `Capital virtuel : ${fmtEUR.format(SIM_PROFILE.startCash)}.`, `Ticket conseillé : ${fmtEUR.format(SIM_PROFILE.defaultAmount)}.`, `Exposition maximale : ${fmtEUR.format(SIM_PROFILE.maxExposure)}.` ]);
  setActionFeedback("info", "Profil de simulation changé", `${SIM_PROFILE.label} est actif. L’autre portefeuille local est conservé.`);
}

function atlasCreateProofId(sequence, time = new Date()) {
  const stamp = time.toISOString().replace(/[^0-9]/g, "").slice(0, 14);
  return `SIM-${stamp}-${String(sequence).padStart(4, "0")}`;
}

function simLog(entry) {
  if (!state.sim) loadSimulation();
  const time = new Date();
  const sequence = Math.max(1, Math.trunc(atlasFiniteNumber(state.sim.nextLogSequence, state.sim.logs.length + 1)));
  state.sim.nextLogSequence = sequence + 1;
  state.sim.logs.unshift({ time: time.toISOString(), proof_id: atlasCreateProofId(sequence, time), proof_schema: ATLAS_PROOF_SCHEMA, ...entry });
  state.sim.logs = state.sim.logs.slice(0, 100);
}

function getPositionValue(symbol, scenarioPct = 0) {
  if (!state.sim) loadSimulation();
  const pos = state.sim.positions[symbol];
  if (!pos) return 0;
  return pos.qty * getPositionMarketPrice(symbol, scenarioPct);
}

function estimatePositionExit(symbol, scenarioPct = 0, costs = readSimCostInputs()) {
  if (!state.sim) loadSimulation();
  const pos = state.sim.positions[symbol];
  if (!pos) return null;
  const marketPrice = getPositionMarketPrice(symbol, scenarioPct);
  const exitExecutionPrice = marketPrice * (1 - costs.exitImpactPct / 100);
  const grossExecutionValue = Math.max(0, pos.qty * exitExecutionPrice);
  const sellFeeEur = grossExecutionValue * costs.sellFeePct / 100;
  const netProceedsEur = Math.max(0, grossExecutionValue - sellFeeEur);
  const grossMarketValue = pos.qty * marketPrice;
  const grossPnlEur = grossMarketValue - pos.invested;
  const netPnlEur = netProceedsEur - pos.invested;
  const exitFactor = Math.max(0.000001, (1 - costs.exitImpactPct / 100) * (1 - costs.sellFeePct / 100));
  const breakEvenMarketPrice = pos.qty > 0 ? pos.invested / (pos.qty * exitFactor) : 0;
  return { marketPrice, exitExecutionPrice, grossMarketValue, grossExecutionValue, sellFeeEur, netProceedsEur, grossPnlEur, netPnlEur, breakEvenMarketPrice };
}

function getSimulationTotals(scenarioPct = 0) {
  if (!state.sim) loadSimulation();
  const positionsValue = Object.keys(state.sim.positions).reduce((sum, sym) => sum + getPositionValue(sym, scenarioPct), 0);
  const total = state.sim.cash + positionsValue;
  return { positionsValue, total, pnl: total - state.sim.initialCash };
}

function getSimulationNetTotals(scenarioPct = 0, costs = readSimCostInputs()) {
  if (!state.sim) loadSimulation();
  const exits = Object.keys(state.sim.positions).map(sym => estimatePositionExit(sym, scenarioPct, costs)).filter(Boolean);
  const netPositionsValue = exits.reduce((sum, item) => sum + item.netProceedsEur, 0);
  const total = state.sim.cash + netPositionsValue;
  return { netPositionsValue, total, pnl: total - state.sim.initialCash, exits };
}

function getSimulationProfileStatus() {
  if (!state.sim) loadSimulation();
  const totals = getSimulationTotals();
  const remainingExposure = Math.max(0, SIM_PROFILE.maxExposure - totals.positionsValue);
  return { profile: SIM_PROFILE.label, start_cash_eur: SIM_PROFILE.startCash, allowed_symbols: SIM_PROFILE.allowedSymbols, default_amount_eur: SIM_PROFILE.defaultAmount, max_per_operation_eur: SIM_PROFILE.maxPerOperation, max_exposure_eur: SIM_PROFILE.maxExposure, current_exposure_eur: totals.positionsValue, remaining_exposure_eur: remainingExposure, min_reserve_eur: SIM_PROFILE.minReserve, cash_eur: state.sim.cash };
}

function profileRefusal(message, extra = {}) { return commandError(message, { profile: getSimulationProfileStatus(), ...extra }); }

function simulationRefusal(message, extra = {}, options = {}) {
  if (!state.sim) loadSimulation();
  simLog({ type: "REFUS", message });
  saveSimulation();
  if (options.render !== false) renderSimulation();
  return profileRefusal(message, extra);
}

function simulationPayload() {
  if (!state.sim) loadSimulation();
  const costs = readSimCostInputs();
  const totals = getSimulationTotals();
  const netTotals = getSimulationNetTotals(0, costs);
  const positions = Object.keys(state.sim.positions).map(sym => {
    const pos = state.sim.positions[sym];
    const exit = estimatePositionExit(sym, 0, costs);
    return { symbol: sym, name: pos.name, qty: pos.qty, avg_price_eur: pos.avgPrice, current_price_eur: exit?.marketPrice ?? pos.lastPrice, invested_eur: pos.invested, value_eur: exit?.grossMarketValue ?? 0, pnl_eur: exit?.grossPnlEur ?? 0, estimated_net_exit_eur: exit?.netProceedsEur ?? 0, estimated_net_pnl_eur: exit?.netPnlEur ?? 0, estimated_break_even_price_eur: exit?.breakEvenMarketPrice ?? 0 };
  });
  return { mode: "paper_trading_only", profile: getSimulationProfileStatus(), cost_assumptions: costs, cash_eur: state.sim.cash, initial_cash_eur: state.sim.initialCash, positions_value_eur: totals.positionsValue, total_value_eur: totals.total, pnl_eur: totals.pnl, estimated_net_total_eur: netTotals.total, estimated_net_pnl_eur: netTotals.pnl, realized_pnl_eur: state.sim.realizedPnl || 0, positions, logs: state.sim.logs.slice(0, 10) };
}

function simulateOrder(side, symbolInput = null, amountInput = null, options = {}) {
  const symbol = normalizeSymbol(symbolInput || els.simSymbol?.value || "");
  const amount = Number(amountInput ?? els.simAmount?.value ?? 0);
  if (!symbol) return simulationRefusal("Actif manquant.", {}, options);
  if (!Number.isFinite(amount) || amount <= 0) return simulationRefusal("Montant invalide.", {}, options);
  if (!SIM_PROFILE.allowedSymbols.includes(symbol)) return simulationRefusal(`${SIM_PROFILE.label} : ${symbol} refusé. Autorisés : ${SIM_PROFILE.allowedSymbols.join(" / ")}.`, { requested_symbol: symbol }, options);
  const coin = findCoinByQuery(symbol)
    || Object.values(ATLAS_EXECUTION_ASSET_META).find(meta => meta.symbol === symbol)
    || null;
  if (!coin) return simulationRefusal(`Actif autorisé mais sans route de cotation : ${symbol}.`, { requested_symbol: symbol }, options);
  if (!state.sim) loadSimulation();
  const injectedQuote = atlasExecutionQuoteIsFreshBinance(options.marketQuote) ? options.marketQuote : null;
  const executionQuote = injectedQuote || atlasExchangeQuoteForCoin(coin.id);
  if (!atlasExecutionQuoteIsFreshBinance(executionQuote)) {
    return simulationRefusal(
      "Simulation suspendue : une cotation Binance fraîche est requise. Le snapshot CoinGecko n’est pas utilisé comme prix d’exécution.",
      { requested_symbol:symbol, exchange_feed:state.dataBroker?.exchangeFeed?.status || "indisponible" },
      options
    );
  }
  const marketPrice = Number(executionQuote.price);
  if (!Number.isFinite(marketPrice) || marketPrice <= 0) return simulationRefusal("Cotation Binance invalide pour simulation.", {}, options);
  const sym = coin.symbol.toUpperCase();
  if (amount > SIM_PROFILE.maxPerOperation) return simulationRefusal(`${SIM_PROFILE.label} : maximum par opération = ${fmtEUR.format(SIM_PROFILE.maxPerOperation)}.`, { requested_amount_eur: amount }, options);
  const costs = readSimCostInputs();
  const pos = state.sim.positions[sym] || { symbol: sym, name: coin.name, qty: 0, avgPrice: 0, invested: 0, lastPrice: marketPrice, buyFeesEur: 0, entryImpactEur: 0 };

  if (side === "buy") {
    const totals = getSimulationTotals();
    if (amount > state.sim.cash) return simulationRefusal("Capital virtuel insuffisant.", { cash: state.sim.cash, requested: amount }, options);
    if (state.sim.cash - amount < SIM_PROFILE.minReserve) return simulationRefusal(`${SIM_PROFILE.label} : réserve minimale obligatoire = ${fmtEUR.format(SIM_PROFILE.minReserve)}.`, { cash_after_order_eur: state.sim.cash - amount }, options);
    if (totals.positionsValue + amount > SIM_PROFILE.maxExposure) return simulationRefusal(`${SIM_PROFILE.label} : exposition maximale = ${fmtEUR.format(SIM_PROFILE.maxExposure)}.`, { exposure_after_order_eur: totals.positionsValue + amount }, options);

    const buyFeeEur = amount * costs.buyFeePct / 100;
    const netAssetBudget = Math.max(0, amount - buyFeeEur);
    const executionPrice = marketPrice * (1 + costs.entryImpactPct / 100);
    const qty = executionPrice > 0 ? netAssetBudget / executionPrice : 0;
    if (!(qty > 0)) return simulationRefusal("Les hypothèses de coûts ne laissent aucun montant convertible.", {}, options);
    const entryImpactEur = Math.max(0, qty * executionPrice - qty * marketPrice);
    const oldQty = pos.qty;
    const newQty = oldQty + qty;
    pos.avgPrice = newQty > 0 ? ((oldQty * (pos.avgPrice || marketPrice)) + qty * executionPrice) / newQty : executionPrice;
    pos.qty = newQty;
    pos.invested += amount;
    pos.lastPrice = marketPrice;
    pos.lastPriceSource = String(executionQuote.source || "Binance");
    pos.lastPriceTimestamp = new Date(Number(executionQuote.timestamp) || Date.now()).toISOString();
    pos.buyFeesEur += buyFeeEur;
    pos.entryImpactEur += entryImpactEur;
    state.sim.positions[sym] = pos;
    state.sim.cash -= amount;
    simLog({ type: "SIM_BUY", symbol: sym, amount_eur: amount, market_price_eur: marketPrice, execution_price_eur: executionPrice, market_source:String(executionQuote.source || "Binance"), market_timestamp:new Date(Number(executionQuote.timestamp) || Date.now()).toISOString(), buy_fee_eur: buyFeeEur, entry_impact_eur: entryImpactEur, qty, message: `Achat simulé ${sym} pour ${fmtEUR.format(amount)} · cotation ${String(executionQuote.source || "Binance")} · frais ${fmtEUR.format(buyFeeEur)} · quantité ${qty.toFixed(8)}.` });
  } else if (side === "sell") {
    if (!pos.qty || pos.qty <= 0) return simulationRefusal(`Aucune position virtuelle à vendre pour ${sym}.`, {}, options);
    const maxMarketValue = pos.qty * marketPrice;
    const requestedMarketValue = Math.min(amount, maxMarketValue);
    const qty = Math.min(pos.qty, requestedMarketValue / marketPrice);
    const soldRatio = qty / pos.qty;
    const executionPrice = marketPrice * (1 - costs.exitImpactPct / 100);
    const grossExecutionValue = Math.max(0, qty * executionPrice);
    const sellFeeEur = grossExecutionValue * costs.sellFeePct / 100;
    const netProceedsEur = Math.max(0, grossExecutionValue - sellFeeEur);
    const allocatedCostBasis = pos.invested * soldRatio;
    const realizedPnlEur = netProceedsEur - allocatedCostBasis;
    pos.qty -= qty;
    pos.invested = Math.max(0, pos.invested - allocatedCostBasis);
    pos.lastPrice = marketPrice;
    pos.lastPriceSource = String(executionQuote.source || "Binance");
    pos.lastPriceTimestamp = new Date(Number(executionQuote.timestamp) || Date.now()).toISOString();
    state.sim.cash += netProceedsEur;
    state.sim.realizedPnl = atlasFiniteNumber(state.sim.realizedPnl, 0) + realizedPnlEur;
    if (pos.qty <= 0.00000001) delete state.sim.positions[sym]; else state.sim.positions[sym] = pos;
    simLog({ type: "SIM_SELL", symbol: sym, amount_eur: grossExecutionValue, market_price_eur: marketPrice, execution_price_eur: executionPrice, market_source:String(executionQuote.source || "Binance"), market_timestamp:new Date(Number(executionQuote.timestamp) || Date.now()).toISOString(), sell_fee_eur: sellFeeEur, net_proceeds_eur: netProceedsEur, realized_pnl_eur: realizedPnlEur, qty, message: `Vente simulée ${sym} · cotation ${String(executionQuote.source || "Binance")} · brut ${fmtEUR.format(grossExecutionValue)} · net ${fmtEUR.format(netProceedsEur)} · résultat ${atlasSignedEUR(realizedPnlEur)}.` });
  }
  saveSimulation();
  if (options.render !== false) renderSimulation();
  return commandOk(`sim_${side} ${sym} ${amount}`, { side, symbol: sym, amount_eur: amount, market_price_eur: marketPrice, market_source:String(executionQuote.source || "Binance"), market_timestamp:new Date(Number(executionQuote.timestamp) || Date.now()).toISOString(), costs, portfolio: simulationPayload() });
}

function simLogTypeLabel(type) {
  if (type === "SIM_BUY") return "ACHAT SIMULÉ";
  if (type === "SIM_SELL") return "VENTE SIMULÉE";
  if (type === "REFUS") return "REFUS";
  if (type === "RESET") return "RESET";
  return String(type || "INFO");
}

function simLogLine(entry) {
  const time = entry?.time ? new Date(entry.time).toLocaleTimeString("fr-FR", { hour:"2-digit", minute:"2-digit", second:"2-digit" }) : "";
  const label = simLogTypeLabel(entry?.type);
  const msg = entry?.message || "";
  return time ? `${label} · ${msg} · ${time}` : `${label} · ${msg}`;
}

function renderSimulation() {
  if (!state.sim) loadSimulation();
  const totals = getSimulationTotals();
  if (els.simProfileTitle) els.simProfileTitle.textContent = `Profil actif : ${SIM_PROFILE.label}`;
  if (els.simProfileBadge) els.simProfileBadge.textContent = `Profil ${fmtEUR.format(SIM_PROFILE.startCash)}`;
  if (els.simProfileCapital) els.simProfileCapital.textContent = `${fmtEUR.format(SIM_PROFILE.startCash)} virtuels`;
  if (els.simProfileTicket) els.simProfileTicket.textContent = fmtEUR.format(SIM_PROFILE.defaultAmount);
  if (els.simProfileMaxOperation) els.simProfileMaxOperation.textContent = fmtEUR.format(SIM_PROFILE.maxPerOperation);
  if (els.simProfileMaxExposure) els.simProfileMaxExposure.textContent = fmtEUR.format(SIM_PROFILE.maxExposure);
  if (els.simProfileMinReserve) els.simProfileMinReserve.textContent = fmtEUR.format(SIM_PROFILE.minReserve);
  if (els.simProfileAllowedAssets) els.simProfileAllowedAssets.textContent = SIM_PROFILE.allowedSymbols.join(" · ");
  document.querySelectorAll("[data-sim-profile]").forEach(button => {
    const active = button.dataset.simProfile === SIM_PROFILE.key;
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });
  renderSchoolProfileLabels();
  if (els.simProfileStatus) {
    const profile = getSimulationProfileStatus();
    els.simProfileStatus.textContent = `${profile.allowed_symbols.join(" / ")} · ticket ${fmtEUR.format(profile.default_amount_eur)} · max ${fmtEUR.format(profile.max_per_operation_eur)} · exposé ${fmtEUR.format(profile.current_exposure_eur)} / ${fmtEUR.format(profile.max_exposure_eur)} · réserve min ${fmtEUR.format(profile.min_reserve_eur)}`;
  }
  setText(els.simCash, fmtEUR.format(atlasZeroCurrency(state.sim.cash)));
  setText(els.simPositionsValue, fmtEUR.format(atlasZeroCurrency(totals.positionsValue)));
  setText(els.simTotalValue, fmtEUR.format(atlasZeroCurrency(totals.total)));
  if (els.simPnL) {
    const pnl = atlasZeroCurrency(totals.pnl);
    els.simPnL.textContent = atlasSignedEUR(pnl);
    els.simPnL.classList.toggle("pnl-pos", pnl >= 0);
    els.simPnL.classList.toggle("pnl-neg", pnl < 0);
  }
  const costs = readSimCostInputs();
  const positions = Object.keys(state.sim.positions);
  if (els.simPositions) {
    els.simPositions.innerHTML = positions.length ? positions.map(sym => {
      const pos = state.sim.positions[sym];
      const exit = estimatePositionExit(sym, 0, costs);
      const grossPnl = atlasZeroCurrency(exit?.grossPnlEur || 0);
      const netPnl = atlasZeroCurrency(exit?.netPnlEur || 0);
      return `<div class="sim-position-row"><b>${escapeHtml(sym)}</b><span title="Quantité fictive">${pos.qty.toFixed(8)}</span><span title="Prix moyen d’entrée">${fmtEUR.format(pos.avgPrice || 0)}</span><span title="Prix actuel">${fmtEUR.format(exit?.marketPrice || 0)}</span><span title="Valeur brute">${fmtEUR.format(exit?.grossMarketValue || 0)}</span><span class="${grossPnl >= 0 ? "pnl-pos" : "pnl-neg"}" title="Gain ou perte avant frais (P/L brut)">${atlasSignedEUR(grossPnl)}</span><span class="${netPnl >= 0 ? "pnl-pos" : "pnl-neg"}" title="Gain ou perte après frais (P/L net estimé)">${atlasSignedEUR(netPnl)}</span></div>`;
    }).join("") : "Aucune position simulée.";
  }
  if (els.simLog) els.simLog.textContent = state.sim.logs.length ? state.sim.logs.map(simLogLine).join("\n") : "Aucune simulation lancée.";
  renderSimulationEducation();
  renderTransactionProofLedger();
  renderLearningJourneyCockpit();
}

function renderSimulationScenario() {
  if (!els.simScenarioOutput) return;
  if (!state.sim) loadSimulation();
  const symbols = Object.keys(state.sim.positions);
  if (!symbols.length) {
    els.simScenarioOutput.textContent = "Crée d’abord la position BTC de 50 € dans « Mode École guidé » avec « 1 · Tester une opération prudente ». Les scénarios afficheront ensuite le gain ou la perte avant frais, les coûts et le résultat après frais.";
    return;
  }
  const costs = readSimCostInputs();
  const pct = atlasFiniteNumber(atlasSimulationScenarioPct, 0);
  const totals = getSimulationTotals(pct);
  const netTotals = getSimulationNetTotals(pct, costs);
  const rows = symbols.map(sym => {
    const exit = estimatePositionExit(sym, pct, costs);
    return `${sym} · prix scénario ${fmtEUR.format(exit.marketPrice)} · valeur brute ${fmtEUR.format(exit.grossMarketValue)} · gain/perte avant frais ${atlasSignedEUR(exit.grossPnlEur)} · résultat après frais ${atlasSignedEUR(exit.netPnlEur)}`;
  });
  els.simScenarioOutput.textContent = [`SCÉNARIO ${atlasSignedPct(pct)}`, ...rows, `Portefeuille brut : ${fmtEUR.format(totals.total)}`, `Portefeuille net estimé : ${fmtEUR.format(netTotals.total)}`, `Résultat net estimé : ${atlasSignedEUR(netTotals.pnl)}`, "Aucune position n’a été modifiée."].join("\n");
}

function setSecurityGateItem(key, stateName, text) {
  const item = els.simSecurityGateList?.querySelector(`[data-gate="${key}"]`);
  if (!item) return;
  item.dataset.state = stateName;
  const span = item.querySelector("span");
  if (span) span.textContent = text;
}

function renderSimulationSecurityGate() {
  if (!els.simSecurityGateStatus || !els.simSecurityGateList) return;
  if (!state.sim) loadSimulation();
  const symbol = normalizeSymbol(els.simSymbol?.value || "BTC");
  const amount = atlasFiniteNumber(els.simAmount?.value, 0);
  const totals = getSimulationTotals();
  const costs = readSimCostInputs();
  const checks = {
    mode: { ok: true, text: "Local · aucun ordre réel" },
    source: { ok: atlasAnalysisLiveReady(), text: atlasAnalysisLiveReady() ? "Snapshot public exploitable" : "Livecheck requis" },
    asset: { ok: SIM_PROFILE.allowedSymbols.includes(symbol), text: SIM_PROFILE.allowedSymbols.includes(symbol) ? `${symbol} autorisé` : `${symbol || "Actif"} refusé` },
    amount: { ok: amount > 0 && amount <= SIM_PROFILE.maxPerOperation, text: amount > 0 && amount <= SIM_PROFILE.maxPerOperation ? `${fmtEUR.format(amount)} dans la limite` : `Maximum ${fmtEUR.format(SIM_PROFILE.maxPerOperation)}` },
    exposure: { ok: totals.positionsValue <= SIM_PROFILE.maxExposure + 0.005, text: `${fmtEUR.format(totals.positionsValue)} / ${fmtEUR.format(SIM_PROFILE.maxExposure)}` },
    reserve: { ok: state.sim.cash >= SIM_PROFILE.minReserve - 0.005, text: `${fmtEUR.format(state.sim.cash)} disponibles` },
    costs: { ok: costs.confirmed, warn: !costs.confirmed, text: costs.confirmed ? `${getSimRoundTripCostPct(costs).toFixed(2)} % confirmé` : "Hypothèses non confirmées" },
    leverage: { ok: true, text: "Spot uniquement · levier bloqué" }
  };
  Object.entries(checks).forEach(([key, check]) => setSecurityGateItem(key, check.ok ? "ok" : (check.warn ? "warn" : "blocked"), check.text));
  const blocked = Object.values(checks).filter(item => !item.ok && !item.warn).length;
  const warnings = Object.values(checks).filter(item => item.warn).length;
  if (blocked) {
    els.simSecurityGateStatus.textContent = `ROUGE · ${blocked} blocage${blocked > 1 ? "s" : ""}`;
    els.simSecurityGateStatus.className = "pill danger";
    els.simSecurityGateReading.textContent = "La simulation doit être corrigée avant de lancer le test : actif, montant, source, exposition ou réserve non conforme.";
  } else if (warnings) {
    els.simSecurityGateStatus.textContent = "ORANGE · coûts à vérifier";
    els.simSecurityGateStatus.className = "pill warn";
    els.simSecurityGateReading.textContent = "Les verrous du profil sont conformes, mais les hypothèses de frais et d’écarts ne sont pas encore confirmées.";
  } else {
    els.simSecurityGateStatus.textContent = "VERT · exercice cohérent";
    els.simSecurityGateStatus.className = "pill ok";
    els.simSecurityGateReading.textContent = "Exercice fictif cohérent dans le profil débutant. Ce verdict ne constitue pas une autorisation d’opération réelle.";
  }
}

function renderSimulationEducation() {
  const costs = readSimCostInputs();
  const roundTripPct = getSimRoundTripCostPct(costs);
  const netTotals = getSimulationNetTotals(0, costs);
  const firstSymbol = Object.keys(state.sim?.positions || {})[0] || null;
  const firstExit = firstSymbol ? estimatePositionExit(firstSymbol, 0, costs) : null;
  if (els.simRoundTripCost) els.simRoundTripCost.textContent = `${roundTripPct.toFixed(2)} %`;
  if (els.simBreakEvenPrice) els.simBreakEvenPrice.textContent = firstExit ? `${firstSymbol} · ${fmtEUR.format(firstExit.breakEvenMarketPrice)}` : "Aucune position";
  if (els.simNetPnL) {
    const pnl = atlasZeroCurrency(netTotals.pnl);
    els.simNetPnL.textContent = atlasSignedEUR(pnl);
    els.simNetPnL.classList.toggle("pnl-pos", pnl >= 0);
    els.simNetPnL.classList.toggle("pnl-neg", pnl < 0);
  }
  if (els.simCostStatus) {
    els.simCostStatus.textContent = costs.confirmed ? "Hypothèses confirmées" : "À renseigner";
    els.simCostStatus.className = costs.confirmed ? "pill ok" : "pill warn";
  }
  if (els.simCostTruth) els.simCostTruth.textContent = costs.confirmed ? "Confirmé pour cet exercice" : "Hypothèses non confirmées";
  renderSimulationScenario();
  renderSimulationSecurityGate();
}

function atlasWithdrawalAllowedNetworks(asset) {
  const map = { BTC: ["bitcoin"], ETH: ["ethereum"], SOL: ["solana"], USDC: ["ethereum", "solana", "polygon"] };
  return map[String(asset || "").toUpperCase()] || [];
}

function renderWithdrawalSafety() {
  if (!els.withdrawalSafetyStatus || !els.withdrawalSafetyOutput) return;
  const asset = String(els.withdrawAsset?.value || "BTC").toUpperCase();
  const network = String(els.withdrawNetwork?.value || "").toLowerCase();
  const amount = Math.max(0, atlasFiniteNumber(els.withdrawAmount?.value, 0));
  const fee = Math.max(0, atlasFiniteNumber(els.withdrawFee?.value, 0));
  const destination = els.withdrawDestinationVerified?.checked === true;
  const smallTest = els.withdrawSmallTest?.checked === true;
  const noThirdParty = els.withdrawNoThirdParty?.checked === true;
  const networkOk = atlasWithdrawalAllowedNetworks(asset).includes(network);
  const amountOk = amount > 0 && fee >= 0 && fee < amount;
  const blocked = [networkOk, amountOk, destination, noThirdParty].filter(value => !value).length;
  const net = Math.max(0, amount - fee);
  const lines = [
    `Actif : ${asset}`,
    `Réseau pédagogique : ${network || "—"}`,
    `Montant fictif : ${amount}`,
    `Frais fictifs : ${fee}`,
    `Montant net estimé : ${net}`,
    `Destination vérifiée : ${destination ? "oui" : "non"}`,
    `Petit test prévu : ${smallTest ? "oui" : "non"}`,
    "Aucune adresse, clé ou transaction réelle n’est utilisée."
  ];
  if (blocked) {
    els.withdrawalSafetyStatus.textContent = `ROUGE · ${blocked} blocage${blocked > 1 ? "s" : ""}`;
    els.withdrawalSafetyStatus.className = "pill danger";
    lines.unshift("RETRAIT FICTIF REFUSÉ");
    if (!networkOk) lines.push("Motif : réseau incohérent avec l’actif dans cette démonstration.");
    if (!amountOk) lines.push("Motif : montant nul ou frais supérieurs au montant.");
    if (!destination) lines.push("Motif : destination non vérifiée indépendamment.");
    if (!noThirdParty) lines.push("Motif : un tiers dicte l’adresse ou le trajet.");
  } else if (!smallTest) {
    els.withdrawalSafetyStatus.textContent = "ORANGE · petit test requis";
    els.withdrawalSafetyStatus.className = "pill warn";
    lines.unshift("TRAJET COHÉRENT MAIS INCOMPLET");
    lines.push("Prévoir un petit transfert test avant tout montant plus important.");
  } else {
    els.withdrawalSafetyStatus.textContent = "VERT · test fictif cohérent";
    els.withdrawalSafetyStatus.className = "pill ok";
    lines.unshift("RETRAIT TEST FICTIF COHÉRENT");
    lines.push("Ce verdict n’autorise aucun retrait réel et ne certifie pas le support d’un réseau par Kraken.");
  }
  els.withdrawalSafetyOutput.textContent = lines.join("\n");
}

function analyzeScamSignals() {
  if (!els.scamSentinelChecks || !els.scamSentinelStatus || !els.scamSentinelOutput) return;
  const labels = {
    guaranteed_return: "rendement garanti",
    urgency: "urgence artificielle",
    fake_support: "support demandant un secret",
    unlock_payment: "paiement exigé pour retirer",
    remote_access: "accès distant demandé",
    forced_address: "adresse imposée par un tiers",
    unlimited_approval: "autorisation illimitée incomprise",
    send_to_receive: "envoi préalable pour recevoir davantage"
  };
  const checked = [...els.scamSentinelChecks.querySelectorAll('input:checked')].map(input => input.value);
  if (!checked.length) {
    els.scamSentinelStatus.textContent = "VERT · aucun signal déclaré";
    els.scamSentinelStatus.className = "pill ok";
    els.scamSentinelOutput.textContent = "Aucun signal coché. Cela ne certifie pas la légitimité d’une sollicitation : vérifie toujours le domaine, le prestataire et le canal officiel.";
    return;
  }
  els.scamSentinelStatus.textContent = `ROUGE · ${checked.length} signal${checked.length > 1 ? "aux" : ""}`;
  els.scamSentinelStatus.className = "pill danger";
  els.scamSentinelOutput.textContent = [
    "RISQUE CRITIQUE — ARRÊT",
    ...checked.map(key => `• ${labels[key] || key}`),
    "",
    "Ne rien envoyer, ne rien signer, ne transmettre aucun code et ne pas installer d’accès distant.",
    "Revenir au site ou au support officiel par un canal ouvert manuellement."
  ].join("\n");
}

function transactionProofEntries(filter = "all") {
  if (!state.sim) loadSimulation();
  const allowed = new Set(["SIM_BUY", "SIM_SELL", "REFUS"]);
  return (state.sim.logs || []).filter(entry => allowed.has(entry.type) && (filter === "all" || entry.type === filter));
}

function proofTypeLabel(type) {
  return type === "SIM_BUY" ? "Achat" : type === "SIM_SELL" ? "Vente" : type === "REFUS" ? "Refus" : String(type || "Info");
}

function proofResult(entry) {
  if (entry.type === "SIM_SELL" && Number.isFinite(Number(entry.realized_pnl_eur))) return atlasSignedEUR(Number(entry.realized_pnl_eur));
  if (entry.type === "REFUS") return "Bloqué";
  if (Number.isFinite(Number(entry.qty))) return `${Number(entry.qty).toFixed(8)} unité(s)`;
  return "Enregistré";
}

function renderTransactionProofLedger() {
  if (!els.transactionProofRows) return;
  if (!state.sim) loadSimulation();
  const all = transactionProofEntries("all");
  const filter = els.transactionProofFilter?.value || "all";
  const rows = transactionProofEntries(filter);
  const buys = all.filter(e => e.type === "SIM_BUY").length;
  const sells = all.filter(e => e.type === "SIM_SELL").length;
  const refusals = all.filter(e => e.type === "REFUS").length;
  if (els.proofBuyCount) els.proofBuyCount.textContent = String(buys);
  if (els.proofSellCount) els.proofSellCount.textContent = String(sells);
  if (els.proofRefusalCount) els.proofRefusalCount.textContent = String(refusals);
  if (els.proofRealizedPnl) els.proofRealizedPnl.textContent = atlasSignedEUR(state.sim.realizedPnl || 0);
  if (els.transactionProofStatus) els.transactionProofStatus.textContent = `${all.length} preuve${all.length > 1 ? "s" : ""}`;
  els.transactionProofRows.innerHTML = rows.length ? rows.map(entry => {
    const time = entry.time ? new Date(entry.time).toLocaleString("fr-FR") : "—";
    const amount = Number.isFinite(Number(entry.amount_eur)) ? fmtEUR.format(Number(entry.amount_eur)) : "—";
    return `<tr><td><code>${escapeHtml(entry.proof_id || "legacy")}</code></td><td>${escapeHtml(time)}</td><td>${escapeHtml(proofTypeLabel(entry.type))}</td><td>${escapeHtml(entry.symbol || "—")}</td><td>${escapeHtml(amount)}</td><td>${escapeHtml(proofPriceAndCosts(entry))}</td><td>${escapeHtml(proofResult(entry))}</td></tr>`;
  }).join("") : '<tr><td colspan="7">Aucune preuve correspondant au filtre.</td></tr>';
}

function transactionProofPayload() {
  if (!state.sim) loadSimulation();
  return { schema:ATLAS_PROOF_SCHEMA, generated_at:new Date().toISOString(), build:ATLAS_BUILD, mode:"simulation_local_only", real_execution:false, entries:transactionProofEntries("all") };
}

function buildTransactionProofMarkdown() {
  const data = transactionProofPayload();
  const lines = ["# TRANSACTION PROOF LEDGER — Agent-Crypto", "", `Build : ${ATLAS_BUILD}`, `Export : ${data.generated_at}`, "", "Simulation locale uniquement — aucun ordre réel.", ""];
  if (!data.entries.length) lines.push("Aucune preuve de simulation.");
  data.entries.forEach(entry => lines.push(`## ${entry.proof_id || "legacy"}`, "", `- Heure : ${entry.time || "—"}`, `- Type : ${proofTypeLabel(entry.type)}`, `- Actif : ${entry.symbol || "—"}`, `- Montant : ${Number.isFinite(Number(entry.amount_eur)) ? fmtEUR.format(Number(entry.amount_eur)) : "—"}`, `- Prix et coûts : ${proofPriceAndCosts(entry)}`, `- Résultat : ${proofResult(entry)}`, `- Message : ${entry.message || "—"}`, ""));
  return lines.join("\n");
}

function exportTransactionProofMarkdown() {
  const stamp = new Date().toISOString().slice(0,10);
  downloadTextFile(`agent_crypto_transaction_proofs_${stamp}.md`, "text/markdown", buildTransactionProofMarkdown());
}

function exportTransactionProofJSON() {
  const stamp = new Date().toISOString().slice(0,10);
  downloadTextFile(`agent_crypto_transaction_proofs_${stamp}.json`, "application/json", JSON.stringify(transactionProofPayload(), null, 2));
}

function simulationDataSnapshot() { if (!state.sim) loadSimulation(); const totals = getSimulationTotals(); return { generated_at: new Date().toISOString(), version: ATLAS_RELEASE, public_only: true, warning: "Données publiques et simulation locale uniquement. Aucun compte réel, aucune clé API, aucun wallet.", profile: getSimulationProfileStatus(), simulation: simulationPayload(), totals: { cash_eur: state.sim.cash, positions_value_eur: totals.positionsValue, total_value_eur: totals.total, pnl_eur: totals.pnl }, market_snapshot: publicMarketSnapshot() };
}

function positionLinesForMarkdown() { if (!state.sim) loadSimulation(); const positions = Object.keys(state.sim.positions || {}); if (!positions.length) return ["Aucune position simulée."]; return positions.map(sym => { const pos = state.sim.positions[sym]; const value = getPositionValue(sym); return `- ${sym} : ${fmtEUR.format(value)} simulés, quantité fictive ${Number(pos.qty || 0).toFixed(8)}.`; });
}

function downloadSimulationJSON() { const stamp = new Date().toISOString().slice(0, 10); const data = simulationDataSnapshot(); downloadTextFile(`agent_crypto_data_snapshot_${stamp}.json`, "application/json", JSON.stringify(data, null, 2)); if (els.simLearningOutput) { els.simLearningOutput.textContent = [ "DATA SNAPSHOT JSON PRÊT", "", "Contenu :", `- profil actif : ${SIM_PROFILE.label} ;`, "- simulation locale ;", "- positions fictives ;", "- logs de simulation ;", "- snapshot public BTC / ETH / SOL si Livecheck est actif.", "", "Sécurité :", "- aucune clé API ;", "- aucun wallet ;", "- aucun compte réel ;", "- aucune donnée personnelle." ].join("\n"); }
}

function countRefusalTypes(records) { const counts = { montant_trop_gros: 0, crypto_non_autorisee: 0, plafond_ou_reserve: 0, livecheck_requis: 0, autres_refus: 0 }; records.forEach(record => { const logs = record?.snapshot?.simulation?.logs || []; logs.forEach(log => { const msg = String(log.message || ""); if (log.type !== "REFUS") return; if (msg.includes("maximum par opération")) counts.montant_trop_gros += 1; else if (msg.includes("refusé. Autorisés")) counts.crypto_non_autorisee += 1; else if (msg.includes("réserve minimale")) counts.plafond_ou_reserve += 1; else if (msg.includes("Livecheck requis")) counts.livecheck_requis += 1; else counts.autres_refus += 1; }); }); return counts;
}

function refusalSummaryText(records = readCollectorMemory()) {
  const counts = countRefusalTypes(records);
  const total = Object.values(counts).reduce((sum, n) => sum + n, 0);
  const lines = [
    "RÉSUMÉ DES REFUS DE SÉCURITÉ",
    "",
    `Total refus observés : ${total}`,
    "",
    `- Montant trop gros : ${counts.montant_trop_gros}`,
    `- Crypto non autorisée : ${counts.crypto_non_autorisee}`,
    `- Plafond / réserve : ${counts.plafond_ou_reserve}`,
    `- Livecheck requis : ${counts.livecheck_requis}`,
    `- Autres refus : ${counts.autres_refus}`,
    "",
    "Interprétation :"
  ];
  if (total === 0) {
    lines.push("Aucun refus de sécurité n’est actuellement mémorisé. Rien n’est requis pour poursuivre les modules.");
  } else {
    if (counts.montant_trop_gros) lines.push(`- Le profil a refusé au moins une opération dépassant son maximum de ${fmtEUR.format(SIM_PROFILE.maxPerOperation)}.`);
    if (counts.crypto_non_autorisee) lines.push(`- Le périmètre d’actifs autorisés reste ${SIM_PROFILE.allowedSymbols.join(" / ")}.`);
    if (counts.plafond_ou_reserve) lines.push(`- La réserve minimale du profil reste ${fmtEUR.format(SIM_PROFILE.minReserve)}.`);
    if (counts.livecheck_requis) lines.push("- Au moins une opération a été bloquée faute de cotation exploitable.");
  }
  lines.push("", "Conclusion : un refus mémorisé est une trace de protection, pas une transaction réelle.");
  return lines.join("\n");
}

function summarizeRefusals() { renderMemoryExplorer(refusalSummaryText()); setActionFeedback("info", "Refus résumés", "Les refus de sécurité sont comptés et expliqués.", els.memoryExplorerOutput);
}

function setSimManualFields(symbol, amount) { if (els.simSymbol) els.simSymbol.value = symbol; if (els.simAmount) els.simAmount.value = String(amount);
}

function renderSchoolProfileLabels() {
  const unit = SIM_PROFILE.maxExposure / 3;
  if (els.schoolSafeLabel) els.schoolSafeLabel.textContent = `BTC ${fmtEUR.format(SIM_PROFILE.defaultAmount)} · doit être accepté`;
  if (els.schoolTooBigLabel) els.schoolTooBigLabel.textContent = `BTC ${fmtEUR.format(SIM_PROFILE.maxPerOperation * 5)} · doit être refusé`;
  if (els.schoolForbiddenLabel) els.schoolForbiddenLabel.textContent = `DOGE ${fmtEUR.format(SIM_PROFILE.defaultAmount)} · doit être refusé`;
  if (els.schoolFillLabel) els.schoolFillLabel.textContent = `BTC ${fmtEUR.format(unit)} + ETH ${fmtEUR.format(unit)} + SOL ${fmtEUR.format(unit)}`;
  if (els.schoolExceedLabel) els.schoolExceedLabel.textContent = `Après ${fmtEUR.format(SIM_PROFILE.maxExposure)} exposés, BTC ${fmtEUR.format(SIM_PROFILE.defaultAmount)} doit être refusé`;
  if (els.schoolResetTitle) els.schoolResetTitle.textContent = `Remettre le profil actif à ${fmtEUR.format(SIM_PROFILE.startCash)}`;
  if (els.schoolResetLabel) els.schoolResetLabel.textContent = `Réinitialiser uniquement ${SIM_PROFILE.label}`;
}

function renderSchoolResult(kind, title, text, bullets = []) { const el = els.schoolResult || document.getElementById("schoolResult"); if (!el) return; el.classList.remove("ok", "refusal", "err", "neutral"); el.classList.add(kind || "neutral"); const items = bullets.map(item => `<li>${escapeHtml(item)}</li>`).join(""); el.innerHTML = ` <b>${escapeHtml(title)}</b> <p>${escapeHtml(text)}</p> <ul>${items}</ul> `;
}

function schoolNeedsLivecheck() { if (state.liveOk && state.coins.length) return false; renderSchoolResult("err", "Livecheck requis", "Clique d’abord sur Lancer Livecheck. Le simulateur refuse de travailler sans prix réel chargé.", [ "Aucun prix n’est inventé.", "Aucun test n’est lancé tant que la source marché n’est pas prête.", "Après Livecheck OK, recommence le test guidé." ]); return true;
}

function runSchoolTest(testName, options = {}) {
  const renderUi = options.render !== false;
  const renderOutput = options.output !== false && renderUi;
  const safeAmount = SIM_PROFILE.defaultAmount;
  const tooBigAmount = SIM_PROFILE.maxPerOperation * 5;
  const ceilingUnit = SIM_PROFILE.maxExposure / 3;
  if (testName === "reset_100") {
    resetSimulation({ render:renderUi });
    setSimManualFields("BTC", safeAmount);
    if (renderOutput) renderCommandOutput(commandOk("reset_sim", simulationPayload()));
    if (renderUi) renderSchoolResult("neutral", `Simulateur remis à ${fmtEUR.format(SIM_PROFILE.startCash)}`, "Tu repars avec un portefeuille virtuel propre pour le profil actif.", [ `Capital virtuel : ${fmtEUR.format(SIM_PROFILE.startCash)}.`, "Position : 0 €.", "L’autre profil reste conservé." ]);
    return true;
  }
  if (!atlasExecutionQuoteIsFreshBinance(options.marketQuote) && schoolNeedsLivecheck()) return;
  let result = null;
  if (testName === "safe_btc_5") {
    resetSimulation({ render:renderUi });
    setSimManualFields("BTC", safeAmount);
    result = simulateOrder("buy", "BTC", safeAmount, { render:renderUi, marketQuote:options.marketQuote || null });
    if (renderOutput) renderCommandOutput(result);
    if (renderUi) renderSchoolResult(result?.ok ? "ok" : "err", result?.ok ? "Accepté : opération prudente" : "Erreur inattendue", result?.ok ? `BTC ${fmtEUR.format(safeAmount)} est accepté : ticket conseillé ${fmtEUR.format(SIM_PROFILE.defaultAmount)}, maximum ${fmtEUR.format(SIM_PROFILE.maxPerOperation)}.` : (result?.error || "Le test n’a pas donné le résultat attendu."), result?.ok ? [ `Tu as investi ${fmtEUR.format(safeAmount)} virtuels.`, `Il reste environ ${fmtEUR.format(state.sim.cash)} virtuels disponibles.`, "Une quantité fictive de BTC apparaît dans Portefeuille virtuel." ] : [ "Aucun argent réel.", "Regarde le journal pour le détail." ]);
    if (result?.ok) {
      const learning = loadLearningCockpitState();
      if (learning.module_key === "risk") recordLearningPracticeEvidence("risk_position", true);
      else if (learning.module_key === "spot") recordLearningPracticeEvidence("spot_position", true);
    }
    return result;
  }
  if (testName === "too_big_btc_50") {
    resetSimulation();
    setSimManualFields("BTC", tooBigAmount);
    result = simulateOrder("buy", "BTC", tooBigAmount);
    renderCommandOutput(result);
    renderSchoolResult(result?.ok === false ? "refusal" : "err", result?.ok === false ? "Refus normal : opération trop grosse" : "Erreur : ce test aurait dû être refusé", result?.ok === false ? `Tu as demandé ${fmtEUR.format(tooBigAmount)}, mais le profil limite chaque opération à ${fmtEUR.format(SIM_PROFILE.maxPerOperation)}.` : "Le test n’a pas respecté la règle attendue.", result?.ok === false ? [ "Le refus protège ton capital virtuel.", "Aucune validation réelle n’a été envoyée.", "La règle apprise : ne pas mettre trop gros d’un coup." ] : [ "Ce test doit être revu." ]);
    return;
  }
  if (testName === "forbidden_doge_5") {
    resetSimulation();
    setSimManualFields("DOGE", safeAmount);
    result = simulateOrder("buy", "DOGE", safeAmount);
    renderCommandOutput(result);
    renderSchoolResult(result?.ok === false ? "refusal" : "err", result?.ok === false ? "Refus normal : crypto non autorisée" : "Erreur : DOGE aurait dû être refusé", result?.ok === false ? `Le profil autorise seulement ${SIM_PROFILE.allowedSymbols.join(", ")}. DOGE reste volontairement bloqué.` : "Le test n’a pas respecté la règle attendue.", result?.ok === false ? [ "Tu apprends à limiter le périmètre.", "Moins d’actifs = moins de confusion au début.", "Les autres cryptos peuvent être observées sans être autorisées dans ce profil." ] : [ "Ce test doit être revu." ]);
    return;
  }
  if (testName === "fill_ceiling") {
    resetSimulation();
    setSimManualFields("SOL", ceilingUnit);
    const r1 = simulateOrder("buy", "BTC", ceilingUnit);
    const r2 = simulateOrder("buy", "ETH", ceilingUnit);
    const r3 = simulateOrder("buy", "SOL", ceilingUnit);
    renderCommandOutput(r3);
    const ok = r1?.ok && r2?.ok && r3?.ok;
    renderSchoolResult(ok ? "ok" : "err", ok ? `Plafond rempli : ${fmtEUR.format(SIM_PROFILE.maxExposure)} exposés` : "Erreur pendant le remplissage du plafond", ok ? `Le simulateur a réparti ${fmtEUR.format(ceilingUnit)} sur BTC, ETH et SOL.` : "Une des trois opérations n’a pas été acceptée.", ok ? [ `Capital restant : environ ${fmtEUR.format(SIM_PROFILE.minReserve)}.`, `Exposition virtuelle : environ ${fmtEUR.format(SIM_PROFILE.maxExposure)}.`, "Le profil actif a atteint son plafond de sécurité." ] : [ r1?.error || "BTC : état inconnu.", r2?.error || "ETH : état inconnu.", r3?.error || "SOL : état inconnu." ]);
    return;
  }
  if (testName === "exceed_ceiling") {
    resetSimulation();
    simulateOrder("buy", "BTC", ceilingUnit);
    simulateOrder("buy", "ETH", ceilingUnit);
    simulateOrder("buy", "SOL", ceilingUnit);
    setSimManualFields("BTC", safeAmount);
    result = simulateOrder("buy", "BTC", safeAmount);
    renderCommandOutput(result);
    renderSchoolResult(result?.ok === false ? "refusal" : "err", result?.ok === false ? "Refus normal : plafond déjà atteint" : "Erreur : le dépassement aurait dû être refusé", result?.ok === false ? `Après ${fmtEUR.format(SIM_PROFILE.maxExposure)} virtuels exposés, l’app bloque tout nouvel achat simulé.` : "Le simulateur n’a pas bloqué le dépassement.", result?.ok === false ? [ `Exposition maximale : ${fmtEUR.format(SIM_PROFILE.maxExposure)}.`, `Réserve minimale conservée : ${fmtEUR.format(SIM_PROFILE.minReserve)}.`, "La règle apprise : ne pas tout exposer, même en simulation." ] : [ "Ce test doit être revu." ]);
  }
}

