function atlasMetalsMathFinite(value) {
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function atlasMetalsMathSampleStd(values) {
  const rows = (Array.isArray(values) ? values : [])
    .map(atlasMetalsMathFinite)
    .filter(Number.isFinite);
  if (rows.length < 2) return null;
  const mean = rows.reduce((sum, value) => sum + value, 0) / rows.length;
  const variance = rows.reduce(
    (sum, value) => sum + (value - mean) ** 2,
    0
  ) / (rows.length - 1);
  return Math.sqrt(Math.max(0, variance));
}

function atlasMetalsMathDrawdown(points) {
  if (!Array.isArray(points) || points.length < 2) return null;
  let peak = points[0];
  let peakIndex = 0;
  let maxPct = 0;
  let start = points[0];
  let trough = points[0];
  points.forEach((point, index) => {
    if (point.y > peak.y) {
      peak = point;
      peakIndex = index;
    }
    const pct = peak.y > 0 ? ((peak.y - point.y) / peak.y) * 100 : 0;
    if (pct > maxPct) {
      maxPct = pct;
      start = points[peakIndex];
      trough = point;
    }
  });
  return { pct: maxPct, start, trough };
}

function atlasMetalsMathCoreMetrics() {
  const metals = atlasParallelMarketMetalsState();
  const asset = atlasParallelMarketActiveMetal();
  const periodDays = Number(metals.period || 7);
  const periodLabel = atlasChartPeriodLabel(periodDays);
  const rows = atlasMetalsQuoteFoundationPeriodRows(periodDays);
  const points = atlasMetalsQuoteFoundationAssetPoints(asset.id, periodDays);
  const returns = [];
  for (let index = 1; index < points.length; index += 1) {
    const previous = Number(points[index - 1].y);
    const current = Number(points[index].y);
    if (previous > 0 && current > 0) returns.push(Math.log(current / previous));
  }
  const volatilitySessionPct = returns.length >= 2
    ? atlasMetalsMathSampleStd(returns) * 100
    : null;
  const drawdown = atlasMetalsMathDrawdown(points);
  const values = points.map(point => Number(point.y)).filter(Number.isFinite);
  const low = values.length ? Math.min(...values) : null;
  const high = values.length ? Math.max(...values) : null;
  const amplitudePct = Number.isFinite(low) && low > 0 && Number.isFinite(high)
    ? ((high - low) / low) * 100
    : null;
  const completenessPct = rows.length
    ? Math.min(100, (points.length / rows.length) * 100)
    : null;
  const reading = atlasMetalsQuoteFoundationHorizonReading(asset.id, periodDays);
  const quote = atlasMetalsQuoteFoundationQuote(asset.id);
  const first = points[0] || null;
  const last = points[points.length - 1] || null;
  const latestStepPct = points.length >= 2
    ? ((points[points.length - 1].y / points[points.length - 2].y) - 1) * 100
    : null;
  return {
    asset,
    periodDays,
    periodLabel,
    rows,
    points,
    returns,
    reading,
    quote,
    first,
    last,
    latestStepPct,
    volatilitySessionPct,
    drawdown,
    low,
    high,
    amplitudePct,
    completenessPct,
    ready: reading?.available === true && points.length >= 2
  };
}

function atlasMetalsMathFormatPct(value, digits = 2) {
  if (!Number.isFinite(Number(value))) return "Indisponible";
  const number = Number(value);
  const sign = number > 0 ? "+" : "";
  return `${sign}${new Intl.NumberFormat("fr-FR", {
    minimumFractionDigits: digits,
    maximumFractionDigits: digits
  }).format(number)} %`;
}

function atlasMetalsMathDate(value) {
  const timestamp = Number(value);
  return Number.isFinite(timestamp)
    ? new Date(timestamp).toLocaleDateString("fr-FR")
    : "—";
}

function atlasMetalsMathRestoreCryptoLabels() {
  const shell = document.getElementById("math");
  if (!shell) return false;
  shell.dataset.mathDomain = "crypto";
  shell.classList.remove("atlas-math-metals");
  const eyebrow = shell.querySelector(".atlas-math-dock-head .eyebrow");
  const title = shell.querySelector(".atlas-math-dock-head h2");
  const muted = shell.querySelector(".muted-line");
  const detailsTitle = shell.querySelector(".atlas-score-components h3");
  if (eyebrow) eyebrow.textContent = "ATLAS MATH CORE V3";
  if (title) title.textContent = "Risque historique et qualité de série";
  if (muted) muted.textContent = "Lecture humaine d’abord · mesures factuelles et limites visibles.";
  if (detailsTitle) detailsTitle.textContent = "Composantes de l’indice";
  return true;
}

function atlasRenderMetalsMathCore() {
  const shell = document.getElementById("math");
  if (!shell) return false;
  const metrics = atlasMetalsMathCoreMetrics();
  const asset = metrics.asset;
  const intraday = metrics.periodDays === 1;
  const observationUnit = intraday ? "points Futures intraday" : "séances Futures";
  const historicalSource = intraday ? "Yahoo Finance Futures · intraday 5 min" : "Yahoo Finance Futures";
  shell.dataset.mathDomain = "metals";
  shell.classList.add("atlas-math-metals");
  const color = ATLAS_METALS_CHART_COLORS[asset.id] || "#ffd46a";
  shell.style.setProperty("--crypto-color", color);
  shell.style.setProperty("--crypto-gradient", `linear-gradient(135deg, ${color}, rgba(77,226,235,.82))`);
  shell.dataset.cryptoId = `metals-${asset.id}`;

  const eyebrow = shell.querySelector(".atlas-math-dock-head .eyebrow");
  const title = shell.querySelector(".atlas-math-dock-head h2");
  const contextLine = document.getElementById("atlasMathContextLine");
  const muted = shell.querySelector(".muted-line");
  const detailsTitle = shell.querySelector(".atlas-score-components h3");
  if (eyebrow) eyebrow.textContent = "ATLAS MATH CORE MÉTAUX V1";
  if (title) title.textContent = `${asset.name} · qualité et risque historique`;
  if (contextLine) contextLine.textContent = `${asset.symbol} · ${metrics.periodLabel} · ${metrics.points.length} ${observationUnit} · ${historicalSource}`;
  if (muted) muted.textContent = intraday
    ? "Historique Futures intraday · cotation actuelle Gold API séparée · aucune prévision."
    : "Historique Futures quotidien · cotation actuelle Gold API séparée · aucune prévision.";
  if (detailsTitle) detailsTitle.textContent = "Contrôles de la série Métaux";

  const quality = Number.isFinite(metrics.completenessPct)
    ? Math.max(0, Math.min(100, Math.round(metrics.completenessPct)))
    : 0;
  const scoreRing = document.getElementById("scoreRing");
  const scoreValue = document.getElementById("scoreValue");
  const scoreLabel = document.getElementById("scoreLabel");
  if (scoreRing) scoreRing.style.setProperty("--score", quality);
  if (scoreValue) scoreValue.textContent = metrics.rows.length ? String(quality) : "—";
  if (scoreLabel) scoreLabel.textContent = metrics.rows.length ? "Qualité série" : "En attente";

  const breakdown = document.getElementById("scoreBreakdown");
  if (breakdown) {
    breakdown.innerHTML = `
      <div><span>${intraday ? "Points attendus" : "Séances attendues"}</span><b>${metrics.rows.length || "—"}</b></div>
      <div><span>Points valides</span><b>${metrics.points.length || "—"}</b></div>
      <div><span>Rendements</span><b>${metrics.returns.length || "—"}</b></div>
      <div><span>Unité</span><b>${escapeHtml(metrics.points[0]?.currency || metrics.quote?.currency || "USD")}</b></div>
      <div><span>Anti-invention</span><b>ACTIF</b></div>
    `;
  }

  const variationText = metrics.reading?.available
    ? atlasMetalsMathFormatPct(metrics.reading.percent)
    : "Non mesurée";
  const direction = metrics.reading?.available
    ? Math.abs(metrics.reading.percent) < 0.5
      ? "mouvement limité"
      : metrics.reading.percent > 0
        ? "progression sur la fenêtre"
        : "recul sur la fenêtre"
    : "historique insuffisant";
  const human = document.getElementById("atlasHumanVerdict");
  if (human) {
    human.classList.remove("ok", "warn", "refus");
    human.classList.add(metrics.ready ? "warn" : "refus");
    human.innerHTML = metrics.ready
      ? `<b>Fenêtre réelle :</b> ${escapeHtml(metrics.periodLabel)} · ${metrics.points.length} ${escapeHtml(observationUnit)} · ${escapeHtml(atlasMetalsMathDate(metrics.first?.x))} → ${escapeHtml(atlasMetalsMathDate(metrics.last?.x))}.<br><b>Lecture :</b> ${escapeHtml(direction)} · variation ${escapeHtml(variationText)} · volatilité par relevé ${escapeHtml(atlasMetalsMathFormatPct(metrics.volatilitySessionPct))} · drawdown max ${escapeHtml(atlasMetalsMathFormatPct(metrics.drawdown?.pct))}.<br><b>Limites :</b> ${intraday ? "historique Futures intraday" : "historique quotidien Futures"} uniquement ; aucune prévision.`
      : `<b>Math Core Métaux :</b> série en constitution pour cette fenêtre.<br><b>Disponible :</b> ${metrics.points.length} ${escapeHtml(observationUnit)} réel${metrics.points.length > 1 ? "s" : ""}.<br><b>Stop :</b> aucune valeur absente n’est remplacée.`;
  }

  const summaryGrid = document.getElementById("atlasSummaryGrid");
  if (summaryGrid) {
    summaryGrid.innerHTML = `
      <div><span>Série réelle</span><b>${metrics.points.length || "—"} ${intraday ? "points" : "séances"}</b></div>
      <div><span>Variation fenêtre</span><b>${escapeHtml(variationText)}</b></div>
      <div><span>Volatilité / séance</span><b>${escapeHtml(atlasMetalsMathFormatPct(metrics.volatilitySessionPct))}</b></div>
      <div><span>Drawdown maximal</span><b>${escapeHtml(atlasMetalsMathFormatPct(metrics.drawdown?.pct))}</b></div>
    `;
  }

  const currentPrice = metrics.quote?.price !== null && metrics.quote?.price !== undefined
    ? atlasMetalsQuoteFoundationPriceText(metrics.quote)
    : "Indisponible";
  const panel = document.getElementById("atlasMathCorePanel");
  if (panel) {
    panel.innerHTML = [
      atlasMathCard("Actif et fenêtre", asset.symbol, `${asset.name} · ${metrics.periodLabel}`, historicalSource, "wide"),
      atlasMathCard("Cotation actuelle", currentPrice, "Gold API · référence indicative actuelle", "Séparée de la série Futures", "wide"),
      atlasMathCard("Variation fenêtre", variationText, metrics.reading?.detail || "Historique insuffisant"),
      atlasMathCard("Dernière séance", atlasMetalsMathFormatPct(metrics.latestStepPct), metrics.last ? atlasMetalsMathDate(metrics.last.x) : "Indisponible"),
      atlasMathCard("Volatilité / séance", atlasMetalsMathFormatPct(metrics.volatilitySessionPct), `${metrics.returns.length} rendements logarithmiques`),
      atlasMathCard("Drawdown maximal", atlasMetalsMathFormatPct(metrics.drawdown?.pct), metrics.drawdown ? `${atlasMetalsMathDate(metrics.drawdown.start?.x)} → ${atlasMetalsMathDate(metrics.drawdown.trough?.x)}` : "Indisponible"),
      atlasMathCard("Amplitude haut / bas", atlasMetalsMathFormatPct(metrics.amplitudePct), Number.isFinite(metrics.low) && Number.isFinite(metrics.high) ? `${metrics.low.toLocaleString("fr-FR")} → ${metrics.high.toLocaleString("fr-FR")} ${metrics.points[0]?.currency || "USD"}` : "Indisponible"),
      atlasMathCard("Qualité de série", metrics.rows.length ? `${quality} %` : "Indisponible", `${metrics.points.length}/${metrics.rows.length || 0} ${intraday ? "points" : "séances"} valides`),
      atlasMathCard("Provenance", historicalSource, intraday ? "Série publique intraday · contrats Futures" : "Série quotidienne publique · contrats Futures", intraday ? "Gold API distinct pour le prix actuel" : "Gold API distinct pour le prix actuel", "wide"),
      atlasMathCard("Limites", "Observation seulement", intraday ? "Fenêtre Futures intraday · aucune prévision ni mélange avec la cotation Gold API" : "Aucune prévision, recommandation ou mélange spot/Futures", "Décision humaine uniquement", "wide")
    ].join("");
  }

  const verdict = document.getElementById("atlasMathVerdict");
  if (verdict) {
    verdict.className = `atlas-verdict ${metrics.ready ? "warn" : "refus"}`;
    verdict.innerHTML = metrics.ready
      ? `<b>Math Core Métaux actif</b> · ${intraday ? "série Futures intraday" : "série Futures"} mesurée · décision humaine`
      : `<b>Math Core Métaux suspendu</b> · série réelle insuffisante`;
  }

  state.metalsMath = {
    schema: "atlas_math_core_metals_v1",
    asset_id: asset.id,
    symbol: asset.symbol,
    period_days: metrics.periodDays,
    sessions: metrics.points.length,
    variation_pct: metrics.reading?.available ? metrics.reading.percent : null,
    volatility_session_pct: metrics.volatilitySessionPct,
    max_drawdown_pct: metrics.drawdown?.pct ?? null,
    amplitude_pct: metrics.amplitudePct,
    completeness_pct: metrics.completenessPct,
    current_quote_source: metrics.quote?.source_name || metrics.quote?.source_id || null,
    historical_source: historicalSource,
    spot_futures_separated: true,
    prediction_generated: false,
    updated_at: new Date().toISOString()
  };

  if (typeof atlasV2SyncMathRail === "function") atlasV2SyncMathRail();
  return true;
}

let atlasMetalsMathReturnParent = null;

let atlasMetalsMathReturnNext = null;

let atlasMetalsMathReturnDock = null;

function atlasMetalsMathCorePlace(metalsActive) {
  const shell = document.getElementById("math");
  const host = document.getElementById("atlasMetalsMathHost");
  if (!shell || !host) return false;

  if (metalsActive) {
    host.hidden = false;
    if (shell.parentElement !== host) {
      atlasMetalsMathReturnParent = shell.parentElement;
      atlasMetalsMathReturnNext = shell.nextSibling;
      atlasMetalsMathReturnDock = {
        top: shell.classList.contains("is-top"),
        side: shell.classList.contains("is-side"),
        rail: shell.classList.contains("is-rail"),
        dataset: shell.dataset.mathDock || "side"
      };
      host.appendChild(shell);
    }
    shell.classList.remove("is-side", "is-rail");
    shell.classList.add("is-top");
    shell.dataset.mathDock = "top";
    shell.hidden = false;
    return true;
  }

  host.hidden = true;
  if (shell.parentElement === host && atlasMetalsMathReturnParent) {
    if (
      atlasMetalsMathReturnNext
      && atlasMetalsMathReturnNext.parentNode === atlasMetalsMathReturnParent
    ) {
      atlasMetalsMathReturnParent.insertBefore(shell, atlasMetalsMathReturnNext);
    } else {
      atlasMetalsMathReturnParent.appendChild(shell);
    }
    shell.classList.remove("is-top", "is-side", "is-rail");
    if (atlasMetalsMathReturnDock?.top) shell.classList.add("is-top");
    else if (atlasMetalsMathReturnDock?.rail) shell.classList.add("is-rail");
    else shell.classList.add("is-side");
    shell.dataset.mathDock = atlasMetalsMathReturnDock?.dataset || "side";
    atlasMetalsMathReturnParent = null;
    atlasMetalsMathReturnNext = null;
    atlasMetalsMathReturnDock = null;
  }
  return true;
}

let atlasParallelMarketHoldTimer = 0;

let atlasParallelMarketHoldConsumed = false;

function atlasParallelMarketSafeRead(key) {
  try {
    const parsed = JSON.parse(localStorage.getItem(key) || "null");
    return parsed && typeof parsed === "object" ? parsed : null;
  } catch {
    return null;
  }
}

function atlasParallelMarketReadDomain() {
  try {
    const value = String(
      localStorage.getItem(ATLAS_PARALLEL_MARKET_DOMAIN_KEY) || ""
    ).trim();
    return ATLAS_PARALLEL_MARKET_DOMAINS.includes(value)
      ? value
      : "crypto";
  } catch {
    return "crypto";
  }
}

function atlasParallelMarketDomain() {
  return ATLAS_PARALLEL_MARKET_DOMAINS.includes(state.marketDomain)
    ? state.marketDomain
    : "crypto";
}

function atlasParallelMarketMetalsState() {
  return state.parallelMarkets.metals;
}

function atlasParallelMarketValidMetalIds(ids) {
  const available = new Set(ATLAS_METALS_ASSETS.map(asset => asset.id));
  const normalized = Array.isArray(ids)
    ? ids
        .map(id => String(id || ""))
        .filter(id => available.has(id))
        .filter((id, index, list) => list.indexOf(id) === index)
        .slice(0, ATLAS_METALS_ASSETS.length)
    : [];

  return normalized.length
    ? normalized
    : ATLAS_METALS_ASSETS.map(asset => asset.id);
}

function atlasParallelMarketMetalsRead() {
  const saved = atlasParallelMarketSafeRead(
    ATLAS_PARALLEL_MARKET_METALS_STATE_KEY
  );
  const metals = atlasParallelMarketMetalsState();
  if (!saved) {
    metals.period = 7;
    metals.resultVisibilityVersion = "28.2.62";
    return metals;
  }

  metals.period = [1, 7, 30, 90, 365].includes(Number(saved.period))
    ? Number(saved.period)
    : 7;
  const visibilityMigrated = String(saved.resultVisibilityVersion || "") === "28.2.61";
  if (!visibilityMigrated && metals.period === 1) metals.period = 7;
  metals.resultVisibilityVersion = "28.2.62";
  metals.view = saved.view === "base100" ? "base100" : "price";
  metals.scale = saved.scale === "logarithmic"
    ? "logarithmic"
    : "linear";
  metals.section = saved.section === "critical"
    ? "critical"
    : "prices";
  metals.activeId = ATLAS_METALS_ASSETS.some(
    asset => asset.id === String(saved.activeId || "")
  )
    ? String(saved.activeId)
    : "gold";
  metals.marketFilter = [
    "all",
    "monetary",
    "precious-industrial",
    "industrial"
  ].includes(String(saved.marketFilter || ""))
    ? String(saved.marketFilter)
    : "all";
  metals.selectionIds = atlasParallelMarketValidMetalIds(
    saved.selectionIds
  );
  if (!visibilityMigrated) atlasParallelMarketMetalsWrite();
  return metals;
}

function atlasParallelMarketMetalsWrite() {
  const metals = atlasParallelMarketMetalsState();
  const payload = {
    schema: "agent_crypto_parallel_market_metals_state_v1",
    savedAt: new Date().toISOString(),
    period: Number(metals.period || 7),
    resultVisibilityVersion: "28.2.61",
    view: metals.view === "base100" ? "base100" : "price",
    scale: metals.scale === "logarithmic"
      ? "logarithmic"
      : "linear",
    section: metals.section === "critical"
      ? "critical"
      : "prices",
    activeId: ATLAS_METALS_ASSETS.some(
      asset => asset.id === String(metals.activeId || "")
    )
      ? String(metals.activeId)
      : "gold",
    marketFilter: [
      "all",
      "monetary",
      "precious-industrial",
      "industrial"
    ].includes(String(metals.marketFilter || ""))
      ? String(metals.marketFilter)
      : "all",
    selectionIds: [...metals.selectionIds]
  };

  try {
    localStorage.setItem(
      ATLAS_PARALLEL_MARKET_METALS_STATE_KEY,
      JSON.stringify(payload)
    );
    return true;
  } catch {
    return false;
  }
}

function atlasParallelMarketSelectedMetals() {
  const selected = new Set(
    atlasParallelMarketMetalsState().selectionIds
  );
  return ATLAS_METALS_ASSETS.filter(asset => selected.has(asset.id));
}

function atlasParallelMarketSetControlsDisabled(disabled) {
  document
    .querySelectorAll(
      "#analyste .chart-v2-toolbar button, "
      + "#analyste .compare-actions button"
    )
    .forEach(button => {
      if (disabled) {
        if (!button.hasAttribute("data-parallel-market-disabled")) {
          button.dataset.parallelMarketDisabled =
            button.disabled ? "1" : "0";
        }
        button.disabled = true;
        button.setAttribute("aria-disabled", "true");
      } else if (button.hasAttribute("data-parallel-market-disabled")) {
        button.disabled =
          button.dataset.parallelMarketDisabled === "1";
        button.removeAttribute("data-parallel-market-disabled");
        if (!button.disabled) button.removeAttribute("aria-disabled");
      }
    });
}

function atlasParallelMarketActiveMetal() {
  const metals = atlasParallelMarketMetalsState();
  return ATLAS_METALS_ASSETS.find(
    asset => asset.id === String(metals.activeId || "")
  ) || ATLAS_METALS_ASSETS[0];
}

function atlasParallelMarketMetalsAllIds() {
  return ATLAS_METALS_ASSETS.map(asset => asset.id);
}

function atlasParallelMarketMetalsAllActive() {
  const metals = atlasParallelMarketMetalsState();
  const selected = new Set(metals.selectionIds);
  return metals.view === "base100"
    && ATLAS_METALS_ASSETS.every(asset => selected.has(asset.id));
}

function atlasParallelMarketSetActiveMetal(metalId) {
  const id = String(metalId || "");
  if (!ATLAS_METALS_ASSETS.some(asset => asset.id === id)) {
    return false;
  }
  const metals = atlasParallelMarketMetalsState();
  metals.activeId = id;
  // A single metal is always read on its real price scale.
  metals.view = "price";
  atlasParallelMarketMetalsWrite();
  atlasParallelMarketRenderMetals();
  atlasWorkspaceScheduleSave?.(120);
  return true;
}

function atlasParallelMarketShowAllMetals() {
  const metals = atlasParallelMarketMetalsState();
  metals.selectionIds = atlasParallelMarketMetalsAllIds();
  metals.view = "base100";
  atlasParallelMarketMetalsWrite();
  atlasParallelMarketRenderMetals();
  atlasWorkspaceRenderStrip?.();
  atlasWorkspaceScheduleSave?.(120);
  return true;
}

function atlasParallelMarketHiddenState(element, hidden, key) {
  if (!element) return;
  const attribute = `data-parallel-market-${key}-hidden-state`;

  if (hidden) {
    if (!element.hasAttribute(attribute)) {
      element.setAttribute(attribute, element.hidden ? "1" : "0");
    }
    element.hidden = true;
    return;
  }

  if (element.hasAttribute(attribute)) {
    element.hidden = element.getAttribute(attribute) === "1";
    element.removeAttribute(attribute);
  }
}

function atlasParallelMarketSetMetalsMarketFilter(filter) {
  const value = [
    "all",
    "monetary",
    "precious-industrial",
    "industrial"
  ].includes(String(filter || ""))
    ? String(filter)
    : "all";

  atlasParallelMarketMetalsState().marketFilter = value;
  atlasParallelMarketMetalsWrite();
  atlasParallelMarketRenderMetalsMarket();
  atlasWorkspaceScheduleSave?.(120);
  return value;
}

function atlasMetalsStructuralArray(value) {
  return Array.isArray(value) ? value : [];
}

function atlasMetalsStructuralRegistry() {
  return (
    atlasMetalsStructuralState.registry
    || ATLAS_METALS_STRUCTURAL_FALLBACK
  );
}

function atlasMetalsStructuralAsset(assetId = null) {
  const id = String(
    assetId
    || atlasParallelMarketActiveMetal()?.id
    || "gold"
  );

  return atlasMetalsStructuralArray(
    atlasMetalsStructuralRegistry()?.assets
  ).find(asset => asset?.id === id)
    || atlasMetalsStructuralArray(
      ATLAS_METALS_STRUCTURAL_FALLBACK?.assets
    ).find(asset => asset?.id === id)
    || ATLAS_METALS_STRUCTURAL_FALLBACK.assets[0];
}

function atlasMetalsStructuralSource(sourceId) {
  const id = String(sourceId || "");

  return atlasMetalsStructuralArray(
    atlasMetalsStructuralRegistry()?.sources
  ).find(source => source?.id === id)
    || atlasMetalsStructuralArray(
      ATLAS_METALS_STRUCTURAL_FALLBACK?.sources
    ).find(source => source?.id === id)
    || null;
}

function atlasMetalsStructuralSourceRow(source, note = "") {
  const row = document.createElement("span");
  const name = document.createElement("b");
  const description = document.createElement("small");
  const status = document.createElement("em");

  name.textContent = String(
    source?.short_name || source?.name || "Source"
  );
  description.textContent = String(
    note
    || source?.title
    || source?.role
    || "Source publique"
  );
  status.textContent = String(
    source?.status_label || "RÉFÉRENCE"
  );
  status.classList.add(
    atlasMarketRegistrySourceToneClass(
      source?.status_tone || "reference"
    )
  );

  row.dataset.marketSourceId = String(source?.id || "");
  row.dataset.structuralSource = "true";
  row.append(name, description, status);
  return row;
}

function atlasMetalsStructuralValidate(payload) {
  if (
    payload?.schema
    !== "agent_crypto_metals_structural_registry_v1"
  ) {
    throw new Error("Registre structurel incompatible");
  }

  const assets = atlasMetalsStructuralArray(payload?.assets);
  const sources = atlasMetalsStructuralArray(payload?.sources);
  const required = new Set([
    "gold",
    "silver",
    "platinum",
    "palladium",
    "copper"
  ]);

  if (
    assets.length !== required.size
    || assets.some(asset => !required.has(asset?.id))
  ) {
    throw new Error("Registre structurel incomplet");
  }

  if (sources.length < 4) {
    throw new Error("Sources structurelles incomplètes");
  }

  assets.forEach(asset => {
    if (
      !asset?.production?.display
      || !asset?.reserves?.display
      || !asset?.production?.top_display
      || !asset?.uses?.display
      || !asset?.eu_status?.display
      || !Array.isArray(asset?.source_ids)
    ) {
      throw new Error(
        `Données structurelles invalides : ${asset?.id || "?"}`
      );
    }
  });

  return payload;
}

async function atlasMetalsStructuralLoad() {
  atlasMetalsStructuralState.status = "loading";
  atlasMetalsStructuralState.error = null;

  try {
    const payload = await atlasMarketRegistryFetchJson(
      ATLAS_METALS_STRUCTURAL_REGISTRY_PATH
    );

    atlasMetalsStructuralState.registry =
      atlasMetalsStructuralValidate(payload);
    atlasMetalsStructuralState.status = "loaded";
    atlasMetalsStructuralState.origin = "json_local";
    atlasMetalsStructuralState.loadedAt =
      new Date().toISOString();
  } catch (error) {
    atlasMetalsStructuralState.registry =
      ATLAS_METALS_STRUCTURAL_FALLBACK;
    atlasMetalsStructuralState.status = "fallback";
    atlasMetalsStructuralState.origin =
      "fallback_intégré";
    atlasMetalsStructuralState.loadedAt = null;
    atlasMetalsStructuralState.error = String(
      error?.message || error || "Erreur structure"
    );
  }

  atlasParallelMarketRenderMetals();
  return atlasMetalsStructuralState.status;
}

function atlasMetalsStructuralRenderSourceDock(assetId = null) {
  const asset = atlasMetalsStructuralAsset(assetId);
  const list = document.getElementById(
    "atlasMetalsSourceList"
  );
  const stateLabel = document.getElementById(
    "atlasMetalsSourceDockState"
  );

  if (!list || !asset) return;

  const sources = atlasMetalsStructuralArray(
    asset.source_ids
  )
    .map(atlasMetalsStructuralSource)
    .filter(Boolean);

  list.replaceChildren();

  sources.forEach(source => {
    let note = source.title;

    if (source.id === "usgs_mcs_2026") {
      note = "Production · réserves · usages";
    } else if (source.id === "rmis_eu_2023") {
      note = "Criticité et statut stratégique UE";
    } else if (source.id === "iea_critical_minerals_2026") {
      note = "Scénarios offre-demande du cuivre";
    } else if (source.id === "world_bank_pink_sheet_2026") {
      note = "Historique mensuel public · non importé";
    }

    list.append(
      atlasMetalsStructuralSourceRow(source, note)
    );
  });

  if (stateLabel) {
    stateLabel.textContent =
      `${sources.length} source`
      + `${sources.length > 1 ? "s" : ""}`
      + " publique"
      + `${sources.length > 1 ? "s" : ""}`;
  }

  const meta = atlasMarketRegistryAssetMeta(asset.id);
  setText(
    document.getElementById("atlasMetalsSourceDockTitle"),
    `${meta.name} · ${meta.symbol}`
  );
}

function atlasMetalsStructuralRenderCatalog() {
  const list = document.getElementById(
    "atlasMetalsRegistryList"
  );
  const summary = document.getElementById(
    "atlasMetalsRegistrySummary"
  );
  if (!list) return;

  const sources = atlasMetalsStructuralArray(
    atlasMetalsStructuralRegistry()?.sources
  );

  list.replaceChildren();

  sources.forEach(source => {
    list.append(
      atlasMetalsStructuralSourceRow(
        source,
        source.title
      )
    );
  });

  if (summary) {
    const origin =
      atlasMetalsStructuralState.status === "loaded"
        ? "registre JSON local"
        : "fallback public intégré";

    summary.textContent =
      `${sources.length} sources publiques · `
      + "5 métaux · données 2025 · "
      + `${origin} · aucun prix`;
  }

  list.dataset.registryStatus =
    atlasMetalsStructuralState.status;
}

function atlasMetalsStructuralRenderMarketRows() {
  atlasMetalsStructuralArray(
    atlasMetalsStructuralRegistry()?.assets
  ).forEach(record => {
    const row = document.querySelector(
      `[data-metals-market-row="${record.id}"]`
    );
    if (!row) return;

    const cells = row.querySelectorAll("td");
    if (cells.length < 8) return;

    cells[4].textContent = "—";
    cells[5].textContent = "—";
    cells[6].textContent = "USGS 2026";
    cells[7].textContent = "Structure disponible";
    row.dataset.structuralState = "available";
    row.dataset.structuralYear =
      String(record.data_year || 2025);
  });
}

