function atlasParallelMarketRenderMetals() {
  const metals = atlasParallelMarketMetalsState();
  const selected = new Set(metals.selectionIds);
  const allSeriesActive = atlasParallelMarketMetalsAllActive();

  const activeMetal = atlasParallelMarketActiveMetal();

  document.querySelectorAll("[data-metal-id]").forEach(button => {
    const active = selected.has(button.dataset.metalId);
    const focused = button.dataset.metalId === activeMetal.id;
    button.classList.toggle("is-active", active);
    button.classList.toggle("is-focus", focused);
    button.setAttribute("aria-pressed", active ? "true" : "false");
    button.setAttribute("aria-current", focused ? "true" : "false");
  });

  document.querySelectorAll("[data-metal-row]").forEach(row => {
    row.hidden = !selected.has(row.dataset.metalRow);
    row.classList.toggle(
      "is-focus",
      row.dataset.metalRow === activeMetal.id
    );
  });

  document.querySelectorAll("[data-metal-legend]").forEach(item => {
    const id = String(item.dataset.metalLegend || "");
    const active = selected.has(id);
    const focused = id === activeMetal.id;
    const asset = ATLAS_METALS_ASSETS.find(record => record.id === id);
    const reading = atlasMetalsQuoteFoundationHorizonReading(id, metals.period);
    item.hidden = !active;
    item.classList.toggle("is-focus", focused && !allSeriesActive);
    item.classList.toggle("is-comparison", allSeriesActive);
    item.style.setProperty(
      "--atlas-metal-series-color",
      ATLAS_METALS_CHART_COLORS[id] || "#9fb3c2"
    );
    item.textContent = allSeriesActive && reading?.available
      ? `${asset?.symbol || id.toUpperCase()} ${atlasMetalsHumanReadingPercent(reading.percent)}`
      : asset?.symbol || id.toUpperCase();
    item.title = reading?.available
      ? `${asset?.name || id} · ${atlasMetalsHumanReadingPercent(reading.percent)} · cliquer pour revenir au prix réel`
      : `${asset?.name || id} · cliquer pour afficher le prix réel`;
  });

  const allSeriesButton = document.querySelector("[data-metals-all-series]");
  if (allSeriesButton) {
    allSeriesButton.classList.toggle("is-active", allSeriesActive);
    allSeriesButton.setAttribute(
      "aria-pressed",
      allSeriesActive ? "true" : "false"
    );
    allSeriesButton.textContent = allSeriesActive ? "TOUS 5/5" : "TOUS";
  }

  document.querySelectorAll("[data-metals-period]").forEach(button => {
    const value = Number(button.dataset.metalsPeriod);
    const active = value === Number(metals.period);
    button.classList.toggle("is-active", active);
    const spotReading = value === 1
      ? atlasMetalsQuoteFoundationHorizonReading(atlasParallelMarketActiveMetal().id, 1)
      : null;
    button.classList.remove("is-unavailable");
    button.classList.toggle("is-building", value === 1 && spotReading?.available !== true);
    button.setAttribute("aria-pressed", active ? "true" : "false");
    if (value === 1) {
      button.title = spotReading?.available
        ? "Historique 24 h réel · Yahoo Finance Futures intraday"
        : `Intraday Futures en attente · ${spotReading?.detail || "première collecte GitHub Actions requise"}`;
      button.setAttribute(
        "aria-label",
        spotReading?.available
          ? "24 heures mesurées par Yahoo Finance Futures intraday"
          : "Historique Futures intraday 24 heures en attente"
      );
    }
  });

  document.querySelectorAll("[data-metals-view]").forEach(button => {
    const active = button.dataset.metalsView === metals.view;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });

  document.querySelectorAll("[data-metals-section]").forEach(button => {
    const active = button.dataset.metalsSection === metals.section;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  });

  document.querySelectorAll("[data-metals-view-panel]").forEach(panel => {
    panel.hidden = panel.dataset.metalsViewPanel !== metals.section;
  });

  const assets = atlasParallelMarketSelectedMetals();
  const symbols = assets.map(asset => asset.symbol).join(" / ");
  const summary = document.getElementById(
    "atlasMetalsSelectionSummary"
  );
  if (summary) {
    summary.textContent = assets.length
      ? `${assets.length} métal${assets.length > 1 ? "x" : ""} `
        + `sélectionné${assets.length > 1 ? "s" : ""} · ${symbols}`
      : "Aucun métal sélectionné";
  }

  const truth = document.getElementById(
    "atlasMetalsFoundationTruth"
  );
  if (truth) {
    const quoteSummary = atlasMetalsQuoteFoundationSummary();
    truth.textContent = metals.section === "critical"
      ? "USGS préparé · import structurel non connecté"
      : `${metals.view === "base100" ? "Base 100" : "Prix"} · `
        + `${atlasChartPeriodLabel(metals.period)} · `
        + quoteSummary.truth;
  }

  atlasParallelMarketRenderMetalsDetail();
  atlasParallelMarketRenderMetalsMarket();
  atlasMarketRegistryRenderCatalog();
  if (atlasParallelMarketDomain() === "metals") renderAtlasMathCore();
}

function atlasParallelMarketRender() {
  const domain = atlasParallelMarketDomain();
  const metalsActive = domain === "metals";
  const analyst = document.getElementById("analyste");
  const switchButton = document.getElementById("atlasMarketDomainSwitch");
  const switchValue = document.getElementById("atlasMarketDomainSwitchValue");
  const cryptoToolbar = document.querySelector(
    "#analyste .chart-v2-toolbar"
  );
  const metalsToolbar = document.getElementById(
    "atlasMetalsUnifiedToolbar"
  );
  const foundation = document.getElementById("atlasParallelMarketFoundation");
  const canvas = document.getElementById("mainChart");
  const overlay = document.getElementById("atlasChartInsightOverlay");
  const comparisonSelection = document.getElementById("comparisonSelection");
  const legend = document.getElementById("chartV2Legend");
  const tooltip = document.getElementById("atlasChartTooltip");
  const refresh = document.getElementById("atlasChartRefresh");
  const cryptoDetail = document.getElementById("detailPanel");
  const metalsDetail = document.getElementById("atlasMetalsDetailPanel");
  const chartCaption = document.getElementById("chartCaption");
  const metalsStatus = document.getElementById("atlasMetalsDomainStatus");
  const cryptoMarketRibbons = document.getElementById("market-workspace");
  const cryptoMarketGrid = document.getElementById("marketWorkspaceGrid");
  const metalsMarketArea = document.getElementById("atlasMetalsMarketArea");
  const cryptoCommandBar = document.getElementById("livecheck");
  const metalsCommandBar = document.getElementById("atlasMetalsCommandBar");
  const cryptoLiveStatus = document.getElementById("liveStatus");
  const metalsLiveStatus = document.getElementById("atlasMetalsLiveStatus");
  const metalsAnalysisFoundation = document.getElementById(
    "atlasMetalsAnalysisFoundation"
  );

  document.documentElement.dataset.atlasMarketDomain = domain;
  if (analyst) analyst.dataset.marketDomain = domain;
  atlasMetalsMathCorePlace(metalsActive);

  if (cryptoToolbar) {
    cryptoToolbar.hidden = metalsActive;
    cryptoToolbar.setAttribute(
      "aria-hidden",
      metalsActive ? "true" : "false"
    );
  }

  if (metalsToolbar) {
    metalsToolbar.hidden = !metalsActive;
    metalsToolbar.setAttribute(
      "aria-hidden",
      metalsActive ? "false" : "true"
    );
  }

  if (switchButton) {
    switchButton.dataset.domain = domain;
    switchButton.setAttribute("aria-pressed", metalsActive ? "true" : "false");
    switchButton.setAttribute(
      "aria-label",
      metalsActive
        ? "Marché Métaux actif. Cliquer pour revenir au marché Crypto."
        : "Marché Crypto actif. Cliquer pour afficher le marché Métaux."
    );
    switchButton.title = metalsActive
      ? "Marché Métaux · cliquer pour revenir à Crypto"
      : "Marché Crypto · cliquer pour afficher Métaux";
  }

  if (switchValue) {
    switchValue.textContent = metalsActive ? "MÉTAUX" : "CRYPTO";
  }
  if (foundation) foundation.hidden = !metalsActive;
  if (canvas) canvas.hidden = metalsActive;

  atlasParallelMarketHiddenState(overlay, metalsActive, "overlay");
  atlasParallelMarketHiddenState(
    comparisonSelection,
    metalsActive,
    "comparison"
  );
  atlasParallelMarketHiddenState(legend, metalsActive, "legend");
  atlasParallelMarketHiddenState(tooltip, metalsActive, "tooltip");
  atlasParallelMarketHiddenState(refresh, metalsActive, "refresh");
  atlasParallelMarketHiddenState(chartCaption, metalsActive, "caption");

  if (metalsStatus) metalsStatus.hidden = !metalsActive;

  atlasParallelMarketHiddenState(
    cryptoCommandBar,
    metalsActive,
    "header-command"
  );
  atlasParallelMarketHiddenState(
    cryptoLiveStatus,
    metalsActive,
    "header-live"
  );

  if (metalsCommandBar) {
    metalsCommandBar.hidden = !metalsActive;
  }
  if (metalsLiveStatus) {
    metalsLiveStatus.hidden = !metalsActive;
  }

  if (metalsAnalysisFoundation) {
    metalsAnalysisFoundation.hidden = !metalsActive;
    metalsAnalysisFoundation.setAttribute(
      "aria-hidden",
      metalsActive ? "false" : "true"
    );
  }

  atlasParallelMarketHiddenState(
    cryptoMarketRibbons,
    metalsActive,
    "market-ribbons"
  );
  atlasParallelMarketHiddenState(
    cryptoMarketGrid,
    metalsActive,
    "market-grid"
  );
  if (metalsMarketArea) metalsMarketArea.hidden = !metalsActive;

  if (cryptoDetail) {
    if (metalsActive) {
      if (!cryptoDetail.hasAttribute("data-parallel-market-hidden-state")) {
        cryptoDetail.dataset.parallelMarketHiddenState =
          cryptoDetail.hidden ? "1" : "0";
      }
      cryptoDetail.hidden = true;
    } else if (
      cryptoDetail.hasAttribute("data-parallel-market-hidden-state")
    ) {
      cryptoDetail.hidden =
        cryptoDetail.dataset.parallelMarketHiddenState === "1";
      cryptoDetail.removeAttribute("data-parallel-market-hidden-state");
    }
  }

  if (metalsDetail) {
    metalsDetail.hidden = !metalsActive;
    metalsDetail.setAttribute(
      "aria-hidden",
      metalsActive ? "false" : "true"
    );
  }

  if (cryptoDetail) {
    cryptoDetail.setAttribute(
      "aria-hidden",
      metalsActive ? "true" : "false"
    );
  }

  const detailRail = document.getElementById("detailPanelRail");
  if (detailRail) {
    detailRail.setAttribute(
      "aria-hidden",
      metalsActive ? "true" : "false"
    );
    detailRail.tabIndex = metalsActive ? -1 : 0;
  }

  atlasParallelMarketSetControlsDisabled(metalsActive);

  if (metalsActive) {
    atlasParallelMarketRenderMetals();
    setText(
      document.getElementById("selectedAssetTitle"),
      atlasMetalsQuoteFoundationSummary().quoteCount > 0
        ? "Marché Métaux — cotations publiques"
        : "Marché Métaux — observation sans cotation"
    );
  } else {
    const coin = getSelectedCoin();
    if (coin) {
      setText(
        document.getElementById("selectedAssetTitle"),
        `${coin.name} — ${coin.symbol}`
      );
    }
    requestAnimationFrame(() => {
      try {
        state.chartEngineV2.realChart?.resize?.();
      } catch {}
      if (typeof atlasRedrawCurrentChartV2 === "function") {
        atlasRedrawCurrentChartV2();
      }
    });
  }

  if (!metalsActive) renderAtlasMathCore();
  atlasWorkspaceRenderStrip?.();
  atlasWorkspaceSlotsRender?.();
  return domain;
}

function atlasParallelMarketSetDomain(domain, options = {}) {
  const next = ATLAS_PARALLEL_MARKET_DOMAINS.includes(domain)
    ? domain
    : "crypto";

  if (next === atlasParallelMarketDomain() && options.force !== true) {
    atlasParallelMarketRender();
    return next;
  }

  if (atlasScannerTransaction || atlasScannerQueuedRequest) {
    atlasScannerCancel(
      "changement de marché parallèle",
      {
        keepUi: false,
        keepOverlay: false
      }
    );
  }

  state.marketDomain = next;

  if (options.persist !== false) {
    try {
      localStorage.setItem(
        ATLAS_PARALLEL_MARKET_DOMAIN_KEY,
        next
      );
    } catch {}
  }

  atlasParallelMarketMetalsWrite();
  atlasParallelMarketRender();

  if (options.save !== false) {
    atlasWorkspaceScheduleSave?.(120);
  }

  window.dispatchEvent(
    new CustomEvent("atlas:market-domain", {
      detail: {
        domain: next,
        source: options.source || "interface"
      }
    })
  );

  return next;
}

function atlasParallelMarketToggle(source = "interface") {
  return atlasParallelMarketSetDomain(
    atlasParallelMarketDomain() === "crypto"
      ? "metals"
      : "crypto",
    {
      source
    }
  );
}

function atlasParallelMarketToggleMetal(metalId) {
  const id = String(metalId || "");
  const available = new Set(ATLAS_METALS_ASSETS.map(asset => asset.id));
  if (!available.has(id)) return false;

  const metals = atlasParallelMarketMetalsState();
  metals.activeId = id;
  const selected = new Set(metals.selectionIds);

  if (selected.has(id)) selected.delete(id);
  else selected.add(id);

  metals.selectionIds = ATLAS_METALS_ASSETS
    .map(asset => asset.id)
    .filter(assetId => selected.has(assetId));

  atlasParallelMarketMetalsWrite();
  atlasParallelMarketRenderMetals();
  atlasWorkspaceScheduleSave?.(120);
  return true;
}

function atlasParallelMarketSetMetalsPeriod(period) {
  const value = Number(period);
  if (![1, 7, 30, 90, 365].includes(value)) return false;
  atlasParallelMarketMetalsState().period = value;
  atlasParallelMarketMetalsWrite();
  atlasParallelMarketRenderMetals();
  atlasWorkspaceRenderStrip?.();
  atlasWorkspaceScheduleSave?.(120);
  void atlasMetalsQuoteFoundationReloadHistory();
  return true;
}

function atlasParallelMarketSetMetalsView(view) {
  atlasParallelMarketMetalsState().view =
    view === "base100" ? "base100" : "price";
  atlasParallelMarketMetalsWrite();
  atlasParallelMarketRenderMetals();
  atlasWorkspaceRenderStrip?.();
  atlasWorkspaceScheduleSave?.(120);
  return true;
}

function atlasParallelMarketSetMetalsSection(section) {
  atlasParallelMarketMetalsState().section =
    section === "critical" ? "critical" : "prices";
  atlasParallelMarketMetalsWrite();
  atlasParallelMarketRenderMetals();
  atlasWorkspaceRenderStrip?.();
  atlasWorkspaceScheduleSave?.(120);
  return true;
}

function atlasParallelMarketInit() {
  const switchButton = document.getElementById(
    "atlasMarketDomainSwitch"
  );
  const longPress = document.getElementById(
    "atlasMarketDomainLongPress"
  );
  const foundation = document.getElementById(
    "atlasParallelMarketFoundation"
  );
  const metalsMarketArea = document.getElementById(
    "atlasMetalsMarketArea"
  );
  const metalsToolbar = document.getElementById(
    "atlasMetalsUnifiedToolbar"
  );

  atlasParallelMarketMetalsRead();
  atlasMetalsCursorInspectorInit();
  atlasMarketRegistryRender();
  atlasMetalsStructuralRenderActive();
  void atlasMarketRegistryLoad();
  void atlasMetalsStructuralLoad();
  void atlasMetalsQuoteFoundationLoad();

  switchButton?.addEventListener("click", event => {
    event.preventDefault();
    atlasParallelMarketToggle("domain-badge");
  });

  longPress?.addEventListener("click", event => {
    event.preventDefault();
    if (atlasParallelMarketHoldConsumed) {
      atlasParallelMarketHoldConsumed = false;
    }
  });

  longPress?.addEventListener("pointerdown", event => {
    if (event.button !== 0) return;
    atlasParallelMarketHoldConsumed = false;
    window.clearTimeout(atlasParallelMarketHoldTimer);
    atlasParallelMarketHoldTimer = window.setTimeout(() => {
      atlasParallelMarketHoldTimer = 0;
      atlasParallelMarketHoldConsumed = true;
      atlasParallelMarketToggle("title-long-press");
    }, ATLAS_PARALLEL_MARKET_HOLD_MS);
  });

  const cancelHold = () => {
    window.clearTimeout(atlasParallelMarketHoldTimer);
    atlasParallelMarketHoldTimer = 0;
  };

  longPress?.addEventListener("pointerup", cancelHold);
  longPress?.addEventListener("pointercancel", cancelHold);
  longPress?.addEventListener("pointerleave", cancelHold);

  longPress?.addEventListener("keydown", event => {
    if (event.shiftKey && ["Enter", " "].includes(event.key)) {
      event.preventDefault();
      atlasParallelMarketToggle("title-keyboard");
    }
  });

  metalsMarketArea?.addEventListener("click", event => {
    const card = event.target.closest("[data-metals-market-card]");
    if (card) {
      event.preventDefault();
      atlasParallelMarketSetActiveMetal(
        card.dataset.metalsMarketCard
      );
      return;
    }

    const row = event.target.closest("[data-metals-market-row]");
    if (row) {
      event.preventDefault();
      atlasParallelMarketSetActiveMetal(
        row.dataset.metalsMarketRow
      );
      return;
    }

    const filter = event.target.closest(
      "[data-metals-market-filter]"
    );
    if (filter) {
      event.preventDefault();
      atlasParallelMarketSetMetalsMarketFilter(
        filter.dataset.metalsMarketFilter
      );
    }
  });

  metalsToolbar?.addEventListener("click", event => {
    const period = event.target.closest("[data-metals-period]");
    if (period) {
      event.preventDefault();
      atlasParallelMarketSetMetalsPeriod(
        period.dataset.metalsPeriod
      );
      return;
    }

    const view = event.target.closest("[data-metals-view]");
    if (view) {
      event.preventDefault();
      atlasParallelMarketSetMetalsView(
        view.dataset.metalsView
      );
      return;
    }

    const section = event.target.closest("[data-metals-section]");
    if (section) {
      event.preventDefault();
      atlasParallelMarketSetMetalsSection(
        section.dataset.metalsSection
      );
    }
  });

  foundation?.addEventListener("click", event => {
    const allSeries = event.target.closest("[data-metals-all-series]");
    if (allSeries) {
      event.preventDefault();
      atlasParallelMarketShowAllMetals();
      return;
    }

    const legendItem = event.target.closest("[data-metal-legend]");
    if (legendItem) {
      event.preventDefault();
      atlasParallelMarketSetActiveMetal(
        legendItem.dataset.metalLegend
      );
      return;
    }

    const metal = event.target.closest("[data-metal-id]");
    if (metal) {
      event.preventDefault();
      atlasParallelMarketToggleMetal(metal.dataset.metalId);
      return;
    }

    const row = event.target.closest("[data-metal-row]");
    if (row) {
      event.preventDefault();
      atlasParallelMarketSetActiveMetal(row.dataset.metalRow);
      return;
    }

    const period = event.target.closest("[data-metals-period]");
    if (period) {
      event.preventDefault();
      atlasParallelMarketSetMetalsPeriod(
        period.dataset.metalsPeriod
      );
      return;
    }

    const view = event.target.closest("[data-metals-view]");
    if (view) {
      event.preventDefault();
      atlasParallelMarketSetMetalsView(
        view.dataset.metalsView
      );
      return;
    }

    const section = event.target.closest("[data-metals-section]");
    if (section) {
      event.preventDefault();
      atlasParallelMarketSetMetalsSection(
        section.dataset.metalsSection
      );
    }
  });

  state.marketDomain = atlasParallelMarketReadDomain();
  atlasParallelMarketRender();
  return true;
}

const ATLAS_METALS_REPORT_SCHEMA = "agent_crypto_metals_public_report_v1";

const ATLAS_METALS_REPORT_STORAGE_SCHEMA = "agent_crypto_metals_public_report_indexeddb_v1";

const ATLAS_METALS_REPORT_DB_NAME = "agent_crypto_metals_public_report_memory_v2";

const ATLAS_METALS_REPORT_STORE = "reports";

const ATLAS_METALS_REPORT_RECORD_ID = "current";

const ATLAS_METALS_REPORT_LIMIT_BYTES = 5 * 1024 * 1024;

const ATLAS_METALS_REPORT_INTERFACE_PATH = null;

const atlasMetalsReportState = {
  initialized: false,
  package: null,
  source: "none",
  persistence: { ok: false, bytes: 0, error: "Non enregistrée" },
  restorePromise: null,
  operation: 0
};

function atlasMetalsReportClone(value) {
  return value == null ? value : JSON.parse(JSON.stringify(value));
}

function atlasMetalsReportUtf8Bytes(text) {
  try { return new TextEncoder().encode(String(text || "")).byteLength; }
  catch { return unescape(encodeURIComponent(String(text || ""))).length; }
}

function atlasMetalsReportStableValue(value) {
  if (Array.isArray(value)) return value.map(atlasMetalsReportStableValue);
  if (value && typeof value === "object") {
    return Object.keys(value).sort().reduce((out, key) => {
      out[key] = atlasMetalsReportStableValue(value[key]);
      return out;
    }, {});
  }
  return value;
}

async function atlasMetalsReportSha256(value) {
  const canonical = JSON.stringify(atlasMetalsReportStableValue(value));
  const bytes = new TextEncoder().encode(canonical);
  const digest = await crypto.subtle.digest("SHA-256", bytes);
  return [...new Uint8Array(digest)]
    .map(byte => byte.toString(16).padStart(2, "0"))
    .join("");
}

function atlasMetalsReportIso(value) {
  const raw = String(value || "").trim();
  if (!raw) return null;
  const time = Date.parse(raw);
  return Number.isFinite(time) ? new Date(time).toISOString() : null;
}

function atlasMetalsReportDate(value) {
  const iso = atlasMetalsReportIso(value);
  if (!iso) return "—";
  return new Date(iso).toLocaleString("fr-FR", {
    day: "2-digit", month: "2-digit", year: "numeric",
    hour: "2-digit", minute: "2-digit", second: "2-digit"
  });
}

function atlasMetalsReportPrice(quote) {
  return atlasMetalsQuoteFoundationPriceText(quote);
}

function atlasMetalsReportPercent(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return "—";
  return `${number > 0 ? "+" : ""}${new Intl.NumberFormat("fr-FR", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  }).format(number)} %`;
}

function atlasMetalsReportSnapshotTime(snapshot) {
  return atlasMetalsReportIso(snapshot?.saved_at)
    || atlasMetalsReportIso(snapshot?.quotes?.[0]?.received_at)
    || atlasMetalsReportIso(snapshot?.quotes?.[0]?.source_time)
    || null;
}

function atlasMetalsReportSanitizeCollector(collector) {
  return {
    schema: String(collector?.schema || "agent_crypto_metals_collector_status_v1"),
    status: String(collector?.status || "unknown"),
    provider_id: collector?.provider_id || null,
    provider_name: collector?.provider_name || null,
    last_success_at: atlasMetalsReportIso(collector?.last_success_at),
    assets_expected: Number(collector?.assets_expected || 5),
    assets_received: Number(collector?.assets_received || 0),
    history: atlasMetalsReportClone(collector?.history || null)
  };
}

function atlasMetalsReportHistorySnapshots() {
  const snapshots = Array.isArray(atlasMetalsQuoteFoundationState.history)
    ? atlasMetalsQuoteFoundationState.history
    : [];
  const map = new Map();
  snapshots.filter(Boolean).forEach(snapshot => {
    const quotes = Array.isArray(snapshot?.quotes) ? snapshot.quotes : [];
    if (!quotes.length || quotes.some(quote => quote?.instrument_type !== "future_continuous")) return;
    const key = String(
      snapshot?.snapshot_id
      || atlasMetalsReportSnapshotTime(snapshot)
      || JSON.stringify(quotes)
    );
    if (key) map.set(key, atlasMetalsReportClone(snapshot));
  });
  return [...map.values()].sort((left, right) => {
    return Date.parse(atlasMetalsReportSnapshotTime(left) || 0)
      - Date.parse(atlasMetalsReportSnapshotTime(right) || 0);
  });
}

function atlasMetalsReportHistoryForAsset(assetId, snapshots) {
  return snapshots.map(snapshot => {
    const quote = (Array.isArray(snapshot?.quotes) ? snapshot.quotes : [])
      .find(row => row?.asset_id === assetId && Number.isFinite(Number(row?.price)));
    if (!quote) return null;
    return {
      time: atlasMetalsReportSnapshotTime(snapshot)
        || atlasMetalsReportIso(quote.received_at)
        || atlasMetalsReportIso(quote.source_time),
      price: Number(quote.price),
      currency: String(quote.currency || "").toUpperCase(),
      unit: String(quote.unit || "")
    };
  }).filter(row => row?.time && Number.isFinite(row.price));
}

function atlasMetalsReportHistoryReading(points) {
  if (points.length < 2) {
    return {
      count: points.length,
      change_percent: null,
      label: points.length === 1
        ? "1 relevé réel · trajectoire non calculable"
        : "aucun relevé historique exploitable"
    };
  }
  const first = points[0];
  const last = points[points.length - 1];
  const change = first.price !== 0
    ? ((last.price - first.price) / first.price) * 100
    : null;
  return {
    count: points.length,
    change_percent: Number.isFinite(change) ? change : null,
    label: Number.isFinite(change)
      ? `${points.length} séances Futures · évolution observée ${atlasMetalsReportPercent(change)}`
      : `${points.length} séances Futures · évolution non calculable`
  };
}

function atlasMetalsReportAssetRows(snapshot, historySnapshots) {
  const quotes = Array.isArray(snapshot?.quotes) ? snapshot.quotes : [];
  return ATLAS_METALS_ASSETS.map(base => {
    const quote = quotes.find(row => row?.asset_id === base.id) || null;
    const structure = atlasMetalsStructuralAsset(base.id) || {};
    const points = atlasMetalsReportHistoryForAsset(base.id, historySnapshots);
    const history = atlasMetalsReportHistoryReading(points);
    return {
      id: base.id,
      name: base.name,
      symbol: base.symbol,
      family: base.family,
      quote: quote ? {
        asset_id: base.id,
        symbol: base.symbol,
        price: Number.isFinite(Number(quote.price)) ? Number(quote.price) : null,
        price_eur: Number.isFinite(Number(quote.price_eur)) ? Number(quote.price_eur) : null,
        fx_source_date: quote.fx_source_date || null,
        currency: String(quote.currency || "").toUpperCase(),
        unit: String(quote.unit || ""),
        change_percent:
          quote.change_percent !== null
          && quote.change_percent !== undefined
          && quote.change_percent !== ""
          && Number.isFinite(Number(quote.change_percent))
            ? Number(quote.change_percent)
            : null,
        data_state: String(quote.data_state || "unknown"),
        source_id: quote.source_id || quote.provider_id || null,
        source_name: quote.source_name || quote.provider_name || null,
        source_time: atlasMetalsReportIso(quote.source_time),
        received_at: atlasMetalsReportIso(quote.received_at)
      } : null,
      history,
      history_points: points,
      structure: {
        production: String(structure?.production?.display || "—"),
        reserves: String(structure?.reserves?.display || "—"),
        producers: String(structure?.production?.top_display || "—"),
        uses: String(structure?.uses?.display || "—"),
        eu_status: String(structure?.eu_status?.display || "—"),
        source_ids: Array.isArray(structure?.source_ids)
          ? [...structure.source_ids]
          : []
      }
    };
  });
}

function atlasMetalsReportWarnings(assets, snapshot, historySnapshots) {
  const warnings = [];
  const delayed = assets.filter(asset => asset.quote?.data_state === "data_delayed");
  if (delayed.length) {
    warnings.push(`Cotations différées : ${delayed.map(asset => asset.symbol).join(" / ")}.`);
  }
  const missing = assets.filter(asset => !Number.isFinite(Number(asset.quote?.price)));
  if (missing.length) {
    warnings.push(`Cotations absentes : ${missing.map(asset => asset.symbol).join(" / ")}.`);
  }
  if (historySnapshots.length < 2) {
    warnings.push("Historique insuffisant : une seule séance Futures ne permet pas d’établir une trajectoire.");
  }
  const currencies = new Set(assets.map(asset => asset.quote?.currency).filter(Boolean));
  if (currencies.size > 1) warnings.push("Unités monétaires multiples : comparaison directe des niveaux de prix interdite.");
  if (snapshot?.integrity?.no_invented_values !== true) {
    warnings.push("Verrou anti-invention absent du snapshot.");
  }
  return warnings;
}

function atlasMetalsReportBuildMarkdown(pkg) {
  const assets = pkg.assets;
  const warnings = pkg.warnings;
  const historyCount = pkg.history.length;
  const quoteLines = assets.map(asset => {
    const providerChange = asset.quote?.change_percent;
    const providerChangeAvailable =
      providerChange !== null
      && providerChange !== undefined
      && providerChange !== ""
      && Number.isFinite(Number(providerChange));
    const providerPart = providerChangeAvailable
      ? ` · variation fournisseur ${atlasMetalsReportPercent(providerChange)}`
      : " · variation fournisseur non fournie";
    const eurPart = Number.isFinite(Number(asset.quote?.price_eur))
      ? ` · ${atlasMetalsQuoteFoundationEurText(asset.quote)} indicatif BCE`
      : "";
    return `- ${asset.name} (${asset.symbol}) : ${atlasMetalsReportPrice(asset.quote)}${eurPart}${providerPart} · ${atlasMetalsQuoteFoundationStateLabel(asset.quote)}.`;
  });
  const historyLines = assets.map(asset => `- ${asset.symbol} : ${asset.history.label}.`);
  const structureLines = assets.map(asset => {
    return `- ${asset.symbol} : production ${asset.structure.production} · réserves ${asset.structure.reserves} · producteurs ${asset.structure.producers} · usages ${asset.structure.uses} · UE ${asset.structure.eu_status}.`;
  });
  const warningLines = warnings.length
    ? warnings.map(item => `- ${item}`)
    : ["- Aucune incohérence bloquante détectée dans le paquet 5/5."];
  const watchLines = [
    "- Vérifier l’âge du dernier snapshot public et l’état du collecteur.",
    "- Contrôler la continuité des cinq symboles XAU / XAG / XPT / XPD / HG.",
    "- Comparer les trajectoires uniquement dans la série Futures quotidienne homogène.",
    "- Distinguer cotations spot, futures US, conversion BCE et données structurelles."
  ];
  const complete = assets.every(asset => Number.isFinite(Number(asset.quote?.price)));
  const conclusion = complete
    ? (historyCount >= 2
      ? "Le panier Métaux est complet 5/5. Les variations historiques affichées reposent uniquement sur la série Futures quotidienne conservée ; elles décrivent l’état observé et non une évolution future."
      : "Le panier Métaux est complet 5/5, mais l’historique reste trop court pour qualifier une trajectoire. Le rapport décrit uniquement le snapshot observé.")
    : "Le panier Métaux est incomplet. Le rapport conserve les données disponibles sans remplacer les valeurs absentes.";

  return [
    "**1. État de la collecte**",
    `- Origine : ${pkg.origin.label}.`,
    `- Snapshot : ${atlasMetalsReportDate(pkg.snapshot_at)} · couverture ${pkg.status.quotes}/5.`,
    `- Source de cotation : ${pkg.source.provider_name || "Sources publiques"} · état ${pkg.source.status}.`,
    "- La lecture du rapport ne déclenche aucune requête fournisseur : les données sont déjà publiées par GitHub Actions.",
    "",
    "**2. Panier Métaux précieux et industriels**",
    ...quoteLines,
    "",
    "**3. Lecture des cotations**",
    `- ${complete ? "Les cinq cotations attendues sont présentes." : "Le panier contient des valeurs manquantes."}`,
    "- Les niveaux de prix sont conservés dans leur devise et leur unité source ; la conversion EUR BCE reste informative.",
    "- La variation fournisseur, lorsqu’elle est fournie, reste séparée de la variation calculée sur l’historique Futures public.",
    "",
    "**4. Historique réel et comparaison**",
    `- ${historyCount} séance${historyCount > 1 ? "s" : ""} Futures quotidienne${historyCount > 1 ? "s" : ""} conservée${historyCount > 1 ? "s" : ""}.`,
    ...historyLines,
    "",
    "**5. Structure physique et sources publiques**",
    ...structureLines,
    `- Sources préparées : ${pkg.source.public_sources.join(" · ")}.`,
    "",
    "**6. Contradictions et données manquantes**",
    ...warningLines,
    "",
    "**7. Ce qu’il faut surveiller ensuite**",
    ...watchLines,
    "",
    "**8. Limites et stop point**",
    "- Observation uniquement : aucune prévision, aucun ordre et aucun signal d’exécution.",
    "- Arrêter toute comparaison si les dates, devises, unités ou états de données ne sont plus cohérents.",
    "- Les données structurelles décrivent production, réserves et usages ; elles ne remplacent jamais une cotation de marché.",
    "- Validation humaine uniquement avant une décision ou action financière réelle ; la lecture du rapport reste automatique.",
    "",
    "**9. Conclusion du rapport Métaux public**",
    `- ${conclusion}`
  ].join("\n");
}

async function atlasMetalsReportBuildPackage() {
  const snapshot = atlasMetalsReportClone(atlasMetalsQuoteFoundationState.snapshot);
  if (!snapshot) throw new Error("snapshot Métaux absent");
  const history = atlasMetalsReportHistorySnapshots();
  const assets = atlasMetalsReportAssetRows(snapshot, history);
  const quoteCount = assets.filter(asset => Number.isFinite(Number(asset.quote?.price))).length;
  if (quoteCount !== 5) throw new Error(`panier Métaux incomplet : ${quoteCount}/5`);
  const publicSources = atlasMetalsStructuralArray(atlasMetalsStructuralRegistry()?.sources)
    .map(source => String(source?.short_name || source?.name || "").trim())
    .filter(Boolean);
  const snapshotAt = atlasMetalsReportSnapshotTime(snapshot);
  const source = atlasMetalsReportSanitizeCollector(atlasMetalsQuoteFoundationState.collector);
  const signature = {
    schema: ATLAS_METALS_REPORT_SCHEMA,
    snapshot,
    history,
    structural_version: atlasMetalsStructuralRegistry()?.version || null,
    assets: assets.map(asset => ({
      id: asset.id,
      quote: asset.quote,
      history_points: asset.history_points,
      structure: asset.structure
    }))
  };
  const fingerprint = `sha256:${await atlasMetalsReportSha256(signature)}`;
  const pkg = {
    schema: ATLAS_METALS_REPORT_SCHEMA,
    storage_schema: ATLAS_METALS_REPORT_STORAGE_SCHEMA,
    build: ATLAS_BUILD,
    generated_at: new Date().toISOString(),
    snapshot_at: snapshotAt,
    fingerprint,
    origin: {
      machine: atlasMetalsQuoteFoundationState.origin === "github_archive" ? "github_actions" : "local_cache",
      label: atlasMetalsQuoteFoundationState.origin === "github_archive"
        ? "GitHub Actions · Public Metals Archive"
        : "Cache local complémentaire",
      mode: atlasMetalsQuoteFoundationState.origin
    },
    status: {
      quotes: quoteCount,
      expected: 5,
      history_snapshots: history.length,
      observation_only: true,
      human_validation_required: true,
      provider_requests_for_report: 0
    },
    source: {
      status: source.status,
      provider_id: source.provider_id || snapshot?.provider_id || null,
      provider_name: source.provider_name || snapshot?.provider_name || "Sources publiques",
      last_success_at: source.last_success_at || snapshotAt,
      public_sources: [...new Set(publicSources)]
    },
    snapshot,
    history,
    collector: source,
    assets,
    warnings: atlasMetalsReportWarnings(assets, snapshot, history),
    report_markdown: ""
  };
  pkg.report_markdown = atlasMetalsReportBuildMarkdown(pkg);
  return pkg;
}

async function atlasMetalsReportValidatePackage(input) {
  if (!input || input.schema !== ATLAS_METALS_REPORT_SCHEMA) {
    throw new Error("ce fichier n’est pas un rapport Métaux public");
  }
  if (String(input?.source?.provider_id || input?.snapshot?.provider_id || "") === "metals_dev") {
    throw new Error("ancien rapport Metals.Dev classé archive historique");
  }
  const text = JSON.stringify(input);
  if (atlasMetalsReportUtf8Bytes(text) > ATLAS_METALS_REPORT_LIMIT_BYTES) {
    throw new Error("rapport Métaux trop volumineux");
  }
  const hasForbiddenSecretKey = value => {
    if (Array.isArray(value)) return value.some(hasForbiddenSecretKey);
    if (!value || typeof value !== "object") return false;
    return Object.entries(value).some(([key, child]) => {
      if (/^(?:api[_-]?key|access[_-]?token|github[_-]?token|password|secret)$/i.test(key)) return true;
      return hasForbiddenSecretKey(child);
    });
  };
  if (hasForbiddenSecretKey(input)) {
    throw new Error("champ secret interdit dans la mémoire Métaux");
  }
  const snapshot = atlasMetalsQuoteFoundationValidateSnapshot(input.snapshot);
  const history = (Array.isArray(input.history) ? input.history : [])
    .map(atlasMetalsQuoteFoundationValidateSnapshot);
  if (!String(input.report_markdown || "").trim()) throw new Error("rapport Métaux absent");
  if (!String(input.fingerprint || "").startsWith("sha256:")) throw new Error("empreinte Métaux absente");
  const signature = {
    schema: ATLAS_METALS_REPORT_SCHEMA,
    snapshot,
    history,
    structural_version: atlasMetalsStructuralRegistry()?.version || null,
    assets: (Array.isArray(input.assets) ? input.assets : []).map(asset => ({
      id: asset.id,
      quote: asset.quote,
      history_points: asset.history_points,
      structure: asset.structure
    }))
  };
  const expected = `sha256:${await atlasMetalsReportSha256(signature)}`;
  if (expected !== input.fingerprint) throw new Error("empreinte Métaux différente");
  return {
    ...atlasMetalsReportClone(input),
    snapshot,
    history
  };
}

function atlasMetalsReportOpenDb() {
  return new Promise((resolve, reject) => {
    if (!window.indexedDB) return reject(new Error("IndexedDB indisponible"));
    const request = indexedDB.open(ATLAS_METALS_REPORT_DB_NAME, ATLAS_METALS_REPORT_DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(ATLAS_METALS_REPORT_STORE)) {
        db.createObjectStore(ATLAS_METALS_REPORT_STORE, { keyPath: "id" });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error("ouverture IndexedDB refusée"));
    request.onblocked = () => reject(new Error("IndexedDB bloquée par un autre onglet"));
  });
}

async function atlasMetalsReportDbGet() {
  const db = await atlasMetalsReportOpenDb();
  try {
    return await new Promise((resolve, reject) => {
      const tx = db.transaction(ATLAS_METALS_REPORT_STORE, "readonly");
      const request = tx.objectStore(ATLAS_METALS_REPORT_STORE).get(ATLAS_METALS_REPORT_RECORD_ID);
      request.onsuccess = () => resolve(request.result || null);
      request.onerror = () => reject(request.error || new Error("lecture IndexedDB refusée"));
    });
  } finally { db.close(); }
}

async function atlasMetalsReportDbPut(pkg) {
  const text = JSON.stringify(pkg);
  const bytes = atlasMetalsReportUtf8Bytes(text);
  if (bytes > ATLAS_METALS_REPORT_LIMIT_BYTES) throw new Error("mémoire Métaux trop volumineuse");
  const db = await atlasMetalsReportOpenDb();
  try {
    await new Promise((resolve, reject) => {
      const tx = db.transaction(ATLAS_METALS_REPORT_STORE, "readwrite");
      tx.objectStore(ATLAS_METALS_REPORT_STORE).put({
        id: ATLAS_METALS_REPORT_RECORD_ID,
        package: pkg,
        fingerprint: pkg.fingerprint,
        saved_at: new Date().toISOString()
      });
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error || new Error("écriture IndexedDB refusée"));
      tx.onabort = () => reject(tx.error || new Error("écriture IndexedDB annulée"));
    });
    const record = await atlasMetalsReportDbGet();
    const verified = await atlasMetalsReportValidatePackage(record?.package);
    return { ok: true, bytes, package: verified };
  } finally { db.close(); }
}

function atlasMetalsReportSetStatus(stateName, message, badgeText) {
  const card = document.getElementById("atlasMetalsReportCard");
  const status = document.getElementById("atlasMetalsReportStatus");
  const badge = document.getElementById("atlasMetalsReportBadge");
  if (card) card.dataset.state = stateName;
  if (status) status.textContent = message;
  if (badge) {
    badge.textContent = badgeText;
    badge.className = `pill ${stateName === "ready" ? "ok" : stateName === "warning" || stateName === "error" ? "warn" : ""}`.trim();
  }
}

function atlasMetalsReportHydrateQuoteState(pkg, origin = "book_memory") {
  if (!pkg?.snapshot) return false;
  atlasMetalsQuoteFoundationState.snapshot = pkg.snapshot;
  atlasMetalsQuoteFoundationState.collector = pkg.collector || null;
  atlasMetalsQuoteFoundationState.historyIndex = null;
  atlasMetalsQuoteFoundationState.history = Object.freeze([...(pkg.history || [])]);
  atlasMetalsQuoteFoundationState.contract = atlasMetalsQuoteFoundationState.contract || null;
  atlasMetalsQuoteFoundationState.quotes = Object.freeze([...(pkg.snapshot.quotes || [])]);
  atlasMetalsQuoteFoundationState.status = "loaded";
  atlasMetalsQuoteFoundationState.origin = origin;
  atlasMetalsQuoteFoundationState.loadedAt = new Date().toISOString();
  atlasMetalsQuoteFoundationState.error = null;
  atlasParallelMarketRenderMetals();
  return true;
}

function atlasMetalsReportEscapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function atlasMetalsReportComparisonForAsset(asset) {
  const points = (Array.isArray(asset?.history_points) ? asset.history_points : [])
    .filter(point => point?.time && Number.isFinite(Number(point?.price)))
    .map(point => ({
      time: atlasMetalsReportIso(point.time),
      price: Number(point.price),
      currency: String(point.currency || asset?.quote?.currency || "").toUpperCase(),
      unit: String(point.unit || asset?.quote?.unit || "")
    }))
    .filter(point => point.time)
    .sort((left, right) => Date.parse(left.time) - Date.parse(right.time));

  if (points.length < 2) {
    return {
      comparable: false,
      previous: points.at(-1) || null,
      latest: points.at(-1) || null,
      delta_value: null,
      delta_percent: null,
      direction: "insufficient"
    };
  }

  const previous = points.at(-2);
  const latest = points.at(-1);
  const coherent = previous.currency === latest.currency && previous.unit === latest.unit;
  if (!coherent) {
    return {
      comparable: false,
      previous,
      latest,
      delta_value: null,
      delta_percent: null,
      direction: "incoherent"
    };
  }

  const deltaValue = latest.price - previous.price;
  const deltaPercent = previous.price !== 0
    ? (deltaValue / previous.price) * 100
    : null;
  const epsilon = Math.max(Math.abs(previous.price), Math.abs(latest.price), 1) * 1e-12;
  const direction = Math.abs(deltaValue) <= epsilon
    ? "stable"
    : deltaValue > 0 ? "up" : "down";

  return {
    comparable: true,
    previous,
    latest,
    delta_value: deltaValue,
    delta_percent: Number.isFinite(deltaPercent) ? deltaPercent : null,
    direction
  };
}

function atlasMetalsReportSignedValue(value, point) {
  const number = Number(value);
  if (!Number.isFinite(number)) return "—";
  const absolute = Math.abs(number);
  const maximumFractionDigits = absolute >= 1000 ? 2 : absolute >= 100 ? 3 : absolute >= 1 ? 4 : 6;
  const formatted = new Intl.NumberFormat("fr-FR", {
    minimumFractionDigits: 0,
    maximumFractionDigits
  }).format(absolute);
  const sign = number > 0 ? "+" : number < 0 ? "−" : "";
  const currency = String(point?.currency || "").toUpperCase();
  return `${sign}${formatted}${currency ? ` ${currency}` : ""}`;
}

function atlasMetalsReportComparisonDirection(direction) {
  if (direction === "up") return { label: "Hausse", className: "is-up", symbol: "↗" };
  if (direction === "down") return { label: "Baisse", className: "is-down", symbol: "↘" };
  if (direction === "stable") return { label: "Stable", className: "is-stable", symbol: "→" };
  if (direction === "incoherent") return { label: "Incohérent", className: "is-warning", symbol: "!" };
  return { label: "Insuffisant", className: "is-warning", symbol: "·" };
}

function atlasMetalsReportSnapshotCoverage(snapshot) {
  const expected = new Set(["gold", "silver", "platinum", "palladium", "copper"]);
  const received = new Set(
    (Array.isArray(snapshot?.quotes) ? snapshot.quotes : [])
      .filter(quote => expected.has(quote?.asset_id) && Number.isFinite(Number(quote?.price)))
      .map(quote => quote.asset_id)
  );
  return `${received.size}/5`;
}

function atlasMetalsReportRenderComparison(pkg) {
  const rows = document.getElementById("atlasMetalsComparisonRows");
  const windowText = document.getElementById("atlasMetalsComparisonWindow");
  const summary = document.getElementById("atlasMetalsComparisonSummary");
  const strip = document.getElementById("atlasMetalsSnapshotStrip");
  const note = document.getElementById("atlasMetalsComparisonNote");
  if (!rows || !windowText || !summary || !strip) return false;

  const assets = Array.isArray(pkg?.assets) ? pkg.assets : [];
  const comparisons = assets.map(asset => ({
    asset,
    comparison: atlasMetalsReportComparisonForAsset(asset)
  }));
  const comparable = comparisons.filter(item => item.comparison.comparable);
  const counts = comparable.reduce((accumulator, item) => {
    accumulator[item.comparison.direction] = (accumulator[item.comparison.direction] || 0) + 1;
    return accumulator;
  }, { up: 0, down: 0, stable: 0 });

  if (!assets.length) {
    rows.innerHTML = '<tr><td colspan="6">Aucune comparaison disponible.</td></tr>';
  } else {
    rows.innerHTML = comparisons.map(({ asset, comparison }) => {
      const direction = atlasMetalsReportComparisonDirection(comparison.direction);
      const previous = comparison.previous ? atlasMetalsReportPrice(comparison.previous) : "—";
      const latest = comparison.latest ? atlasMetalsReportPrice(comparison.latest) : "—";
      const delta = atlasMetalsReportSignedValue(comparison.delta_value, comparison.latest);
      const percent = atlasMetalsReportPercent(comparison.delta_percent);
      return `
        <tr data-direction="${atlasMetalsReportEscapeHtml(comparison.direction)}">
          <td><b>${atlasMetalsReportEscapeHtml(asset?.symbol || "—")}</b><span>${atlasMetalsReportEscapeHtml(asset?.name || asset?.id || "Métal")}</span></td>
          <td>${atlasMetalsReportEscapeHtml(previous)}</td>
          <td>${atlasMetalsReportEscapeHtml(latest)}</td>
          <td>${atlasMetalsReportEscapeHtml(delta)}</td>
          <td>${atlasMetalsReportEscapeHtml(percent)}</td>
          <td><span class="atlas-metals-trend ${direction.className}"><i aria-hidden="true">${direction.symbol}</i>${direction.label}</span></td>
        </tr>`;
    }).join("");
  }

  const comparableTimes = comparable
    .flatMap(item => [item.comparison.previous?.time, item.comparison.latest?.time])
    .filter(Boolean)
    .sort((left, right) => Date.parse(left) - Date.parse(right));
  const previousAt = comparableTimes[0] || null;
  const latestAt = comparableTimes.at(-1) || null;
  windowText.textContent = comparable.length
    ? `Comparaison du ${atlasMetalsReportDate(previousAt)} au ${atlasMetalsReportDate(latestAt)} · ${comparable.length}/5 métaux cohérents.`
    : "Historique insuffisant ou unités incohérentes : aucune variation calculée.";

  summary.textContent = comparable.length
    ? `↑ ${counts.up} · ↓ ${counts.down} · → ${counts.stable}`
    : "0 comparé";
  summary.className = `pill ${comparable.length === 5 ? "ok" : "warn"}`;

  const snapshots = (Array.isArray(pkg?.history) ? pkg.history : [])
    .filter(Boolean)
    .map(snapshot => ({
      snapshot,
      time: atlasMetalsReportSnapshotTime(snapshot)
    }))
    .filter(item => item.time)
    .sort((left, right) => Date.parse(left.time) - Date.parse(right.time))
    .slice(-8);
  strip.innerHTML = snapshots.length
    ? snapshots.map((item, index) => `
        <span class="${index === snapshots.length - 1 ? "is-latest" : ""}">
          <b>${atlasMetalsReportEscapeHtml(atlasMetalsReportDate(item.time))}</b>
          <small>${atlasMetalsReportEscapeHtml(atlasMetalsReportSnapshotCoverage(item.snapshot))} réel</small>
        </span>`).join("")
    : "<span>Aucune séance Futures conservée.</span>";

  if (note) {
    note.textContent = comparable.length === 5
      ? "Écarts calculés entre les deux dernières séances Futures réelles de chaque métal · aucune prévision · aucune requête fournisseur."
      : "Comparaison suspendue pour toute série incomplète ou incohérente · aucune valeur remplacée ou inventée.";
  }
  return true;
}

function atlasMetalsReportRender() {
  const pkg = atlasMetalsReportState.package;
  const content = document.getElementById("atlasMetalsReportContent");
  if (!pkg) {
    if (content) content.innerHTML = '<p class="atlas-local-response-empty">Aucun rapport Métaux public disponible. Il apparaîtra automatiquement après la première collecte publique complète 5/5.</p>';
    setText(document.getElementById("atlasMetalsReportSnapshot"), "—");
    setText(document.getElementById("atlasMetalsReportOrigin"), "—");
    setText(document.getElementById("atlasMetalsReportQuotes"), "0/5");
    setText(document.getElementById("atlasMetalsReportHistory"), "0 séance Futures");
    setText(document.getElementById("atlasMetalsReportPersistence"), "Non enregistrée");
    atlasMetalsReportRenderComparison(null);
    ["btnAtlasMetalsReportCopy", "btnAtlasMetalsReportExportMd"]
      .forEach(id => document.getElementById(id)?.setAttribute("disabled", ""));
    return false;
  }
  if (content) content.innerHTML = atlasLocalReportHtml(pkg.report_markdown);
  atlasMetalsReportRenderComparison(pkg);
  setText(document.getElementById("atlasMetalsReportSnapshot"), atlasMetalsReportDate(pkg.snapshot_at));
  setText(document.getElementById("atlasMetalsReportOrigin"), pkg.origin?.label || "Archive publique");
  setText(document.getElementById("atlasMetalsReportQuotes"), `${pkg.status?.quotes || 0}/5`);
  const count = Number(pkg.status?.history_snapshots || pkg.history?.length || 0);
  setText(document.getElementById("atlasMetalsReportHistory"), `${count} séances Futures`);
  setText(
    document.getElementById("atlasMetalsReportPersistence"),
    atlasMetalsReportState.persistence.ok
      ? `IndexedDB · ${Math.max(1, Math.round(atlasMetalsReportState.persistence.bytes / 1024))} Ko vérifiés`
      : "IndexedDB · non vérifiée"
  );
  ["btnAtlasMetalsReportCopy", "btnAtlasMetalsReportExportMd"]
    .forEach(id => document.getElementById(id)?.removeAttribute("disabled"));
  return true;
}

async function atlasMetalsReportActivate(pkg, source, persist = true) {
  const clean = await atlasMetalsReportValidatePackage(pkg);
  atlasMetalsReportState.package = clean;
  atlasMetalsReportState.source = source;
  atlasMetalsReportState.persistence = { ok: false, bytes: 0, error: "Non vérifiée" };
  atlasMetalsReportRender();
  if (persist) {
    const saved = await atlasMetalsReportDbPut(clean);
    atlasMetalsReportState.package = saved.package;
    atlasMetalsReportState.persistence = { ok: true, bytes: saved.bytes, error: "" };
  }
  atlasMetalsReportHydrateQuoteState(
    atlasMetalsReportState.package,
    source === "public" ? "github_archive"
      : source === "local" ? "local_bridge"
        : source === "indexeddb" ? "book_memory"
          : "book_memory"
  );
  atlasMetalsReportRender();
  const label = source === "public" ? "Publique" : source === "local" ? "Locale" : source === "indexeddb" ? "Restaurée" : "Importée";
  atlasMetalsReportSetStatus(
    "ready",
    `${label} · rapport Métaux ${clean.status.quotes}/5 · ${clean.status.history_snapshots} séance${clean.status.history_snapshots > 1 ? "s" : ""} Futures · IndexedDB vérifiée.`,
    label
  );
  return clean;
}

async function atlasMetalsReportLoadFromInterface() {
  if (!ATLAS_METALS_REPORT_INTERFACE_PATH) return null;
  try {
    const separator = ATLAS_METALS_REPORT_INTERFACE_PATH.includes("?") ? "&" : "?";
    const response = await fetch(
      `${ATLAS_METALS_REPORT_INTERFACE_PATH}${separator}build=${encodeURIComponent(ATLAS_BUILD)}`,
      { cache: "no-store", headers: { "Accept": "application/json" } }
    );
    if (!response.ok) throw new Error(`mémoire Interface indisponible (${response.status})`);
    const candidate = await atlasMetalsReportValidatePackage(await response.json());
    const current = atlasMetalsReportState.package;
    const candidateTime = Date.parse(candidate.snapshot_at || candidate.generated_at || 0) || 0;
    const currentTime = Date.parse(current?.snapshot_at || current?.generated_at || 0) || 0;
    if (current && currentTime > candidateTime) return current;
    await atlasMetalsReportActivate(candidate, "interface", true);
    atlasMetalsReportSetStatus(
      "ready",
      `Inscrite dans l’Interface · rapport Métaux ${candidate.status.quotes}/5 · lecture automatique sur ce poste.`,
      "Inscrite"
    );
    return candidate;
  } catch (error) {
    if (!atlasMetalsReportState.package) {
      atlasMetalsReportSetStatus("warning", `Rapport Interface indisponible : ${error?.message || error}.`, "À vérifier");
    }
    return null;
  }
}

async function atlasMetalsReportRestore() {
  atlasMetalsReportSetStatus("working", "Restauration de la mémoire Métaux…", "Restauration");
  try {
    const record = await atlasMetalsReportDbGet();
    if (!record?.package) {
      atlasMetalsReportSetStatus("empty", "En attente de la première collecte publique complète 5/5 · aucune publication manuelle requise.", "Prêt");
      return null;
    }
    const clean = await atlasMetalsReportValidatePackage(record.package);
    atlasMetalsReportState.package = clean;
    atlasMetalsReportState.source = "indexeddb";
    atlasMetalsReportState.persistence = {
      ok: true,
      bytes: atlasMetalsReportUtf8Bytes(JSON.stringify(clean)),
      error: ""
    };
    atlasMetalsReportHydrateQuoteState(clean, "book_memory");
    atlasMetalsReportRender();
    atlasMetalsReportSetStatus("ready", `Restaurée depuis IndexedDB · rapport Métaux ${clean.status.quotes}/5 disponible.`, "Restaurée");
    return clean;
  } catch (error) {
    atlasMetalsReportState.persistence = { ok: false, bytes: 0, error: String(error?.message || error) };
    atlasMetalsReportRender();
    atlasMetalsReportSetStatus("warning", `IndexedDB indisponible : ${atlasMetalsReportState.persistence.error}. Les données publiques restent consultables en ligne.`, "À vérifier");
    return null;
  }
}

async function atlasMetalsReportProduceFromCurrent() {
  if (!["github_archive", "local_bridge"].includes(atlasMetalsQuoteFoundationState.origin)) return false;
  const count = atlasMetalsQuoteFoundationSummary().quoteCount;
  if (count !== 5) return false;
  const operation = ++atlasMetalsReportState.operation;
  atlasMetalsReportSetStatus("working", "Données publiques 5/5 reçues · construction du rapport Métaux…", "Construction");
  try {
    const pkg = await atlasMetalsReportBuildPackage();
    if (operation !== atlasMetalsReportState.operation) return false;
    if (atlasMetalsReportState.package?.fingerprint === pkg.fingerprint) {
      atlasMetalsReportHydrateQuoteState(atlasMetalsReportState.package, atlasMetalsQuoteFoundationState.origin);
      atlasMetalsReportRender();
      atlasMetalsReportSetStatus("ready", "Rapport Métaux déjà inscrit pour ce snapshot · aucune nouvelle requête fournisseur.", "Conservé");
      return true;
    }
    await atlasMetalsReportActivate(pkg, atlasMetalsQuoteFoundationState.origin === "github_archive" ? "public" : "local", true);
    return true;
  } catch (error) {
    atlasMetalsReportSetStatus("warning", `Rapport non inscrit : ${error?.message || error}. Les cotations restent disponibles.`, "À vérifier");
    return false;
  }
}

async function atlasMetalsReportCopy() {
  const text = atlasMetalsReportState.package?.report_markdown || "";
  if (!text) return;
  try { await navigator.clipboard.writeText(text); }
  catch {
    const area = document.createElement("textarea");
    area.value = text;
    area.style.position = "fixed";
    area.style.opacity = "0";
    document.body.appendChild(area);
    area.select();
    document.execCommand("copy");
    area.remove();
  }
  atlasMetalsReportSetStatus("ready", "Rapport Métaux copié.", "Conservé");
}

function atlasMetalsReportExportJson() {
  const pkg = atlasMetalsReportState.package;
  if (!pkg) return;
  const stamp = new Date(pkg.snapshot_at || pkg.generated_at || Date.now())
    .toISOString().replace(/[:.]/g, "-");
  downloadTextFile(
    `agent_crypto_metals_report_${stamp}.json`,
    "application/json;charset=utf-8",
    JSON.stringify(pkg, null, 2)
  );
  atlasMetalsReportSetStatus("ready", "JSON du rapport Métaux exporté · aucune requête fournisseur.", "Exportée");
}

function atlasMetalsReportExportMd() {
  const pkg = atlasMetalsReportState.package;
  if (!pkg) return;
  const stamp = new Date(pkg.snapshot_at || pkg.generated_at || Date.now())
    .toISOString().replace(/[:.]/g, "-");
  const text = [
    "# Rapport Métaux public",
    "",
    `- Interface : ${ATLAS_RELEASE}`,
    `- Snapshot : ${atlasMetalsReportDate(pkg.snapshot_at)}`,
    `- Origine : ${pkg.origin?.label || "Archive publique"}`,
    `- Empreinte : ${pkg.fingerprint}`,
    "- Mode : observation uniquement",
    "",
    pkg.report_markdown
  ].join("\n");
  downloadTextFile(`agent_crypto_metals_report_${stamp}.md`, "text/markdown;charset=utf-8", text);
  atlasMetalsReportSetStatus("ready", "Rapport Métaux Markdown exporté.", "Exportée");
}

async function atlasMetalsReportImportFile(file) {
  if (!file) return false;
  if (file.size > ATLAS_METALS_REPORT_LIMIT_BYTES) throw new Error("fichier Métaux trop volumineux");
  const input = JSON.parse(await file.text());
  await atlasMetalsReportActivate(input, "import", true);
  return true;
}

function atlasMetalsReportInit() {
  if (atlasMetalsReportState.initialized) return atlasMetalsReportState.restorePromise;
  atlasMetalsReportState.initialized = true;
  document.getElementById("btnAtlasMetalsReportCopy")?.addEventListener("click", atlasMetalsReportCopy);
  document.getElementById("btnAtlasMetalsReportExportMd")?.addEventListener("click", atlasMetalsReportExportMd);
  atlasMetalsReportRender();
  atlasMetalsReportState.restorePromise = (async () => {
    await atlasMetalsReportRestore();
    return atlasMetalsReportState.package;
  })();
  return atlasMetalsReportState.restorePromise;
}

function atlasMetalsQuoteFoundationSummary() {
  const summary = atlasMetalsQuoteFoundationSummaryCore();
  if (!["book_memory", "interface_memory"].includes(atlasMetalsQuoteFoundationState.origin) || summary.quoteCount < 1) return summary;
  return {
    quoteCount: summary.quoteCount,
    short: `Archive publique ${summary.quoteCount}/5`,
    domain: `${summary.quoteCount}/5 cotations restaurées depuis le rapport public Métaux`,
    market: `${summary.quoteCount}/5 cotations conservées · historique public annuel`,
    truth: `${summary.quoteCount}/5 cotations réelles restaurées depuis GitHub / IndexedDB`
  };
}

async function atlasMetalsQuoteFoundationLoad() {
  const status = await atlasMetalsQuoteFoundationLoadCore();
  await atlasMetalsReportState.restorePromise;
  if (["local_bridge", "github_archive"].includes(atlasMetalsQuoteFoundationState.origin)
      && atlasMetalsQuoteFoundationSummary().quoteCount === 5) {
    await atlasMetalsReportProduceFromCurrent();
  } else if (atlasMetalsReportState.package
      && atlasMetalsQuoteFoundationSummary().quoteCount === 0) {
    atlasMetalsReportHydrateQuoteState(atlasMetalsReportState.package, "book_memory");
  }
  return status;
}

async function atlasMetalsQuoteFoundationReloadHistory() {
  const ok = await atlasMetalsQuoteFoundationReloadHistoryCore();
  if (ok) await atlasMetalsReportProduceFromCurrent();
  return ok;
}

