const MARKET_CACHE_KEY = "agent_crypto_erith_ia_market_cache_top250_v4";

const LEGACY_MARKET_CACHE_KEYS = ["agent_crypto_erith_ia_market_cache_top50_v2", "agent_crypto_erith_ia_market_cache_v1_1_alpha_26_37_top50", "agent_crypto_erith_ia_market_cache_v1_1_alpha_26_36_atomic_250", "agent_crypto_erith_ia_market_cache_cmc_top50_v2"];

function saveMarketCache() {
  if (!state.coins?.length || !["direct", "github-public"].includes(state.sourceLock?.mode) || !atlasCanonicalSnapshot(state.coins)) return;
  try {
    localStorage.setItem(MARKET_CACHE_KEY, JSON.stringify({
      schema: "atlas_market_cache_top250_v1",
      version: ATLAS_RELEASE,
      saved_at: new Date().toISOString(),
      canonical_source: ATLAS_CANONICAL_MARKET_SOURCE,
      source_mode: state.sourceLock.mode,
      snapshot_id: state.sourceLock.snapshotId,
      source: state.mainSource || ATLAS_CANONICAL_MARKET_SOURCE,
      timestamp: state.timestamp || new Date().toISOString(),
      coins: state.coins,
      global: state.global
    }));
  } catch {}
}

function loadMarketCache() {
  const keys = [MARKET_CACHE_KEY, ...LEGACY_MARKET_CACHE_KEYS];
  for (const key of keys) {
    try {
      const raw = localStorage.getItem(key);
      const parsed = raw ? JSON.parse(raw) : null;
      if (!parsed || parsed.canonical_source !== ATLAS_CANONICAL_MARKET_SOURCE || !atlasCanonicalSnapshot(parsed.coins)) continue;
      if (key !== MARKET_CACHE_KEY) {
        try { localStorage.setItem(MARKET_CACHE_KEY, JSON.stringify({ ...parsed, version: ATLAS_RELEASE, migrated_from: key })); } catch {}
      }
      return parsed;
    } catch {}
  }
  return null;
}

function atlasPrimeMarketCacheSilently() {
  const cache = loadMarketCache();
  atlasStartup.cacheAvailable = !!cache;
  atlasStartup.cacheTimestamp = cache?.timestamp || null;
  return !!cache;
}

function applyMarketCache(reason = "CoinGecko direct indisponible : dernière lecture directe conservée en archive locale.") {
  const cache = loadMarketCache();
  if (!cache) return false;
  const applied = atlasApplyCanonicalSnapshot({ coins: cache.coins, global: cache.global, timestamp: cache.timestamp, snapshotId: cache.snapshot_id, sourceLabel: cache.source ? `${cache.source} · archive locale` : "CoinGecko · archive locale" }, "local-cache");
  if (!applied) return false;
  setLiveStatus("warn", "Mode archive");
  setText(els.sourceName, state.mainSource);
  setText(els.sourceTime, atlasExactTimestampLabel(state.timestamp));
  setTableDecision(`DONNÉES HISTORIQUES ANCIENNES · snapshot ${atlasExactTimestampLabel(state.timestamp)} · analyses suspendues`, "warn");
  atlasRenderMarketAccessNotice();
  renderAll();
  return true;
}

const atlasBinanceEurUsdtKlineCache = new Map();

function agentCryptoSnapshotLocalStorage(keys) {
  const snapshot = {};
  for (const key of keys) {
    try { snapshot[key] = localStorage.getItem(key); }
    catch (error) {
      const failure = new Error(String(error?.message || error || "lecture localStorage impossible"));
      failure.code = `${AGENT_CRYPTO_RESET_ERROR_PREFIX}-LOCALSTORAGE-SNAPSHOT`;
      throw failure;
    }
  }
  return snapshot;
}

function agentCryptoRestoreLocalStorage(snapshot = {}) {
  const failures = [];
  for (const [key, value] of Object.entries(snapshot)) {
    try {
      if (value === null) localStorage.removeItem(key);
      else localStorage.setItem(key, value);
    } catch (error) {
      failures.push({ key, error:String(error?.message || error) });
    }
  }
  return { ok:failures.length === 0, failures };
}

function agentCryptoClearLocalStorage(keys) {
  const failures = [];
  for (const key of keys) {
    try {
      localStorage.removeItem(key);
      if (localStorage.getItem(key) !== null) failures.push({ key, error:"clé encore présente après suppression" });
    } catch (error) {
      failures.push({ key, error:String(error?.message || error) });
    }
  }
  if (failures.length) {
    const failure = new Error("certaines données Agent-Crypto n’ont pas pu être supprimées");
    failure.code = `${AGENT_CRYPTO_RESET_ERROR_PREFIX}-LOCALSTORAGE-CLEAR`;
    failure.details = failures;
    throw failure;
  }
  return { ok:true, removed:keys };
}

function atlasMemoryCanonicalSnapshotId(record) {
  const nested = record?.snapshot?.market_snapshot || {};
  const direct = String(
    record?.market_snapshot_id
    || record?.source_snapshot_id
    || nested?.snapshot_id
    || nested?.snapshotId
    || ""
  ).trim();
  if (direct) return direct;
  const sourceTime = String(
    record?.market_generated_at
    || record?.source_time
    || nested?.source_time
    || ""
  ).trim();
  return sourceTime ? `legacy-source-time:${sourceTime}` : "";
}

function atlasMemoryRecordTime(record) {
  const nested = record?.snapshot?.market_snapshot || {};
  return record?.market_generated_at || record?.source_time || nested?.source_time || record?.saved_at || null;
}

function atlasDistinctMarketMemory(records = []) {
  const ordered = [...records]
    .filter(record => record && record.saved_at)
    .sort((a, b) => Date.parse(a.saved_at || 0) - Date.parse(b.saved_at || 0));
  const map = new Map();
  for (const record of ordered) {
    const collector = record.collector_id || "local-legacy";
    const canonicalId = atlasMemoryCanonicalSnapshotId(record);
    const fallbackId = record.snapshot_id || record.id || record.saved_at;
    const key = `${collector}::${canonicalId || fallbackId}`;
    map.set(key, record);
  }
  return [...map.values()].sort((a, b) => Date.parse(atlasMemoryRecordTime(a) || 0) - Date.parse(atlasMemoryRecordTime(b) || 0));
}

function memoryDominantTags(records) { const counts = countLearningTags(records); const entries = Object.entries(counts).sort((a, b) => b[1] - a[1]); if (!entries.length) return "aucun tag dominant"; return entries.map(([tag, count]) => `${tag} (${count})`).join(", ");
}

