  let profileRole = "";
  try { collector = String(typeof getCollectorId === "function" ? getCollectorId() : "").toLowerCase(); } catch (_) {}
  try { profileRole = String(typeof atlasOperatorProfileRead === "function" ? atlasOperatorProfileRead()?.role || "" : "").toLowerCase(); } catch (_) {}
